const STORY_CATALOG = [{"id":"so-dua","url":"https://truyencotich.top/doc-truyen/so-dua","title":"Sọ Dừa","summary":"Ngày xưa, có hai vợ chồng một lão nông nghèo đi ở cho nhà một phú ông. Họ hiền lành, chăm chỉ nhưng đã ngoài năm mươi tuổi mà chưa có lấy một mụn con...","cat":"vn"},{"id":"truyen-co-tich-tam-cam","url":"https://truyencotich.top/doc-truyen/truyen-co-tich-tam-cam","title":"Truyện cổ tích Tấm Cám","summary":"Ngày xửa ngày xưa, có hai chị em cùng cha khác mẹ, chị tên là Tấm, em tên là Cám. Mẹ Tấm mất sớm, sau đó mấy năm cha Tấm cũng qua đời, Tấm ở với dì ghẻ là mẹ Cám...","cat":"vn"},{"id":"thach-sanh-ly-thong","url":"https://truyencotich.top/doc-truyen/thach-sanh-ly-thong","title":"Thạch Sanh - Lý Thông","summary":"Xưa ở quận Cao Bình có gia đình bác tiều phu Thạch Nghĩa, vợ chồng tuổi cao mà vẫn không con. Ông bà lo buồn và ra sức làm việc nghĩa. Ông thì sửa cầu, sửa cống, khơi rãnh, đắp đường. B�� thì nấu nước cho người qua đường uống...","cat":"vn"},{"id":"truyen-co-tich-cay-khe","url":"https://truyencotich.top/doc-truyen/truyen-co-tich-cay-khe","title":"Truyện cổ tích Cây Khế","summary":"Xưa có một gia đình nọ, người cha và người mẹ mất sớm để lại hai anh em sống với nhau. Người anh thì bản tính tham lam ích kỉ, người em thì ngược lại hiền lành chất phác và luôn biết nhường nhịn...","cat":"vn"},{"id":"thanh-giong","url":"https://truyencotich.top/doc-truyen/thanh-giong","title":"Thánh Gióng","summary":"Vào thời của vua Hùng Vương trước đây, ở một vùng nọ có người đàn bà tuổi cũng đã cao, nhưng vẫn phải sống lủi thủi một mình mãi...","cat":"vn"},{"id":"cay-tre-tram-dot","url":"https://truyencotich.top/doc-truyen/cay-tre-tram-dot","title":"Cây tre trăm đốt","summary":"Chuyện xưa kể lại rằng, ở vùng nọ có một người nông phu rất nghèo khó, vì vậy nên anh ta không còn cách nào khác là phải đến ở cho nhà một phú ông vô cùng giàu có...","cat":"vn"},{"id":"su-tich-con-rong-chau-tien","url":"https://truyencotich.top/doc-truyen/su-tich-con-rong-chau-tien","title":"Sự tích con rồng cháu tiên","summary":"Cách đây lâu đời lắm, ở Lĩnh Nam có một thủ lĩnh tên là Lộc Tục, hiệu là Kinh Dương Vương, sức khoẻ tuyệt trần, lại có tài đi lại dưới nước như đi trên cạn...","cat":"vn"},{"id":"su-tich-trau-cau","url":"https://truyencotich.top/doc-truyen/su-tich-trau-cau","title":"Sự tích Trầu Cau","summary":"Ngày xưa, một nhà quan lang họ Cao có hai người con trai hơn nhau một tuổi và giống nhau như in, đến nỗi người ngoài không phân biệt được ai là anh, ai là em...","cat":"vn"},{"id":"em-be-thong-minh","url":"https://truyencotich.top/doc-truyen/em-be-thong-minh","title":"Em bé thông minh","summary":"Ngày xửa ngày xưa, thưở ấy ở nước ta đang cần người hiền tài giúp nước, các quan trong triều cũng đã già cả rồi, sức không còn nhiều, nhà Vua bèn sai một viên quan đi dò la khắp nước để tìm ra người tài giỏi cùng vua lo toan việc nước...","cat":"vn"},{"id":"su-tich-banh-chung-banh-day","url":"https://truyencotich.top/doc-truyen/su-tich-banh-chung-banh-day","title":"Sự Tích bánh chưng bánh dày","summary":"Bấy giờ là thời kì trị vì của vua Hùng. Nhưng vì tuổi vua càng ngày càng già hơn, thời gian ngồi ngai vàng cũng đã đằng đẵng biết bao năm trời...","cat":"vn"},{"id":"su-tich-dua-hau","url":"https://truyencotich.top/doc-truyen/su-tich-dua-hau","title":"Sự tích dưa hấu","summary":"Ngày xửa ngày xưa, có chàng trai trẻ tuổi tên gọi Mai An Tiêm. Vốn chàng ở một nước rất xa tận ngoài vùng biển phía Nam, sau này lại bị bán trở thành nô. Vào một ngày nọ, bọn lái buôn đem chàng tới bán lại cho Hùng Vương làm nô lệ...","cat":"vn"},{"id":"son-tinh-thuy-tinh","url":"https://truyencotich.top/doc-truyen/son-tinh-thuy-tinh","title":"Sơn Tinh - Thủy Tinh","summary":"Vào đời Vua Hùng thứ 18, Vua có một người con gái đã đến tuổi cập kê, công chúa có dung nhan xinh đẹp tuyệt trần, lại còn có một làn da trắng trẻo mịn màng, dáng người nàng cũng cao ráo. Tên của nàng công chúa này là Mỵ Nương...","cat":"vn"},{"id":"no-duyen-trong-mong","url":"https://truyencotich.top/doc-truyen/no-duyen-trong-mong","title":"Nợ duyên trong mộng","summary":"Ngày xưa ở động Sơn-la thuộc Hưng-hóa có một chàng trẻ tuổi tên là Chu sinh. Bố mẹ mất sớm, chàng được chú đưa về nuôi cho ăn học. Nhưng người chú yêu dấu cháu bao nhiêu thì người thím lại ghét bỏ bấy nhiêu...","cat":"vn"},{"id":"su-tich-ho-guom","url":"https://truyencotich.top/doc-truyen/su-tich-ho-guom","title":"Sự tích hồ Gươm","summary":"Vào thời ấy, giặc Minh đặt ách đô hộ ở nước Nam. Chúng coi dân ta như cỏ rác, thi hành nhiều điều bạo ngược làm cho thiên hạ căm giận đến tận xương tủy...","cat":"vn"},{"id":"tu-thuc-gap-tien","url":"https://truyencotich.top/doc-truyen/tu-thuc-gap-tien","title":"Từ Thức gặp tiên","summary":"Vào đời nhà Trần ở châu Ái có một chàng trẻ tuổi tên là Từ Thức. Chàng vốn con nhà quan. Năm 20 tuổi nhờ học giỏi thi đ��� cao, chàng được bổ một chân tri huyện ở một huyện vùng Bắc...","cat":"vn"},{"id":"vien-ngoc-uoc-cua-qua","url":"https://truyencotich.top/doc-truyen/vien-ngoc-uoc-cua-qua","title":"Viên ngọc ước của quạ","summary":"Ngày xưa, có một anh chàng trẻ tuổi tên là Đê. Nhà anh nghèo khó, cha mẹ phải cho đi ở tại một nhà lão trọc phú. Trọc phú bắt anh chăn trâu. Nhưng anh có thói ham chơi bời...","cat":"vn"},{"id":"su-tich-ho-ba-be","url":"https://truyencotich.top/doc-truyen/su-tich-ho-ba-be","title":"Sự tích hồ Ba Bể","summary":"Vào hồi đó ở xã Nam-mẫu có mở một hội &quot;vô già&quot; cúng Phật. Mọi người nô nức đi xem. Ai nấy đều lo ăn chay niệm Phật và làm những việc từ thiện như buông cá, thả chim...","cat":"vn"},{"id":"lo-nuoc-than-ai-mua-hanh-toi","url":"https://truyencotich.top/doc-truyen/lo-nuoc-than-ai-mua-hanh-toi","title":"Lọ nước thần - Ai mua hành tôi","summary":"Ngày xưa có một anh chàng trẻ tuổi chưa có vợ, sống bằng nghề làm ruộng. Một ngày nọ anh xách búa lên rừng đốn củi. Trong khi đang lúi húi chặt cây, anh trông thấy một con quạ tha một con chim sẻ...","cat":"vn"},{"id":"nang-tien-oc","url":"https://truyencotich.top/doc-truyen/nang-tien-oc","title":"Nàng tiên ốc","summary":"Chuyện xưa kể lại rằng, ở ngôi làng nọ có bà lão sinh sống, tuổi bà cũng đã cao, lại rất nghèo khó. Bởi vì làm lụng vất vả bao năm nên nhìn hình dáng của bà rất ốm yếu, gầy gò, nét mặt của bà thì luôn nhăn nhúm, lúc nào cũng có vẻ đượm buồn...","cat":"vn"},{"id":"su-tich-con-thach-sung","url":"https://truyencotich.top/doc-truyen/su-tich-con-thach-sung","title":"Sự tích con thạch sùng","summary":"Ngày trước, ở vùng nọ có đôi vợ chồng Thạch Sùng, gia đình vốn nghèo khó. Họ cùng nhau sống chui sống lủi ở túp lều ngay gần chợ để xin ăn cho qua ngày...","cat":"vn"},{"id":"cau-be-tich-chu","url":"https://truyencotich.top/doc-truyen/cau-be-tich-chu","title":"Cậu bé Tích Chu","summary":"Ngày xưa, có một bạn tên là Tích Chu. Bố mẹ Tích Chu mất sớm, Tích Chu ở với bà. Hàng ngày bà phải làm việc quần quật kiếm tiền nuôi Tích Chu, có thức gì ngon bà cũng dành cho Tích Chu. Ban đêm, khi Tích Chu ngủ thì bà thức quạt...","cat":"vn"},{"id":"tri-khon-cua-ta-day","url":"https://truyencotich.top/doc-truyen/tri-khon-cua-ta-day","title":"Trí khôn của ta đây","summary":"Một ngày nọ, có con cọp rất lớn từ trong rừng sâu đi ra ngoài, nó trông thấy ở ngay thửa ruộng cạnh rừng có bác nông dân cùng con trâu mộng chăm chỉ cày cuốc...","cat":"vn"},{"id":"su-tich-song-to-lich","url":"https://truyencotich.top/doc-truyen/su-tich-song-to-lich","title":"Sự tích sông Tô Lịch","summary":"Ngày xưa về đời nhà Lý có một ông vua bị bệnh đau mắt. Mấy ông thầy thuốc chuyên môn chữa mắt ở trong kinh thành cũng như ngoài nội thành đều được vời vào cung chạy chữa...","cat":"vn"},{"id":"chang-ngoc-hoc-khon","url":"https://truyencotich.top/doc-truyen/chang-ngoc-hoc-khon","title":"Chàng ngốc học khôn","summary":"Ngày xưa, có anh chàng tên là Đần lấy chị vợ tên là Khôn. Cả đời một chữ cắn làm đôi không biết, anh ta lại chẳng chịu thò đầu đi đâu, chỉ ru rú ở xó nhà để vợ sai bảo, từ việc nhỏ tới việc lớn, nên đã đần lại càng đần thêm...","cat":"vn"},{"id":"no-nhu-chua-chom","url":"https://truyencotich.top/doc-truyen/no-nhu-chua-chom","title":"Nợ như chúa chổm","summary":"Vào thời nhà Lê, có một ông quan lớn trong triều tên là Mạc Đăng Dung có chí muốn cướp ngôi vua. Nhà vua biết được tin đó nhưng thế lực của Mạc rất lớn, ông ta cầm binh quyền, bè đảng lại đông nên không thể làm gì được...","cat":"vn"},{"id":"truyen-co-tich-qua-bau-tien","url":"https://truyencotich.top/doc-truyen/truyen-co-tich-qua-bau-tien","title":"Truyện cổ tích quả bầu tiên","summary":"Ngày xửa, ngày xưa có một chú bé con nhà nghèo, nhưng vô cùng tốt bụng. Chú luôn luôn sẵn lòng giúp đỡ, chăm sóc mọi người, mọi vật xung quanh mình. Vì thế cứ mỗi độ xuân về, chim chóc lại ríu rít kéo nhau tới làm tổ, hót vang quanh nhà chú bé....","cat":"vn"},{"id":"nguoi-con-gai-nam-xuong","url":"https://truyencotich.top/doc-truyen/nguoi-con-gai-nam-xuong","title":"Người con gái Nam Xương","summary":"Ngày xưa, ở làng Nam-xương có cô gái tên là Vũ Thị Thiết, người đã xinh đẹp lại thùy mị nết na. Nàng lấy chồng là Trương sinh vốn là người cùng làng. Trương sinh có tính cả ghen, hay để tâm xét nét vợ...","cat":"vn"},{"id":"su-tich-cay-vu-sua","url":"https://truyencotich.top/doc-truyen/su-tich-cay-vu-sua","title":"Sự tích cây vú sữa","summary":"Ngày xưa, có một cậu bé được mẹ cưng chiều nên rất nghịch và ham chơi. Một lần, bị mẹ mắng, cậu vùng vằng bỏ đi. Cậu la cà khắp nơi, mẹ cậu ở nhà không biết cậu ở đâu nên buồn lắm...","cat":"vn"},{"id":"su-tich-ong-cong-ong-tao","url":"https://truyencotich.top/doc-truyen/su-tich-ong-cong-ong-tao","title":"Sự tích ông công ông táo","summary":"Ngày xưa, có hai vợ chồng son nhà nghèo. Họ đều sinh nhai bằng nghề làm thuê làm mướn. Tuy nghèo nhưng họ rất yêu nhau...","cat":"vn"},{"id":"ong-tuong-gay","url":"https://truyencotich.top/doc-truyen/ong-tuong-gay","title":"Ông tướng gầy","summary":"Thuở xưa có một người thợ rừng lực lưỡng khoẻ mạnh. Cái rìu cái búa thông thường anh cầm lỏng tay, phải thuê thợ rèn đánh to bằng hai bàn tay xoè, dùng mới vừa sức...","cat":"vn"},{"id":"coc-kien-troi","url":"https://truyencotich.top/doc-truyen/coc-kien-troi","title":"Cóc kiện trời","summary":"Ngày xửa ngày xưa, vào một năm không nhớ rõ năm nào, trời làm hạn hán khủng khiếp, nắng lửa hết tháng này đến tháng khác thiêu cháy cây cối, hút cạn nước sông ngòi, đầm hồ...","cat":"vn"},{"id":"bung-lam-da-chiu","url":"https://truyencotich.top/doc-truyen/bung-lam-da-chiu","title":"Bụng làm dạ chịu","summary":"Ngày xưa, có một anh chàng vô công rồi nghề, ngày ngày chỉ biết ăn bám vợ và khoác lác. Người vợ rất lấy làm bực mình vì phải nai lưng ra làm nuôi chồng và ba đứa con...","cat":"vn"},{"id":"chua-do-ong-nghe-da-de-hang-tong","url":"https://truyencotich.top/doc-truyen/chua-do-ong-nghe-da-de-hang-tong","title":"Chưa đỗ ông nghè đã đe hàng tổng","summary":"Ngày xưa có một người học trò nghèo nhưng học giỏi, được Thiên Ðình rất chú ý, trong sổ thiên tào hồi đó đã ghi cho anh chàng đậu tiến sĩ, làm quan đến thượng thư...","cat":"vn"},{"id":"su-tich-con-da-trang","url":"https://truyencotich.top/doc-truyen/su-tich-con-da-trang","title":"Sự tích con Dã Tràng","summary":"Có hai vợ chồng một ông già tên là Dã Tràng. Trong vườn họ có một hang rắn. Thường ngày làm cỏ gần đấy, ông già vẫn thấy có một cặp vợ chồng rắn hổ mang ra vào trong hang...","cat":"vn"},{"id":"su-tich-trai-sau-rieng","url":"https://truyencotich.top/doc-truyen/su-tich-trai-sau-rieng","title":"Sự tích trái sầu riêng","summary":"Ngày ấy, vào thời Tây Sơn, có một chàng trẻ tuổi người vùng Đồng-nai. Chàng là người tài kiêm văn võ, đã từng vung gươm hưởng ứng cái bất bình của mọi người...","cat":"vn"},{"id":"su-tich-cay-huyet-du","url":"https://truyencotich.top/doc-truyen/su-tich-cay-huyet-du","title":"Sự tích cây Huyết Dụ","summary":"Ngày xưa có một bác đồ tể chuyên mua lợn về giết thịt để mang bán ở chợ. Nhà bác ta ở bên cạnh một ngôi chùa làng. Hàng ngày, vào lúc mờ sáng là lúc sư cụ bên chùa theo lệ thường thức dậy tụng kinh...","cat":"vn"},{"id":"trang-nguyen-giap-hai","url":"https://truyencotich.top/doc-truyen/trang-nguyen-giap-hai","title":"Trạng nguyên Giáp Hải","summary":"Trạng nguyên Giáp Hải là một nhân vật lịch sử có thật thời nhà Mạc, được ghi chép trong Đại việt sử ký toàn thư. Tuy xuất thân nghèo khổ, nhưng sự kiên trì học tập và tài năng của ông đã được lịch sử ghi nhận và lưu truyền trong dân gian...","cat":"vn"},{"id":"rach-dui-giau-ngoc","url":"https://truyencotich.top/doc-truyen/rach-dui-giau-ngoc","title":"Rạch đùi giấu ngọc","summary":"Ngày xưa, một ông vua nước ngoài có một viên ngọc vô cùng quý giá. Viên ngọc có hai điều lạ, một là cầm trên tay tưởng chừng rất nhẹ, thế nhưng đặt vào đâu thì ở đấy nặng trĩu...","cat":"vn"},{"id":"gian-may-tao-o-voi-ai","url":"https://truyencotich.top/doc-truyen/gian-may-tao-o-voi-ai","title":"Giận mày tao ở với ai","summary":"Ngày xưa, có một phú ông tự cho mình có tính nhẫn nại ít ai bì kịp. Phú ông có một cô con gái nhan sắc rất là xinh đẹp. Ngày con gái đến tuổi lấy chồng, phú ông liền nghĩ ra một cách...","cat":"vn"},{"id":"cai-can-thuy-ngan","url":"https://truyencotich.top/doc-truyen/cai-can-thuy-ngan","title":"Cái cân thuỷ ngân","summary":"Ngày xưa, có một nhà làm nghề buôn bán, gian tham chế ra một cái cân cán rỗng, trong đổ thủy ngân, hai đầu bịt đồng, không ai biết. Khi cân hàng bán cho người ta thì dốc cán về đằng móc, còn khi cân hàng mua của ai thì dốc cán cân về đằng quả...","cat":"vn"},{"id":"su-tich-chu-cuoi-cay-da","url":"https://truyencotich.top/doc-truyen/su-tich-chu-cuoi-cay-da","title":"Sự tích chú cuội cây đa","summary":"Ngày xưa ở một miền nọ có một người tiều phu tên là Cuội. Một hôm, như lệ thường, Cuội vác rìu vào rừng sâu tìm cây mà chặt. Khi đến gần một con suối nhỏ, Cuội bỗng giật mình trông thấy một cái hang cọp...","cat":"vn"},{"id":"anh-chang-ho-dao","url":"https://truyencotich.top/doc-truyen/anh-chang-ho-dao","title":"Anh chàng họ Đào","summary":"Ngày xưa ở huyện Đông-sơn có một anh học trò họ Đào. Anh đẹp trai, học giỏi, chỉ phải một tội là nhà rất nghèo. Thường ngày anh cắp sách sang làng bên cạnh học với một ông đồ...","cat":"vn"},{"id":"su-tich-thap-bao-an","url":"https://truyencotich.top/doc-truyen/su-tich-thap-bao-an","title":"Sự tích tháp báo ân","summary":"Ngày xưa ở xã Bình-Quân, huyện Cẩm- giàng, có vợ chồng một phú ông nọ sinh được mỗi một cô con gái. Cô xinh đẹp nhất làng, tính nết lại dịu dàng, hiền hậu. nhân nhà cô có nuôi thầy cho con trai học, phú ông cũng cho con gái theo đòi nghiên bút...","cat":"vn"},{"id":"cua-thien-tra-dia","url":"https://truyencotich.top/doc-truyen/cua-thien-tra-dia","title":"Của thiên trả địa","summary":"Ngày xưa, có Thiên và Địa là hai anh chàng cày thuê cuộc mướn cùng ở một làng. Họ giống nhau ở chỗ anh nào anh ấy đều nghèo rớt mùng tơi và đều mồ côi cha mẹ...","cat":"vn"},{"id":"le-nhu-ho","url":"https://truyencotich.top/doc-truyen/le-nhu-ho","title":"Lê Như Hổ","summary":"Ở làng Tiên-châu bây giờ thuộc về tỉnh Hưng-yên, ngày trước có một anh học trò họ Lê. Người anh to cao, ăn khỏe như hổ, bởi thế người ta gọi là Như Hổ...","cat":"vn"},{"id":"con-mu-luong","url":"https://truyencotich.top/doc-truyen/con-mu-luong","title":"Con mụ Lường","summary":"Ngày xưa, có hai vợ chồng một người phú thương trẻ tuổi. Chồng thường rong buồm chạy khắp trong Nam ngoài Bắc và các nước xa xôi, chuyên bán hàng đi và cất hàng về...","cat":"vn"},{"id":"ret-nang-ban","url":"https://truyencotich.top/doc-truyen/ret-nang-ban","title":"Rét nàng Bân","summary":"Ngày xửa ngày xưa, có hai vợ chồng một người phú thương trẻ tuổi. Chồng thường rong buồm chạy khắp trong Nam ngoài Bắc và các nước xa xôi, chuyên bán hàng đi và cất hàng về...","cat":"vn"},{"id":"cay-tao-than","url":"https://truyencotich.top/doc-truyen/cay-tao-than","title":"Cây táo thần","summary":"Ngày xửa, ngày xưa đã lâu lắm rồi, có một cây táo thần mọc ở ngoại ô thành phố. Hàng ngày bọn trẻ thường đến chơi ở đó, nô đùa xung quanh cây táo và bứt những quả táo ngon trên cành để chia nhau ăn...","cat":"vn"},{"id":"su-tich-cai-not-duoi-co-con-trau","url":"https://truyencotich.top/doc-truyen/su-tich-cai-not-duoi-co-con-trau","title":"Sự tích cái nốt dưới cổ con trâu","summary":"Ngày đó trâu cùng nói một thứ tiếng với người. Nhờ thế người dùng lời nói để sai khiến con vật theo ý muốn của mình rất tiện. Cũng như thế, những gã mục đồng đối với trâu không dám đánh đập tàn tệ hoặc cho ăn thiếu thốn vì sợ trâu mách chủ...","cat":"vn"},{"id":"su-tich-cai-chan-sau-con-cho","url":"https://truyencotich.top/doc-truyen/su-tich-cai-chan-sau-con-cho","title":"Sự tích cái chân sau con chó","summary":"Ngày xưa có một người đàn bà tên là Thanh Đề rất sùng đạo Phật. Bà ta sùng Phật đến nỗi cho rằng những cơm bánh do lúa gạo người ta trồng ra ở đồng ruộng thì không thể nào tinh khiết được, nên không một thứ nào đáng đem lễ Phật....","cat":"vn"},{"id":"su-tich-con-chuon-chuon","url":"https://truyencotich.top/doc-truyen/su-tich-con-chuon-chuon","title":"Sự tích con Chuồn Chuồn","summary":"Ngày ấy trong một khu rừng có cái đầm nước thật to, mỗi con vật được phân công một việc. Riêng Chuồn Chuồn được mọi vật giao nhiệm vụ trông coi thời tiết...","cat":"vn"},{"id":"hon-truong-ba-da-hang-thit","url":"https://truyencotich.top/doc-truyen/hon-truong-ba-da-hang-thit","title":"Hồn trương ba da hàng thịt","summary":"Ngày xưa, có một người tên là Trương Ba, còn trẻ tuổi nhưng đánh cờ tướng rất cao. Nước cờ của anh chàng không mấy ai trong thiên hạ địch nổi. Bao nhiêu giải cờ trong những hội hè mùa xuân đều về tay anh. Tiếng đồn vang khắp nướcc...","cat":"vn"},{"id":"nguoi-hoc-tro-va-ba-con-quy","url":"https://truyencotich.top/doc-truyen/nguoi-hoc-tro-va-ba-con-quy","title":"Người học trò và ba con quỷ","summary":"Ngày xưa, ở một vùng nọ có hai vợ chồng một nhà phú hộ tuổi đã già mới sinh được mụn con gái, nên hết sức chiều chuộng. Cô gái lớn lên hình dung đẹp đẽ ít ai bì kịp, bố mẹ lại càng nâng niu như vàng như ngọc...","cat":"vn"},{"id":"su-tich-cong-chua-lieu-hanh","url":"https://truyencotich.top/doc-truyen/su-tich-cong-chua-lieu-hanh","title":"Sự tích công chúa Liễu Hạnh","summary":"Ngày xưa, ở trên thiên đình có cô con gái Ngọc Hoàng tên là Liễu Hạnh. Tính tình cô phóng túng ngang bướng, không chịu theo khuôn phép nhà trời. Ngọc Hoàng hết lòng dạy dỗ nhưng vô ích, cô chứng nào vẫn giữ tật ấy....","cat":"vn"},{"id":"quan-am-thi-kinh","url":"https://truyencotich.top/doc-truyen/quan-am-thi-kinh","title":"Quan Âm Thị Kính","summary":"Ngày xửa ngày xưa, tại một vùng nọ có một phú ông giàu có họ Mãng, gia đình họ có một cô con gái rất bụ bẫm và đáng yêu. Người mẹ hay khen: Ôi, con gái bố mẹ thật đáng yêu, con thật xinh đẹp biết bao…","cat":"vn"},{"id":"noi-doi-nhu-cuoi","url":"https://truyencotich.top/doc-truyen/noi-doi-nhu-cuoi","title":"Nói dối như cuội","summary":"Ngày xưa có một anh chàng trẻ tuổi tên là Cuội. Từ thuở nhỏ, Cuội mồ côi cả cha lẫn mẹ phải đi ở với chú thím. Hắn ta là tay láu lỉnh, đặc biệt về môn lừa người thì rất thành thạo...","cat":"vn"},{"id":"chang-lia","url":"https://truyencotich.top/doc-truyen/chang-lia","title":"Chàng Lía","summary":"Ngày xưa c�� một nhà nông phu nghèo ở Gò Sặt, tỉnh Bình-định có một đứa con trai tên là Lía. Từ thuở lọt lòng, Lía đã mồ côi cha nhưng chóng lớn và khỏe mạnh...","cat":"vn"},{"id":"yet-kieu","url":"https://truyencotich.top/doc-truyen/yet-kieu","title":"Yết Kiêu","summary":"Ngày xưa có một người tên là Yết Kiêu ở làng Hạ-bì làm nghề đánh cá. Một hôm, ông ta đi dọc theo bờ biển về làng bỗng thấy trên bãi có hai con trâu đang ghì sừng húc nhau dưới bóng trăng khuya...","cat":"vn"},{"id":"ke-trom-day-hoc-tro","url":"https://truyencotich.top/doc-truyen/ke-trom-day-hoc-tro","title":"Kẻ trộm dạy học trò","summary":"Ngày xưa có một tay ăn trộm lành nghề. Lão ta thấy mình tuổi già sức yếu nên muốn truyền cái bí kíp của lối sinh nhai &quot;trèo tường khoét vách&quot; cho một vài đồ đệ...","cat":"vn"},{"id":"su-tich-cay-ca-phe","url":"https://truyencotich.top/doc-truyen/su-tich-cay-ca-phe","title":"Sự tích cây cà phê","summary":"Ngày xưa, ở một vùng đất nọ nơi của những con sông và dòng thác gặp nhau có một buôn làng nhỏ sinh sống. Họ sống yên bình bên những nương ngô nương sắn xanh mướt núi rừng...","cat":"vn"},{"id":"su-tich-con-nhai","url":"https://truyencotich.top/doc-truyen/su-tich-con-nhai","title":"Sự tích con nhái","summary":"Ngày xưa có một vị hòa thượng trẻ tuổi nổi tiếng chân tu. Mọi “thị dục” của bản thân, hòa thượng đều kiên quyết cắt đứt, chỉ một lòng chuyên chú vào lẽ hư vô của đạo Thiền. Nhà vua nghe tiếng, vô cùng kính trọng, vời về cung, ban tước quốc sư..","cat":"vn"},{"id":"ba-chua-beo","url":"https://truyencotich.top/doc-truyen/ba-chua-beo","title":"Bà chúa bèo","summary":"Ngày xửa ngày xưa ở một làng nọ có một cô bé hiền lành, chịu thương chịu khó. Một ngày cô ngồi ở bờ ruộng lặng nhìn những cây lúa nghẹn đòng ở ruộng nhà. Cô thương cho lúa và lo cho gia đình mình. Năm nay mất mùa thì lại bữa cơm bữa cháo...","cat":"vn"},{"id":"su-tich-hoa-thuy-tinh","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-thuy-tinh","title":"Sự tích hoa thủy tinh","summary":"Ngày xửa ng��y xưa, trong một ngôi làng nọ, có hai vợ chồng nghèo, rất nghèo, họ nghèo đến nỗi không có nổi một căn nhà để ở, không có 1 mảnh ruộng để nuôi thân....","cat":"vn"},{"id":"su-tich-cay-nhan-sam","url":"https://truyencotich.top/doc-truyen/su-tich-cay-nhan-sam","title":"Sự tích cây nhân sâm","summary":"Ngày xưa, có hai vợ chồng người tiều phu nghèo khổ, làm lụng vất vả quanh năm. Tờ mờ sáng đã ra đi làm, đến tối mịt mới về nhà mà cũng không kiếm đủ gạo ăn...","cat":"vn"},{"id":"su-tich-ong-ba-muoi","url":"https://truyencotich.top/doc-truyen/su-tich-ong-ba-muoi","title":"Sự tích ông ba mươi","summary":"Đã từ lâu lắm, trên cõi trời có một người có sức khỏe lạ lùng, những việc dời núi, lấp biển, đội đá, bẻ cây,… không một ai bì kịp. Nói về tài phép, ông cũng thần thông biến hóa vượt xa nhiều vị trên Thiên Đình","cat":"vn"},{"id":"chang-coc","url":"https://truyencotich.top/doc-truyen/chang-coc","title":"Chàng cóc","summary":"Ngày xưa, trong một bản vắng, có hai vợ chồng nọ đã sống qua nhiều mùa nương mà chưa có con nối dòng. Họ buồn rầu như cỏ tranh già ngày nắng. Ngày ngày, người vợ thắp hương cầu khấn mong trời thương cảnh nghèo đơn chiếc ban cho một đứa con...","cat":"vn"},{"id":"vua-heo","url":"https://truyencotich.top/doc-truyen/vua-heo","title":"Vua heo","summary":"Ngày xửa ngày xưa có một cậu bé mồ côi, quần áo rách rưới lang thang đi ăn xin khắp nơi, có lần đến ngôi làng nọ, có một người thấy cậu cũng nhanh nhẹn bèn mang cậu về nhà nuôi để sai vặt...","cat":"vn"},{"id":"su-tich-cay-choi","url":"https://truyencotich.top/doc-truyen/su-tich-cay-choi","title":"Sự tích cây chổi","summary":"Ngày trước ở trên cung đình của nhà trời có người đàn bà rất khéo tay, bà nấu ăn rất ngon. Những thứ bánh trái mà bà chế ra đều là tuyệt phẩm cả, chỉ cần nếm qua những món ăn ấy là lại không cách nào quên được hương vị của nó...","cat":"vn"},{"id":"cuu-vat-vat-tra-on-cuu-nhan-nhan-bao-oan","url":"https://truyencotich.top/doc-truyen/cuu-vat-vat-tra-on-cuu-nhan-nhan-bao-oan","title":"Cứu vật, vật trả ơn - Cứu nhân, nhân báo oán","summary":"Ngày xưa, có một anh chàng không có tài nghề gì cả, chỉ được cái hiền lành hay thương người. Từ lúc vợ chết, anh ta trở n��n túng bấn tợn. Có dạo phải ngửa tay ăn xin...","cat":"vn"},{"id":"su-tich-con-thieu-than","url":"https://truyencotich.top/doc-truyen/su-tich-con-thieu-than","title":"Sự tích con thiêu thân","summary":"Ngày xưa, ở một làng gần phá Tam Giang (Thừa Thiên- Huế ngày nay), có một chàng trai khoẻ mạnh, thông minh nhưng phải cái tính hơi gàn dở, làm gì cũng khác người, lại chẳng ham thích cái gì được lâu...","cat":"vn"},{"id":"su-tich-thanh-lang-chem","url":"https://truyencotich.top/doc-truyen/su-tich-thanh-lang-chem","title":"Sự tích Thánh làng Chèm","summary":"Ngày xưa, ở làng Chèm có một người họ Lý khỏe mạnh lạ thường. Đặc biệt thân thể của anh ta quá khổ, đo được hai trượng sáu thước bề cao. Vì thế đi đâu ai cũng kinh sợ người ta gọi là Ông Trọng...","cat":"vn"},{"id":"su-tich-khan-tang","url":"https://truyencotich.top/doc-truyen/su-tich-khan-tang","title":"Sự tích khăn tang","summary":"Nhà giàu nhưng lại không con trai, nên bao nhiêu tình thương họ đều dồn vào những cô con gái. Lần lượt năm cô lớn lên, ai nấy đều lập gia đình và đi ở riêng...","cat":"vn"},{"id":"su-tich-chim-hit-co","url":"https://truyencotich.top/doc-truyen/su-tich-chim-hit-co","title":"Sự tích chim hít cô","summary":"Ngày xưa, có hai cô cháu ở chung với nhau một nhà. Người cô già, chồng chết từ lâu. Đứa cháu còn bé chừng mười hai tuổi mồ côi cha mẹ...","cat":"vn"},{"id":"su-tich-cay-neu-ngay-tet","url":"https://truyencotich.top/doc-truyen/su-tich-cay-neu-ngay-tet","title":"Sự tích cây nêu ngày tết","summary":"Ngày trước, cũng chẳng ai biết rõ là bắt đầu từ khi nào và bằng cách nào đó, Quỷ đã chiếm đoạt hết từng tấc đất ở nước ta. Con người chỉ là ăn nhờ ở đậu, cũng như làm rẽ ruộng đất thuộc sở hữu của Quỷ mà thôi...","cat":"vn"},{"id":"su-tich-con-khi","url":"https://truyencotich.top/doc-truyen/su-tich-con-khi","title":"Sự tích con khỉ","summary":"Chuyện rất lâu trước đây kể lại rằng, ở làng nọ có người con gái phải đi ở cho nhà trưởng giả. Ở nơi này nàng suốt ngày phải làm việc quần quật, còn bị chủ nhà đối xử vô cùng tệ bạc...","cat":"vn"},{"id":"nang-ong-chua","url":"https://truyencotich.top/doc-truyen/nang-ong-chua","title":"Nàng ong chúa","summary":"Ngày xưa có một người học trò nhà nghèo rớt mùng tơi tên là Sĩ. Anh ở với bà mẹ già lụ khụ. Anh muốn lấy vợ để vợ đỡ đần công việc nhà và phụng dưỡng mẹ già, nhưng hỏi mấy đám, người ta thấy nhà anh luôn năm thiếu ăn nên đều lắc đầu từ chối...","cat":"vn"},{"id":"ba-chang-thien-nghe","url":"https://truyencotich.top/doc-truyen/ba-chang-thien-nghe","title":"Ba chàng thiện nghệ","summary":"Ngày xưa, có nhà họ Lê có một cô gái nhan sắc xinh đẹp. Không những thế, nàng còn văn hay chữ tốt, lại thạo đủ các nghề. Những cô gái đẹp trong vùng khó có cô nào ăn đứt...","cat":"vn"},{"id":"su-tich-con-de","url":"https://truyencotich.top/doc-truyen/su-tich-con-de","title":"Sự tích con dế","summary":"Ngày xưa, có một người đàn ông hai vợ, người vợ cả chết sớm để lại một đứa con trai còn bé tên là Văn Linh. Người vợ lẽ cũng sinh được một đứa con trai khác tên là Văn Lang...","cat":"vn"},{"id":"truyen-thuyet-thanh-co-loa","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-thanh-co-loa","title":"Truyền thuyết thành Cổ Loa","summary":"Khi đã chiếm được đất Văn Lang, An Dương Vương đổi tên nước là Âu Lạc, đóng đô ở Phong Khê. Khu đất chọn để đắp thành là một quả đồi đất rắn như đá. Ðám đông người hì hục đào đất, khuân đất hết ngày nọ sang ngày kia, tòa thành cao dần...","cat":"vn"},{"id":"bon-cau-noi-bi-hiem","url":"https://truyencotich.top/doc-truyen/bon-cau-noi-bi-hiem","title":"Bốn câu nói bí hiểm","summary":"Có một vị vua trẻ đẹp, nhưng phải tội say mê phụ nữ quá độ, đã tiêu phí hầu hết cả thời gian để đi lại với phụ nữ trong cung đình. Một hôm, nhà vua cưỡi ngựa dạo chơi trong một cánh rừng...","cat":"vn"},{"id":"tra-tan-hon-da","url":"https://truyencotich.top/doc-truyen/tra-tan-hon-da","title":"Tra tấn hòn đá","summary":"Ngày xưa có hai vợ chồng một người nghèo, suốt năm đầu tắt mặt tối, ăn bữa sớm không biết có bữa chiều. Kỳ ấy năm hết Tết đến mà trong nhà không có lấy một bát gạo...","cat":"vn"},{"id":"tieu-diet-mang-xa","url":"https://truyencotich.top/doc-truyen/tieu-diet-mang-xa","title":"Tiêu diệt mãng xà","summary":"Ngày xưa, trong một hang núi nọ có một con mãng xà. Đầu nó to bằng cái chum, trên đầu có mào đỏ, hai mắt như hai quả quýt, thân dài hơn trượng...","cat":"vn"},{"id":"lay-bay-nhu-cao-bien-day-non","url":"https://truyencotich.top/doc-truyen/lay-bay-nhu-cao-bien-day-non","title":"Lẩy bẩy như Cao Biền dậy non","summary":"Ngày xưa ở Trung-quốc có Cao Biền rất giỏi nghề địa lý. Những phép hô thần tróc quỷ, ông đều thông thạo. Tiếng đồn vang khắp nơi. Hoàng đế Trung-quốc nghe tiếng liền triệu Biền vào cung ủy thác cho việc kiếm một ngôi đất xây dựng lăng tẩm...","cat":"vn"},{"id":"bo-beo-bo-gay","url":"https://truyencotich.top/doc-truyen/bo-beo-bo-gay","title":"Bò béo bò gầy","summary":"Ngày ấy vào thời vua Lê chúa Trịnh có hai vợ chồng một người nho sinh họ Lê. Nhân ngày cuối năm dắt nhau về thăm quê quán trong thành...","cat":"vn"},{"id":"mieng-trau-ky-dieu","url":"https://truyencotich.top/doc-truyen/mieng-trau-ky-dieu","title":"Miếng trầu kỳ diệu","summary":"Ngày xưa, có một anh học trò tầm thường tên là Hồ Sinh. Gia tư của hắn cũng không lấy gì làm thiếu thốn, nhưng ngày đêm, hắn chỉ những mong muốn một chút danh phận...","cat":"vn"},{"id":"su-tich-hon-vong-phu","url":"https://truyencotich.top/doc-truyen/su-tich-hon-vong-phu","title":"Sự tích hòn Vọng Phu","summary":"Ngày xưa, có đôi vợ chồng nghèo sinh được hai mụn con: đứa lớn là trai mười một tuổi, đứa bé là gái lên sáu tuổi. Mỗi lần hai vợ chồng đi làm đồng hay đi đâu vắng, thường để hai con ở lại nhà, dặn anh trông nom em gái...","cat":"vn"},{"id":"dong-tien-van-lich","url":"https://truyencotich.top/doc-truyen/dong-tien-van-lich","title":"Đồng tiền Vạn Lịch","summary":"Ngày xưa ở huyện Thanh Trì có một anh chàng học trò nghèo họ Nguyễn. Anh ta mồ côi cha, nhà cửa sa sút. Người mẹ làm nghề chống đò ngang cố nuôi cho con ăn học...","cat":"vn"},{"id":"dua-con-troi-danh-hay-la-truyen-tiec-ga-chon-me","url":"https://truyencotich.top/doc-truyen/dua-con-troi-danh-hay-la-truyen-tiec-ga-chon-me","title":"Đứa con trời đánh hay là truyện Tiếc gà chôn mẹ","summary":"Xưa có một người đàn ông tính rất vũ phu. Đối với vợ con, hơi động một tý là hắn đánh đập không tiếc tay...","cat":"vn"},{"id":"ong-o","url":"https://truyencotich.top/doc-truyen/ong-o","title":"Ông Ồ","summary":"Ngày xưa ở cửa Sót thuộc Hà-tĩnh có một người làng chài có sức khỏe hơn đời. Ông ta làm việc gấp đôi gấp ba người thường, sức ăn mỗi bữa có thể hết một nồi mười cơm...","cat":"vn"},{"id":"nguoi-a-dao-voi-giac-minh","url":"https://truyencotich.top/doc-truyen/nguoi-a-dao-voi-giac-minh","title":"Người ả đào với giặc Minh","summary":"Làng Đào-đặng thuộc tỉnh Hưng-yên khi xưa có một thôn, trong thôn có nhiều con gái người đẹp hát hay, hầu hết đều làm nghề ả đào...","cat":"vn"},{"id":"cai-kien-may-kien-cu-khoai","url":"https://truyencotich.top/doc-truyen/cai-kien-may-kien-cu-khoai","title":"Cái kiến mày kiện củ khoai","summary":"Ngày xưa, có một anh chàng sinh trưởng trong một gia đình giàu có. Nhà hắn có ao thả cá, có trâu bò, ruộng vườn khá nhiều. Ngày ấy ở gần làng hắn có một cô gái nết na, nhan sắc xinh đẹp, chỉ phải cái tội nghèo...","cat":"vn"},{"id":"am-duong-giao-chien","url":"https://truyencotich.top/doc-truyen/am-duong-giao-chien","title":"Âm dương giao chiến","summary":"Ngày ấy, có một trận mưa lụt rất dữ dội, khúc đê ở xã Thọ-triền bị vỡ, mùa màng hư hại, nhà cửa, súc vật trôi nổi theo dòng nước bạc...","cat":"vn"},{"id":"con-vo-khon-lay-thang-chong-dai-nhu-bong-hoa-lai-cam-bai-cut-trau","url":"https://truyencotich.top/doc-truyen/con-vo-khon-lay-thang-chong-dai-nhu-bong-hoa-lai-cam-bai-cut-trau","title":"Con vợ khôn lấy thằng chồng dại như bông hoa lài cấm bãi cứt trâu","summary":"Xưa, có một người đàn bà làm nghề dệt vải. Nàng bản tính thông minh tháo vát, nhưng lấy phải người chồng đần độn không làm được nghề gì nên thân...","cat":"vn"},{"id":"nguoi-ho-lieu-va-diem-vuong","url":"https://truyencotich.top/doc-truyen/nguoi-ho-lieu-va-diem-vuong","title":"Người họ Liêu và Diêm Vương","summary":"Ngày ấy có dòng họ Liêu, không hiểu do nguyên cớ nào mà người trong họ thường bị nạn chết non...","cat":"vn"},{"id":"giet-cho-khuyen-chong","url":"https://truyencotich.top/doc-truyen/giet-cho-khuyen-chong","title":"Giết chó khuyên chồng","summary":"Ngày xưa có hai anh em nhà kia, anh có lắm tiền nhiều bạc, còn em thì cam phận túng bấn. Nhưng người anh vẫn không mấy khi đoái hoài tới em mình, trái lại chỉ thân thiết với bọn vô lại, nay rượu chè, mai cờ bạc làm vui...","cat":"vn"},{"id":"chiec-ao-tang-hinh","url":"https://truyencotich.top/doc-truyen/chiec-ao-tang-hinh","title":"Chiếc áo tàng hình","summary":"Ngày xưa ở vùng Cao Bằng có một chàng trẻ tuổi, nay đây mai đó làm nghề chài lưới, tên là Triều. Gia sản của anh không có gì ngoài bộ đồ nghề...","cat":"vn"},{"id":"ha-o-loi","url":"https://truyencotich.top/doc-truyen/ha-o-loi","title":"Hà Ô Lôi","summary":"Vào thời nhà Trần, ở làng Ma La gần thành Thăng Long có Đặng Sĩ Dinh tuổi còn trẻ mà đã làm quan to. Ông ta có một người vợ rất đẹp. Hai vợ chồng yêu nhau rất mực....","cat":"vn"},{"id":"di-phai-thang-chet-troi-con-toi-phai-doi-sau-sanh","url":"https://truyencotich.top/doc-truyen/di-phai-thang-chet-troi-con-toi-phai-doi-sau-sanh","title":"Dì phải thằng chết trôi, còn tôi phải đôi sấu sành","summary":"Ngày xưa có một anh chàng trẻ tuổi kiết xác, chưa có vợ. Nhà anh ta lại ở bên cạnh nhà một phú ông có cô con gái đến tuổi lấy chồng...","cat":"vn"},{"id":"bich-cau-ky-ngo","url":"https://truyencotich.top/doc-truyen/bich-cau-ky-ngo","title":"Bích Câu kỳ ngộ","summary":"Vào đời Hồng Đức, có một người học trò nghèo, sớm mồ côi cha mẹ, trọ học ở phường Bích Câu, phía Nam thành Thăng Long...","cat":"vn"},{"id":"nguoi-cuoi-ma","url":"https://truyencotich.top/doc-truyen/nguoi-cuoi-ma","title":"Người cưới ma","summary":"Ngày xưa có một anh đồ họ Lê, nhà nghèo khó, phải bỏ đi các nơi làm nghề gõ đầu trẻ. Về sau anh được một phú ông một làng nọ đón về “ngồi” ở nhà để cho con khỏi đi học xa...","cat":"vn"},{"id":"su-tich-chim-quoc","url":"https://truyencotich.top/doc-truyen/su-tich-chim-quoc","title":"Sự tích chim quốc","summary":"Ngày ấy có đôi bạn chí thân là Quắc và Nhân. Họ đều là con nhà học trò nghèo, lại đều mồ côi cha mẹ, Quắc được học nhiều hơn bạn: anh chàng làm thầy đồ dạy trẻ...","cat":"vn"},{"id":"bon-nguoi-ban","url":"https://truyencotich.top/doc-truyen/bon-nguoi-ban","title":"Bốn người bạn","summary":"Xưa có bốn người bạn, mỗi người quê quán một phương. Vì thuở trẻ cùng học với nhau một thầy, nên họ có dịp sống chung với nhau lâu ngày, rồi dần dần trở nên những người bạn nối khố. Về sau lớn lên, họ lại từ giã thầy, mỗi người làm ăn một ngả...","cat":"vn"},{"id":"cai-chen-gao-dua","url":"https://truyencotich.top/doc-truyen/cai-chen-gao-dua","title":"Cái Chén Gáo Dừa","summary":"Ngày xưa, ở một vùng nọ, có vợ chồng kia hiền lành và chăm chỉ, hai người lấy nhau đã lâu mà vẫn chưa có con, họ cầu Trời khấn Phật mãi nhưng vẫn chưa có kết quả. Hôm ấy, sau khi hai vợ chồng đi lễ chùa về, trời đang nắng bỗng nổi cơn mưa lớn...","cat":"vn"},{"id":"su-tich-meo-va-chuot","url":"https://truyencotich.top/doc-truyen/su-tich-meo-va-chuot","title":"Sự tích mèo và chuột","summary":"Ngày ấy các kho của nhà trời thường hay bị nạn trộm cắp, vì vậy Ngọc Hoàng thượng đế cần tìm một kẻ chuyên trông nom kho tàng...","cat":"vn"},{"id":"con-voi-voi-nguoi-quan-tuong-gia","url":"https://truyencotich.top/doc-truyen/con-voi-voi-nguoi-quan-tuong-gia","title":"Con voi với người quản tượng già","summary":"Ngày xưa, vào đời nhà Lê, nhà vua có nuôi một con voi rất khôn, dùng để cỡi. Voi có 3 cái đai bằng vàng đeo chặt ở cổ. Đến thời Lê mạt vận, con voi không chịu ở với ai nữa...","cat":"vn"},{"id":"co-ghep","url":"https://truyencotich.top/doc-truyen/co-ghep","title":"Cố ghép","summary":"Ngày xưa, ở dưới chân núi Hồng-Lĩnh về phía Đông nam, có một xóm nhỏ gồm mấy gia đình đánh cá. Họ luôn sống giữa những tiếng gầm thét của sóng biển. Nhưng không may, một ngày kia, một trận bão lớn đã cuốn đi...","cat":"vn"},{"id":"luoi-dao-than","url":"https://truyencotich.top/doc-truyen/luoi-dao-than","title":"Lưỡi dao thần","summary":"Xưa kia, có một em bé ở đợ chăn trâu cho nhà giàu. Đàn trâu nhà này đông lắm, không ai chịu cho em chăn chung. Quanh năm em phải một mình chăn riêng đàn trâu, giữa chốn rừng hoang, đồng vắng. Chẳng có ai trò chuyện...","cat":"vn"},{"id":"con-ho-co-nghia","url":"https://truyencotich.top/doc-truyen/con-ho-co-nghia","title":"Con hổ có nghĩa","summary":"Ngày xửa ngày xư, ở huyện Đông Triều tỉnh Quảng Ninh vùng Đông Bắc nước ta có một người đàn bà họ Trần, làm nghề đỡ đẻ và nổi tiếng mát tay. Bà sống trong ngôi nhà nhỏ ven đường, cách rừng vài dặm...","cat":"vn"},{"id":"van-khu-hoai-son-nang-tri-tu-thoi-lai-bach-thuy-kha-thoi-sinh","url":"https://truyencotich.top/doc-truyen/van-khu-hoai-son-nang-tri-tu-thoi-lai-bach-thuy-kha-thoi-sinh","title":"Vận khứ hoài sơn năng trí tử, thời lai bạch thủy khả thôi sinh","summary":"Ngày xưa, có một ông lang xem mạch chữa bệnh rất giỏi. Các môn nội khoa cũng như ngoại khoa ông đều thành thạo. Ông lại là một người chính trực. Mọi nơi tôn ông làm danh sư, vì vậy nổi tiếng một thời...","cat":"vn"},{"id":"bui-cam-ho","url":"https://truyencotich.top/doc-truyen/bui-cam-ho","title":"Bùi Cầm Hổ","summary":"Vào thời nhà Lê có một anh chàng nghèo khổ quê ở Kẻ-treo sát chân núi Hồng-lĩnh tên là Hổ. Lúc còn nhỏ Hổ có đi học dăm ba chữ với một cụ đồ già. Lớn lên Hổ sống một thân một mình không cha mẹ anh em gì cả...","cat":"vn"},{"id":"vo-tong-danh-ho-tren-doi-canh-duong","url":"https://truyencotich.top/doc-truyen/vo-tong-danh-ho-tren-doi-canh-duong","title":"Võ Tòng đánh hổ trên đồi Cảnh Dương","summary":"Trên núi Cảnh Dương có một con cọp rất lớn, cứ đến chiều là ra đón ở đường, để hại người qua lại, xưa nay giết hại đã có tới hai ba mươi tên hảo hán, mà chưa ai làm sao trị nổi...","cat":"vn"},{"id":"nguoi-tho-moc-nam-hoa","url":"https://truyencotich.top/doc-truyen/nguoi-tho-moc-nam-hoa","title":"Người thợ mộc Nam Hoa","summary":"Làng Nam-hoa có một người thợ mộc khéo tay tên là Chuẩn.Thưở trẻ ông lưu lạc khắp nơi vừa làm thuê vừa học nghề. Nghe ở đâu có thợ khéo là ông cố nằn nì xin học cho được, dù có phải phục dịch thế nào cũng rất vui lòng...","cat":"vn"},{"id":"vang-lay-con-vua","url":"https://truyencotich.top/doc-truyen/vang-lay-con-vua","title":"Vàng lấy con vua","summary":"Ngày xửa ngày xưa, có một em bé tên là Vàng, Vàng mới lên tám tuổi thì bố chết. Nhà nghèo, em phải theo mẹ đi làm thuê khắp đó đây. Quần quật suốt ngày mà mẹ con vẫn không đủ ăn...","cat":"vn"},{"id":"hai-anh-em-truyen-co-tich-viet-nam","url":"https://truyencotich.top/doc-truyen/hai-anh-em-truyen-co-tich-viet-nam","title":"Hai anh em - Truyện cổ tích Việt Nam","summary":"Ngày xưa có hai anh em nhà kia, cha mẹ chết sớm hai anh em ở với nhau. Người anh thì chăm chỉ làm lụng còn người em thì chỉ chơi bời lêu lổng, suốt ngày chẳng mó tay vào việc gì...","cat":"vn"},{"id":"cha-me-nuoi-con-be-ho-lai-lang-con-nuoi-cha-me-ke-thang-ke-ngay","url":"https://truyencotich.top/doc-truyen/cha-me-nuoi-con-be-ho-lai-lang-con-nuoi-cha-me-ke-thang-ke-ngay","title":"Cha mẹ nuôi con bể hồ lai láng, con nuôi cha mẹ kể tháng kể ngày","summary":"Xưa, có hai vợ chồng một nhà nọ làm ăn chí thú. Họ sinh được ba người con, đều là con trai. Hai vợ chồng nuôi con rất chăm chút...","cat":"vn"},{"id":"chang-ngoc-duoc-kien","url":"https://truyencotich.top/doc-truyen/chang-ngoc-duoc-kien","title":"Chàng ngốc được kiện","summary":"Ngày xưa có anh chàng nghèo khổ không nhà không cửa, không cha không mẹ, tính ngốc nghếch, nên người ta gọi là chàng Ngốc...","cat":"vn"},{"id":"su-tich-ca-he","url":"https://truyencotich.top/doc-truyen/su-tich-ca-he","title":"Sự tích cá he","summary":"Ngày xưa có một nhà sư trẻ tuổi rất ngoan đạo. Sau hơn ba mươi năm khổ công tu luyện, sư thuộc lòng tất cả các kinh kệ nhà Phật, lại giỏi thuyết pháp...","cat":"vn"},{"id":"su-tich-hoa-phuong","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-phuong","title":"Sự tích hoa phượng","summary":"Ngày xưa, xưa lắm, ở một vùng đất đồi kia, có một ông thầy dạy võ nổi tiếng về tài đánh kiếm. Vợ ông chết sớm, ông thương vợ, không lấy ai nữa nên ông không có con...","cat":"vn"},{"id":"su-tich-con-moi","url":"https://truyencotich.top/doc-truyen/su-tich-con-moi","title":"Sự tích con mối","summary":"Một chàng trẻ tuổi nhà giàu, ao ước một người vợ đẹp như tiên. Cha mẹ hỏi cho đám nào hắn cũng không vừa ý...","cat":"vn"},{"id":"su-tich-nuoc-bien-man","url":"https://truyencotich.top/doc-truyen/su-tich-nuoc-bien-man","title":"Sự tích nước biển mặn","summary":"Ngày xưa,từ rất lâu rồi,có một chàng trai nghèo sống bên bờ biển. Ngày đó biển êm đềm, trong xanh và phẳng lặng, nước biển dịu ngọt không có những con sóng xô bờ. Chàng trai sống bằng nghề đánh cá, chàng làm việc rất chăm chỉ...","cat":"vn"},{"id":"su-tich-con-ve-sau","url":"https://truyencotich.top/doc-truyen/su-tich-con-ve-sau","title":"Sự tích con Ve Sầu","summary":"Hàng ngày, người anh phải đi làm thuê làm mướn, làm quần quật từ sáng sớm đến trời tối. Nhưng hai anh em vẫn không đủ cái ăn, cái mặc...","cat":"vn"},{"id":"con-coc-liem-nuoc-mua","url":"https://truyencotich.top/doc-truyen/con-coc-liem-nuoc-mua","title":"Con cóc liếm nước mưa","summary":"Có hai người bạn Ân và Nghĩa cùng làm nghề sơn tràng. Thường ngày họ vào trong rừng sâu tìm cây đốn ngã xuống, phạt cành lá, rồi cho trâu kéo ra bán cho bọn lái gỗ...","cat":"vn"},{"id":"bay-dieu-uoc","url":"https://truyencotich.top/doc-truyen/bay-dieu-uoc","title":"Bảy điều ước","summary":"Ngày xưa có hai vợ chồng bác nông sinh được hai người con trai. Người anh thì tham lam, lười biếng còn người em thì thật thà, tốt bụng, chăm chỉ chịu thương chịu khó...","cat":"vn"},{"id":"su-tich-thanh-loi","url":"https://truyencotich.top/doc-truyen/su-tich-thanh-loi","title":"Sự tích thành Lồi","summary":"Ngày xưa, có một ông vua nước Chăm muốn lấy một nàng công chúa nước Đại Việt làm vợ. Nhà vua nghe nói công chúa Huyền Trân nhan sắc tuyệt trần, những phi tần trong cung vua khó bề sánh kịp...","cat":"vn"},{"id":"su-tich-con-muoi","url":"https://truyencotich.top/doc-truyen/su-tich-con-muoi","title":"Sự tích con muỗi","summary":"Có hai vợ chồng nhà nọ yêu nhau rất mực. Ngày mới lấy nhau, họ đã từng ăn thề hẹn không bỏ nhau. Nếu không may một trong hai người chết đi thì người kia sẽ chết theo để xuống âm ty cho có bạn...","cat":"vn"},{"id":"trinh-phu-hai-chong","url":"https://truyencotich.top/doc-truyen/trinh-phu-hai-chong","title":"Trinh phụ hai chồng","summary":"Ngày xưa có một gia đình nọ có một người con gái xinh xắn nết na. Lúc nàng lớn lên có một người học trò nghèo họ Đỗ đưa trầu cau đến hỏi làm vợ...","cat":"vn"},{"id":"kien-nganh-da","url":"https://truyencotich.top/doc-truyen/kien-nganh-da","title":"Kiện ngành đa","summary":"Ngày xưa có hai vợ chồng một người lái buôn hương. Họ chưa có con cái gì cả. Chồng vắng nhà liên miên, chỉ thỉnh thoảng mới về một lần...","cat":"vn"},{"id":"to-dau-ma-dai-nho-dai-ma-khon","url":"https://truyencotich.top/doc-truyen/to-dau-ma-dai-nho-dai-ma-khon","title":"To đầu mà dại, nhỏ dái mà khôn","summary":"Một hôm voi đang đủng đỉnh đi chơi bỗng gặp hổ. Hai bên chào hỏi chuyện trò chán chê, đoạn hổ bảo với voi...","cat":"vn"},{"id":"cua-troi-troi-lai-lay-di-giuong-doi-mat-ech-lam-chi-duoc-troi","url":"https://truyencotich.top/doc-truyen/cua-troi-troi-lai-lay-di-giuong-doi-mat-ech-lam-chi-duoc-troi","title":"Của trời trời lại lấy đi, giương đôi mắt ếch làm chi được trời","summary":"Ngày xưa có một người nghèo khổ quá. Ngày ngày ông ra bãi biển cố sức mò cua bắt ốc để lấy miếng ăn, nhưng không bao giờ đủ...","cat":"vn"},{"id":"hai-ong-tuong-da-rai","url":"https://truyencotich.top/doc-truyen/hai-ong-tuong-da-rai","title":"Hai ông tướng Đá Rãi","summary":"Dưới thời nhà Lý, có một ông vua, nhân một hôm đi du ngoạn về mi���n núi xứ Đoài, tự nhiên thấy ở sườn núi nứt ra một khe rộng, rồi từ trong đi ra hai người to lớn lạ thường...","cat":"vn"},{"id":"anh-em-sinh-nam","url":"https://truyencotich.top/doc-truyen/anh-em-sinh-nam","title":"Anh em sinh năm","summary":"Ngày xưa có hai vợ chồng nhà nọ chỉ sinh được có mỗi một người con gái. Vì thế họ nuôi nấng dạy dỗ rất chăm chút...","cat":"vn"},{"id":"bon-anh-tai","url":"https://truyencotich.top/doc-truyen/bon-anh-tai","title":"Bốn anh tài","summary":"Ngày xưa có hai vợ chồng nhà nghèo mà không có con. Hai người khấn vái hết đền này đến chùa khác, mãi sau mới sinh được một mụn con trai...","cat":"vn"},{"id":"dai-vuong-hai-hay-la-truyen-giet-thuong-luong","url":"https://truyencotich.top/doc-truyen/dai-vuong-hai-hay-la-truyen-giet-thuong-luong","title":"Đại vương Hai hay là truyện giết thuồng luồng","summary":"Ngày xưa, ở làng Hoa-viên, bây giờ thuộc tỉnh Hà-tĩnh, có một anh chàng tên là Hai. Lúc còn trẻ, cha mất sớm, anh chàng mặc sức chơi bời, mẹ không thể ngăn cản nổi...","cat":"vn"},{"id":"bay-giao-chin-quyen-y","url":"https://truyencotich.top/doc-truyen/bay-giao-chin-quyen-y","title":"Bảy Giao, Chín Quyển ỳ","summary":"Ngày xưa ở làng chợ Cả-sê bây giờ thuộc tỉnh Mỹ-tho có hai anh em ruột: một người tên là Bảy Giao, một người tên là Chín Quỳ. Cha mẹ họ mất sớm chỉ để lại cho vài mẫu ruộng xấu...","cat":"vn"},{"id":"bom-lai-gap-bom-hay-bom-gia-mac-bay-co-ke","url":"https://truyencotich.top/doc-truyen/bom-lai-gap-bom-hay-bom-gia-mac-bay-co-ke","title":"Bợm lại gặp bợm hay bợm già mắc bẫy cò ke","summary":"Ngày ấy, chợ Xuân là một nơi đô hội lớn của trấn Hải-dương. Vào khoảng ngày phiên, khách buôn bán, người qua lại đông nghìn nghịt...","cat":"vn"},{"id":"ba-luoi-riu","url":"https://truyencotich.top/doc-truyen/ba-luoi-riu","title":"Ba lưỡi rìu","summary":"Xưa có một anh chàng tiều phu nghèo, cha mẹ anh bệnh nặng nên qua đời sớm, anh phải sống mồ côi cha mẹ từ nhỏ và tài sản của anh chỉ có một chiếc rìu. Hàng ngày anh phải xách rìu vào rừng để đốn củi bán để lấy tiền kiếm sống qua ngày...","cat":"vn"},{"id":"than-sat","url":"https://truyencotich.top/doc-truyen/than-sat","title":"Thần sắt","summary":"Xưa có anh nông dân một mình sống ở cái lều ven rừng. Anh không có một tấc sắt nên làm ăn rất vất vả. Anh chặt củi bằng đá, đẽo cây bằng gỗ, đào hố tra bắp bằng đầu que. Khổ sở hết chỗ nói, thế mà nghèo vẫn hoàn nghèo...","cat":"vn"},{"id":"con-moi-lam-chung","url":"https://truyencotich.top/doc-truyen/con-moi-lam-chung","title":"Con mối làm chứng","summary":"Ngày xưa có hai vợ chồng một nhà nghèo đói nọ, có một đứa con, chừng mười một, mười hai tuổi nhưng thông minh lanh lợi hơn người. Thiếu ăn, nhà ấy thường phải đâm đầu đi vay nợ. Một năm nọ, trời làm đói kém, hai vợ chồng phải...","cat":"vn"},{"id":"su-tich-bong-hoa-cuc","url":"https://truyencotich.top/doc-truyen/su-tich-bong-hoa-cuc","title":"Sự tích bông hoa cúc","summary":"Ngày xưa, đã lâu lắm rồi, không ai còn nhớ rõ là tự bao giờ. Ở một vùng nọ có hai mẹ con rất nghèo sống với nhau. Người mẹ đau yếu luôn. Mắt bà mờ dần đi, còn tai thì ù không nghe rõ.","cat":"vn"},{"id":"nguoi-lay-ech","url":"https://truyencotich.top/doc-truyen/nguoi-lay-ech","title":"Người lấy Ếch","summary":"Vào đời nhà Lê, có ông bà Trần Cao ngày rằm tháng bảy một năm nọ theo lệ thường mang vàng hương lễ vật tìm đến miếu Long Hải vương để làm lễ cầu phúc...","cat":"vn"},{"id":"hai-co-gai-va-cuc-buou","url":"https://truyencotich.top/doc-truyen/hai-co-gai-va-cuc-buou","title":"Hai cô gái và cục bướu","summary":"Xưa có một cô gái con nhà nghèo khó. Không may cho cô là khi sinh ra đã mang một cục bướu ở mặt. Người càng lớn cục bướu càng to, vì vậy nhan sắc của cô thua em kém chị...","cat":"vn"},{"id":"con-cho-biet-noi","url":"https://truyencotich.top/doc-truyen/con-cho-biet-noi","title":"Con chó biết nói","summary":"Ngày xưa, có một ông già giàu nhất làng. Tiền bạc của ông kiếm được phần nhiều là do những món nợ ăn lời quá vốn, hoặc những âm mưu cướp giật ruộng đất, nhà cửa của dân lành. Càng có nhiều tiền lão càng cay nghiệt...","cat":"vn"},{"id":"su-tich-cay-xuong-rong","url":"https://truyencotich.top/doc-truyen/su-tich-cay-xuong-rong","title":"Sự tích cây Xương rồng","summary":"Cách đây lâu lắm rồi, khi ấy còn chưa có loài người, trái đất còn hoang vu lắm, thấy vậy Ngọc Hoàng bèn lấy một nắm đât và nhỏ vào đó một giọt nước thần để tạo ra một chàng trai. Rồi Ngọc Hoàng dạy cho chàng trai biết săn bắn, biết làm nhà...","cat":"vn"},{"id":"su-tich-hoa-mao-ga","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-mao-ga","title":"Sự tích hoa Mào Gà","summary":"Ngày xưa, chú gà nào cũng có một cái mào đỏ rất đẹp như mào các chú gà trống bây giờ. Một buổi sớm, gà Mơ soi mình trong vũng nước và sung sướng thấy cái mào rực rỡ nằm trên đỉnh đầu của mình như một chùm hoa đỏ rực...","cat":"vn"},{"id":"chu-dong-tu-va-tien-dung","url":"https://truyencotich.top/doc-truyen/chu-dong-tu-va-tien-dung","title":"Chử Đồng Tử và Tiên Dung","summary":"Thời Hùng Vương thứ ba có một người con gái nhan sắc như tiên, đặt tên là Tiên Dung. Tiên Dung rất đẹp, song tự nguyện không lấy chồng, chỉ ham thích phong cảnh, thường đi du lịch khắp nơi trong nước...","cat":"vn"},{"id":"nang-tien-thu-chin","url":"https://truyencotich.top/doc-truyen/nang-tien-thu-chin","title":"Nàng tiên thứ chín","summary":"Ngày xưa, có một bà cụ già có một người con trai lớn, nhưng bà nghèo quá chẳng có tiền để hỏi vợ cho con. Ðêm nào thấy con trai nằm ngủ một mình bên bếp lửa, bà cũng ra đầu sàn ngồi nhìn trời mà khóc...","cat":"vn"},{"id":"ban-toc-dai-ban","url":"https://truyencotich.top/doc-truyen/ban-toc-dai-ban","title":"Bán tóc đãi bạn","summary":"Ngày xưa, có ba người học trò là Tùng, Trúc, Mai, quê ở ba miền khác nhau, tình cờ cùng học với nhau một thầy. Cha mẹ họ đều nghèo túng nhưng vẫn cố gắng cho con đi học...","cat":"vn"},{"id":"chang-mo-coi","url":"https://truyencotich.top/doc-truyen/chang-mo-coi","title":"Chàng mồ côi","summary":"Mồ Côi càng lớn càng làm khoẻ. Không có ruộng vườn, ngày ngày chàng đem sức đổi lấy hai bữa ăn. Thấy chàng cần cù, và có lòng tốt, các bậc già cả, các cô con gái và các em bé đều quý mến...","cat":"vn"},{"id":"su-tich-hoa-mai-vang","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-mai-vang","title":"Sự tích hoa Mai vàng","summary":"Ngày xửa ngày xưa, có một cô bé rất giàu lòng yêu thương. Cô yêu bố mẹ mình, chị mình đã đành, cô còn yêu cả bà con quanh xóm, yêu cả ba ông Táo bằng đá núi đêm ngày chịu khói lửa để nấu cơm, hầm ngô, nướng thịt cho mọi người ăn.","cat":"vn"},{"id":"con-cho-con-meo-va-anh-chang-ngheo-kho","url":"https://truyencotich.top/doc-truyen/con-cho-con-meo-va-anh-chang-ngheo-kho","title":"Con chó, con mèo và anh chàng nghèo khổ","summary":"Ngày xưa có hai mẹ con một anh chàng nhà nghèo rớt mùng tơi. Anh chàng lang thang đi kiếm việc làm nhưng chả có ai thuê cả. Mãi sau có một chủ thuyền buôn thấy anh khỏe mạnh lại biết bơi lội mới thuê làm thủy thủ...","cat":"vn"},{"id":"nguoi-dan-ba-mat-tich","url":"https://truyencotich.top/doc-truyen/nguoi-dan-ba-mat-tich","title":"Người đàn bà mất tích","summary":"Vào đời nhà Lê, có một người đàn bà trẻ tuổi lấy chồng họ Mai. Một hôm nghe tin người chị ruột của mình đau nặng, nàng bèn nói với chồng để mình đi lại chăm sóc thuốc men vì nhà chị rất neo người...","cat":"vn"},{"id":"ba-lon-duoi-uoi","url":"https://truyencotich.top/doc-truyen/ba-lon-duoi-uoi","title":"Bà lớn đười ươi","summary":"Trong vùng rừng núi miền Tuyên Hưng có giống khỉ gọi là dã nữ. Thỉnh thoảng người ta bắt được vài con đem về tập cho nói một vài tiếng người. Họ nuôi chơi làm cảnh, và quen gọi là đười ươi...","cat":"vn"},{"id":"con-ga-va-con-ho","url":"https://truyencotich.top/doc-truyen/con-ga-va-con-ho","title":"Con gà và con hổ","summary":"Thỏ, hổ và gà có lần ở chung với nhau để hợp sức phát nương rẫy. Ngày đầu tiên, thỏ và hổ đi cắt tranh, giao cho gà nhiệm vụ trông nhà và nấu ăn...","cat":"vn"},{"id":"gai-ngoan-day-chong","url":"https://truyencotich.top/doc-truyen/gai-ngoan-day-chong","title":"Gái ngoan dạy chồng","summary":"Ngày xưa có một người nhà giàu, vợ chết sớm, chỉ có độc một người con trai, đứa con vốn người xấu nết, đần độn, lại là tay chơi bời lêu lổng không chịu học hành hay làm ăn gì cả. Thấy con không lo nối nghiệp nhà, người nhà giàu rất buồn phiền...","cat":"vn"},{"id":"goc-tich-ruong-thac-dao-hay-la-truyen-le-phung-hieu","url":"https://truyencotich.top/doc-truyen/goc-tich-ruong-thac-dao-hay-la-truyen-le-phung-hieu","title":"Gốc tích ruộng thác đao hay là truyện Lệ Phụng Hiểu","summary":"Đời Lý, ở vùng Thanh-hóa có Lê Phụng Hiểu. Nhà Hiểu ở gần một hòn núi nhỏ nhô lên ở giữa cánh đồng gọi là núi Bơng (Băng-sơn) nên người ta cũng gọi Hiểu là ông Bơng...","cat":"vn"},{"id":"su-tich-song-nha-be-hay-la-truyen-thu-huon","url":"https://truyencotich.top/doc-truyen/su-tich-song-nha-be-hay-la-truyen-thu-huon","title":"Sự tích sông Nhà Bè hay là truyện Thủ Huồn","summary":"Ngày xưa ở Gia-định có một người tên là Thủ Huồn. Hắn xuất thân làm thơ lại. Trong hơn hai mươi năm luồn lọt trong các nha các ti, hắn đã làm cho bao nhiêu gia đình tan nát, bao nhiêu người bị oan uổng...","cat":"vn"},{"id":"tim-me","url":"https://truyencotich.top/doc-truyen/tim-me","title":"Tìm mẹ","summary":"Ngày xưa, ở một làng nhỏ, có một người mẹ. Người mẹ nuôi hai đứa con. Đứa nhớn là thằng Nhà lên năm. Đứa nhỏ là con Gạo lên ba...","cat":"vn"},{"id":"hai-ong-tien-si","url":"https://truyencotich.top/doc-truyen/hai-ong-tien-si","title":"Hai ông tiến sĩ","summary":"Ngày xưa có chàng học trò nghèo không may mồ côi cha mẹ sớm, gia cảnh khó khăn nhưng chàng chịu khó đèn sách nên sớm nổi tiếng là người đức độ và văn hay chữ tốt...","cat":"vn"},{"id":"su-tich-con-tam","url":"https://truyencotich.top/doc-truyen/su-tich-con-tam","title":"Sự tích con tằm","summary":"Ngày xửa ngày xưa ở một làng nọ có người con gái tên gọi là Tơ, mà cả cha lẫn mẹ của nàng đều mất từ sớm, bởi vậy nàng phải đem thân đi hầu hạ cho một bà góa nhà giàu để có cái ăn nơi ở...","cat":"vn"},{"id":"nguoi-tho-duc","url":"https://truyencotich.top/doc-truyen/nguoi-tho-duc","title":"Người thợ đúc","summary":"Xưa có đức thánh Khổng Lồ, chuyên trông nom về nghề đúc và nghề rèn ở hạ giới. Đức thánh thường thân hành đi lại các nơi; khi giáng xuống miền này, lúc hiện ra xứ nọ, thành người trần, để tìm cách dạy thêm cho những người thợ về kỹ xảo...","cat":"vn"},{"id":"than-giu-cua","url":"https://truyencotich.top/doc-truyen/than-giu-cua","title":"Thần giữ của","summary":"Ngày xưa ở vạn Lai-triều thuộc trấn Sơn-nam có một người lái buôn nước ngoài sang ta sinh cơ lập nghiệp. Sau mấy chục năm nhờ có mánh khóe tích trữ: buôn lúc đầu mùa, bán khi giáp hạt, lãi mẹ đẻ lãi con, hắn trở nên giàu có lớn...","cat":"vn"},{"id":"su-tich-cu-mai","url":"https://truyencotich.top/doc-truyen/su-tich-cu-mai","title":"Sự tích củ mài","summary":"Xưa có một gia đình rất đông con, đông đến nỗi bố mẹ không nhớ hết được tên từng đứa. Người chồng tên Đang, người vợ tên Phang...","cat":"vn"},{"id":"su-tich-con-sam","url":"https://truyencotich.top/doc-truyen/su-tich-con-sam","title":"Sự tích con sam","summary":"Ngày xưa có hai vợ chồng một người đánh cá nghèo. Một hôm người chồng ra khơi với bạn nghề. Không may có một trận bão rất lớn nổi lên giữa lúc họ đang thả lưới. Không một người nào thoát khỏi tai nạn...","cat":"vn"},{"id":"su-tich-dam-muc","url":"https://truyencotich.top/doc-truyen/su-tich-dam-muc","title":"Sự tích đầm mực","summary":"Ngày ấy vào đời nhà Trần có một cụ đồ nho ở xã Quang-liệt tên là Chu An. Học vấn của cụ sâu và rộng. Cũng vì tiếng tăm của cụ truyền khắp mọi nơi nên học trò xa gần đến học rất đông...","cat":"vn"},{"id":"nu-hanh-gianh-bac","url":"https://truyencotich.top/doc-truyen/nu-hanh-gianh-bac","title":"Nữ hành giành bạc","summary":"Ngày xưa có nhà phú hộ có một người con trai mười lăm tuổi cho đi học tại nhà một cụ đồ trong làng. Anh chàng bẩm tính ngu độn lại thích chơi bời lêu lổng, nhét cho mấy, chữ cũng không vào...","cat":"vn"},{"id":"no-tinh-chua-tra-cho-ai-khoi-tinh-mang-xuong-tuyen-dai-chua-tan","url":"https://truyencotich.top/doc-truyen/no-tinh-chua-tra-cho-ai-khoi-tinh-mang-xuong-tuyen-dai-chua-tan","title":"Nợ tình chưa trả cho ai, Khối tình mang xuống tuyền đài chưa tan","summary":"Ngày xưa ở huyện Thanh-trì có một anh chàng học trò nghèo họ Nguyễn. Anh ta mồ côi cha, nhà cửa sa sút. Người mẹ làm nghề chống đò ngang cố nuôi cho con ăn học...","cat":"vn"},{"id":"chiec-cau-phuc-duc","url":"https://truyencotich.top/doc-truyen/chiec-cau-phuc-duc","title":"Chiếc cầu phúc đức","summary":"Ngày xưa có anh chàng chuyên sống về nghề ăn trộm. Trong nhà còn có mẹ già phải nuôi. Tuy có lúc được nhiều, có lúc được ít, nhưng trong nhà không bao giờ có của để dành. Hai mẹ con chàng thường phải chịu bữa ăn, bữa nhịn...","cat":"vn"},{"id":"bat-canh-he","url":"https://truyencotich.top/doc-truyen/bat-canh-he","title":"Bát canh hẹ","summary":"Xưa có một người rất có hiếu, không may mắc tội vu oan, phải giam tù đã lâu, không ai được thăm hỏi...","cat":"vn"},{"id":"khong-lo-duc-chuong-hay-la-su-tich-trau-vang-ho-tay","url":"https://truyencotich.top/doc-truyen/khong-lo-duc-chuong-hay-la-su-tich-trau-vang-ho-tay","title":"Khổng Lồ đúc chuông hay là sự tích trâu vàng Hồ Tây","summary":"Vào đời nhà Lý có một người gọi là Khổng Lồ. Nhìn thấy thân thể ông, các tay lực sĩ trong triều ngoài quận đều khiếp sợ, mặc dầu ông chưa từng đọ sức với ai. Từ trẻ Khổng Lồ đã đi tu, ông thường đi chu du thiên hạ...","cat":"vn"},{"id":"con-sao-va-phu-truong-gia","url":"https://truyencotich.top/doc-truyen/con-sao-va-phu-truong-gia","title":"Con sáo và phú trưởng giả","summary":"Ngày xưa có một con sáo nói được tiếng người và hiểu được ý người. Từ lâu, sáo làm bạn với một bác nông dân rất nghèo. Hôm ấy, bác đi cày bắt được sáo ta bị thương nằm nép trong bụi lúa, bèn đưa về chăm sóc...","cat":"vn"},{"id":"su-tich-cay-thi-la","url":"https://truyencotich.top/doc-truyen/su-tich-cay-thi-la","title":"Sự tích cây Thì Là","summary":"Ngày xưa, xưa lắm rồi, cây cỏ chưa có tên chi cả. Một hôm, ông Trời tập hợp tất cả các loài lại, ban cho mỗi loài một cái tên...","cat":"vn"},{"id":"su-tich-den-keo-quan","url":"https://truyencotich.top/doc-truyen/su-tich-den-keo-quan","title":"Sự tích đèn kéo quân","summary":"Ngày xưa, gần đến dịp tết Trung thu, theo lệnh Vua, dân chúng nô nức thi nhau chế ra những chiếc đèn kỳ lạ… nhưng không có chiếc đèn nào làm cho vua vừa ý...","cat":"vn"},{"id":"nguoi-con-hieu-thao","url":"https://truyencotich.top/doc-truyen/nguoi-con-hieu-thao","title":"Người con hiếu thảo","summary":"Ngày xưa trong một gia đình nọ có ba anh em trai, hai người anh thì lười biếng ích kỷ, tham lam ngược lại người con út vừa siêng năng, vừa thật thà hiếu thảo...","cat":"vn"},{"id":"con-tho-va-con-ho","url":"https://truyencotich.top/doc-truyen/con-tho-va-con-ho","title":"Con thỏ và con hổ","summary":"Hổ bị thỏ chơi một mẻ mất mặt, thề từ nay không đội trời chung với thỏ. Một hôm, hổ đi chơi gặp thỏ đang trèo cây ăn mật ong. Hổ đứng đón dưới gốc, trừng mắt bảo thỏ: - Mày đừng có hòng chạy nữa nhé!","cat":"vn"},{"id":"muu-con-tho","url":"https://truyencotich.top/doc-truyen/muu-con-tho","title":"Mưu con thỏ","summary":"Ngày ấy trên rừng không có miếng gì ăn, một chú thỏ mò xuống một ruộng khoai bới trộm. Ngờ đâu chủ ruộng đã nấp sẵn ở túp lều bên cạnh, ập đến tóm ngay lấy thỏ. Thỏ ta giả bộ chết nằm sóng soài...","cat":"vn"},{"id":"ong-nam-cuong","url":"https://truyencotich.top/doc-truyen/ong-nam-cuong","title":"Ông Nam Cường","summary":"Vào thời ấy chẳng rõ là thời nào, ở làng Quần-anh có một người phù thuỷ có nhiều phép thuật lạ lùng. Thường mỗi lần nằm ngủ, ông ngủ liền ba ngày ba đêm, tiếng ngáy như sấm....","cat":"vn"},{"id":"hau-tao","url":"https://truyencotich.top/doc-truyen/hau-tao","title":"Hầu Tạo","summary":"Ở làng Tuần-lễ thuộc xứ Nghệ có một anh chàng tên là Tạo. Tạo sinh ra có một nốt đỏ trong vành tai, người ta cho là có tướng lạ. Chàng chẳng những có sức khỏe như voi mà còn có mưu lược hơn người...","cat":"vn"},{"id":"co-bu","url":"https://truyencotich.top/doc-truyen/co-bu","title":"Cố Bu","summary":"Ngày xưa ở làng Phan-xá thuộc Hà-tĩnh - một làng ngay sát nách con sông mà nước thuỷ triều vẫn lên xuống đều đều - có một người nghèo tên là Bu...","cat":"vn"},{"id":"le-loi","url":"https://truyencotich.top/doc-truyen/le-loi","title":"Lê Lợi","summary":"Hồi ấy, giặc Minh sang xâm chiếm nước ta, đối đãi với dân ta vô cùng tàn ác. Không một ai là không nghiến răng chau mày. Bấy giờ có Lê Lợi nổi quân đánh bại lại chúng...","cat":"vn"},{"id":"su-tich-nui-ba-den","url":"https://truyencotich.top/doc-truyen/su-tich-nui-ba-den","title":"Sự tích núi Bà Đen","summary":"Theo dân gian kể lại rằng, bà Đen tên thật là Lý Thị Thiên Hương, con của ông Lý Thiện – vị quan trấn nhậm Trảng Bàng triều Nguyễn và bà Đặng Ngọc Phụng – một người gốc Bình Định...","cat":"vn"},{"id":"le-van-khoi","url":"https://truyencotich.top/doc-truyen/le-van-khoi","title":"Lê Văn Khôi","summary":"Ngày xưa vào triều Minh Mạng, có một chàng trai nhà nghèo nhưng có sức khỏe tuyệt trần. Anh chàng thường chống đò ngang ở bến đò Thiên Tả kiếm ăn. Lúc mới sinh, anh có ba cái nốt đỏ ở bụng, ai nấy đều bảo là tướng rất quý...","cat":"vn"},{"id":"ba-vanh","url":"https://truyencotich.top/doc-truyen/ba-vanh","title":"Ba Vành","summary":"Ngày xưa, ở làng Minh Giám có một chàng trai nổi tiếng khỏe mạnh. Lúc mới sinh có nhiều tướng lạ: tay dài quá gối, răng liền một hàng, trên trán có ba đường chỉ ngang.Vì thế lớn lên, người ta quen gọi chàng là Ba Vành...","cat":"vn"},{"id":"hai-nang-cong-chua-nha-tran","url":"https://truyencotich.top/doc-truyen/hai-nang-cong-chua-nha-tran","title":"Hai nàng công chúa nhà Trần","summary":"Vào thời nhà Trần có một ông vua sinh được năm nàng công chúa, trong đó có hai nàng xinh đẹp: một người tên là Bảo Nương, một người tên là Ngọc Nương. Năm hai nàng đến tuổi lấy chồng...","cat":"vn"},{"id":"vo-ba-cai-vang","url":"https://truyencotich.top/doc-truyen/vo-ba-cai-vang","title":"Vợ ba Cai Vàng","summary":"Ngày xưa ở tổng Hoàng-vân có một viên cai tổng, người ta thường gọi là Cai Vàng. Thưở trẻ ông ta bắt được một viên ngọc kỵ đạn, đeo vào người có phép làm cho những mũi tên hòn đạn sắp đụng vào da thịt phải rẽ đi lối khác...","cat":"vn"},{"id":"nguoi-day-to-va-nguoi-an-trom","url":"https://truyencotich.top/doc-truyen/nguoi-day-to-va-nguoi-an-trom","title":"Người đầy tớ và người ăn trộm","summary":"Ngày xưa có hai anh chàng cùng yêu một cô gái và cùng một lúc đến dạm nàng làm vợ. Trong khi cô gái đang phân vân chưa biết nên lấy người nào thì hai người đàn ông...","cat":"vn"},{"id":"nong-dan-voi-thanh-hoang","url":"https://truyencotich.top/doc-truyen/nong-dan-voi-thanh-hoang","title":"Nông dân với thành hoàng","summary":"Ngày đó ở miếu Thành hoàng có hội hương khói, ai nấy cố biện lễ vật để cầu thần phù hộ. Thành hoàng sai một chú tiểu quỷ đi thám thính xem ai cúng nhiều cúng ít...","cat":"vn"},{"id":"hoa-thuong-va-nguoi-tho-giay","url":"https://truyencotich.top/doc-truyen/hoa-thuong-va-nguoi-tho-giay","title":"Hòa thượng và người thợ giày","summary":"Có một nhà sư tên là Diệu Kế trụ trì ở một ngôi chùa lớn làng Bích-khê. Sư ta vốn ít chữ nhưng được cái sáng dạ, trải qua những ngày cạo đầu cắp níp đi theo các bậc tu hành cũng võ vẽ được ít nhiều kinh kệ...","cat":"vn"},{"id":"nguoi-dan-ba-bi-vu-oan","url":"https://truyencotich.top/doc-truyen/nguoi-dan-ba-bi-vu-oan","title":"Người đàn bà bị vu oan","summary":"Ngày xưa, có hai người lái buôn tơ lụa, một người tên là Lý, một người tên là Tình. Tuy quê ở hai nơi nhưng họ thường đến bán hàng và thường gặp nhau ở một thị trấn nọ...","cat":"vn"},{"id":"ru-nhau-di-kiem-mat-ong","url":"https://truyencotich.top/doc-truyen/ru-nhau-di-kiem-mat-ong","title":"Rủ nhau đi kiếm mật ong","summary":"Có hai anh tên là Bự và Ngốc đều không ai chịu kém ai về mặt ngu đần. Nhưng Bự vẫn thường cho mình là khôn hơn Ngốc...","cat":"vn"},{"id":"soi-bac-tim-ra-thu-pham","url":"https://truyencotich.top/doc-truyen/soi-bac-tim-ra-thu-pham","title":"Sợi bấc tìm ra thủ phạm","summary":"Ngày xưa có một tay phú thương tên là Phong. Hắn ta có mười chiếc mành lớn chở hàng hóa bán khắp trong Nam ngoài Bắc...","cat":"vn"},{"id":"nang-bianat-truyen-co-dan-toc-nguoi-bana","url":"https://truyencotich.top/doc-truyen/nang-bianat-truyen-co-dan-toc-nguoi-bana","title":"Nàng Bianat (Truyện cổ dân tộc người BaNa)","summary":"Ngày xưa, có gia đình ông bà Hơ Rô sinh được tám con gái. Tám cô đều xinh cả, nhưng đẹp nhất và tốt nhất là Bia Nát, cô gái út...","cat":"vn"},{"id":"vi-sao-nguoi-song-khong-con-tham-nguoi-chet-duoc-nua-truyen-co-dan-toc-bru","url":"https://truyencotich.top/doc-truyen/vi-sao-nguoi-song-khong-con-tham-nguoi-chet-duoc-nua-truyen-co-dan-toc-bru","title":"Vì sao người sống không còn thăm người chết được nữa ? (Truyện cổ dân tộc Bru)","summary":"Ngày xưa có hai anh em mồ côi đều chết vợ. Người em phát rẫy cạnh bên mộ vợ và thường bị lợn rừng đến phá...","cat":"vn"},{"id":"chang-don-cui-va-con-tinh","url":"https://truyencotich.top/doc-truyen/chang-don-cui-va-con-tinh","title":"Chàng đốn củi và con tinh","summary":"Ngày xưa có một anh chàng nghèo khó, sống một thân một mình. Tuy làm việc tất lực nhưng đói rách vẫn hoàn đói rách...","cat":"vn"},{"id":"phan-xu-tai-tinh","url":"https://truyencotich.top/doc-truyen/phan-xu-tai-tinh","title":"Phân xử tài tình","summary":"Ngày xưa, có một ông quan huyện có tài xét xử. Trong dân gian có vụ nào rắc rối gay go nhất, ông đều có cách tìm ra manh mối và phân xử công bằng...","cat":"vn"},{"id":"su-tich-chim-cu-gay","url":"https://truyencotich.top/doc-truyen/su-tich-chim-cu-gay","title":"Sự tích chim Cu Gáy","summary":"Ngày xưa, ở một nơi rất xa về phía bắc, nơi đó lúc nào trời cũng lạnh và tuyết phủ mặt đất gần như suốt năm, có một người đàn bà nghèo khổ sống ở đó...","cat":"vn"},{"id":"nha-su-mat-tai","url":"https://truyencotich.top/doc-truyen/nha-su-mat-tai","title":"Nhà sư mất tai","summary":"Vào một thời xa xưa của xứ Phù Tang tam đảo, các sứ quân tranh quyền, giành ảnh hưởng, khu vực… rất là gây cấn. Nơi một đảo nọ có hai vị sứ quân Lang và Hân tranh chấp với nhau từ mấy mươi năm qua, hao binh tổn tướng rất nhiều...","cat":"vn"},{"id":"cai-chet-cua-bon-ong-su","url":"https://truyencotich.top/doc-truyen/cai-chet-cua-bon-ong-su","title":"Cái chết của bốn ông sư","summary":"Xưa có một người làm nghề kiếm mật ong và sáp nuôi thân. Hàng ngày ông ta đeo trên lưng một chiếc gùi, tay cầm cán có buộc bùi nhùi và giẻ đi vào rừng tìm tổ ong...","cat":"vn"},{"id":"tinh-con-chuot","url":"https://truyencotich.top/doc-truyen/tinh-con-chuot","title":"Tinh con chuột","summary":"Ngày xưa có một anh học trò, con một nhà phú hộ, được nuông chiều và chăm chút rất mực. Năm hai mươi tuổi, cha mẹ lấy vợ cho. Vợ chàng là một người có nhan sắc lại đoan chính...","cat":"vn"},{"id":"su-tich-tho-tai-dai-duoi-ngan","url":"https://truyencotich.top/doc-truyen/su-tich-tho-tai-dai-duoi-ngan","title":"Sự tích thỏ tai dài đuôi ngắn","summary":"Trong một khu rừng nọ, có một con cọp dữ và một con heo rừng hung hãn. Cọp và heo, con thì cậy có móng vuốt sắc, con thì cậy có bộ nanh dài, bắt nạt tất cả mọi loài...","cat":"vn"},{"id":"vu-kien-chau-chau","url":"https://truyencotich.top/doc-truyen/vu-kien-chau-chau","title":"Vụ kiện châu chấu","summary":"Ngày ấy có một con châu chấu mải mê kiếm ăn lạc mất đường về. Tối đến, trời rét lại mưa rơi rả rích, làm cho châu chấu ta run rẩy...","cat":"vn"},{"id":"su-tich-cau-noi-troi-danh-tranh-mieng-an","url":"https://truyencotich.top/doc-truyen/su-tich-cau-noi-troi-danh-tranh-mieng-an","title":"Sự tích câu nói Trời đánh tránh miếng ăn","summary":"Người xưa kể lại, trong một gia đình có 3 người gồm bố mẹ đi làm ruộng và đứa con gái nhỏ ở nhà chuyên lo việc bếp núc. Như thường lệ, khi hai vợ chồng này đi làm, cô bé nấu cơm...","cat":"vn"},{"id":"su-tich-ngu-hanh-son-da-nang","url":"https://truyencotich.top/doc-truyen/su-tich-ngu-hanh-son-da-nang","title":"Sự tích Ngũ Hành Sơn Đà Nẵng","summary":"Ngày xưa, có một ông cụ già sống một thân một mình trong một túp lều còn trên bãi biển vắng. Những người dân gần đó không biết ông cụ đến đấy làm gì và đến từ lúc nào...","cat":"vn"},{"id":"su-tich-ong-binh-voi","url":"https://truyencotich.top/doc-truyen/su-tich-ong-binh-voi","title":"Sự tích ông bình vôi","summary":"Ngày xưa, có một người con gái con một nhà giàu có. Cô rất đẹp nhưng cũng rất kiêu. Cô đã từng làm cho các bạn gái xa lánh mình. Cô làm cho các chàng trai ghét cô vô hạn...","cat":"vn"},{"id":"su-tich-da-ba-rau","url":"https://truyencotich.top/doc-truyen/su-tich-da-ba-rau","title":"Sự tích đá Bà rầu","summary":"Ngày xưa, có gia đình một người thuyền chài có một cô gái rất xinh tươi. Khi cô đã lớn, nhiều chàng trai muốn xin kết duyên với nàng, nhưng chưa có đám nào thành cả...","cat":"vn"},{"id":"su-tich-chim-ken-ken","url":"https://truyencotich.top/doc-truyen/su-tich-chim-ken-ken","title":"Sự tích chim kền kền","summary":"Trong xóm kia có hai người sống hai cảnh đời trái ngược. Một người giàu của để tận ngoài ngõ, chê cơm gạo đỏ không ăn, trong nhà thịt rượu ê hề. Lại có một người tàn tật, ít khi được bát cơm nóng...","cat":"vn"},{"id":"su-tich-hoa-ban-trang","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-ban-trang","title":"Sự tích hoa ban trắng","summary":"Thuở ấy, có một chàng trai tên là Khum đem lòng yêu cô gái tên là Ban. Khum vừa giỏi làm nương, lại có tài săn bắn...","cat":"vn"},{"id":"su-tich-dinh-lang-da-hoa","url":"https://truyencotich.top/doc-truyen/su-tich-dinh-lang-da-hoa","title":"Sự tích đình làng Đa Hòa","summary":"Ngày xưa ở làng Đa-hòa có một ông thầy phù thủy cao tay, tên là Dọng. Không những ông có nhiều phép lạ mà còn có lòng thương người...","cat":"vn"},{"id":"tu-dao-hanh-hay-la-su-tich-thanh-lang","url":"https://truyencotich.top/doc-truyen/tu-dao-hanh-hay-la-su-tich-thanh-lang","title":"Từ Đạo Hạnh hay là sự tích Thánh Láng","summary":"Vào thời Lý có một ông sư quê ở làng Láng gần kinh đô, tên là Từ Vinh. Từ Vinh học được phép tàng hình. Không những thế, hắn còn biết cả phép biến mình thành bất cứ con vật gì hay bất cứ một người nào khác...","cat":"vn"},{"id":"lay-chong-de","url":"https://truyencotich.top/doc-truyen/lay-chong-de","title":"Lấy chồng dê","summary":"Ngày xưa, ở một vùng gần biển, có hai vợ chồng nhà nọ, đầu tóc đã hoa râm mà vẫn hiếm hoi. Hai vợ chồng cầu khấn khắp nơi mong có mụn con khỏi phải hiu quạnh lúc tuổi già...","cat":"vn"},{"id":"thay-cuu-tro","url":"https://truyencotich.top/doc-truyen/thay-cuu-tro","title":"Thầy cứu trò","summary":"Ngày xưa có một anh học trò côi cút hiền lành. Nghe tin ở một tỉnh Đàng ngoài có một ông thầy nổi tiếng tài cao học rộng...","cat":"vn"},{"id":"co-gai-lua-thay-sai-xa-truong-va-ong-quan-huyen","url":"https://truyencotich.top/doc-truyen/co-gai-lua-thay-sai-xa-truong-va-ong-quan-huyen","title":"Cô gái lừa thày sãi, xã trưởng và ông quan huyện","summary":"Ở một huyện nọ có một chị góa chồng mặt mày sáng sủa dễ coi, lại khôn ngoan lanh lợi. Thấy có đóa hoa xinh dễ vin dễ hái, nhiều anh chàng thường ngấp nghé...","cat":"vn"},{"id":"ngam-ngai-tim-tram-hay-la-su-tich-nui-mau-tu","url":"https://truyencotich.top/doc-truyen/ngam-ngai-tim-tram-hay-la-su-tich-nui-mau-tu","title":"Ngậm ngải tìm trầm hay là sự tích núi Mẫu tử","summary":"Ngày xưa, trên một vùng núi cao tại một tỉnh Đàng trong, có hai vợ chồng nhà nọ đến sinh cơ lập nghiệp. Họ cũng trồng lúa bắp, chăn nuôi gà lợn và săn chim bắt thỏ như mọi nhà khác...","cat":"vn"},{"id":"cai-vet-do-tren-ma-cong-nuong","url":"https://truyencotich.top/doc-truyen/cai-vet-do-tren-ma-cong-nuong","title":"Cái vết đỏ trên má công nương","summary":"Ngày ấy có một ông thượng thư đầu triều nổi tiếng là người nghiêm khắc và hách dịch. Ông có tính nóng như lửa. Đã thế ông lại có quyền &quot;tiền trảm hậu tấu&quot; nên không khỏi giết oan một số người vô tội...","cat":"vn"},{"id":"cuong-bao-dai-vuong","url":"https://truyencotich.top/doc-truyen/cuong-bao-dai-vuong","title":"Cường Bạo đại vương","summary":"Ngày xửa ngày xưa, có một chàng trẻ tuổi làm nghề mò tôm bắt cá tại vùng sông Bồi. Tuy quanh năm chỉ che thân một mảnh khố rách, chui rúc trong một túp lều ven sông, nhưng anh vẫn vui vẻ làm ăn, miệng luôn ca hát...","cat":"vn"},{"id":"chuyen-chang-lut","url":"https://truyencotich.top/doc-truyen/chuyen-chang-lut","title":"Chuyện chàng Lút","summary":"Ở làng nọ có anh chàng Lút bị hủi ăn từ đầu đến chân. Trông người xấu xí, hom hem như sắp chết đến nơi rồi...","cat":"vn"},{"id":"sinh-con-roi-moi-sinh-cha-sinh-chau-giu-nha-roi-moi-sinh-ong","url":"https://truyencotich.top/doc-truyen/sinh-con-roi-moi-sinh-cha-sinh-chau-giu-nha-roi-moi-sinh-ong","title":"Sinh con rồi mới sinh cha, sinh cháu giữ nhà rồi mới sinh ông","summary":"Ngày xưa có Giáp và Ất là hai người kết bạn với nhau. Nhà Giáp có của ăn của để, còn Ất thì túng bấn lắm, thường phải nhờ vả Giáp...","cat":"vn"},{"id":"lam-on-hoa-hai","url":"https://truyencotich.top/doc-truyen/lam-on-hoa-hai","title":"Làm ơn hóa hại","summary":"Xưa có Trần Công là người có lòng sốt sắng. Ai có việc gì nhờ vả, ông đều sẵn sàng. Trong đời ông, ông đã từng đi lại nhiều nơi, đến đâu cũng hết lòng giúp đỡ người nguy kẻ khó mà không quản ngại...","cat":"vn"},{"id":"huyen-quang","url":"https://truyencotich.top/doc-truyen/huyen-quang","title":"Huyền Quang","summary":"Vào thời nhà Trần có một người học trò trẻ tuổi ở xứ Bắc tên là Huyền Quang. Nhà chàng không đất cắm dùi nhưng cha mẹ chàng thì cố công cố sức làm thuê làm mướn các nơi để nuôi con ăn học...","cat":"vn"},{"id":"con-ma-bao-thu","url":"https://truyencotich.top/doc-truyen/con-ma-bao-thu","title":"Con ma báo thù","summary":"Ngày xưa ở Gia-định có một tên cướp lợi hại bị bắt và kết án tử hình. Trong ngục, hắn ta bảo người nhà đem hậu lễ đến chạy chọt với tên quan án để mong quan cố tìm cách cứu hắn thoát chết...","cat":"vn"},{"id":"ran-bao-oan","url":"https://truyencotich.top/doc-truyen/ran-bao-oan","title":"Rắn báo oán","summary":"Ngày ấy, trong một gò đất cây cối mọc um tùm ở làng Nhị Khê gọi là gò Rùa, có một con rắn mẹ sống với một đàn con...","cat":"vn"},{"id":"su-tich-chim-tu-hu","url":"https://truyencotich.top/doc-truyen/su-tich-chim-tu-hu","title":"Sự tích chim tu hú","summary":"Ngày xưa có hai nhà sư Năng Nhẫn và Bất Nhẫn. Hai người cùng cạo đầu xuất gia từ ngày còn trẻ và cùng tu ở một ngôi chùa hẻo lánh...","cat":"vn"},{"id":"nguoi-hoc-tro-va-con-ho","url":"https://truyencotich.top/doc-truyen/nguoi-hoc-tro-va-con-ho","title":"Người học trò và con hổ","summary":"Một con hổ đi dạo trong rừng, vô tình bị lọt vào bẫy. Con vật hung hăng giãy giụa, hết húc đầu đến dùng răng gặm bẫy tìm cách chui ra, nhưng bẫy làm bằng những cây tre đực rất chắc nên không thể làm gì được...","cat":"vn"},{"id":"su-tich-den-con","url":"https://truyencotich.top/doc-truyen/su-tich-den-con","title":"Sự tích đền Cờn","summary":"Ngày xưa có một ông vua một nước láng giềng tên là Đế Bính. Vua lên ngôi giữa lúc nước nhà có giặc ngoài đột nhập bờ cõi. Quân giặc rất đông và rất mạnh. Quân đội nhà vua chống chọi không nổi đành chịu thất bại...","cat":"vn"},{"id":"nguoi-hoc-tro-ngheo-va-ngoc-hoang","url":"https://truyencotich.top/doc-truyen/nguoi-hoc-tro-ngheo-va-ngoc-hoang","title":"Người học trò nghèo và Ngọc hoàng","summary":"Ngày xưa, có một nhà kia trải đã mấy đời sống trong cảnh khố rách áo ôm. Đến đời người cháu nội là một anh học trò không đất cắm dùi...","cat":"vn"},{"id":"tam-va-tu","url":"https://truyencotich.top/doc-truyen/tam-va-tu","title":"Tam và Tứ","summary":"Ngày xưa có một người làm nghề bưng trống tên là Tam. Mỗi lần làm xong một số hàng có đủ trống con trống lớn, ông thường mang đi các vùng lân cận để bán...","cat":"vn"},{"id":"hai-bay-muoi-ba","url":"https://truyencotich.top/doc-truyen/hai-bay-muoi-ba","title":"Hai bảy mười ba","summary":"Ngày xưa, ở huyện Hà-đông thuộc tỉnh Quảng có hai vợ chồng nhà nọ, chồng quen thói lấn lướt vợ, nhưng vợ cũng không phải tay vừa...","cat":"vn"},{"id":"quan-tu","url":"https://truyencotich.top/doc-truyen/quan-tu","title":"Quân tử","summary":"Ngày xưa, có một anh chàng nghèo sống một thân một mình. Anh thường ăn ở nhân đức với mọi người, lòng nhân đức của anh còn ban phát đến cả giống vật...","cat":"vn"},{"id":"cho-than","url":"https://truyencotich.top/doc-truyen/cho-than","title":"Chó thần","summary":"Ngày xưa, ở một phủ nọ miền thượng du, có vị lão quan họ Lê được dân chúng kính yêu như cha già, vì trong bao nhiêu năm cai trị vùng này, cụ đối xử với dân như con cháu trong nhà...","cat":"vn"},{"id":"my-chau-trong-thuy-hay-la-truyen-no-than","url":"https://truyencotich.top/doc-truyen/my-chau-trong-thuy-hay-la-truyen-no-than","title":"Mỵ Châu - Trọng Thủy hay là truyện nỏ thần","summary":"Ngày xưa trị vì cõi đất Âu-lạc có một ông vua tên là An Dương Vương. Vua có một nàng công chúa tên là Mỵ Châu. Mỵ Châu rất xinh đẹp và ngày ấy đã đến tuổi yêu đương...","cat":"vn"},{"id":"hai-con-co-va-con-rua","url":"https://truyencotich.top/doc-truyen/hai-con-co-va-con-rua","title":"Hai con cò và con rùa","summary":"Ngày trước, có một người đàn bà rất mực kiêu căng và chua ngoa. Hễ giận người nào hay gặp việc gì trái ý là bà ta nói cạnh nói khóe chửi bới không tiếc lời, cố gào đến tận tam đại người ta cho được mới nghe...","cat":"vn"},{"id":"su-tich-hoa-co-may","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-co-may","title":"Sự tích hoa Cỏ May","summary":"Ngày xửa ngày xưa, tại một ngôi làng nọ có đôi trai gái yêu nhau rất thắm thiết. Nàng xinh đẹp, là con gái của một gia đình giàu có, một tiểu thư khuê các, còn chàng chỉ là anh đốn củi nghèo, mồ côi...","cat":"vn"},{"id":"su-tich-cay-khoai-lang","url":"https://truyencotich.top/doc-truyen/su-tich-cay-khoai-lang","title":"Sự tích cây khoai lang","summary":"Ở bìa rừng, có hai bà cháu nghèo khổ sinh sống. Hằng ngày, hai bà cháu phải đi đào củ mài để ăn...","cat":"vn"},{"id":"su-tich-chim-go-song","url":"https://truyencotich.top/doc-truyen/su-tich-chim-go-song","title":"Sự tích chim gò sóng","summary":"Các già làng thường chỉ tay ra con suối trước nhà chảy từ rừng sâu đổ về thung lũng uốn lượn quanh bản trông giống như một con rắn lớn, để bắt đầu câu chuyện về con nước hiền, con nước dữ...","cat":"vn"},{"id":"hai-anh-em-va-con-cho-da","url":"https://truyencotich.top/doc-truyen/hai-anh-em-va-con-cho-da","title":"Hai anh em và con chó đá","summary":"Ngày xưa có hai anh em ruột, người nào cũng đã có vợ và ở riêng. Vợ chồng người anh thóc bồ rạ đụn, có của ăn của để, nhưng keo cú thì không ai bằng...","cat":"vn"},{"id":"chiec-hu-than-ky","url":"https://truyencotich.top/doc-truyen/chiec-hu-than-ky","title":"Chiếc hũ thần kỳ","summary":"Ngày xưa có hai anh em nhà kia, người anh nhờ buôn bán nên giàu có, em làm nghề đốn củi nên chỉ đắp đủ qua ngày...","cat":"vn"},{"id":"su-tich-thac-cam-vang","url":"https://truyencotich.top/doc-truyen/su-tich-thac-cam-vang","title":"Sự tích thác Cam Vàng","summary":"Ngày xửa ngày xưa, cạnh thác nước Cam Vàng, có hai ông bà lão nọ sinh sống bằng nghề trồng trọt. Hai người đã già mà vẫn không có con cái nên cuộc sống rất khổ cực, buồn tẻ...","cat":"vn"},{"id":"su-tich-cay-ngo","url":"https://truyencotich.top/doc-truyen/su-tich-cay-ngo","title":"Sự tích cây Ngô","summary":"Khi đã gần 70 tuổi, Phùng Khắc Khoan vẫn được tin tưởng cử đi sứ nhà Minh để xin cầu phong cho vua Lê Thế Tông. Trên đường đi sứ, ông luôn tìm hiểu cách làm ăn của người dân ở mỗi địa phương đi qua, nhằm giúp cho dân mình khi trở về nước...","cat":"vn"},{"id":"bay-canh-hoa-vang","url":"https://truyencotich.top/doc-truyen/bay-canh-hoa-vang","title":"Bảy cánh hoa vàng","summary":"Chiếc tủ của những phép màu trên tiên giới bấy lâu nay vẫn còn khóa kín. Bao nhiêu mây trắng đã trôi qua, rồi biết bao nhiêu mây xanh, mây hồng, mây cam, mây tím...","cat":"vn"},{"id":"nguoi-con-gai-than-ran","url":"https://truyencotich.top/doc-truyen/nguoi-con-gai-than-ran","title":"Người con gái Thần Rắn","summary":"Về phía Nam suối Ngọc có cái miếu cổ, hư sập rồi không ai chữa lại. Dựa bên miếu có cây đào to lớn, cành lá um tùm. Trong miếu có hang, hang sâu thăm thẳm. Dưới hang có một con rắn to lớn không biết ngần nào...","cat":"vn"},{"id":"chiec-hu-than-dieu","url":"https://truyencotich.top/doc-truyen/chiec-hu-than-dieu","title":"Chiếc hũ thần diệu","summary":"Ngày xưa có hai anh em nhà kia, người anh nhờ buôn bán nên giàu có, em làm nghề đốn củi nên chỉ đắp đủ qua ngày. Tết đến, người em túng thiếu không tiền làm cỗ cúng ông bà...","cat":"vn"},{"id":"su-tich-bao-li-xi-ngay-tet","url":"https://truyencotich.top/doc-truyen/su-tich-bao-li-xi-ngay-tet","title":"Sự tích bao lì xì ngày tết","summary":"Theo truyền thuyết, có một con yêu quái đáng sợ tên là “Sui.” Hàng năm vào đêm giao thừa, nó sẽ đến chạm vào đầu trẻ em đang ngủ ba lần. Sợ quá, em bé sẽ khóc lớn và sau đó sẽ bị đau đầu, bị sốt, và nói nhảm...","cat":"vn"},{"id":"ba-co-tien","url":"https://truyencotich.top/doc-truyen/ba-co-tien","title":"Ba cô tiên","summary":"Ngày xửa ngày xưa, có một chú bé mặc dầu tuổi đã lên sáu nhưng chú vẫn bé tí ti, chú chỉ bé vỏn vẹn bằng ngón tay cái của mọi người. Chính vì vậy ai cũng gọi chú bé là chú bé tí hon...","cat":"vn"},{"id":"su-tich-chiec-ken-moi","url":"https://truyencotich.top/doc-truyen/su-tich-chiec-ken-moi","title":"Sự tích chiếc kèn môi","summary":"Trên ngọn núi cao nọ, có một cái hang lớn. Trong hang có một con quỷ dữ. Ngày nào con quỷ cũng thịt bò thịt ngựa lấy máu làm rượu uống, lấy thịt làm thức nhắm...","cat":"vn"},{"id":"chang-na-a","url":"https://truyencotich.top/doc-truyen/chang-na-a","title":"Chàng Na Á","summary":"Ngày xưa có một chàng trai tên là Na Á. Anh mồ côi cha từ sớm, ở với mẹ già. Nhà Na Á nghèo, anh phải làm nghề đánh cá để nuôi thân, nuôi mẹ. Anh thẳng tính, không kiêng nể một ai, cũng chẳng sợ trời phật...","cat":"vn"},{"id":"than-tru-troi","url":"https://truyencotich.top/doc-truyen/than-tru-troi","title":"Thần trụ trời","summary":"Thuở ấy, chưa có muôn vật và loài người. Trời đất chỉ là một vùng hỗn độn, tối tăm. Bỗng xuất hiện một vị thần khổng lồ, cao lớn vô cùng, chân dài không sao tả xiết. Mỗi bước thần đi là băng từ vùng này qua vùng khác, vượt từ núi nọ sang núi kia...","cat":"vn"},{"id":"su-tich-nghe-moc","url":"https://truyencotich.top/doc-truyen/su-tich-nghe-moc","title":"Sự tích nghề mộc","summary":"Sau khi đã sáng tạo ra loài người, lại thấy loài người phải sống chui rúc trong các hang đá tối tăm lạnh lẽo. Ngọc Hoàng thương tình bèn sai một vị thần bày cho loài người cách làm nhà cửa và các vật dụng sinh hoạt...","cat":"vn"},{"id":"ba-khong-on","url":"https://truyencotich.top/doc-truyen/ba-khong-on","title":"Bà Khổng Ôn","summary":"Thời bà Khổng Ôn sống là thời kỳ đất nước mới thanh bình, đất còn thấp, nước chiếm phần nhiều. Nước thường xuyên cậy thế mạnh gây ra những trận lũ lụt hòng dìm đất xuống...","cat":"vn"},{"id":"su-tich-ba-chua-vinh","url":"https://truyencotich.top/doc-truyen/su-tich-ba-chua-vinh","title":"Sự tích bà chúa Vĩnh","summary":"Tục truyền rằng, bà chúa Vĩnh chính là con gái của bà Tồ Cô. Khi các chị em cùng một bọc đã chia nhau đi mỗi người một nơi, riêng bà chúa Vĩnh thương mẹ hơn cả nên vẫn quanh quẩn ở lại vùng Phật Tích cho gần gũi mẹ...","cat":"vn"},{"id":"su-tich-ba-choa","url":"https://truyencotich.top/doc-truyen/su-tich-ba-choa","title":"Sự tích bà Chóa","summary":"Những người con gái của bà Tổ Cô sau khi rời bọc mẹ đẻ, họ bảo nhau đi thật xa. Cứ đi, cứ đi, đâu chẳng là Đất Mẹ. Dù cách bao nhiêu đường đất mà biết làm đúng lời mẹ dạy thì vẫn gần với mẹ...","cat":"vn"},{"id":"su-tich-hung-hai-tri-nuoc","url":"https://truyencotich.top/doc-truyen/su-tich-hung-hai-tri-nuoc","title":"Sự tích Hùng Hải trị nước","summary":"Lạc Long Quân xuống biển, giao lại nước cho con trai cả là Hùng Quốc Vương. Hùng Vương thấy các sông ngòi năm nào cũng dâng nước to làm hại dân làng, mới sai thủy bộ chia nhau giữ gìn các thác ghềnh...","cat":"vn"},{"id":"chuyen-to-tien-mo-nuoc","url":"https://truyencotich.top/doc-truyen/chuyen-to-tien-mo-nuoc","title":"Chuyện tổ tiên mở nước","summary":"Hùng Vương trị đất lạc, đặt tên nước là Văn Lang, chia ra thành nhiều khu vực cho các anh em mỗi người cai quản một nơi, còn một số thì ở với mẹ, anh cả được tôn làm vua, tức là Hùng Vương...","cat":"vn"},{"id":"bac-kim-thang","url":"https://truyencotich.top/doc-truyen/bac-kim-thang","title":"Bắc kim thang","summary":"Ngày xửa ngày xưa, ở một làng quê nọ, có hai người bạn làm nghề buôn bán cùng nhau. Một người đi soi đèn bắt ếch về đêm, còn anh kia thì chuyên đi bán dầu thắp đèn vào rạng sáng. Nhà họ dựng trên một cù lao nhỏ ven sông, tách biệt với làng xóm..","cat":"vn"},{"id":"su-tich-chim-da-da","url":"https://truyencotich.top/doc-truyen/su-tich-chim-da-da","title":"Sự tích chim đa đa","summary":"Ngày xưa có một em bé mồ côi cha từ hồi còn nhỏ. Người mẹ sau một thời gian tang chế cũng đi lấy chồng. Vì bà con thân thích nội ngoại không còn ai nên nó phải theo mẹ về ở với bố ghẻ. Bố ghẻ tính rất vũ phu, coi cả hai mẹ con như kẻ ăn đứa ở...","cat":"vn"},{"id":"nang-tien-gao","url":"https://truyencotich.top/doc-truyen/nang-tien-gao","title":"Nàng tiên gạo","summary":"Ngày xưa, có một nhà chỉ có hai mẹ con. Người mẹ già yếu, không đi nương rẫy làm được nữa. Cô gái rất thương mẹ, suốt ngày chăm chỉ làm lụng nuôi mẹ già...","cat":"vn"},{"id":"su-tich-hoa-ngoc-lan","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-ngoc-lan","title":"Sự tích hoa Ngọc Lan","summary":"Ngày xửa ngày xưa, tất cả các loài cây trên Trái Đất thuở ban đầu mới chỉ có lá mà chưa có hoa như bây giờ. Trời sai Thần Sắc Đẹp dùng bút vẽ muôn ngàn bông hoa khác nhau cho cây cối..","cat":"vn"},{"id":"su-tich-cay-quat","url":"https://truyencotich.top/doc-truyen/su-tich-cay-quat","title":"Sự tích cây Quất","summary":"Ngày xưa, có ba người bạn nhỏ chơi rất thân với nhau. Thư thích đọc sách ngâm thơ. Mộc ham trồng cây, hái cỏ. Quân mê xem đánh võ, múa đao. Quân vừa bị câm lại bị điếc. Muốn nói gì, Quân phải ra hiệu bằng tay chân...","cat":"vn"},{"id":"su-tich-deo-phat-tu","url":"https://truyencotich.top/doc-truyen/su-tich-deo-phat-tu","title":"Sự tích đèo phật tử","summary":"Ngày xưa có bốn người đêm ngày đọc kinh niệm phật quyết tu cho thành đạo. Bốn người có bốn họ khác nhau: Hoàng, Trần, Lí, Lắm. Ba người là đàn ông, riêng người họ Lắm là con gái...","cat":"vn"},{"id":"con-rua-vang","url":"https://truyencotich.top/doc-truyen/con-rua-vang","title":"Con Rùa Vàng","summary":"Ngày xưa có hai người bạn thân, người giầu tên là Đại trượng phu, người nghèo tên là Chí quân tử. Vợ chồng Đại trượng phu thấy bạn nghèo ngỏ ý muốn giúp cho để buôn bán...","cat":"vn"},{"id":"vua-ba","url":"https://truyencotich.top/doc-truyen/vua-ba","title":"Vua bà","summary":"Tục truyền rằng, cũng là con do bà Tồ Cô đẻ ra, nhưng Nhữ Nương khác hẳn các chị em sinh cùng một bọc. Nhừ Nương đã thấp gầy, da lại đen trong khi ai cũng môi son má đỏ, da trắng tóc dài, thân hình đầy đặn dịu dàng nổi tiếng xinh đẹp...","cat":"vn"},{"id":"su-tich-dam-ga","url":"https://truyencotich.top/doc-truyen/su-tich-dam-ga","title":"Sự tích đầm gà","summary":"Giáp chân núi Chẹ có một cái đầm sau gọi là đầm Gà. Tục truyền, ở quanh đầm ấy ngày xưa đã xảy ra một trận đánh lớn giữa Sơn Tinh và Thủy Tinh...","cat":"vn"},{"id":"su-tich-ngoi-lat","url":"https://truyencotich.top/doc-truyen/su-tich-ngoi-lat","title":"Sự tích ngòi Lạt","summary":"Ở địa phận xã Minh Quang, phía tây núi Ba Vì có một con ngòi lớn từ sông Đà ăn thông vào chân núi. Tục truyền đó là dấu vết con đường tiến quân của Thủy Tinh ngày trước...","cat":"vn"},{"id":"su-tich-ao-vua","url":"https://truyencotich.top/doc-truyen/su-tich-ao-vua","title":"Sự tích ao vua","summary":"Trên lưng chừng sườn núi Tản về phía địa phận xã Tân Lĩnh, huyện Ba Vì, có một cái ao sâu. Ao nhỏ nhưng bốn mùa lúc nào nước cũng trong xanh và sâu thẳm. Dân địa phương gọi đó là Ao Vua...","cat":"vn"},{"id":"mot-dieu-uoc","url":"https://truyencotich.top/doc-truyen/mot-dieu-uoc","title":"Một điều ước","summary":"Một ngày mùa thu, khi đó trong những cánh rừng, những hàng cây đã rụng hết những chiếc lá cuối cùng trên thân mình để đón đợi một mùa đông giá rét. Những con chim trú đông cũng đã bỏ chỗ trú ẩn của mình để đi nơi khác...","cat":"vn"},{"id":"anh-va-em-gai","url":"https://truyencotich.top/doc-truyen/anh-va-em-gai","title":"Anh và em gái","summary":"Có hai anh em nhà kia mồ côi mẹ. Một hôm, anh dắt em gái đi thủ thỉ nói: Từ ngày mẹ mất, anh em mình không có lúc nào sung sướng nữa. Mẹ ghẻ hàng ngày đánh đập, xin cái gì thì thượng cẳng chân, hạ cẳng tay đuổi đi...","cat":"vn"},{"id":"hai-chi-em","url":"https://truyencotich.top/doc-truyen/hai-chi-em","title":"Hai chị em","summary":"Ngày xưa, trong nhà nọ có hai chị em, mỗi người một tính nết. Người chị xinh đẹp, tham lam và lười nhác. Người em bị què tay, nhưng rất siêng năng làm lụng. Người chị cậy khoẻ, cậy xinh, sáng trưa chiều tối chỉ luẩn quẩn nào gương nào lược...","cat":"vn"},{"id":"su-tich-dua-bo","url":"https://truyencotich.top/doc-truyen/su-tich-dua-bo","title":"Sự tích dưa bở","summary":"Ngày xửa ngày xưa, có một cặp vợ chồng nhà nghèo quanh năm bảo ban chăm chỉ làm lụng mà vẫn không đủ ăn. Vì thế, họ thường xuyên phải đi xin thóc gạo của những người ở cùng trong bản. Nhưng xin mãi thì mọi người cũng chán, chẳng cho nữa...","cat":"vn"},{"id":"nu-than-vang","url":"https://truyencotich.top/doc-truyen/nu-than-vang","title":"Nữ thần Vàng","summary":"Nữ thần Vàng thường hiện lên dưới dạng một thiếu nữ kiều Diễm với những vòng hào quang rực rỡ. Ở nơi nào nàng hiện ra thường sẽ là những vùng sáng rực trong đêm. Đó là theo lời đồn của thiên hạ chứ thực ra ít ai được chiêm ngưỡng...","cat":"vn"},{"id":"van-cat-than-nu-hay-ba-chua-lieu","url":"https://truyencotich.top/doc-truyen/van-cat-than-nu-hay-ba-chua-lieu","title":"Vân cát thần nữ hay bà chúa Liễu","summary":"Bà chúa Liễu hay Quỳnh Nương công chúa. Ở thôn An Hải, xã Vân Cát, huyện Thiên Bản, Sơn Nam Hạ (nay là huyện Vụ Bản, tỉnh Hà Nam Ninh) có vợ chồng ông Lê Thái Công rất hiền đức, hay làm điều lành. Ông bà đã có một con trai...","cat":"vn"},{"id":"lac-long-quan-giet-moc-tinh","url":"https://truyencotich.top/doc-truyen/lac-long-quan-giet-moc-tinh","title":"Lạc Long Quân giết Mộc tinh","summary":"Nối tiếp chiến tích trừ yêu diệt ma của Lạc Long Quân là câu truyện mang lại sự yên ổn cho nhân dân ở đồng bằng. Đến đâu, thần cũng đưa những phương pháp canh tác mới, dạy cho mọi người thay vào lối làm ăn cũ...","cat":"vn"},{"id":"lac-long-quan-giet-tru-cuu-vi-ho-tinh","url":"https://truyencotich.top/doc-truyen/lac-long-quan-giet-tru-cuu-vi-ho-tinh","title":"Lạc Long Quân giệt trừ Cửu vĩ Hồ tinh","summary":"Lạc Long Quân giúp dân trừ yêu diệt ma, lần diệt nạn nạn thủy quái khiến cho nhân dân miền biển vui mừng khôn xiết. Lạc Long Quân đi đến đâu cũng được hoan hô chúc tụng. Sau đó, thần lại tiếp tục đi thăm dân sự...","cat":"vn"},{"id":"chum-vang-chum-ran","url":"https://truyencotich.top/doc-truyen/chum-vang-chum-ran","title":"Chum vàng chum rắn","summary":"Ngày xưa có hai vợ chồng quê nghèo đói nhưng ăn ở hiền lành và tử tế với mọi người. Một hôm, trong lúc cầy cuốc ở ngoài đồng, người chồng gặp được hũ vàng. Anh lẳng lặng vùi hũ vàng lại rồi về khoe với vợ...","cat":"vn"},{"id":"nguoi-hoc-tro-va-con-cho-da","url":"https://truyencotich.top/doc-truyen/nguoi-hoc-tro-va-con-cho-da","title":"Người học trò và con chó đá","summary":"Ngày xưa, có người học trò hôm nào đến nhà thày cũng phải đi qua một nơi có con chó đá. Khi người ấy qua thì con chó đá nhỏm dậy tỏ vẻ mừng rỡ. Người học trò lấy làm lạ...","cat":"vn"},{"id":"nang-vo-trung","url":"https://truyencotich.top/doc-truyen/nang-vo-trung","title":"Nàng vỏ trứng","summary":"Ngày xưa, trên đất Mường Ai có hai anh em mồ côi cha mẹ từ lúc còn nhỏ, người anh tên là Cả, em tên là Hai. Hàng ngày hai anh em vác cần câu ra suối, câu được cá đem đi đổi lấy quần áo để mặc, cơm gạo để ăn...","cat":"vn"},{"id":"su-tich-hoa-thien-ly","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-thien-ly","title":"Sự tích hoa Thiên Lý","summary":"Ngày xưa, xưa xưa, có một chàng trai thổi sáo rất hay. Hay đến mức, một con rắn lục mê tiếng sáo của chàng, đã quyết tâm tu luyện cho thành người để giành chàng làm chồng, mặc dù chàng đã có vợ...","cat":"vn"},{"id":"ba-chang-dung-si","url":"https://truyencotich.top/doc-truyen/ba-chang-dung-si","title":"Ba chàng dũng sĩ","summary":"Ở làng kia, có một người đàn bà rất chăm làm. Từ mờ sáng, khi chim Mơ lang vừa cất tiếng hót thì đã thấy bà rời làng lên nương rồi. Bà cặm cụi làm việc cho đến khi ngôi sao Bắc đẩu lấp lánh trên trời cao mới lại tr�� về làng...","cat":"vn"},{"id":"su-tich-con-heo","url":"https://truyencotich.top/doc-truyen/su-tich-con-heo","title":"Sự tích con Heo","summary":"Ngày xưa có một gia đình nông dân sống rất nhân hậu. Vợ chồng cày sâu cuốc bẫm, tiết kiệm giúp đỡ người nghèo. Họ đã tạo được trâu khỏe, ruộng tốt, cất được 5 gian nhà gỗ lim, vườn cau, ao cá. Cuộc sống tưởng thế đã thanh nhàn...","cat":"vn"},{"id":"su-tich-cay-kim-giao","url":"https://truyencotich.top/doc-truyen/su-tich-cay-kim-giao","title":"Sự tích cây Kim Giao","summary":"Ngày xửa ngày xưa, có một đôi trai gái yêu nhau tha thiết lắm. Người con trai tên là Kim, người con gái tên là Giao. Cả hai đều là con của nhưng gia đình nghèo túng, quanh năm làm thuê, làm mướn, nhưng ai nấy cũng lương thiện và rất tốt bụng...","cat":"vn"},{"id":"ong-dai-ong-coc-hay-su-tich-song-ky-cung","url":"https://truyencotich.top/doc-truyen/ong-dai-ong-coc-hay-su-tich-song-ky-cung","title":"Ông Dài, Ông Cộc hay Sự tích sông Kỳ Cùng","summary":"Ngày xưa, ở vùng sông Tranh thuộc về tỉnh Đông có hai vợ chồng một nhà nọ, gia tư cũng vào hạng khá, nhưng tuổi già mà chưa có con...","cat":"vn"},{"id":"su-tich-12-con-giap","url":"https://truyencotich.top/doc-truyen/su-tich-12-con-giap","title":"Sự tích 12 con giáp","summary":"Khi xưa tên các loại vật đều do Ngọc Hoàng đặt cho và ngài đang muốn chọn một số con vật nào đó xứng đáng để đặt tên năm và làm chúa tể thay mặt Ngọc Hòang cai quản ở hạ giới...","cat":"vn"},{"id":"nang-cu-pen","url":"https://truyencotich.top/doc-truyen/nang-cu-pen","title":"Nàng Cu Pên","summary":"Ngày xửa, ngày xưa ở trên một vùng núi cao phía bắc dãy Trường Sơn có chàng Đào Lu dũng mãnh, tuấn tú và nàng Cu Pên xinh đẹp thùy mị nết na. Hai người ở cách nhau một ngọn đèo cao quanh năm mây phủ, không một dấu chân người...","cat":"vn"},{"id":"su-tich-qua-roi","url":"https://truyencotich.top/doc-truyen/su-tich-qua-roi","title":"Sự tích quả roi","summary":"Ngày xưa, có một người thầy nổi tiếng là dạy giỏi và hiền lành. Một hôm có ba người trẻ tuổi đến xin ông nhận vào học. Hai anh là con nhà nghèo. Một anh là con nhà giàu, không muốn học nhưng bị bố bắt ép phải học để may ra kiếm được vài chữ...","cat":"vn"},{"id":"nguoi-dan-ba-tiet-liet","url":"https://truyencotich.top/doc-truyen/nguoi-dan-ba-tiet-liet","title":"Người đàn bà tiết liệt","summary":"Ngày xưa ở vùng Bắc Ninh là đất nổi tiếng có nhiều con gái đẹp, có một cô gái làng Cách bi, về làm vợ ông cử nhân Nguyên Hanh, giữ chức tri huyện Thủy đường, người ta vẫn thường gọi là bà huyện Thủy đường...","cat":"vn"},{"id":"su-tich-cao-lanh","url":"https://truyencotich.top/doc-truyen/su-tich-cao-lanh","title":"Sự tích Cao Lãnh","summary":"Đồng Tháp Mười ngoài ruộng lúa phì nhiêu và cá tôm lấp lánh, sen nở bạt ngàn, còn có sự tích về một địa danh mà không hẳn ai cũng biết, đó là: Cao Lãnh. Hồi trước có cặp vợ chồng Đỗ Công Tường, tục danh là Lãnh, từ miền trung đến đây lập nghiệp...","cat":"vn"},{"id":"dam-cuoi-chuot","url":"https://truyencotich.top/doc-truyen/dam-cuoi-chuot","title":"Đám cưới chuột","summary":"Đây là một chú chuột nhắt. Một chú Chuột Nhắt còn trẻ. Tuy vậy, cứ thực sự thì diện mạo của chú cũng chẳng có vẻ mĩ miều gì mấy...","cat":"vn"},{"id":"nang-tien-coc","url":"https://truyencotich.top/doc-truyen/nang-tien-coc","title":"Nàng tiên cóc","summary":"Ngày xưa, có hai vợ chồng nông dân hiếm hoi, cầu Trời khấn Phật mãi người vợ mới có thai, nhưng đến khi sinh ra, không phải là người mà lại là một con cóc...","cat":"vn"},{"id":"su-tich-hoa-dao","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-dao","title":"Sự tích hoa đào","summary":"Ngày xưa, ở phía Đông núi Sóc Sơn, Bắc Việt có một cây hoa đào mọc đã lâu đời. Cành lá đào to lớn khác thường, bóng cây che phủ cả một vùng rộng.Có 2 vị thần tên là Trà và Uất Lũy trú ngụ ở trên cây hoa đào khổng lồ này...","cat":"vn"},{"id":"su-tich-qua-dua","url":"https://truyencotich.top/doc-truyen/su-tich-qua-dua","title":"Sự tích quả dứa","summary":"Huyền Nương là tên một cô gái mười lăm, không thích làm những việc bếp núc, thêu thùa vá may, tối ngày chỉ lo ca hát không để ý vào việc gì. Mẹ nàng là một góa phụ không mấy giàu sang, lại có tính chanh chua soi mói thiên hạ...","cat":"vn"},{"id":"re-tran","url":"https://truyencotich.top/doc-truyen/re-tran","title":"Rể trăn","summary":"Xưa, có một bà sinh được ba người con gái. Một hôm bà đi bắt cá ngoài đồng, giữa lúc đang mò cá, bỗng có một con trăn bò đến quấn vào chân bà. Bà sợ hãi kêu lên, trăn nói: Nếu bà muốn tôi thả ra thì phải gả cho tôi một trong ba đứa con gái của bà...","cat":"vn"},{"id":"su-tich-nguoi-me","url":"https://truyencotich.top/doc-truyen/su-tich-nguoi-me","title":"Sự tích người mẹ","summary":"Ngày xưa, khi tạo ra người Mẹ đầu tiên trên thế gian, ông Trời đã làm việc miệt mài suốt sáu ngày liền, quên ăn quên ngủ mà vẫn chưa xong việc...","cat":"vn"},{"id":"su-tich-don-banh-tet","url":"https://truyencotich.top/doc-truyen/su-tich-don-banh-tet","title":"Sự tích đòn bánh Tét","summary":"Sự tích bánh dày bánh chưng ngày tết cổ truyền của Lang Liêu thì ai ai cũng biết, nhưng sự tích về đòn bánh tét ngày tết cổ truyền Việt Nam thì ít người biết, nhất là với giới trẻ...","cat":"vn"},{"id":"su-tich-chim-nam-trau-sau-cot-va-chim-bat-co-troi-cot","url":"https://truyencotich.top/doc-truyen/su-tich-chim-nam-trau-sau-cot-va-chim-bat-co-troi-cot","title":"Sự tích chim năm trâu sáu cột và chim bắt cô trói cột","summary":"Ngày xưa, có một bác lực điền tên là Ba ở trong một xóm dưới chân núi. Bác không có ruộng phải làm rẽ năm sào của một phú ông ở làng bên cạnh. Phú ông là tay giàu có nhất tổng: ruộng đất trâu bò ở rải rác các thôn xóm nhiều không đếm xiết...","cat":"vn"},{"id":"su-tich-sao-hom-va-sao-mai","url":"https://truyencotich.top/doc-truyen/su-tich-sao-hom-va-sao-mai","title":"Sự tích Sao hôm và Sao mai","summary":"Xưa có một anh tiều phu nọ đến suối thình lình gặp một bầy tiên đang tắm. Tiên vội khoác áo bay về trời, còn sót lại một cô bay không được vì bộ áo của cô bị anh tiều phu giấu. Nhờ vậy, anh tiều phu nọ bắt cô tiên về làm vợ...","cat":"vn"},{"id":"su-tich-tieng-keu-cua-vac-co-du-di-da-da-va-chuot","url":"https://truyencotich.top/doc-truyen/su-tich-tieng-keu-cua-vac-co-du-di-da-da-va-chuot","title":"Sự tích tiếng kêu của vạc, cộ, dủ dỉ, đa đa và chuột","summary":"Xưa Cò, Vạc, Cộc, Dủ dỉ và Đa đa ăn ở với nhau như anh em một nhà. Chúng nó sống một cuộc đời sung sướng và hòa thuận...","cat":"vn"},{"id":"nang-xuan-huong","url":"https://truyencotich.top/doc-truyen/nang-xuan-huong","title":"Nàng Xuân Hương","summary":"Ngày xưa ở tỉnh Bắc có nàng con gái trong trắng như hoa thủy tiên nên có tên là Xuân Hương. Cha nàng là một ông đồ nhà nghèo, đã mất từ lâu. Nàng ở với mẹ, hai mẹ con tần tảo nuôi nhau...","cat":"vn"},{"id":"trang-hien","url":"https://truyencotich.top/doc-truyen/trang-hien","title":"Trạng Hiền","summary":"Vào thời nhà Trần, ở một làng nọ bây giờ thuộc về Nam-định có một em bé tên là Hiền. Hiền được cha mẹ cạo đầu làm tiểu, cho ở với một ông sư trên chùa. Hàng ngày, Hiền phải hầu hạ sư, quét dọn chùa và làm các công việc vặt...","cat":"vn"},{"id":"trong-nghia-khinh-tai","url":"https://truyencotich.top/doc-truyen/trong-nghia-khinh-tai","title":"Trọng nghĩa khinh tài","summary":"​​​​​​​Ngày xưa ở Thanh-hóa có một người tên là Nguyễn Đình Phương. Nhà ông vườn cau ao cá, lại có chừng ba chục mẫu ruộng: trong nhà, vợ con, kẻ làm người lụng khá đông. Nhưng ông vốn là người hào hiệp...","cat":"vn"},{"id":"su-tich-bo-long-qua-va-bo-long-cong","url":"https://truyencotich.top/doc-truyen/su-tich-bo-long-qua-va-bo-long-cong","title":"Sự tích bộ lông quạ và bộ lông công","summary":"Xưa kia Quạ và Công là đôi bạn chí thân. Cũng vì màu lông của chúng giống nhau: con nào con nấy đều xám xịt như vừa rúc ở bùn lên...","cat":"vn"},{"id":"duyen-no-tai-sinh","url":"https://truyencotich.top/doc-truyen/duyen-no-tai-sinh","title":"Duyên nợ tái sinh","summary":"Ngày xưa, có một anh học trò trẻ tuổi nhà nghèo xơ nghèo xác. Vì có cha mẹ già, anh phải lang thang đây đó làm nghề gõ đầu trẻ để nuôi thân và nuôi cha mẹ. Mãi về sau, anh được một phú ông ở một làng nọ mời về &quot;ngồi&quot; tại nhà...","cat":"vn"},{"id":"su-tich-nui-tan-vien","url":"https://truyencotich.top/doc-truyen/su-tich-nui-tan-vien","title":"Sự tích núi Tản Viên","summary":"Ngày xưa, có một người tiều phu cứ sáng tinh mơ thì vác búa vào rừng đốn củi....","cat":"vn"},{"id":"co-gai-lay-chong-hoang-tu","url":"https://truyencotich.top/doc-truyen/co-gai-lay-chong-hoang-tu","title":"Cô gái lấy chồng hoàng tử","summary":"Ngày xưa ở một làng nọ có một cô con gái đẹp. Thấy mọi người đều trầm trồ về nhan sắc của mình, cô bỗng có cái nguyện vọng thầm kín là được lấy hoàng tử làm chồng...","cat":"vn"},{"id":"chiec-giay-thom","url":"https://truyencotich.top/doc-truyen/chiec-giay-thom","title":"Chiếc giày thơm","summary":"Ngày xưa, ở chợ Đồng-xuân có cô gái họ Trương, con một gia đình giàu có lớn. Cô gái mặt hoa da phấn và đã đến tuổi yêu đương. Thường ngày sống trong nhung lụa, có kẻ hầu người hạ nên cô ít khi bước chân ra ngoài...","cat":"vn"},{"id":"su-tich-bai-ong-nam","url":"https://truyencotich.top/doc-truyen/su-tich-bai-ong-nam","title":"Sự tích bãi ông Nam","summary":"Ngày ấy, những người dân chài vùng biển Nam trong khi ra khơi làm ăn thường bị nạn bão tố. Mỗi lần bão tố thình lình xảy ra, nếu trên đất liền chỉ đổ cửa đổ nhà thì trên mặt biển khơi có thể chết hàng trăm hàng ngàn mạng người...","cat":"vn"},{"id":"su-tich-vinh-ha-long","url":"https://truyencotich.top/doc-truyen/su-tich-vinh-ha-long","title":"Sự tích vịnh Hạ Long","summary":"Truyền thuyết kể rằng: Ngày xưa, xa xưa lắm, một lần nước ta có giặc ngoại xâm, trời sai rồng mẹ mang một đàn con xuống cứu giúp. Đánh giặc xong, rồng mẹ và đàn con ở lại hạ giới...","cat":"vn"},{"id":"su-tich-cay-nhan-tran","url":"https://truyencotich.top/doc-truyen/su-tich-cay-nhan-tran","title":"Sự tích cây nhân trần","summary":"Ngày xưa có một nữ bệnh nhân mắc căn bệnh nan y thân hình ốm yếu gầy guộc, sắc mặt thì vàng vọt, niêm mạc hai mắt có màu mơ chín, mệt mỏi…. đến tìm gặp danh y Hoa Đà để chữa bệnh...","cat":"vn"},{"id":"ba-chua-ngoc","url":"https://truyencotich.top/doc-truyen/ba-chua-ngoc","title":"Bà Chúa Ngọc","summary":"Ngày xưa, ở xã Đại An gần cù lao Huân tỉnh Khánh Hòa có một đôi vợ chồng già không có con cáị Ông bà ở trong một căn nhà lá dựng bên vách núi, làm nghề trồng dưạ Năm ấy, đến độ dưa chín, sáng nào ra ruộng thăm, ông bà cũng thấy dưa bị hái trộm...","cat":"vn"},{"id":"su-tich-hoa-muoi-gio","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-muoi-gio","title":"Sự tích hoa mười giờ","summary":"Tia nắng ban mai hôm nào cũng đi ngang qua cửa phòng cô bé nhưng cô bé lúc thì mải chơi, lúc mải học cho nên ít khi để ý tới nó. Căn phòng của cô bé hướng ra mảnh vườn nhỏ mà ở đó ba của cô bé đã trồng rất nhiều loài hoa...","cat":"vn"},{"id":"hai-ong-tien","url":"https://truyencotich.top/doc-truyen/hai-ong-tien","title":"Hai ông tiên","summary":"Ngày xưa, có một người con trai tên là Hiếu, cha làm nghề đốn củi bị cọp tha mất, còn một mẹ già với mấy em dại, Hiếu phải ngày ngày đi vào rừng, làm lụng khó nhọc để nuôi mẹ và các em...","cat":"vn"},{"id":"su-tich-hoa-da-quy","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-da-quy","title":"Sự tích hoa Dã Quỳ","summary":"Ngày xửa ngày xưa, nơi buôn sóc nọ có chàng K’lang của núi rừng yêu tha thiết nàng H’limh của con suối.Ngày ngày chàng K’lang vào rừng săn bắt thú rừng còn nàng khéo léo dệt tấm chăn kiệu chồng...","cat":"vn"},{"id":"su-tich-1000-con-hac-giay","url":"https://truyencotich.top/doc-truyen/su-tich-1000-con-hac-giay","title":"Sự tích 1000 con hạc giấy","summary":"Chuyện kể rằng một nàng tiểu thư đài các con gái huyện quan yêu say đắm một chàng thư sinh nghèo. Hai trái tim đến với nhau bằng tình yêu tinh khôi tuổi xuân thì. Chuyện đến tai huyện quan, ông đùng đùng nổi giận và ra sức ngăn cấm...","cat":"vn"},{"id":"su-tich-cay-du-du","url":"https://truyencotich.top/doc-truyen/su-tich-cay-du-du","title":"Sự tích cây Đu Đủ","summary":"Ngày xưa có một bác nông dân nghèo có thú nuôi chim. Một hôm chim của ông ăn mất 3 hạt bắp của quan làng...","cat":"vn"},{"id":"su-tich-cay-nhan","url":"https://truyencotich.top/doc-truyen/su-tich-cay-nhan","title":"Sự tích cây Nhãn","summary":"Ngày xưa… xưa.. rất xưa, có một tên ăn cướp, cướp được rất nhiều của, cất được rất nhiều nhà, mà vẫn chưa thỏa lòng tham. Hắn không chỉ muốn giàu, hắn còn muốn làm vua...","cat":"vn"},{"id":"su-tich-cay-dua","url":"https://truyencotich.top/doc-truyen/su-tich-cay-dua","title":"Sự tích cây Dừa","summary":"Ngày xưa ở vùng đất nọ có gia đình nhà nghèo cảnh mẹ góa, con côi. Hai mẹ con ngày ngày cày thuê cuốc mướn cho tên địa chủ giàu có trong vùng, mà cảnh đói cơm thiếu áo vẫn xảy ra ngày một ngày hai...","cat":"vn"},{"id":"su-tich-cai-mo","url":"https://truyencotich.top/doc-truyen/su-tich-cai-mo","title":"Sự tích cái mõ","summary":"Ngày xưa, có một vị Hòa Thượng trụ trì một cảnh chùa ở gần bờ sông trong một thôn quê. Mỗi khi có việc ra tỉnh, Ngài quá giang bằng chiếc đò ngang. Hôm ấy nhằm ngày 13 tháng bảy, Ngài quá giang ra tỉnh để chủ lễ một đàn kỳ siêu...","cat":"vn"},{"id":"keo-cay-gia-no","url":"https://truyencotich.top/doc-truyen/keo-cay-gia-no","title":"Kéo cày giả nợ","summary":"Xưa, có một người tên gọi là Chu văn Địch làm ăn vất vả, cửa nhà đói kém, nhưng tính khí hiền lành, ăn ở thật thà, có nhân có đức. Trong hạt, có một nhà giàu thường cho người ấy vay nợ, năm nào cũng vậy, vay vay giả giả đã nhiều...","cat":"vn"},{"id":"su-tich-hat-thoc","url":"https://truyencotich.top/doc-truyen/su-tich-hat-thoc","title":"Sự tích hạt thóc","summary":"Ngày xưa, có một người đàn bà nghèo. Chồng chết sớm, bà ở vậy nuôi đứa con trai duy nhất. Điều đáng buồn là cậu con trai càng được cưng chiều, càng đâm ra hư hỏng, bất hiếu, và không nghe lời mẹ...","cat":"vn"},{"id":"vi-sao-huou-bi-mat-duoi","url":"https://truyencotich.top/doc-truyen/vi-sao-huou-bi-mat-duoi","title":"Vì sao hươu bị mất đuôi","summary":"Ngày xửa, ngày xưa có hai ông bà lão sống với nhau trong căn nhà tranh nhỏ cu kỹ ở ven một rừng già, rộng lớn. Hàng ngày, họ cùng nhau dạo chơi trong vườn, buổi tối ngồi bên bếp lửa chuyện trò. Họ sống cuộc sống thanh bình, yên ả...","cat":"vn"},{"id":"su-tich-loai-ngong","url":"https://truyencotich.top/doc-truyen/su-tich-loai-ngong","title":"Sự tích loài ngỗng","summary":"Những chú ngỗng con nở ra đều có bộ lông màu trắng tinh. Vì chúng đều xuất thân từ những quả trứng rất trắng của mẹ. Mỗi lần nghịch bơi lặn ở ao nước bẩn thỉu, có bị lấm bẩn thì mẹ chúng chỉ cần dội qua nước sạch...","cat":"vn"},{"id":"su-tich-con-ech","url":"https://truyencotich.top/doc-truyen/su-tich-con-ech","title":"Sự tích con ếch","summary":"Ngay từ sáng sớm đã có tiếng loa rao vang khắp cánh đồng: “Thi tài… thi tài… chọn người tài giỏi đi dự đại hội thể thao đầm sen đây!”. Bọn ếch, nhái, chẫu chuộc lao xao gọi nhau đi thi. Lão cóc được đề cử làm trưởng ban giám khảo...","cat":"vn"},{"id":"tho-nau-xu-kien","url":"https://truyencotich.top/doc-truyen/tho-nau-xu-kien","title":"Thỏ Nâu xử kiện","summary":"Ngày ấy, ở một làng nọ có một anh nhà giàu sống sung sướng trong lụa là gấm vóc. Cạnh nhà anh ta là túp lều của hai vợ chồng nông dân nghèo. Hai nhà tuy có hoàn cảnh khác nhau nhưng lại xây dựng được tình xóm giềng rất tốt...","cat":"vn"},{"id":"lam-sanh-va-xuan-nuong","url":"https://truyencotich.top/doc-truyen/lam-sanh-va-xuan-nuong","title":"Lâm Sanh và Xuân Nương","summary":"Ngày xưa, quan tổng đốc Lâm Phụng huyện Châu Thai nổi tiếng hiền đức bao nhiêu thì phu nhân Lý Phi Nương mang tiếng độc ác bấy nhiêu. Khi quan tổng đốc qua đời, phu nhân cưới nàng Xuân Nương cho con trai là Lâm Sanh...","cat":"vn"},{"id":"su-tich-hoa-bo-cong-anh","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-bo-cong-anh","title":"Sự tích hoa Bồ Công Anh","summary":"Đã lâu lắm rồi, khi con người mới hình thành nên các quốc gia và đang cố gắng củng cố sự vững mạnh của đất nước mình. Ở một vương quốc nọ, cũng giống như nhiều quốc gia khác, họ đang sống trong những ngày tháng đầu tiên...","cat":"vn"},{"id":"ba-ba-hoang-hau","url":"https://truyencotich.top/doc-truyen/ba-ba-hoang-hau","title":"Ba bà hoàng hậu","summary":"Ngày xửa, ngày xưa, có một ông vua trẻ. Ðức vua cai trị một vương quốc giàu có, xinh đẹp, nhưng đẹp nhất có lẽ là ba bà hoàng hậu của đức vua. Ba vị hoàng hậu này vừa có sắc lẫn có tài, nên cả ba đều được đức vua sủng ái như nhau...","cat":"vn"},{"id":"meo-day-ho","url":"https://truyencotich.top/doc-truyen/meo-day-ho","title":"Mèo dạy Hổ","summary":"Lúc nào Hổ cũng vênh váo tự xưng mình là chúa tể sơn lâm. Nó khoe bộ vuốt sắc, bộ nanh nhọn có thể cào rách và cắn thủng bộ da của con voi già hàng trăm tuổi. Nó khoe có bàn tay khỏe có thể tát chết tươi bất cứ con vật nào...","cat":"vn"},{"id":"su-tich-ao-ba-ba","url":"https://truyencotich.top/doc-truyen/su-tich-ao-ba-ba","title":"Sự tích áo Bà Ba","summary":"Ngày xưa, từ vua quan đến người thường không phân biệt trai hay gái, điều mặc áo dài đúng theo cổ tục. Có một anh đánh cá ở ven biển rất nghèo túng mà vẫn phải mặc áo dài đàng hoàng như mọi người...","cat":"vn"},{"id":"me-chong-buoc-toi-nang-dau","url":"https://truyencotich.top/doc-truyen/me-chong-buoc-toi-nang-dau","title":"Mẹ chồng buộc tội nàng dâu","summary":"Ngày xưa ở tỉnh Thái nguyên miền Bắc, có một bà mẹ chồng sống với nàng dâu, cả hai đều góa chồng. Bà mẹ chồng đang còn trẻ, không muốn ở vậy, nên thường lén lút đi lại với một người hàng xóm...","cat":"vn"},{"id":"su-tich-hoa-hong-bach","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-hong-bach","title":"Sự tích hoa hồng bạch","summary":"Câu chuyện này xảy ra vào thời mà những khu vườn còn ngập tràn cỏ dại, các loài hoa rất hiếm và chưa có hương thơm, còn hoa hồng chỉ có một màu đỏ thắm...","cat":"vn"},{"id":"chang-chom","url":"https://truyencotich.top/doc-truyen/chang-chom","title":"Chàng Chôm","summary":"Ngày xưa, mường Vong có khu rừng Bái Mân. Giữa rừng là làng người ở. Nương rẫy lúa ngô hơi tốt. Ngô lúa đang xanh tươi, thì có trận lũ to ập đến. Mưa suốt bảy ngày tám đêm, hạt mưa bằng quả cà quả khế...","cat":"vn"},{"id":"nguoi-chet-de-con","url":"https://truyencotich.top/doc-truyen/nguoi-chet-de-con","title":"Người chết đẻ con","summary":"Ngày xưa, có người đàn bà nhà quê sắp đến ngày sinh đẻ thì nhuốm phải bệnh nặng. Biết mình không thể sống nổi để cho con ra đời, lúc hấp hối, thiếu phụ ứa nước mắt nhìn chồng, tay sờ soạng lên bụng chửa, nghẹn ngào...","cat":"vn"},{"id":"su-tich-hoa-linh-lan","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-linh-lan","title":"Sự tích hoa Linh Lan","summary":"Thời xa xưa có một chàng Gù bất hạnh, sống đơn độc, không biết cha mẹ mình là ai, anh em thân thuộc cũng không có, chẳng ai coi chàng là bạn. Ðối với tình yêu, chàng chỉ biết qua sách vở...","cat":"vn"},{"id":"su-tich-hoa-sen","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-sen","title":"Sự tích hoa Sen","summary":"Ngày xửa, ngày xưa ở một ngôi làng nhỏ có 2 cô bé mồ côi cha mẹ từ nhỏ. Hai cô bé được một người tốt bụng đưa về nuôi, ông là một người chuyên hát xẩm. Hàng ngày ông dạy cho 2 cô bé những điệu múa bài hát hay...","cat":"vn"},{"id":"su-tich-con-trau","url":"https://truyencotich.top/doc-truyen/su-tich-con-trau","title":"Sự tích con trâu","summary":"Vào thuở ban sơ, Ngọc Hoàng, vị vua trên thiên đình đã tạo nên trái đất và để cho loài người cùng muông thú chung sống cùng nhau. Ngọc Hoàng khá hài lòng khi hai loài sống hòa hợp với nhau và đã sai một vị thần xuống trần gian...","cat":"vn"},{"id":"tai-sao-trau-den-bo-vang","url":"https://truyencotich.top/doc-truyen/tai-sao-trau-den-bo-vang","title":"Tại sao trâu đen, bò vàng?","summary":"Trâu và bò ngày xưa là hai anh em kết nghĩa. Chúng cùng sinh ra ở một vùng nông thôn hẻo lánh. Khi còn nhỏ cả hai đều có một bộ lông trắng rất đẹp và mịn màng...","cat":"vn"},{"id":"su-tich-con-ho","url":"https://truyencotich.top/doc-truyen/su-tich-con-ho","title":"Sự tích con hổ","summary":"Ngày xưa có một gia đình rất đông con, quanh năm vất vả với nương rẫy. Trồng lúa, tỉa ngô hàng năm cũng không đủ cơm ăn, đến nỗi ăn rau rừng không kịp mọc, ăn măng rừng đến nỗi không kịp nhú khỏi mặt đất...","cat":"vn"},{"id":"su-tich-con-tran-nha-noc","url":"https://truyencotich.top/doc-truyen/su-tich-con-tran-nha-noc","title":"Sự tích con trăn nhả nọc","summary":"Ngày xửa ngày xưa, có đôi vợ chồng mới cưới. Một hôm, anh chồng dẫn vợ về thăm nhà bố mẹ. Đường xa, họ phải qua những cánh rừng rộng. Ở một quãng đường rừng hai người vừa đi qua có một con Trăn trườn ra...","cat":"vn"},{"id":"ho-va-cac-con-vat-nho-be","url":"https://truyencotich.top/doc-truyen/ho-va-cac-con-vat-nho-be","title":"Hổ và các con vật nhỏ bé","summary":"Ngày xưa, ở trên núi Ba Vì có một con Hổ rất hung dữ. Mỗi khi bắt được con vật nào nó thường đùa giỡn làm cho con vật đó khiếp sợ rồi mới ăn thịt. Một hôm, Hổ đang lang thang đi tìm mồi thì nhìn thấy một con Rùa bé nhỏ...","cat":"vn"},{"id":"con-vet-hay-bat-chuoc","url":"https://truyencotich.top/doc-truyen/con-vet-hay-bat-chuoc","title":"Con Vẹt hay bắt chước","summary":"Khi mùa xuân về, các giống chim và thú vật rủ nhau tới rừng hoa mở hội. Nào Voi, Gấu, Hổ, Lợn lòi… trổ tài thi khỏe. Nào Khỉ, Vượn, Sóc… đua tranh nhau trèo leo. Và các giống chim thì khoe tiếng hót hay...","cat":"vn"},{"id":"chim-sau-va-cao","url":"https://truyencotich.top/doc-truyen/chim-sau-va-cao","title":"Chim sâu và Cáo","summary":"Có một thời gian Chim sâu và Cáo là một đôi bạn chí thân. Cáo chạy đến đâu, Chim sâu cũng bay tới đó. Có một lần Cáo nói - Này bạn, chúng ra hãy cùng nhau gieo trồng lúa đi...","cat":"vn"},{"id":"bac-si-soi","url":"https://truyencotich.top/doc-truyen/bac-si-soi","title":"Bác sĩ Sói","summary":"Sói kiếm mồi trong rừng, chợt nhìn thấy một chú ngựa đang ăn ngoài đồng cỏ. Chú ngựa béo tốt quá, mà không có ai trông cả. Mõm chú không có cương, cổ chú không có dây buộc...","cat":"vn"},{"id":"ba-cai-chuong-trau","url":"https://truyencotich.top/doc-truyen/ba-cai-chuong-trau","title":"Ba cái chuồng trâu","summary":"Ngày xưa có ba cô gái con nhà giàu được bố mẹ yêu quý nuông chiều hết mực. Ba cô lớn như thổi và ngày càng xinh đẹp. Hai cô chị lấy chồng giàu. Cô Út lấy chồng nghèo. Ba cô lần lượt ra ở riêng...","cat":"vn"},{"id":"gan-coc-tia","url":"https://truyencotich.top/doc-truyen/gan-coc-tia","title":"Gan cóc tía","summary":"Trong rừng kia có một con cọp rất dữ tợn. Mọi con vật trong rừng đều phải sợ Cọp. Một hôm Cọp đi ngang qua hang Cóc Tía. Cóc Tía nghĩ bụng: “Mình phải dùng mưu trí để Cọp hết tính hống hách mới được”...","cat":"vn"},{"id":"kinh-va-ba-na-la-anh-em","url":"https://truyencotich.top/doc-truyen/kinh-va-ba-na-la-anh-em","title":"Kinh và Ba Na là anh em","summary":"Ngày xưa, khi loài người còn thưa thớt, có một nhà nọ có hai anh em trai. Xứ họ ở bằng phẳng, rộng thênh thang, quay đầu bốn phía đều thấy chân trời tròn vành vạnh như một vành nong...","cat":"vn"},{"id":"tieng-trong-me-linh","url":"https://truyencotich.top/doc-truyen/tieng-trong-me-linh","title":"Tiếng trống Mê Linh","summary":"Trưng Trắc và Trưng Nhị là hai chị em đứng đầu đất Mê Linh. Đã từ lâu, Mê Linh rộn rã tiếng trống. Đó là những chiếc trống lớn đúc toàn bằng đồng, rực rỡ sắc vàng, rền vang những âm thanh hùng tráng...","cat":"vn"},{"id":"chang-ngoc-va-ga-bom","url":"https://truyencotich.top/doc-truyen/chang-ngoc-va-ga-bom","title":"Chàng ngốc và gã bợm","summary":"Ngày xưa có một anh chàng, nhà giàu có nhưng phải cái ngu ngốc thì không ai bằng. Một hôm, nghe nói trong vùng có đám hội lớn mở luôn mười đêm ngày, hắn vội vã thắng bộ cánh rất sang...","cat":"vn"},{"id":"chuyen-rua-va-khi","url":"https://truyencotich.top/doc-truyen/chuyen-rua-va-khi","title":"Chuyện Rùa và Khỉ","summary":"Ngày xưa, có một bác rùa già sống cùng vợ và gia đình trong một cái hồ lớn, bao quanh hồ là một khu rừng rộng lớn, trong rừng có rất nhiều thú hoang. Đặc biệt là loài khỉ, chúng di chuyển thành đàn với số lượng lớn theo bờ hồ...","cat":"vn"},{"id":"su-tich-con-chau-chuoc","url":"https://truyencotich.top/doc-truyen/su-tich-con-chau-chuoc","title":"Sự tích con Chẫu Chuộc","summary":"Truyện xưa kể rằng, ở xứ Thanh có một lão nhà giàu có nhưng rất keo kiệt, bủn xỉn. Lão nuôi trong nhà một anh cố nông nghèo hèn nhưng hiền lành, khoẻ mạnh. Cha mẹ anh mất sớm chẳng để lại cho anh cái gì ngoài một túp lều rách...","cat":"vn"},{"id":"su-tich-con-meo","url":"https://truyencotich.top/doc-truyen/su-tich-con-meo","title":"Sự tích con Mèo","summary":"Ngày xưa, có hai chị em hổ đói bụng dẫn nhau đi kiếm ăn. Lúc này đang là mùa đông gió rét, sương gió lạnh cắt da, cắt thịt. Rét đến mức chẳng có con thú nào chịu ra khỏi tổ nên hai chị em hổ không thể kiếm được thức ăn...","cat":"vn"},{"id":"su-tich-cau-noi-nhan-nhu-khi","url":"https://truyencotich.top/doc-truyen/su-tich-cau-noi-nhan-nhu-khi","title":"Sự tích câu nói Nhăn như khỉ","summary":"Ngày xưa, trong làng nọ, có một bà cụ già nuôi một đàn chó con, con nào con nấy bụ bẫm, xinh xắn và rất đáng yêu. Bà cụ rất yêu bầy chó của mình. Nhìn chúng đùa nghịch trong sân trông thật vui mắt...","cat":"vn"},{"id":"than-lua-truyen-co-tich-dan-toc-tay","url":"https://truyencotich.top/doc-truyen/than-lua-truyen-co-tich-dan-toc-tay","title":"Thần Lúa - Truyện cổ tích dân tộc Tày","summary":"Ngày xưa có một người đàn bà nghèo, tuổi cao rồi mới sinh được một cậu con trai. Bà đặt tên con là Pọ Khâu (có nghĩa là Bố Lúa), ý mong mỏi con sẽ không phải ăn trái cây, lá rừng quanh năm suốt tháng như mình...","cat":"vn"},{"id":"ca-bong-than","url":"https://truyencotich.top/doc-truyen/ca-bong-than","title":"Cá Bống thần","summary":"Ngày xửa, ngày xưa, có hai anh em mồ côi, tính tình trái ngược hoàn toàn. Người em chăm chỉ, hiền lành, thật thà còn người anh gian ngoan lại tham lam độc ác. Anh ta vơ vét hết tất cả những gì bố mẹ để lại, chẳng cho người em bất cứ thứ gì...","cat":"vn"},{"id":"than-cuong","url":"https://truyencotich.top/doc-truyen/than-cuong","title":"Thần cuống","summary":"Ngày xưa, tại xã Khúc Phụ, tổng Thổ Bình, châu Chiêm Hóa, thuộc tỉnh Tuyên Quang, có một bà lão góa không con, ở thôn Mô Cuống, mỗi ngày thường đến thác Cuống bắt tôm cá về ăn...","cat":"vn"},{"id":"su-tich-con-cao-cao","url":"https://truyencotich.top/doc-truyen/su-tich-con-cao-cao","title":"Sự tích con cào cào","summary":"Cào cào xưa kia là một cô gái đẹp. Tính cô thích ăn diện như­ng vì nhà nghèo, nên cô chư­a đ­ược thỏa ý muốn. Một hôm, nhà vua bị mất một cô công chúa. Vua sai quân lính đi tìm khắp đó đây. Lúc đó cô gái đẹp đang kiếm củi bên một gốc cây...","cat":"vn"},{"id":"chiec-thung-than-dieu","url":"https://truyencotich.top/doc-truyen/chiec-thung-than-dieu","title":"Chiếc thùng thần diệu","summary":"Ngày xưa, có một ông nông dân rất nghèo, một hôm ông đang đào đất thì thấy một cái thùng rất to, lúc đó vô tình ông đánh rơi một hạt dẻ vào trong thùng, lập tức ông đếm được 81 hạt dẻ...","cat":"vn"},{"id":"su-tich-co-va-lua","url":"https://truyencotich.top/doc-truyen/su-tich-co-va-lua","title":"Sự tích Cỏ và Lúa","summary":"Ngày xưa cỏ và lúa là con cùng một mẹ. Khi lớn lên, mẹ cho cỏ và lúa ở riêng mỗi người một cánh đồng. Lúa vốn chăm chỉ làm lụng, chịu thương chịu khó nên mỗi ngày một khỏe mạnh, tươi tốt, làm ra những hạt thóc mẩy căng như hạt chanh...","cat":"vn"},{"id":"su-tich-cai-ong-nho","url":"https://truyencotich.top/doc-truyen/su-tich-cai-ong-nho","title":"Sự tích cái ống nhổ","summary":"Ngày xưa có một nhà sư già nổi danh là một vị đại đạo đức chân tu danh tiếng ngài được truyền đi khắp nơi, bá tánh tứ phương ào ạt tới chùa thọ giáo càng ngày càng đông. Một ngày kia, ngài quyết định đi vào rừng thẳm ẩn dật...","cat":"vn"},{"id":"cai-sot","url":"https://truyencotich.top/doc-truyen/cai-sot","title":"Cái sọt","summary":"Ngày xửa ngày xưa ở một làng kia có một gia đình nghèo khó. Nhà có bốn người, hai vợ chồng, đứa con trai nhỏ tuổi và ông bố chồng đã già. Năm tháng ròng rã, ông bố phải làm lụng vất vả, giờ đây đã quá già yếu không còn cất nhắc được việc gì....","cat":"vn"},{"id":"su-tich-mua-gat","url":"https://truyencotich.top/doc-truyen/su-tich-mua-gat","title":"Sự tích mùa gặt","summary":"Tục truyền ngày x­ưa khi vua Hùng mới dựng nư­ớc, ven các con sông Thao, sông Đà, sông Lô đất đai màu mỡ, cây cối tốt t­ươi. Cư­ dân Văn Lang vẽ chàm vào ng­ười xuống đồng bắt cá về ăn...","cat":"vn"},{"id":"con-co-con-cong-va-con-vet","url":"https://truyencotich.top/doc-truyen/con-co-con-cong-va-con-vet","title":"Con Cò, con Công và con Vẹt","summary":"Ngày xửa, ngày xưa, trong khu rừng nọ có ba loài chim sống với nhau và yêu thương nhau hết mực. Đó là con cò, con công và con vẹt. Một hôm, có ba anh chàng rủ nhau vào rừng săn thú...","cat":"vn"},{"id":"vuong-quoc-chuot","url":"https://truyencotich.top/doc-truyen/vuong-quoc-chuot","title":"Vương quốc chuột","summary":"Ngày xưa, có một vị vua cai quản một vùng đất rộng lớn, ở đấy có rất nhiều chuột sinh sống. Những con chuột này có nguồn thực phẩm dồi dào và sống rất kỉ luật. Chúng không bao giờ phá hoại cuộc sống của con người...","cat":"vn"},{"id":"su-tich-con-dia-con-muoi-va-con-vat","url":"https://truyencotich.top/doc-truyen/su-tich-con-dia-con-muoi-va-con-vat","title":"Sự tích con Đỉa, con Muỗi và con Vắt","summary":"Ngày xửa ngày xưa, ở một buôn làng kia, có một người đàn bà goá chồng, sống với ba đứa con trai còn nhỏ. Gần đó có một con quỷ chuyên hút máu và ăn thịt người, nó rất thèm ăn thịt ba đứa trẻ này. Nhưng những đứa trẻ suốt ngày chỉ ở trong nhà chơi...","cat":"vn"},{"id":"su-tich-cay-thuoc-phien","url":"https://truyencotich.top/doc-truyen/su-tich-cay-thuoc-phien","title":"Sự tích cây thuốc phiện","summary":"Ngày xửa ngày xưa, có vua Đen có tài &quot;bang giao&quot; rất tài giỏi bằng cách cho con gái mình làm dâu các nươc láng giềng. Vua Đen có ba người con gái, đặt tên là công chúa Cả, công chúa Hai và công chúa Ba...","cat":"vn"},{"id":"duc-nguoi","url":"https://truyencotich.top/doc-truyen/duc-nguoi","title":"Đúc người","summary":"Ngày xưa có đức thánh Khổng Lồ, chuyên trông nom về nghề đúc và nghề rèn ở hạ giới. Đức thánh thường thân hành đi lại các nơi; khi giáng xuống miền này, lúc hiện ra xứ nọ, thành người trần, để tìm cách dạy thêm cho những người thợ về kỹ xảo...","cat":"vn"},{"id":"su-tich-hoa-ngo-dong","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-ngo-dong","title":"Sự tích hoa ngô đồng","summary":"Ngày xửa ngày xưa tại một vùng nào đó có một người đàn ông đánh đàn rất hay. Tiếng đàn của người đàn ông hay đến nỗi ai nghe thấy cũng đều phải khen ngợi...","cat":"vn"},{"id":"su-tich-hoa-sim-va-hoa-mua","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-sim-va-hoa-mua","title":"Sự tích hoa Sim và hoa Mua","summary":"Từ thuở xa xưa nước Việt mình bị giống người mắt ti hí ở phương bắc thường xuyên xuống xâm lược, cướp phá, với dã tâm thôn tín người Việt...","cat":"vn"},{"id":"su-tich-ong-nam-cheo","url":"https://truyencotich.top/doc-truyen/su-tich-ong-nam-cheo","title":"Sự tích Ông Năm Chèo","summary":"Truyện kể rằng, khi Phật Thầy Tây An còn tại thế, ông Đình Tây là người thường hầu hạ bên ngài. Một hôm Phật Thầy vì lòng hiếu sinh, đã kêu ông Đình xuống Láng để đỡ đẻ cho một sản phụ trong khi người ấy chỉ ở một mình trong căn chòi giữa đồng...","cat":"vn"},{"id":"con-giun-khon-ngoan","url":"https://truyencotich.top/doc-truyen/con-giun-khon-ngoan","title":"Con Giun khôn ngoan","summary":"Xưa có một người bắt một con Giun nhỏ làm mồi để câu Cá. Khi bị chìm xuống nước, con Giun thấy một con Cá muốn đến đớp, mới bảo Cá rằng...","cat":"vn"},{"id":"ba-chau","url":"https://truyencotich.top/doc-truyen/ba-chau","title":"Bà cháu","summary":"Ngày xửa ngày xưa, ở một làng kia có hai em bé, một trai, một gái. Trai là anh, gái là em. Bố mẹ mất sớm, hai em về sống với bà ngoại. Bà già lắm và cũng nghèo lắm. Ba bà cháu rau cháo nuôi nhau...","cat":"vn"},{"id":"tham-thi-tham","url":"https://truyencotich.top/doc-truyen/tham-thi-tham","title":"Tham thì thâm","summary":"Ngày xưa, trong một làng ven sông Đà có một người rất giàu có, nhưng tính tình tham lam, gian ác. Một hôm, vào tối tháng chạp, có một cụ già rách rưới, không biết từ đâu đến, đi vào làng...","cat":"vn"},{"id":"dan-vit-troi","url":"https://truyencotich.top/doc-truyen/dan-vit-troi","title":"Đàn vịt trời","summary":"Một hôm, Cuội đến Mường Vang chơi. Đi đường mệt, Cuội ngồi nghỉ bên một bờ hồ rộng. Giữa hồ, một đàn vịt trời [3] bơi lội tung tăng. Cuội đếm một con, hai con, … năm con, mười con và nhiều lắm...","cat":"vn"},{"id":"bay-chang-trai","url":"https://truyencotich.top/doc-truyen/bay-chang-trai","title":"Bảy chàng trai","summary":"Ngày xửa ngày xưa, có nhà nọ đã nghèo lại đông con. Bảy người con trai đã lớn mà chưa ai có vợ, ở riêng. Họ làm ăn cật lực, cũng không đủ ăn, chỉ vì thiếu đất phá rẫy làm nương....","cat":"vn"},{"id":"su-tich-con-bim-bip","url":"https://truyencotich.top/doc-truyen/su-tich-con-bim-bip","title":"Sự tích con Bìm Bịp","summary":"Ngày xưa, có một thiếu nữ con nhà khuê các, không hiểu vì duyên cớ gì mà cạo đầu đi tu, rồi lặn lội qua Tây phương tìm Phật. Trải qua rừng sâu núi hiểm, thân gái một mình, nàng chịu biết bao gian nguy cực khổ...","cat":"vn"},{"id":"su-tich-chim-tri-boi-mo","url":"https://truyencotich.top/doc-truyen/su-tich-chim-tri-boi-mo","title":"Sự tích chim Trĩ bới mộ","summary":"Ngày ấy, ở một làng nọ, có hai mẹ con sống đầm ấm bên nhau trong một căn nhà nhỏ dựng sát bìa rừng. Người con trai đã lớn, hàng ngày vác cung nỏ vào rừng săn bắn, còn người mẹ thì chăm sóc vườn nương....","cat":"vn"},{"id":"chang-don-cui-va-ba-vat-quy","url":"https://truyencotich.top/doc-truyen/chang-don-cui-va-ba-vat-quy","title":"Chàng đốn củi và ba vật quý","summary":"Ngày xưa, có một anh chàng nghèo khó sống một thân một mình. Tuy làm việc vất vả nhưng anh vẫn đói rách. Những bông lúa do bàn tay anh vun bón cứ thi nhau chạy về nhà lão trọc phú...","cat":"vn"},{"id":"muoi-hai-thang","url":"https://truyencotich.top/doc-truyen/muoi-hai-thang","title":"Mười hai tháng","summary":"Hiền và Nhàn là hai chị em cùng cha khác mẹ. Từ ngày bố mất, Hiền càng bị dì ghẻ và em ghét bỏ. Mụ dì ghẻ hắt hủi Hiền, chỉ vì Hiền ngoan ngoãn và xinh đẹp, còn Nhàn, con đẻ mụ ta, thì vừa xấu lại vừa ác...","cat":"vn"},{"id":"hon-da-than","url":"https://truyencotich.top/doc-truyen/hon-da-than","title":"Hòn đá thần","summary":"Ngày xưa, có hai vợ chồng ông Lâm, nhà nghèo lại phải nuôi một đàn con năm đứa đang tuổi ăn tuổi chơi. Hai vợ chồng làm lụng hết sức mà vẫn không kiếm đủ sống...","cat":"vn"},{"id":"loai-chim-hoc-xay-to","url":"https://truyencotich.top/doc-truyen/loai-chim-hoc-xay-to","title":"Loài chim học xây tổ","summary":"Một lần, Phượng Hoàng, nhà thông thái nhất trong các loài chim, mở lớp học về cách làm tổ. Phượng Hoàng bắt đầu nói – Việc làm tổ không phải là một chuyện dễ dàng...","cat":"vn"},{"id":"meo-xu-kien","url":"https://truyencotich.top/doc-truyen/meo-xu-kien","title":"Mẹo xử kiện","summary":"Ngày xưa, có một ông quan. Ông ta không ngồi ở công đường chờ dân đưa đơn hầu kiện, mà đi làng này qua làng khác, ai có điều gì oan ức kêu thì ngài xử tại chỗ, không phải chờ ngày này qua tháng khác...","cat":"vn"},{"id":"su-tich-chim-thu-thi-truyen-co-tich-dan-toc-bru","url":"https://truyencotich.top/doc-truyen/su-tich-chim-thu-thi-truyen-co-tich-dan-toc-bru","title":"Sự tích chim Thù Thì - Truyện cổ tích dân tộc Bru","summary":"Có hai anh em nghèo khổ, nhưng lại ngủ quay lưng với nhau, nấu nồi cơm riêng, đốt bếp lửa riêng, nên càng nghèo thêm. Hai người cùng một mẹ sinh ra, nhưng tính tình khác nhau. Người anh tham lam và cáu kỉnh, còn người em thật thà và vụng dại...","cat":"vn"},{"id":"dambri-truyen-co-tich-dan-toc-mnong","url":"https://truyencotich.top/doc-truyen/dambri-truyen-co-tich-dan-toc-mnong","title":"Damb’ri - Truyện cổ tích dân tộc M’nông","summary":"Xưa kia, từ lâu lắm, ở vùng Tây Nguyên có thác Buk So reo vui ca hát đêm ngày. Nhưng vua Prum ở gần đó không thích nghe tiếng thác. Lão bảo tiếng thác reo làm lòng dạ lão rất khó chịu, ăn không ngon, ngủ không yên...","cat":"vn"},{"id":"su-tich-cay-xau-ho","url":"https://truyencotich.top/doc-truyen/su-tich-cay-xau-ho","title":"Sự tích cây xấu hổ","summary":"Ngày xửa ngày xưa, có một cô gái rất đẹp. Xóm làng ai ai cũng trầm trồ khen ngợi. Tên của cô gái là Trinh, hình vóc mảnh mai, dáng đi yểu điệu. Đặc biệt cô có đôi mắt đen huyền che khuất sau đôi hàng lông nheo vừa dài, vừa sậm...","cat":"vn"},{"id":"duong-len-troi","url":"https://truyencotich.top/doc-truyen/duong-len-troi","title":"Đường lên trời","summary":"Ngày xưa, có một chàng trai tốt bụng, khỏe mạnh, làm nương giỏi, đi rừng kiếm củi nhanh gấp đôi kẻ khác mà vẫn đói rách. Anh quyết định đi tìm đường lên trời hỏi xem cớ sao mình phải khổ sở như vậy...","cat":"vn"},{"id":"su-tich-cay-nho-noi","url":"https://truyencotich.top/doc-truyen/su-tich-cay-nho-noi","title":"Sự tích cây Nhọ Nồi","summary":"Ngày xưa ở một làng kia có một cô gái rất xinh. Cô có dáng người mảnh mai, đặc biệt cô có đôi mắt xanh biếc, dài và nhọn. Cô lại khéo tay, chỉ là quần áo nâu sòng, nhưng cô may rất đẹp...","cat":"vn"},{"id":"su-tich-nguoi-lam-chua-muon-loai","url":"https://truyencotich.top/doc-truyen/su-tich-nguoi-lam-chua-muon-loai","title":"Sự tích người làm chúa muôn loài","summary":"Ngày xưa, cõi trời và cõi trần ở rất gần nhau, cũng giống như cõi trần và cõi nước ở liền sát bên nhau vậy. Trong một ngày, tất cả muôn loài ở trên ba cõi đều có thể đi lại chơi bời vài ba bận mà trời vẫn chưa tối...","cat":"vn"},{"id":"truyen-su-tich-hoa-nhai","url":"https://truyencotich.top/doc-truyen/truyen-su-tich-hoa-nhai","title":"Truyện sự tích hoa nhài","summary":"Từ xa xưa trên trái đất khi loài hoa xuất hiện đều khoác trên mình chiếc áo trắng. Ngoài màu trắng thì không có màu sắc nào khác. Sắc trắng nhập tràn khắp mọi nơi làm cho thiên nhiên mang sắc màu đơn điệu...","cat":"vn"},{"id":"ho-kinh-than","url":"https://truyencotich.top/doc-truyen/ho-kinh-than","title":"Hò Kính Thán","summary":"Hò Kính Thán mồ côi cả cha lẫn mẹ từ hồi còn nhỏ. Chàng sống và lớn lên dưới bàn tay chăm sóc của các bác, các chú trong bản. Từ khi lên tám chàng đã phải chăn trâu thuê để kiếm ngày hai bữa...","cat":"vn"},{"id":"truyen-thuyet-ve-con-tau-ben-tre","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-ve-con-tau-ben-tre","title":"Truyền thuyết về Cồn Tàu (Bến Tre)","summary":"Ngày xưa, ở làng chợ Cả Sê bây giờ thuộc tỉnh Mỹ Tho có hai anh em ruột: một người tên là Bảy Giao, một người tên là Chín Quỳ. Cha mẹ họ mất sớm chỉ để lại cho vài mẫu ruộng xấu...","cat":"vn"},{"id":"su-tich-hoa-hue","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-hue","title":"Sự tích hoa Huệ","summary":"Ngày xưa, xưa lắm có một người hay chữ nhưng lại thích lên rừng hái lá thuốc, nhất là tìm kiếm trầm hương để chữa bệnh cứu người. Trầm hương là một thứ nhựa do cây gió tiết ra như thể tự chữa những chỗ cây bị chém, bị gẫy...","cat":"vn"},{"id":"su-tich-ngay-le-vu-lan-bao-hieu","url":"https://truyencotich.top/doc-truyen/su-tich-ngay-le-vu-lan-bao-hieu","title":"Sự tích ngày Lễ Vu Lan báo hiếu","summary":"Ông Ma Ha Một Đặc Già La (thường được gọi là Mục Kiền Liên, gọi tắt là Mục Liên). Vốn là một trong các tu sĩ khác đạo, về sau Mục Liên đã &quot;quy y&quot; cửa Phật và trở thành một đệ tử lớn của cửa Phật, đạt được sáu phép thần thông...","cat":"vn"},{"id":"su-tich-nguoi-trong-cung-trang-truyen-co-dan-toc-dao","url":"https://truyencotich.top/doc-truyen/su-tich-nguoi-trong-cung-trang-truyen-co-dan-toc-dao","title":"Sự tích người trong cung trăng - Truyện cổ dân tộc Dao","summary":"Ngày xưa, có người sinh được hai đứa con trai, đứa nào cũng có sức khỏe hơn người. Một hôm, bố gọi hai đứa con đến ý nói rằng là từ trước đến nay ông ra đã được ăn đủ thứ, duy có thịt thần Sấm là chưa được nếm mùi...","cat":"vn"},{"id":"xin-chon-o-nui-vang","url":"https://truyencotich.top/doc-truyen/xin-chon-o-nui-vang","title":"Xin chôn ở núi vàng","summary":"Xưa có hai vợ chồng một anh nông dân nghèo phát được miếng rẫy ở bìa rừng để trỉa ngô. Khi ngô đã có bắp non thì ngày nào khỉ cũng kéo nhau đến ăn. Vợ chồng anh phải canh giữ rất vất vả...","cat":"vn"},{"id":"chang-re-cop","url":"https://truyencotich.top/doc-truyen/chang-re-cop","title":"Chàng rể cọp","summary":"Chuyện cổ của người Dao kể rằng, xưa kia có một ông vua sinh được ba người con gái xinh đẹp. Có nhiều võ quan đến xin làm rể...","cat":"vn"},{"id":"giac-mo-cua-pho-ma","url":"https://truyencotich.top/doc-truyen/giac-mo-cua-pho-ma","title":"Giấc mơ của phò mã","summary":"Xưa có hai thầy khóa cùng ở một làng. Một người tên là Thiện, người kia tên là Đoàn. Cả hai cùng văn chương lỗi lạc, cùng chữ đẹp như rồng bay phượng múa, lại cùng yêu một cô hàng xóm xinh đẹp...","cat":"vn"},{"id":"nang-tien-trong-nga-voi","url":"https://truyencotich.top/doc-truyen/nang-tien-trong-nga-voi","title":"Nàng tiên trong ngà voi","summary":"Ngày xưa, có một nhà kia sinh được ba người con, hai trai và một gái. Rôn là con trai lớn, làm ăn rất siêng năng, săn bắn giỏi. Ngày nào anh cũng mang về hai ba chục con sóc, con chuột, con rắn mối...","cat":"vn"},{"id":"ai-tot-hon-ai","url":"https://truyencotich.top/doc-truyen/ai-tot-hon-ai","title":"Ai tốt hơn ai?","summary":"Thời trước có hai anh em, cha mẹ mất sớm, sống với nhau rất êm ấm. Hai người làm việc chung với nhau và ăn ở cùng một nhà...","cat":"vn"},{"id":"vuong-quoc-vang-nu-cuoi","url":"https://truyencotich.top/doc-truyen/vuong-quoc-vang-nu-cuoi","title":"Vương quốc vắng nụ cười","summary":"Ngày xửa ngày xưa, có một vương quốc buồn chán kinh khủng chỉ vì cư dân ở đó không ai biết cười. Nói chính xác là chỉ có rất ít trẻ con cười được, còn người lớn thì hoàn toàn không...","cat":"vn"},{"id":"anh-kho-lam-quan-thuong-thu","url":"https://truyencotich.top/doc-truyen/anh-kho-lam-quan-thuong-thu","title":"Anh khờ làm quan thượng thư","summary":"Ngày xưa, có một người tiều phu sống với vợ mình ở một vùng núi non hẻo lánh. Để kiếm miếng ăn hàng ngày, anh phải làm việc cực nhọc ở trong rừng...","cat":"vn"},{"id":"ong-trang-noi","url":"https://truyencotich.top/doc-truyen/ong-trang-noi","title":"Ông trạng Nồi","summary":"Thuở xưa, có một chàng trai nhà nghèo lắm, hàng ngày phải đi kiếm củi lấy tiền ăn học. Chàng rất thông minh và ham học...","cat":"vn"},{"id":"chang-re-hay-chu","url":"https://truyencotich.top/doc-truyen/chang-re-hay-chu","title":"Chàng rể hay chữ","summary":"Một phú hộ muốn chọn cho con gái cưng của mình một người chồng hay chữ. Ở cùng làng có một anh nông dân mồ côi cha mẹ, hằng ngày anh ta phải đi cày thuê cuốc mướn, cuộc sống vất vả mà cũng không đủ ăn.","cat":"vn"},{"id":"nang-nguyen-thi-bich-chau","url":"https://truyencotich.top/doc-truyen/nang-nguyen-thi-bich-chau","title":"Nàng Nguyễn Thị Bích Châu","summary":"Thời Trần, có nàng Nguyễn Thị Bích Châu là vợ vua Duệ Tông. Nàng có nhan sắc xinh đẹp, hơn nữa lại văn hay chữ tốt, trong cung đình nhà vua khó có phi tần nào sánh kịp.","cat":"vn"},{"id":"ta-nguoi-cho-hoa-tra","url":"https://truyencotich.top/doc-truyen/ta-nguoi-cho-hoa-tra","title":"Tạ người cho hoa trà","summary":"Tương truyền khi Lê Hoan là tuần phủ Hưng Yên đứng ra tổ chức cuộc thi thơ vịnh “Kiều” ở Tao đàn Hưng Yên năm 1905, hắn có mời Nguyễn Khuyến vào ban chấm thi.","cat":"vn"},{"id":"thay-thuoc-gioi-cot-o-tam-long","url":"https://truyencotich.top/doc-truyen/thay-thuoc-gioi-cot-o-tam-long","title":"Thầy thuốc giỏi cốt ở tấm lòng","summary":"Cụ tổ bên ngoại của Trừng, người họ Phạm, húy là Bân, có nghề y gia truyền, giữ chức Thái y lệnh để phụng sự Trần Anh Vương. Ngài đem hết của cải trong nhà ra mua các loại thuốc tốt và tích trữ thóc gạo.","cat":"vn"},{"id":"quan-he","url":"https://truyencotich.top/doc-truyen/quan-he","title":"Quận he","summary":"Vào thời nhà Lê, có hai vợ chồng một nhà nghèo ở làng Đồng Lùi, sinh được một người con trai đặt tên là Nguyễn Hữu Cầu. Thuở trẻ, Cầu mồ côi bố, người mẹ túng bấn phải cho chàng đi ở, nhưng sau cũng cố gắng cho đi học.","cat":"vn"},{"id":"doi-bo-gay-lay-bo-beo","url":"https://truyencotich.top/doc-truyen/doi-bo-gay-lay-bo-beo","title":"Ðổi bò gầy lấy bò béo","summary":"Lệ làng đặt ra, các nhà có bò đều dặn con hoặc người ở hết sức giữ gìn. Xiển có một con bò ốm, gầy như cái mo khô, cứ thả cho ăn ở gần đấy...","cat":"vn"},{"id":"phung-hung-danh-ho","url":"https://truyencotich.top/doc-truyen/phung-hung-danh-ho","title":"Phùng Hưng đánh hổ","summary":"Vào khoảng đầu mùa hạ. Chưa năm nào động rừng như vậy. Thú dữ nhan nhản kéo về Đường Lâm, hết bầy này đến lũ khác. Nhưng rồi chỉ một dạo là tất cả đã phải bạt đi miền khác, bởi khiếp oai một con hổ không biết từ đâu tới.","cat":"vn"},{"id":"guom-ong-tu","url":"https://truyencotich.top/doc-truyen/guom-ong-tu","title":"Gươm ông Tú","summary":"Năm ấy, có một tên bạo chúa ở vùng biển xa bỗng nhiên kéo quân đánh lên vùng rừng núi của người Bana...","cat":"vn"},{"id":"chon-cua","url":"https://truyencotich.top/doc-truyen/chon-cua","title":"Chôn của","summary":"Ngày xưa có hai anh em một nhà rất nghèo, ngày ngày vào rừng kiếm củi, hái rau về bán để sinh sống. Trong nhà có một con chó cái, đẻ ra một con chó trắng chỉ có ba chân...","cat":"vn"},{"id":"ong-to-nghe-theu","url":"https://truyencotich.top/doc-truyen/ong-to-nghe-theu","title":"Ông tổ nghề thêu","summary":"Chuyện cũ kể rằng, hồi còn nhỏ tuổi, cậu bé Trần Quốc Khái vốn là một thiếu niên rất ham học. Cậu học ngay cả khi đi đốn củi, lúc kéo vó tôm...","cat":"vn"},{"id":"than-go","url":"https://truyencotich.top/doc-truyen/than-go","title":"Thần gỗ","summary":"Xưa kia, vùng này chỉ có đồi trọc, đồi tranh, đồi sim hoặc tre nữa. Không có gỗ, phải dựng lều mà ở. Mưa to gió lớn là lều đổ. Những nhà giàu có phải đi chặt gỗ ở rừng xa, đài tải về, công phu và tốn kém.","cat":"vn"},{"id":"chang-rua","url":"https://truyencotich.top/doc-truyen/chang-rua","title":"Chàng Rùa","summary":"Ngày xưa có hai vợ chồng nhà kia hiếm hoi mãi mới sinh được một đứa con lại là một chú Rùa bé tí ti...","cat":"vn"},{"id":"su-tich-con-kien-duong","url":"https://truyencotich.top/doc-truyen/su-tich-con-kien-duong","title":"Sự tích con kiến Dương","summary":"Thuở xưa ở một làng nọ có anh chàng họ Dương, rất keo kiệt và lười biếng. Tối ngày chỉ rong chơi đây đó và la cà những nơi đình đám để kiếm ăn.","cat":"vn"},{"id":"su-tich-cay-gao","url":"https://truyencotich.top/doc-truyen/su-tich-cay-gao","title":"Sự tích cây Gạo","summary":"Ngày xưa, xưa, xưa… có một chàng họa sĩ trẻ có tài. Chàng không chỉ có tài vẽ mà còn đoán được người mình vẽ đang lo nghĩ gì, mơ ước gì để vẽ ra.","cat":"vn"},{"id":"truyen-thuyet-cay-gao","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-cay-gao","title":"Truyền thuyết cây gạo","summary":"Trình Trung Ngộ là một chàng trai đẹp ở đất Bắc Hà, nhà rất giàu, thuê thuyền xuống vùng nam buôn bán. Chàng thường đỗ thuyền ở dưới cầu Liễu Khê rồi đi lại vào chợ Nam Xang.","cat":"vn"},{"id":"pham-vien-thanh-tien","url":"https://truyencotich.top/doc-truyen/pham-vien-thanh-tien","title":"Phạm Viên thành tiên","summary":"Ngày xưa, vào đời nhà Lê, ở huyện Đông Thành, có nhà họ Phạm sinh được hai con trai là Phạm Chất và Phạm Viên.","cat":"vn"},{"id":"lac-long-quan-diet-ngu-tinh","url":"https://truyencotich.top/doc-truyen/lac-long-quan-diet-ngu-tinh","title":"Lạc Long Quân diệt Ngư Tinh","summary":"Xưa kia ở vùng biển Nam Hải (Biển Đông hiện nay, Nam Hải là cách phương Bắc gọi vùng biển chủ quyền của Đại Việt ngày xưa) có loài thuồng luồng ba ba luôn ngày ngày rình rập, làm lật thuyền hoặc bắt ngư dân ăn thịt.","cat":"vn"},{"id":"ong-nguyen-khoa-dang","url":"https://truyencotich.top/doc-truyen/ong-nguyen-khoa-dang","title":"Ông Nguyễn Khoa Đăng","summary":"Ngày xưa, có nội tán Nguyễn Khoa Đăng là người có tài xử đoán. Khi còn làm một chức quan nhỏ, ông đến trị nhậm hạt nào thường được mọi người mến phục...","cat":"vn"},{"id":"dinh-bo-linh-dep-loan-12-su-quan","url":"https://truyencotich.top/doc-truyen/dinh-bo-linh-dep-loan-12-su-quan","title":"Đinh Bộ Lĩnh dẹp loạn 12 sứ quân","summary":"Lại một hôm, trong lúc cờ lau tập trận, đoàn trẻ chăn trâu Hoa Lư được tin lũ trẻ sách bên đang đi về phía chúng. Lập tức Bộ Lĩnh cho dàn trận, còn mình thì leo lên một mỏm đá đứng chỉ huy, tay cầm bông lau làm cờ hiệu...","cat":"vn"},{"id":"cuoi-gio-manh-dap-song-du","url":"https://truyencotich.top/doc-truyen/cuoi-gio-manh-dap-song-du","title":"Cưỡi gió mạnh, đạp sóng dữ...","summary":"Thuở ấy, nước ta bị giặc Ngô bên Trung Quốc đô hộ. Giặc Ngô tham tàn bạo ngược, vơ vét của cải, ức hiếp dân lành. Đất nước tiêu điều, xơ xác, lòng dân oán hận, căm hờn.","cat":"vn"},{"id":"vi-su-than-thong-minh","url":"https://truyencotich.top/doc-truyen/vi-su-than-thong-minh","title":"Vị sứ thần thông minh","summary":"Được tin tiến sĩ Nguyễn Duy Thì sẽ dẫn đầu đoàn sứ thần Đại Việt sang nước Minh, vua quan nhà Minh bàn kế thử tài viên chánh sứ 35 tuổi, nổi tiếng tài cao","cat":"vn"},{"id":"ngo-quyen-dai-pha-quan-nam-han","url":"https://truyencotich.top/doc-truyen/ngo-quyen-dai-pha-quan-nam-han","title":"Ngô Quyền đại phá quân Nam Hán","summary":"Ông quê ở Đường Lâm (Ba Vì, Hà Nội ngày nay), là người mưu lược, sức khoẻ vô song. Sau, làm nha tướng cho Dương Đình Nghệ, được Dương Đình Nghệ gả con gái cho, lại cho quyền cai quản Ái Châu (Thanh Hoá ngày nay).","cat":"vn"},{"id":"chu-be-than-dong","url":"https://truyencotich.top/doc-truyen/chu-be-than-dong","title":"Chú bé thần đồng","summary":"Một hôm, nhà ông nghè Lê Trọng Thứ có khách quý tới thăm. Mấy tuần trà đậm đã qua, đến khi chủ nhân toan nhấc chiếc bình nước mưa để rót thêm vào chiếc ấm đồng đang đặt trên bếp than hồng thì chợt nhận ra nước đã cạn.","cat":"vn"},{"id":"su-tich-song-cuu-long","url":"https://truyencotich.top/doc-truyen/su-tich-song-cuu-long","title":"Sự tích sông Cửu Long","summary":"Cửu Long có nhiều tên, trong đó một tên rất quen thuộc với Việt Nam cũng như trên thế giới là sông Công. Công, tiếng Lào Thái có nghĩa là “chờ”. Tại sao lại gọi sông Chờ? Có một sự tích lí thú kể ra như sau...","cat":"vn"},{"id":"su-gia-hoa-binh","url":"https://truyencotich.top/doc-truyen/su-gia-hoa-binh","title":"Sứ giả hòa bình","summary":"Chiêu Văn Vương Trần Nhật Duật là hoàng tử thứ 6 con vua Trần Thái Tông. Ông nổi tiếng thông minh, hiểu nhiều biết rộng.","cat":"vn"},{"id":"lam-van-duoi-ca-sau","url":"https://truyencotich.top/doc-truyen/lam-van-duoi-ca-sau","title":"Làm văn đuổi cá sấu","summary":"Nguyễn Thuyên người ở Vũ Ẻn, phủ Thanh Ba (Phú Thọ), là thượng thư bộ Hình thời nhà Trần. Được vua giao soạn thảo bộ Hình thư, ông thường về các địa phương nghe ngóng dân tình, xem xét việc xử kiện.","cat":"vn"},{"id":"su-tich-cau-noi-con-ga-cuc-tac-la-chanh","url":"https://truyencotich.top/doc-truyen/su-tich-cau-noi-con-ga-cuc-tac-la-chanh","title":"Sự tích câu nói &quot;Con gà cục tác lá chanh...&quot;","summary":"Xưa có một nhà thật giàu có, ruộng nhiều, trâu bò lắm. Phải một hôm đến hơn mười con vừa trâu vừa bò lạc đi đâu mất cả. Sau nhờ bà con láng giềng lùng đi tìm mãi mới lại thấy đủ.","cat":"vn"},{"id":"truyen-thuyet-ve-cai-noi","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-ve-cai-noi","title":"Truyền thuyết về cái nồi","summary":"Trong một quả đồi lớn ở Arnol gần làng Barvas có rất nhiều ma quái. Bọn chúng thường đi bộ đến chơi nhà một gia đình nông dân ở ngay dưới chân núi cách quả đồi không xa.","cat":"vn"},{"id":"le-chan","url":"https://truyencotich.top/doc-truyen/le-chan","title":"Lê Chân","summary":"Công chúa là con gái trưởng vua Trần Thánh Tông, chị gái vua Nhân Tông, vốn tên húy là Trần Quỳnh Nga. Công chúa có dung nhan tuyệt thế, đủ tài thi họa ca ngâm, được phong Thái trưởng công chúa Thiên Thụy.","cat":"vn"},{"id":"thay-lang-bat-dac-di","url":"https://truyencotich.top/doc-truyen/thay-lang-bat-dac-di","title":"Thầy lang bất đắc dĩ","summary":"Ngày xưa có một anh chàng tên là Tân làm nghề cày ruộng. Anh là người thông minh nhưng tính tình có phần nhút nhát, lại phải cái hay phũ phàng với vợ. Người vợ căm lắm, quyết tìm dịp báo thù cho bõ ghét.","cat":"vn"},{"id":"anh-em-ho-dien","url":"https://truyencotich.top/doc-truyen/anh-em-ho-dien","title":"Anh em họ Điền","summary":"Ngày xưa, có giòng họ Điền, anh em ăn ở với nhau từ đời nọ sang đời kia rất là hòa thuận. Về sau, họ này chỉ còn lại có ba anh em. Ba người vẫn chung sống với nhau vui vẻ tử tế, cho đến khi người thứ hai lấy vợ.","cat":"vn"},{"id":"ca-bong-nuot-ca-tre","url":"https://truyencotich.top/doc-truyen/ca-bong-nuot-ca-tre","title":"Cá bống nuốt cá trê","summary":"Ngày xưa có một anh chàng ăn cắp rất tài, hễ biết ai có vàng bạc thì dù cất giấu cẩn thận đến đâu hắn ta cũng rình mò lấy cho bằng được. Hắn thường thi thố thủ đoạn của hắn ở các phiên chợ.","cat":"vn"},{"id":"su-tich-tro-choi-nem-con-ngay-xuan","url":"https://truyencotich.top/doc-truyen/su-tich-tro-choi-nem-con-ngay-xuan","title":"Sự tích trò chơi ném còn ngày xuân","summary":"Ngày xưa có chàng mồ côi tên là Pịa. Cha mẹ Pịa mất từ ngày nào không biết, chú bác, cô dì, cậu mợ, anh chị em của Pịa là ai người ta cũng không hay...","cat":"vn"},{"id":"cay-choi-yeu-tinh","url":"https://truyencotich.top/doc-truyen/cay-choi-yeu-tinh","title":"Cây chổi yêu tinh","summary":"Lâu ngày thành yêu, vật nào cũng thế, không những chỉ có vàng và ngọc… Như trong vườn hoang ở một ấp kia có một tòa miếu cổ xây bằng gạch. Ðằng trước có một cửa nhỏ, chỉ vừa một người ra vào, bên trong chỉ rộng bằng một chiếc chiếu.","cat":"vn"},{"id":"su-tich-hoa-cai-vang","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-cai-vang","title":"Sự tích hoa Cải Vàng","summary":"Ngày xưa, xưa, xưa, tại vùng đồi núi nọ, có một cụ già chỉ bán dao kéo mà nổi tiếng khắp gần xa. Không ôi biết ông cụ ở đâu. Cũng không biết ông đi mua dao kéo hay làm ra dao kéo để bán.","cat":"vn"},{"id":"su-tich-hoa-van-tho","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-van-tho","title":"Sự tích hoa Vạn Thọ","summary":"Ngày xưa có một em bé nghèo, mẹ mất sớm nên chỉ được sống với cha. Cha là chỗ để em nương tựa, nhưng cũng là người em phải chăm sóc, vì từ ngày mẹ không còn, cha em thường bị ốm đau luôn...","cat":"vn"},{"id":"su-tich-cay-hoa-dai","url":"https://truyencotich.top/doc-truyen/su-tich-cay-hoa-dai","title":"Sự tích cây hoa Đại","summary":"Ngày xưa, có một em bé nghèo, rất thương mẹ mà đành phải xa mẹ, đi ở cho một lão đồ tể chuyên giết lợn. Lão đồ tể ngày ngày bắt em lên rừng kiếm củi thể đun nước giết lợn, cạo lông.","cat":"vn"},{"id":"chim-luu-la-hay-la-su-tich-cay-bong-lau","url":"https://truyencotich.top/doc-truyen/chim-luu-la-hay-la-su-tich-cay-bong-lau","title":"Chim lưu lá (Hay là sự tích cây Bông Lau)","summary":"ngày xưa, xưa lắm, có một cụ già rất yêu chim Cụ yêu nhất là những tiếng chim hót hay. Cụ đã yêu và sống với những tiếng hót ấy từ lúc tóc còn xanh. Bây giờ thì tóc cụ đã bạc trắng.","cat":"vn"},{"id":"su-tich-qua-mo","url":"https://truyencotich.top/doc-truyen/su-tich-qua-mo","title":"Sự tích quả Mơ","summary":"Ngày xưa, xưa lắm, có một người trẻ tuổi rất có tài làm thơ. Bố của ông trước kia lại là một thày thuốc giỏi. Vì vậy, ông cũng học được cả nghề bốc thuốc chữa bệnh. ông yêu một cô gái ở thôn bên cạnh.","cat":"vn"},{"id":"su-tich-qua-loong-boong","url":"https://truyencotich.top/doc-truyen/su-tich-qua-loong-boong","title":"Sự tích quả Loòng Boong","summary":"Ở miền Trung, có một giống cây tên gọi là loòng boong. Quả loòng boong chỉ lớn hơn quả hồng bì một tí. Da nó vàng mát. Cùi nó nhìn trong trong như ngọc và đặc biệt quả nào cũng có mang một cái dấu như móng tay của ôi đó bấm vào.","cat":"vn"},{"id":"chu-be-nguoi-va-ong-trang","url":"https://truyencotich.top/doc-truyen/chu-be-nguoi-va-ong-trang","title":"Chú bé Người và ông Trăng","summary":"Vào cái thời xa xưa, có lẽ là xa xưa nhất của con người, ở trên trời chỉ có mặt trời mà chưa có mặt trăng, và ở dưới đất thì con người sống trong hang, trong hốc.","cat":"vn"},{"id":"cai-am-dat","url":"https://truyencotich.top/doc-truyen/cai-am-dat","title":"Cái ấm đất","summary":"Ngày xưa có một người cự phú xứ quê ốm nặng và biết mình thế nào cũng sẽ từ trần liền gọi ba con trai đến bên giường mà bảo rằng: Cha sinh được ba con, nhờ trời cùng khỏe mạnh và nết na.","cat":"vn"},{"id":"cat-nha-giua-ho","url":"https://truyencotich.top/doc-truyen/cat-nha-giua-ho","title":"Cất nhà giữa hồ","summary":"Ngày xưa, ở trên Tây Nguyên, có một em bé tên là Mây. Mây không còn cha để gọi a-ma, cũng không còn mẹ để gọi a-mí. Đã vậy, Mây còn phải đi ở cho tên chúa làng....","cat":"vn"},{"id":"co-tuy-tam","url":"https://truyencotich.top/doc-truyen/co-tuy-tam","title":"Cỏ tuý tâm","summary":"MỘT LÁI BUÔN ĐI MUA HÀNG, khi trở về nhà thì trời đã muộn. Thế là anh ta bước vào một quán trọ nhỏ, đặt tay nải đựng hàng hoá ở một góc quán, bảo nữ chủ quán làm cơm chiều cho mình, và cho nghỉ trọ một đêm.","cat":"vn"},{"id":"tam-tham-bay","url":"https://truyencotich.top/doc-truyen/tam-tham-bay","title":"Tấm thảm bay","summary":"Chàng Linh thích rong chơi đây đó, vậy nên khi thu hoạch mùa màng xong thì chàng đeo tay nải lên đường. Vừa đi vừa hát ngắm cảnh, khi hết thức ăn thì chàng ngừng lại xin phụ giúp công việc cho người ta để kiếm lương thực...","cat":"vn"},{"id":"pham-ong-va-tieu-phu","url":"https://truyencotich.top/doc-truyen/pham-ong-va-tieu-phu","title":"Phạm Ông và Tiều Phu","summary":"Cáo quan, Phạm Ông về dựng một ngôi nhà gỗ năm gian xinh xắn trên đất của cụ Tổ để lại gần bờ sông Lau, hương Hạ Đan. Mảnh đất giàu phù sa, mầu mỡ, cây cối tốt tươi, mùa nào quả ấy.","cat":"vn"},{"id":"nhung-chu-cai-anh-em","url":"https://truyencotich.top/doc-truyen/nhung-chu-cai-anh-em","title":"Những chữ cái anh em","summary":"Hai anh em học hành chăm chỉ giỏi giang nhưng nhà nghèo, cha mẹ già đau bệnh liên miên. Cuộc sống ngày càng khó khăn, phải đi làm thuê kiếm tiền mua gạo và thuốc nên hai anh em bàn với nhau mỗi người đi học một ngày rồi nghỉ một ngày.","cat":"vn"},{"id":"nguoi-me-ke-va-hai-con-trai","url":"https://truyencotich.top/doc-truyen/nguoi-me-ke-va-hai-con-trai","title":"Người mẹ kế và hai con trai","summary":"Nhà nọ, vợ chết sớm để lại một đứa con trai còn nhỏ dại. Người chồng lấy vợ kế, lại cũng sinh được thêm một thằng con trai. Nhưng chẳng bao lâu thì chồng chết. Người mẹ kế tần tảo nuôi hai đứa con trai khôn lớn.","cat":"vn"},{"id":"ech-kien-co-lua","url":"https://truyencotich.top/doc-truyen/ech-kien-co-lua","title":"Ếch kiện Cò Lửa","summary":"Ngày xưa, cánh đồng dưới triền núi nọ có con Ếch và con Cò Lửa cùng làm ăn với nhau. Ếch chăm chỉ cần mẫn hăng hái bắt sâu bọ nuôi con cái và tham gia bảo vệ mùa màng.","cat":"vn"},{"id":"dan-con-hoa-khi","url":"https://truyencotich.top/doc-truyen/dan-con-hoa-khi","title":"Đàn con hoá khỉ","summary":"Ngày ấy, ở một bản nọ, có đôi vợ chồng mơ ước có nhiều con. Chồng nói với vợ: Giàu của không bằng giàu con. Em hãy sinh cho anh mười hai đứa con em nhé!","cat":"vn"},{"id":"truyen-thuyet-ve-ma-tranh","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-ve-ma-tranh","title":"Truyền thuyết về Ma Trành","summary":"Người ta nói, đuôi hổ chính là bùa hộ mệnh của giống mình sọc, miễn là hổ còn đuôi, hổ sẽ không bao giờ bị bắt, tại sao lại thế ? Vì trên đuôi hổ, trú ngụ một giống, gọi là Hổ Trành.","cat":"vn"},{"id":"chang-co-ho-va-cong-chua-nai-to-luy","url":"https://truyencotich.top/doc-truyen/chang-co-ho-va-cong-chua-nai-to-luy","title":"Chàng Cơ-Ho và Công Chúa Nai Tơ-Lúy","summary":"Ngày ấy, trên những vùng núi Tây Nguyên bát ngát có những bộ tộc người sống thành những buôn làng. Họ cùng nhau làm rẫy, làm ruộng, vào rừng săn bắn và xuống suối mò tôm cá.","cat":"vn"},{"id":"chuyen-nguoi-nghia-phu-o-khoai-chau","url":"https://truyencotich.top/doc-truyen/chuyen-nguoi-nghia-phu-o-khoai-chau","title":"Chuyện người nghĩa phụ ở Khoái Châu","summary":"Từ Đạt ở Khoái Châu, lên làm quan tại thành Đông Quan thuê nhà ở cạnh cầu Đồng Xuân, láng giềng với nhà quan Thiêm thư là Phùng Lập Ngôn. Phùng giầu mà Từ nghèo, Phùng xa hoa mà Từ tiết kiệm, Phùng chuộng dễ dãi mà Từ thì giữ lễ.","cat":"vn"},{"id":"cau-chuyen-o-den-hang-vuong","url":"https://truyencotich.top/doc-truyen/cau-chuyen-o-den-hang-vuong","title":"Câu chuyện ở đền Hạng Vương","summary":"Quan Thừa chỉ Hồ Tông Thốc [1] là người hay thơ, lại giỏi lối mỉa mai giễu cợt, khoảng cuối đời Trần, phụng mệnh sang Trung Quốc, nhân đi qua đền Hạng vương có đề một bài thơ....","cat":"vn"},{"id":"chuyen-ga-tra-dong-giang-sinh","url":"https://truyencotich.top/doc-truyen/chuyen-ga-tra-dong-giang-sinh","title":"Chuyện gã trà đồng giáng sinh","summary":"Dương Đức Công tên là Tạc, người phủ Thường Tín xứ Sơn Nam. Về triều vua Huệ Tông nhà Lý, ông làm quan coi việc hình án trấn Tuyên Quang [3] xét rõ mọi điều oan khuất, khiến các vụ án đều được công bằng...","cat":"vn"},{"id":"chuyen-ki-ngo-o-trai-tay","url":"https://truyencotich.top/doc-truyen/chuyen-ki-ngo-o-trai-tay","title":"Chuyện kì ngộ ở trại Tây","summary":"Hà Nhân, người học trò quê ở Thiên Trường, khoảng năm Thiệu Bình ngụ ở kinh sư để tòng học cụ Ức Trai. Mỗi buổi đi học, đường tất phải qua phường Khúc Giang. Trong phường có cái trại, gọi là trại Tây, dinh cơ cũ của quan Thái sư triều Trần.","cat":"vn"},{"id":"chuyen-doi-tung-o-long-cung","url":"https://truyencotich.top/doc-truyen/chuyen-doi-tung-o-long-cung","title":"Chuyện đối tụng ở long cung","summary":"Huyện Vĩnh Lại ở Hồng Châu khi xưa có nhiều giống thủy tộc. Men sông người ta lập đền thờ đến hơn mười chỗ. Năm tháng dần lâu, có chỗ linh thiêng thành yêu; song cầu tạnh đảo mưa đều rất linh ứng...","cat":"vn"},{"id":"chuyen-nghiep-oan-cua-dao-thi","url":"https://truyencotich.top/doc-truyen/chuyen-nghiep-oan-cua-dao-thi","title":"Chuyện nghiệp oan của Đào Thị","summary":"Ả danh kỹ ở Từ Sơn là Đào Thị, tiểu tự Hàn Than, thông hiểu âm luật và chữ nghĩa. Niên hiệu Thiệu Phong thứ năm (1345) đời nhà Trần, nàng được tuyển sung vào làm cung nhân, hằng ngày chầu vua ở tiệc rượu hay ở chiếu bạc.","cat":"vn"},{"id":"cuoc-noi-chuyen-tho-o-kim-hoa","url":"https://truyencotich.top/doc-truyen/cuoc-noi-chuyen-tho-o-kim-hoa","title":"Cuộc nói chuyện thơ ở Kim Hoa","summary":"Huyện Kim Hoa có người con gái họ Ngô tên Chi Lan, là bậc nội trợ hiền của vị tiên sinh họ Phù. Nàng chữ tốt văn hay, nhất là thơ ca càng giỏi lắm. Đức Thuần hoàng đế (Thánh Tông) triều nhà Lê yêu tài văn mặc...","cat":"vn"},{"id":"chuyen-nang-thuy-tieu","url":"https://truyencotich.top/doc-truyen/chuyen-nang-thuy-tieu","title":"Chuyện nàng Thúy Tiêu","summary":"Dư Nhuận Chi người đất Kiến Hưng, tên là Tạo Tân, có tiếng hay thơ; nhất là về những bài hát, lại càng nức danh ở kinh kỳ, mỗi bài làm ra, phường hát bội đem tiền tặng biếu rất hậu để xin lấy. Nhân thế Dư càng nổi thanh giá ở chốn tao đàn.","cat":"vn"},{"id":"chuyen-cai-chua-hoang-o-huyen-dong-trieu","url":"https://truyencotich.top/doc-truyen/chuyen-cai-chua-hoang-o-huyen-dong-trieu","title":"Chuyện cái chùa hoang ở huyện Đông Triều","summary":"Đời nhà Trần, tục tin thần quỷ, thần từ, phật tử chẳng đâu là không có. Các chùa như chùa Hoàng Giang, chùa Đồng Cổ, chùa An Sinh, chùa An Tử, chùa Phổ Minh, quán Ngọc Thanh dựng lên nhan nhản khắp nơi...","cat":"vn"},{"id":"chuyen-tuong-da-xoa","url":"https://truyencotich.top/doc-truyen/chuyen-tuong-da-xoa","title":"Chuyện tướng Dạ Xoa","summary":"Kẻ kỳ sĩ ở hạt Quốc Oai, họ Văn tên là Dĩ Thành tính tình hào hiệp, không chịu để ma quỷ mê hoặc. Phàm những hoa yêu nguyệt quái, và dâm thần lệ quỷ không được liệt vào tự điển, chàng đều coi thường không sợ hãi gì.","cat":"vn"},{"id":"chuyen-chuc-phan-su-o-den-tan-vien","url":"https://truyencotich.top/doc-truyen/chuyen-chuc-phan-su-o-den-tan-vien","title":"Chuyện chức phán sự ở đền Tản Viên","summary":"Ngô Tử Văn tên là Soạn, người huyện Yên Dũng đất Lang Giang. Chàng vốn khẳng khái nóng nẩy, thấy sự tà gian thì không thể chịu được, vùng bắc người ta vẫn khen là một người cương phương.","cat":"vn"},{"id":"chuyen-bua-tiec-dem-o-da-giang","url":"https://truyencotich.top/doc-truyen/chuyen-bua-tiec-dem-o-da-giang","title":"Chuyện bữa tiệc đêm ở Đà Giang","summary":"Năm Bính Dần (1386), vua Trần Phế đế đi săn, đỗ lại trên bờ bắc sông Đà, đêm mở bữa tiệc ở trong trướng. Có một con cáo từ dưới chân núi đi về phía nam, gặp một con vượn già...","cat":"vn"},{"id":"chuyen-doi-dap-cua-nguoi-tieu-phu-o-nui-na","url":"https://truyencotich.top/doc-truyen/chuyen-doi-dap-cua-nguoi-tieu-phu-o-nui-na","title":"Chuyện đối đáp của người tiều phu ở núi Na","summary":"Đất Thanh Hóa phần nhiều là núi, bát ngát bao la đến mấy nghìn dặm. Trong đó có một ngọn núi cao chót vót, tên gọi là núi Na. Núi có cái động, dài mà hẹp, hiểm trở mà quạnh hiu, bụi trần không bén tới, chân người không bước tới.","cat":"vn"},{"id":"chuyen-yeu-quai-o-xuong-giang","url":"https://truyencotich.top/doc-truyen/chuyen-yeu-quai-o-xuong-giang","title":"Chuyện yêu quái ở Xương Giang","summary":"Ở Phong Châu có người họ Hồ tên là Kỳ Vọng. Cuối đời họ Hồ, Kỳ Vọng đi buôn bán, ngụ ở thành Xương Giang, rồi ốm chết ở thành ấy. Người vợ nghèo kiết, không có tiền để đưa ma chồng về quê.","cat":"vn"},{"id":"chuyen-le-nuong","url":"https://truyencotich.top/doc-truyen/chuyen-le-nuong","title":"Chuyện Lệ Nương","summary":"Nguyễn Thị Diễm là người một họ lớn ở huyện Đông Sơn em họ ngoại của Trần Khát Chân; cùng người đàn bà họ Lý quê ở huyện Cẩm Giàng, cùng mở ngôi hàng bán phấn đối cửa nhau tại bên ngoài thành Tây Đô...","cat":"vn"},{"id":"chuyen-ly-tuong-quan","url":"https://truyencotich.top/doc-truyen/chuyen-ly-tuong-quan","title":"Chuyện Lý tướng quân","summary":"Vua Giản Định nhà Hậu Trần lên ngôi ở Mô Độ, hào kiệt bốn phương, gần xa hưởng ứng, đều chiêu tập đồ đảng làm quân Cần Vương. Người huyện Đông Thành là Lý Hữu Chi cũng do chân một người làm ruộng nổi lên...","cat":"vn"},{"id":"chuyen-pham-tu-hu-len-choi-thien-tao","url":"https://truyencotich.top/doc-truyen/chuyen-pham-tu-hu-len-choi-thien-tao","title":"Chuyện Phạm Tử Hư lên chơi thiên tào","summary":"Phạm Tử Hư quê ở Cẩm Giàng, là một người tuấn sảng hào mại không ưa kiềm thúc. Theo học nhà xử sĩ Dương Trạm; Trạm thường răn Tử Hư về cái tính hay kiêu căng. Từ đấy chàng cố sức sửa đổi, trở nên người có đức tính tốt.","cat":"vn"},{"id":"su-tich-con-kien","url":"https://truyencotich.top/doc-truyen/su-tich-con-kien","title":"Sự tích con Kiến","summary":"Ngày xưa có một người nọ vì nghèo đói quá phải đi hành khất. Nhưng đi đến đâu người ta cũng trề môi bảo: “Sức bác khỏe còn hơn trâu, sao không chịu làm mà kiếm ăn? Rõ đồ lười biếng!”","cat":"vn"},{"id":"chang-trang-truyen-co-mnong","url":"https://truyencotich.top/doc-truyen/chang-trang-truyen-co-mnong","title":"Chàng Trăng - Truyện cổ M’nông","summary":"Ngày xửa, ngày xưa, trên rừng núi Tây Nguyên, vùng đất đai của con rồng lửa có hai vợ chồng người nông dân nghèo đã già rồi mà chưa có con.","cat":"vn"},{"id":"su-tich-chuong-trong-mo","url":"https://truyencotich.top/doc-truyen/su-tich-chuong-trong-mo","title":"Sự Tích Chuông, Trống, Mõ","summary":"Ngày xưa, có một thư sinh nghèo học hành rất giỏi, hy vọng thế nào rồi cũng được đỗ cao, làm nên nghiệp lớn. Chàng rất sáng dạ, học đâu nhớ đấy, tấn tới lạ thường, thầy dạy cùng bạn bè đều mến phục.","cat":"vn"},{"id":"tieng-hat-truyen-co-tich-dan-toc-gia-rai","url":"https://truyencotich.top/doc-truyen/tieng-hat-truyen-co-tich-dan-toc-gia-rai","title":"Tiếng hát – Truyện cổ tích dân tộc Gia Rai","summary":"Trên đỉnh một ngọn núi cao vùng Chư Bô-đa có một mỏm đá xanh, giống hệt như hình một em bé kháu khỉnh, xinh xắn cưỡi trên một con voi. Mỏm đá đứng ở chỗ ấy tự bao giờ không một ai biết cả.","cat":"vn"},{"id":"hon-da-co-phep-nhiem-mau","url":"https://truyencotich.top/doc-truyen/hon-da-co-phep-nhiem-mau","title":"Hòn đá có phép nhiệm màu","summary":"Ngày xưa, có một chị vợ hay cãi cọ, nhất định không chịu nhường chồng bất cứ chuyện gì. Anh chồng lại cũng không phải dạng vừa, sẵn sàng nổi cáu rồi giở trò đánh đập vợ. Gia đình vì thế bất hòa luôn.","cat":"vn"},{"id":"nguoi-hoc-tro-voi-con-rua","url":"https://truyencotich.top/doc-truyen/nguoi-hoc-tro-voi-con-rua","title":"Người học trò với con rùa","summary":"Xưa có một người học trò, một hôm, đi học về đi ngang qua bờ sông, thấy mấy người thuyền chài bắt được một con rùa, đang bàn nhau đem về làm thịt để đánh chén.","cat":"vn"},{"id":"cai-na-chin-ranh","url":"https://truyencotich.top/doc-truyen/cai-na-chin-ranh","title":"Cái ná chín rãnh","summary":"Vợ chồng nhà kia hiếm muộn đã lâu. Ngoài năm mươi tuổi mà vẫn chưa sinh được mụn con nào.","cat":"vn"},{"id":"tieu-a-le-truyen-co-dan-toc-bru","url":"https://truyencotich.top/doc-truyen/tieu-a-le-truyen-co-dan-toc-bru","title":"Tiều A Lé - Truyện cổ dân tộc Bru","summary":"Có hai vợ chồng một ông già nọ ngày đêm buồn phiền vì không con. Một buổi lên nương, ông bà bỗng thấy một đứa bé ốm yếu, khắp người chi chít ghẻ lở, nằm khóc oa oa bên đường. Bà già nói với chồng: Ai đem con ném ở đây chắc là ý Giàng muốn cho ta.","cat":"vn"},{"id":"chang-danh-ca-me-nup","url":"https://truyencotich.top/doc-truyen/chang-danh-ca-me-nup","title":"Chàng đánh cá Mê Núp","summary":"Ngày xưa, bên một khúc sông quanh co, nước trong veo soi bóng những rặng tre xanh, có một chàng trai tên là Mê Núp sống bằng nghề chài lưới.","cat":"vn"},{"id":"su-tich-chim-chao-mao-duoi-do","url":"https://truyencotich.top/doc-truyen/su-tich-chim-chao-mao-duoi-do","title":"Sự tích chim chào mào đuôi đỏ","summary":"Ngày xưa, từ thuở đất trời còn yên bình và con người sống chan hòa với cỏ cây, các loại cây trồng như lúa, ngô, khoai, đỗ… đã trở thành những người bạn thân thiết của con người.","cat":"vn"},{"id":"cai-sung-cua-ten-dia-chu","url":"https://truyencotich.top/doc-truyen/cai-sung-cua-ten-dia-chu","title":"Cái sừng của tên địa chủ","summary":"Ngày xưa, có một tên địa chủ vô cùng độc ác. Hắn bóc lột người làm công đến tận xương tủy, lại còn thường xuyên đánh đập, hành hạ họ rất tàn nhẫn...","cat":"vn"},{"id":"chim-ruoi-va-chim-diec","url":"https://truyencotich.top/doc-truyen/chim-ruoi-va-chim-diec","title":"Chim Ruồi và Chim Diệc","summary":"Thuở xưa, có một dòng sông lớn bắt nguồn từ miền núi rồi chảy dài ra tận biển khơi. Có những đoạn nước sông cuộn trào dữ dội, tung bọt trắng xóa giữa ghềnh đá...","cat":"vn"},{"id":"doi-canh-tinh-ban","url":"https://truyencotich.top/doc-truyen/doi-canh-tinh-ban","title":"Đôi cánh tình bạn","summary":"Ngày xưa, bên một dòng sông rộng lớn có một căn chòi nhỏ lợp lá khô với cánh cửa sơn màu xanh bạc phếch...","cat":"vn"},{"id":"nguoi-gieo-hat","url":"https://truyencotich.top/doc-truyen/nguoi-gieo-hat","title":"Người gieo hạt","summary":"Ngày xưa, có một cậu học trò mồ côi cả cha lẫn mẹ từ khi còn rất nhỏ. Tuổi thơ của cậu thiếu thốn biết bao tình thương. Họ hàng chẳng còn mấy ai, chỉ còn duy nhất một người cô ruột...","cat":"vn"},{"id":"cay-nhan-con-doi-va-con-buom","url":"https://truyencotich.top/doc-truyen/cay-nhan-con-doi-va-con-buom","title":"Cây nhãn, con dơi và con bướm","summary":"Ở một góc của khu vườn nhỏ xơ xác có một cây nhãn vừa bước vào mùa kết quả đầu tiên. Những chùm quả đầu mùa đã căng mọng, lớp vỏ ngả vàng báo hiệu độ chín...","cat":"vn"},{"id":"meo-mun-bi-phat","url":"https://truyencotich.top/doc-truyen/meo-mun-bi-phat","title":"Mèo mun bị phạt","summary":"Mùa đông năm ấy, khu rừng phủ một màu xám xịt và buồn bã. Cây cối trơ cành, gió lạnh thổi qua khiến muôn loài đều ủ rũ. Thấy vậy, vua Cọp liền triệu tập tất cả muông thú đến trước sân rừng...","cat":"vn"},{"id":"quyen-sach-bi-lang-quen","url":"https://truyencotich.top/doc-truyen/quyen-sach-bi-lang-quen","title":"Quyển sách bị lãng quên","summary":"Trong một gian phòng cũ kỹ từng là nơi làm việc của một giáo viên, mọi thứ đều phủ đầy bụi thời gian. Bàn ghế nằm ngổn ngang, những vật dụng bị bỏ quên lặng lẽ nằm trong góc tối...","cat":"vn"},{"id":"ba-chua-tram-huong","url":"https://truyencotich.top/doc-truyen/ba-chua-tram-huong","title":"Bà Chúa Trầm Hương","summary":"Ngày xưa, ở vùng núi Đại An, nay thuộc tỉnh Khánh Hòa, có một đôi vợ chồng tiều phu tuổi đã cao nhưng vẫn chưa có con. Cuộc sống của họ tuy nghèo khó nhưng đầm ấm...","cat":"vn"},{"id":"hoang-tu-cua-bien","url":"https://truyencotich.top/doc-truyen/hoang-tu-cua-bien","title":"Hoàng tử cua biển","summary":"Ngày xưa, ở một làng chài nhỏ ven biển, có một người đánh cá nghèo sống cùng vợ và đàn con đông đúc. Ngày nào bác cũng dong thuyền ra khơi từ lúc trời còn mờ sương, thả lưới giữa sóng nước mênh mông, mong kiếm được ít cá mang về...","cat":"vn"},{"id":"khan-do-khan-xanh","url":"https://truyencotich.top/doc-truyen/khan-do-khan-xanh","title":"Khăn Đỏ, Khăn Xanh","summary":"Ngày xưa, có hai chị em gái giống nhau như đúc. Từ khuôn mặt, mái tóc đến dáng người đều chẳng khác gì nhau, khiến nhiều khi ngay cả người quen trong làng cũng nhầm lẫn...","cat":"vn"},{"id":"co-be-quang-khan-do","url":"https://truyencotich.top/doc-truyen/co-be-quang-khan-do","title":"Cô bé quàng khăn đỏ","summary":"Ngày xửa ngày xưa có chuyện kể rằng, có một cô bé thường hay quàng chiếc khăn màu đỏ, vì thế nên mọi người bắt đầu gọi cô bằng cái tên cô bé quàng khăn đỏ...","cat":"world"},{"id":"nang-bach-tuyet-va-bay-chu-lun","url":"https://truyencotich.top/doc-truyen/nang-bach-tuyet-va-bay-chu-lun","title":"Nàng Bạch Tuyết và bảy chú lùn","summary":"Hồi ấy đang giữa mùa đông, hoa tuyết như những lông chim bay khắp bầu trời, có một bà hoàng hậu ngồi khâu bên cửa sổ...","cat":"world"},{"id":"aladdin-va-cay-den-than","url":"https://truyencotich.top/doc-truyen/aladdin-va-cay-den-than","title":"Aladdin và cây đèn thần","summary":"Trong kinh thành một vương quốc thuộc Trung Hoa, rất giàu và rộng, có một người thợ may tên là Mustafa, đặc điểm không gì khác ngoài phong thái nghề nghiệp. Mustafa rất nghèo, công việc chỉ vừa đủ ăn cho ông, vợ và một đứa con trai...","cat":"world"},{"id":"alibaba-va-bon-muoi-ten-cuop","url":"https://truyencotich.top/doc-truyen/alibaba-va-bon-muoi-ten-cuop","title":"Alibaba và bốn mươi tên cướp","summary":"Một ngày nọ, khi đang đốn củi trong rừng, Ali Baba trèo lên một thân cây để chặt một cành cao. Đột nhiên anh ngừng đốn vì nghe có tiếng vó ngựa. Một nhóm người đang cưỡi ngựa đến. Trông họ có vẻ dữ dằn và giống những tên cướp...","cat":"world"},{"id":"co-be-lo-lem","url":"https://truyencotich.top/doc-truyen/co-be-lo-lem","title":"Cô bé Lọ Lem","summary":"Ngày xưa có một người đàn ông giàu có, vợ ông ta ốm nặng. Khi bà cảm thấy mình sắp gần đất xa trời, bà gọi người con gái duy nhất của mình lại bên giường và dặn dò...","cat":"world"},{"id":"nang-cong-chua-ngu-trong-rung","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-ngu-trong-rung","title":"Nàng công chúa ngủ trong rừng","summary":"Ngày xưa, có một ông vua và một bà hoàng hậu ngày nào cũng mong: &quot;Ước gì mình có một đứa con nhỉ?.&quot; Nhưng ước hoài mà vua và hoàng hậu vẫn chưa có con...","cat":"world"},{"id":"chu-tho-may-nho-tho-can-dam","url":"https://truyencotich.top/doc-truyen/chu-tho-may-nho-tho-can-dam","title":"Chú thợ may nhỏ thó can đảm","summary":"Vào một buổi sáng mùa hè đẹp trời, một chú thợ may bé nhỏ ngồi trên phản bên cửa sổ chăm chú khâu, trong lòng có vẻ khoan khoái lắm...","cat":"world"},{"id":"chu-meo-di-hia","url":"https://truyencotich.top/doc-truyen/chu-meo-di-hia","title":"Chú mèo đi hia","summary":"Một bác thợ xay có ba người con trai, gia tài của bác cũng có ba thứ: một cối xay gió, một con lừa và một con mèo. Các con bác xay bột, lừa đi lấy ngũ cốc về xay và chở bột đi, còn mèo thì bắt chuột...","cat":"world"},{"id":"ong-lao-danh-ca-va-con-ca-vang","url":"https://truyencotich.top/doc-truyen/ong-lao-danh-ca-va-con-ca-vang","title":"Ông lão đánh cá và con cá vàng","summary":"Xưa kia, ở một bờ biển rất rộng lớn nọ, có một ông lão làm nghề đánh cá cùng chung sống với người vợ của mình. Hai vợ chồng già sống trong túp lều rách nát, tồi tàn...","cat":"world"},{"id":"con-ran-trang","url":"https://truyencotich.top/doc-truyen/con-ran-trang","title":"Con rắn trắng","summary":"Thuở ấy có một ông vua nổi tiếng trong cả nước là thông minh, học rộng, biết nhiều. Không cái gì là vua không biết. Người ta có cảm giác dường như gió đưa lại cho vua những tin tức bí mật nhất...","cat":"world"},{"id":"cay-but-than","url":"https://truyencotich.top/doc-truyen/cay-but-than","title":"Cây bút thần","summary":"Ngày xửa ngày xưa ở một ngôi làng nọ, có một cậu bé rất thông minh tên là Mã Lương. Cha mẹ Mã Lương mất sớm, cậu phải sống cuộc sống côi cút một mình, hàng ngày vào rừng kiếm củi sống qua ngày...","cat":"world"},{"id":"co-be-ban-diem","url":"https://truyencotich.top/doc-truyen/co-be-ban-diem","title":"Cô bé bán diêm","summary":"Vào buổi đêm giáng sinh ngày ấy, bên ngoài trời những bông tuyết cứ triền miên rơi mãi mà không dừng, những cơn gió lạnh thấu xương lại tô điểm hơn cho cái ngày giáng sinh vô cùng đặc biệt trong năm, cái ngày mà chúa sinh ra đời…","cat":"world"},{"id":"cai-am-may-man-hay-su-tich-con-cao-den-on","url":"https://truyencotich.top/doc-truyen/cai-am-may-man-hay-su-tich-con-cao-den-on","title":"Cái ấm may mắn hay sự tích con cáo đền ơn","summary":"Có hai vợ chồng ông lão sống ở một làng ven núi. Họ rất nghèo, hàng ngày ông lão lên núi kiếm củi đem về làng bán để sống qua ngày...","cat":"world"},{"id":"ba-soi-toc-vang-cua-con-quy","url":"https://truyencotich.top/doc-truyen/ba-soi-toc-vang-cua-con-quy","title":"Ba sợi tóc vàng của con quỷ","summary":"Ngày xưa có một người đàn bà nghèo sinh được một con trai. Khi đứa trẻ ra đời người ta nhìn thấy chỏm đầu của nó còn nằm trong bọc nhau, người ta tiên tri là năm mười sáu tuổi nó sẽ lấy được công chúa...","cat":"world"},{"id":"bay-chim-thien-nga","url":"https://truyencotich.top/doc-truyen/bay-chim-thien-nga","title":"Bầy Chim Thiên Nga","summary":"Ở nơi xa, xa đây lắm, nơi chim nhạn bay đến vào mùa thu, có một nhà vua có mười một con trai và một con gái tên là Li-dơ. Mười một con trai trẻ tuổi ấy đều đeo thánh giá trên ngực và gươm bên mình...","cat":"world"},{"id":"nguoi-da-gau","url":"https://truyencotich.top/doc-truyen/nguoi-da-gau","title":"Người da gấu","summary":"Xưa có một anh thanh niên đi lính, rất dũng cảm, luôn luôn xung phong đi dưới mũi tên hòn đạn. Trong thời chiến, mọi việc đều ổn, nhưng đến thời bình, anh bị thải hồi. Tên đại úy chỉ huy bảo anh tùy muốn đi đâu thì đi...","cat":"world"},{"id":"chu-du-thien-ha-de-hoc-rung-minh","url":"https://truyencotich.top/doc-truyen/chu-du-thien-ha-de-hoc-rung-minh","title":"Chu du thiên hạ để học rùng mình","summary":"Một người cha có hai người con trai. Người con trai cả thông minh, khôn ngoan luôn tìm cách giải quyết tốt nhất mọi việc...","cat":"world"},{"id":"chu-be-ti-hon","url":"https://truyencotich.top/doc-truyen/chu-be-ti-hon","title":"Chú bé tí hon","summary":"Xưa có một bác nông dân nghèo, tối tối bác thường ngồi bên lò sưởi, gẩy than cho lửa cháy, và bác gái ngồi xe chỉ...","cat":"world"},{"id":"muoi-hai-nang-cong-chua-va-nhung-doi-giay-nhay-rach","url":"https://truyencotich.top/doc-truyen/muoi-hai-nang-cong-chua-va-nhung-doi-giay-nhay-rach","title":"Mười hai nàng công chúa và những đôi giày nhảy rách","summary":"Ngày xửa ngày xưa có một ông vua có mười hai cô con gái, cô nào cũng xinh đẹp hơn người. Mười hai cô cùng ngủ trong một căn phòng lớn, giường kê liền nhau thành một dãy...","cat":"world"},{"id":"ba-thay-thuoc-gioi","url":"https://truyencotich.top/doc-truyen/ba-thay-thuoc-gioi","title":"Ba thầy thuốc giỏi","summary":"Ba thầy thuốc kia nghĩ mình đã biết đủ ngón nghề rồi nên rủ nhau đi chu du thiên hạ. Tối đến, họ nghỉ ở một quán trọ. Chủ quán tò mò hỏi họ từ đâu đến và muốn đi đâu nữa. Họ đáp - Chúng tôi đi chu du thiên hạ để hành nghề...","cat":"world"},{"id":"hansel-va-gretel","url":"https://truyencotich.top/doc-truyen/hansel-va-gretel","title":"Hãnsel và Gretel","summary":"Sống ở ven một khu rừng là hai vợ chồng bác tiều phu nghèo, gia đình có hai con, con trai tên là Hãnsel , con gái tên là Gretel. Nhà thường sống bữa đói bữa no cho qua ngày...","cat":"world"},{"id":"ban-oi-trai-khan-ra-sap-thuc-an-di","url":"https://truyencotich.top/doc-truyen/ban-oi-trai-khan-ra-sap-thuc-an-di","title":"Bàn ơi, trải khăn ra, sắp thức ăn đi !","summary":"Đã lâu lắm rồi, hồi đó có một bác thợ may, bác có ba người con trai, mà chỉ có một con dê cái duy nhất. Nhưng vì cả nhà ăn sữa dê nên ngày ngày phải dắt dê ra đồng kiếm cỏ tốt cho nó ăn...","cat":"world"},{"id":"rapunzel-co-gai-toc-dai","url":"https://truyencotich.top/doc-truyen/rapunzel-co-gai-toc-dai","title":"Rapunzel cô gái tóc dài","summary":"Ngày xưa có hai vợ chồng nhà kia không có con, họ mong rằng ngày kia trời sẽ thương cảnh ngộ họ. Nhìn qua cửa sổ sau nhà thì thấy một mảnh vườn tuyệt đẹp, trồng toàn hoa thơm, các loại rau lạ...","cat":"world"},{"id":"nguoi-mua-giac-mo","url":"https://truyencotich.top/doc-truyen/nguoi-mua-giac-mo","title":"Người mua giấc mơ","summary":"Ngày xửa ngày xưa có hai người lái buôn, một già một trẻ. Họ thường cùng nhau đi buôn chuyến. Một ngày họ đi đến bờ biển thuộc làng Teraddomai. Họ đã thấm mệt sau một chặng đường dài nên họ ngồi nghi một lát...","cat":"world"},{"id":"hai-anh-em","url":"https://truyencotich.top/doc-truyen/hai-anh-em","title":"Hai anh em","summary":"Xưa có hai anh em, người anh giàu có mà người em thì nghèo. Người anh là thợ vàng, vốn tính ác nghiệt, người em sống bằng nghề bện chổi bán...","cat":"world"},{"id":"nguoi-cha-do-dau-than-chet","url":"https://truyencotich.top/doc-truyen/nguoi-cha-do-dau-than-chet","title":"Người cha đỡ đầu - Thần Chết","summary":"Người cha đỡ đầu là câu chuyện cổ tích đặc sắc của anh em nhà Grim. Bác nông dân nghèo khi tìm cha đỡ dầu cho đứa con thứ mười ba của mình, đã chọn thần Chết, bởi vì thần Chết là người công bằng nhất...","cat":"world"},{"id":"con-chim-son-ca","url":"https://truyencotich.top/doc-truyen/con-chim-son-ca","title":"Con chim sơn ca","summary":"Ngày xửa ngày xưa, có một người cha có ba cô con gái, trước khi đi xa, ông hỏi các con muốn ông mang về những món quà gì...","cat":"world"},{"id":"su-tich-ong-gia-noel","url":"https://truyencotich.top/doc-truyen/su-tich-ong-gia-noel","title":"Sự tích ông già Noel","summary":"Truyền thuyết Santa Claus được bắt đầu bởi một vị Thánh có tên là Nicholas. Thánh Nicholas sinh vào năm 280 tại một thành phố nhỏ ở miền Tiểu Á. Cha mẹ ông rất giàu nhưng qua đời khi ông còn nhỏ...","cat":"world"},{"id":"su-tich-hoa-hong","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-hong","title":"Sự tích hoa hồng","summary":"Rất lâu trước kia, ở một vương quốc tận cuối phương trời xa phía bên kia khu rừng rậm rạp. Cuộc sống nơi đây vô cùng yên bình và hạnh phúc sau thời gian dài đấu tranh triền miên giành lại quyền tự do...","cat":"world"},{"id":"hoang-tu-ech","url":"https://truyencotich.top/doc-truyen/hoang-tu-ech","title":"Hoàng tử ếch","summary":"Từ thời xa xưa lắm rồi, khi chuyện ước nguyện còn có hiệu nghiệm, một ông vua có mấy cô con gái, cô nào cũng xinh đẹp cả...","cat":"world"},{"id":"hanxo-sat","url":"https://truyencotich.top/doc-truyen/hanxo-sat","title":"Hanxơ sắt","summary":"Ngày xửa ngày xưa có một ông vua trị vì một vương quốc nọ, bao quanh hoàng cung là một khu rừng lớn với đủ các loài muông thú...","cat":"world"},{"id":"nang-scheherazade","url":"https://truyencotich.top/doc-truyen/nang-scheherazade","title":"Nàng Scheherazade","summary":"Sử sách thời Sassanides, thời của những ông vua quốc gia Ba Tư cổ xưa, đất nước có biên cương mở rộng tới tận Ấn Độ và các đảo phụ thuộc lớn nhỏ, trải ra tới phía bên kia sông Hằng và phần đất rộng lớn của Trung Quốc bao la...","cat":"world"},{"id":"con-chim-ki-la","url":"https://truyencotich.top/doc-truyen/con-chim-ki-la","title":"Con chim kì lạ","summary":"Ngày xửa ngày xưa, có một tên phù thủy thường giả dạng người ăn xin để lân la tới các nhà và bắt đi những cô gái đẹp. Không có một ai biết các cô bị đem đi đâu, chỉ biết chẳng có cô nào trở về.","cat":"world"},{"id":"ba-chang-hoang-tu","url":"https://truyencotich.top/doc-truyen/ba-chang-hoang-tu","title":"Ba chàng hoàng tử","summary":"Ngày xửa ngày xưa… có hai hoàng tử thích phiêu lưu, lâu dần quen sống hoang dã nên không trở về nhà nữa. Người em út thường gọi là &quot;chú Ngốc&quot; lên đường đi tìm hai anh...","cat":"world"},{"id":"muoi-hai-chang-luoi","url":"https://truyencotich.top/doc-truyen/muoi-hai-chang-luoi","title":"Mười hai chàng lười","summary":"Có mười hai anh chàng lười kia suốt ngày chẳng làm gì, chủ bắt làm cũng không làm, một tối ra ngồi bãi cỏ thi kể xem ai lười hơn...","cat":"world"},{"id":"co-be-hai-mat","url":"https://truyencotich.top/doc-truyen/co-be-hai-mat","title":"Cô bé hai mắt","summary":"Ngày xưa, có một bà có ba cô con gái. Con lớn tên là Một Mắt vì cô chỉ có độc một mắt ở giữa trán. Cô thứ hai tên là Hai Mắt vì cô có hai mắt như mọi người khác. Cô út tên là Ba Mắt vì cô có ba mắt, mắt thứ ba cũng ở giữa trán...","cat":"world"},{"id":"hai-chang-ferdinand","url":"https://truyencotich.top/doc-truyen/hai-chang-ferdinand","title":"Hai chàng Ferdinand","summary":"Ngày xưa có hai vợ chồng nhà kia, khi họ còn giàu có thì lại chẳng có mụn con nào cả. Đến khi họ tán gia bại sản, nghèo khó thì lại sinh được một mụn con trai, nhưng vì họ nghèo quá nên chẳng ai nhận làm cha đỡ đầu đứa bé...","cat":"world"},{"id":"vua-trom","url":"https://truyencotich.top/doc-truyen/vua-trom","title":"Vua trộm","summary":"Một hôm, hai vợ chồng bác nông dân làm việc xong, định ngồi nghỉ một lát trước căn nhà đơn sơ của họ thì bỗng nhiên có một chiếc xe lộng lẫy bốn ngựa kéo tới đỗ ngay trước nhà. Một quý ông ăn mặc sang trọng từ trên xe bước xuống....","cat":"world"},{"id":"con-quy-trong-chai-thuy-tinh","url":"https://truyencotich.top/doc-truyen/con-quy-trong-chai-thuy-tinh","title":"Con quỷ trong chai thủy tinh","summary":"Ngày xửa ngày xưa, có một người bổ củi nghèo, bác làm việc quần quật từ sáng sớm tới tối mịt. Khi số tiền bác dành dụm được đã kha khá, bác bảo con trai hãy dùng số tiền ấy đi học lấy một nghề....","cat":"world"},{"id":"sau-nguoi-hau","url":"https://truyencotich.top/doc-truyen/sau-nguoi-hau","title":"Sáu người hầu","summary":"Xưa có một bà hoàng hậu già, vốn là một mụ phù thủy. Mụ sinh được một con gái đẹp vào bậc nhất trên đời. Nhưng mụ vốn chỉ tìm cách hại người...","cat":"world"},{"id":"ba-chua-tuyet","url":"https://truyencotich.top/doc-truyen/ba-chua-tuyet","title":"Bà chúa tuyết","summary":"Một người đàn bà góa chồng có hai cô con gái, trong hai cô có một cô đã xinh đẹp lại siêng năng, còn một cô vừa xấu xí lại lười biếng. Bà mẹ cưng cô xấu xí và lười biếng hơn vì cô là con của bà đẻ ra...","cat":"world"},{"id":"nang-cong-chua-va-hat-dau","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-va-hat-dau","title":"Nàng công chúa và hạt đậu","summary":"Ngày xửa ngày xưa, có một hoàng tử muốn tìm một công chúa xứng đáng để cưới làm vợ. Chàng đi khắp thế giới để mong tìm được người hợp ý chàng. Chàng đã gặp biết bao nhiêu công chúa, nhưng ai cũng bị chàng chê ở một điểm nào đấy...","cat":"world"},{"id":"cho-soi-va-bay-chu-de-con","url":"https://truyencotich.top/doc-truyen/cho-soi-va-bay-chu-de-con","title":"Chó sói và bảy chú dê con","summary":"Ngày xửa ngày xưa, có một con dê cái già sinh được bảy chú dê con. Mẹ nào mà chả thương con, dê mẹ thương yêu đàn con của mình lắm. Một ngày kia, dê mẹ vào rừng kiếm thức ăn...","cat":"world"},{"id":"tien-vang-roi-nhu-sao-sa","url":"https://truyencotich.top/doc-truyen/tien-vang-roi-nhu-sao-sa","title":"Tiền vàng rơi như sao sa","summary":"Ngày xửa ngày xưa có một cô bé mồ côi cả cha lẫn mẹ, sống vất vưởng, không nơi nương thân không giường để ngủ, ngoài quần áo đang mặc trên người ra thì không còn có của cải gì nữa...","cat":"world"},{"id":"nang-cong-chua-trong-ong-tre","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-trong-ong-tre","title":"Nàng công chúa trong ống tre","summary":"Thuở xa xưa ở Nhật Bản, có một lão tiều phu chuyên nghề đốn củi. Một ngày nọ, khi đang ở trong rừng, ông phát hiện một đốt tre phát ra những tia sáng vàng rực rỡ. Hiếu kì, ông đến gần nhìn cho rõ...","cat":"world"},{"id":"vua-ech","url":"https://truyencotich.top/doc-truyen/vua-ech","title":"Vua Ếch","summary":"Từ thời xa xưa lắm rồi, khi chuyện ước nguyện còn có hiệu nghiệm, một ông vua có mấy cô con gái, cô nào cũng xinh đẹp cả. Nhưng cô út xinh đẹp lộng lẫy đến nỗi mặt trời tuy đã trông thấy nhiều cảnh đẹp mà vẫn phải ngạc nhiên...","cat":"world"},{"id":"anh-chang-chan-lon","url":"https://truyencotich.top/doc-truyen/anh-chang-chan-lon","title":"Anh chàng chăn lợn","summary":"Ngày xưa ngày xửa, có một chàng hoàng tử vô cùng nghèo, giang sơn của chàng cũng vô cùng nhỏ hẹp. Tuy nói giang sơn nhỏ thì cũng thật là nhỏ đấy nhưng cũng là đủ để cho hoàng tử có thể kén cho mình được một nàng vợ...","cat":"world"},{"id":"muoi-hai-hoang-tu","url":"https://truyencotich.top/doc-truyen/muoi-hai-hoang-tu","title":"Mười hai Hoàng Tử","summary":"Ngày xửa ngày xưa, ở vương quốc kia vua và hoàng hậu sống rất hòa thuận và có mười hai người con trai rất khôi ngô tuấn tú...","cat":"world"},{"id":"ba-dieu-uoc","url":"https://truyencotich.top/doc-truyen/ba-dieu-uoc","title":"Ba điều ước","summary":"Ngày xửa ngày xưa, có một người nhà giàu. Ông ta có một người đầy tớ chăm chỉ, tận tâm với chủ. Ngày nào cũng vậy, anh là người đầu tiên ra khỏi nhà lúc trời sáng và tới đêm khuya là người cuối cùng đi ngủ...","cat":"world"},{"id":"bay-con-qua","url":"https://truyencotich.top/doc-truyen/bay-con-qua","title":"Bảy con quạ","summary":"Ngày xưa có một người có bảy đứa con trai, nên rất mong có một mụn con gái. Khi vợ có mang, bác ta hy vọng lần này sẽ toại nguyện. Quả thật đứa con mới chào đời là con gái...","cat":"world"},{"id":"meo-chuot-ket-nghia","url":"https://truyencotich.top/doc-truyen/meo-chuot-ket-nghia","title":"Mèo chuột kết nghĩa","summary":"Để làm thân với Chuột, Mèo kể lể tâm tình, bày tỏ nguyện vọng tha thiết của mình, làm Chuột nghe cũng bùi tai nên đồng ý ăn chung, ở chung với Mèo...","cat":"world"},{"id":"bac-tho-xay-bot-va-con-quy","url":"https://truyencotich.top/doc-truyen/bac-tho-xay-bot-va-con-quy","title":"Bác thợ xay bột và con quỷ","summary":"Ngày xưa có một bác thợ xay bột. Bác ngày càng trở nên nghèo túng. Gia tài của bác giờ đây chỉ có cối xay và cây táo sau nhà...","cat":"world"},{"id":"con-ngong-vang","url":"https://truyencotich.top/doc-truyen/con-ngong-vang","title":"Con ngỗng vàng","summary":"Ngày xưa, có một người có ba đứa con trai, đứa con út được gọi là chàng Ngốc. Chàng thường bị khinh rẻ, chế giễu và nếu có việc gì thì cũng chẳng ai đếm xỉa đến chàng....","cat":"world"},{"id":"ba-hoang-tu-luoi","url":"https://truyencotich.top/doc-truyen/ba-hoang-tu-luoi","title":"Ba hoàng tử lười","summary":"Ngày xửa ngày xưa, có một ông vua có ba người con trai, vua yêu quý cả ba con như nhau nên rất phân vân, không biết chọn con nào lên nối ngôi sau khi mình qua đời...","cat":"world"},{"id":"cho-soi-va-cao","url":"https://truyencotich.top/doc-truyen/cho-soi-va-cao","title":"Chó sói và cáo","summary":"Sói và cáo sống chung, cái gì sói muốn là cáo phải làm, vì trong hai thì cáo là kẻ yếu nhất. Cáo cũng rất muốn thoát ra khỏi cảnh này....","cat":"world"},{"id":"ga-xay-bot-ngheo-kho-va-chu-meo-dom","url":"https://truyencotich.top/doc-truyen/ga-xay-bot-ngheo-kho-va-chu-meo-dom","title":"Gã xay bột nghèo khổ và chú mèo đốm","summary":"Sống trong nhà xay bột kia là một bác thợ xay nghèo không có vợ con gì cả. Có ba gã giúp việc ở với bác đã nhiều năm nay...","cat":"world"},{"id":"ba-ba-keo-soi","url":"https://truyencotich.top/doc-truyen/ba-ba-keo-soi","title":"Ba bà kéo sợi","summary":"Ngày xưa có một cô gái biếng nhác không muốn kéo sợi. Bà mẹ đã khuyên răn cô nhiều về việc này nhưng cô vẫn không chịu ngồi kéo sợi...","cat":"world"},{"id":"truyen-con-quy-va-ba-nguoi-linh","url":"https://truyencotich.top/doc-truyen/truyen-con-quy-va-ba-nguoi-linh","title":"Truyện con quỷ và ba người lính","summary":"Ngày xưa xảy ra một cuộc chiến tranh lớn. Nhà vua có rất nhiều lính, trả lương cho họ quá ít, không đủ để sống. Có ba người lính bèn rủ nhau đào ngũ...","cat":"world"},{"id":"ba-nguoi-lun-trong-rung","url":"https://truyencotich.top/doc-truyen/ba-nguoi-lun-trong-rung","title":"Ba người lùn trong rừng","summary":"Ngày xưa có một người đàn ông góa vợ và một người đàn bà góa chồng, người đàn bà có một con gái, và người đàn ông cũng có một con gái. Hai đứa bé chơi thân với nhau, thường rủ nhau chơi và sau đó về nhà người đàn bà góa...","cat":"world"},{"id":"ken-pho-ma","url":"https://truyencotich.top/doc-truyen/ken-pho-ma","title":"Kén phò mã","summary":"Ngày xửa ngày xưa có một hoàng tử thích đi chu du thiên hạ. Hoàng tử đem theo một gia nhân trung thành. Một ngày kia họ lạc vào một khu rừng rậm...","cat":"world"},{"id":"su-tich-hat-dau","url":"https://truyencotich.top/doc-truyen/su-tich-hat-dau","title":"Sự tích hạt đậu","summary":"Có một bà lão nghèo khổ ở làng kia kiếm được một mớ đậu mang nấu. Bà vào bếp nhóm lửa. Để đun cho nhanh, bà đút một mớ rơm vào bếp. Lúc bà đổ đậu vào nồi, có một hạt rơi xuống đất mà bà không hề hay biết. Hạt đậu rơi ngay cạnh một sợi rơm...","cat":"world"},{"id":"doi-giay-do","url":"https://truyencotich.top/doc-truyen/doi-giay-do","title":"Đôi giầy đỏ","summary":"Karen là một cô gái nhỏ rất xinh xắn và rất ngoan. Mẹ cô nghèo nên cô chẳng có giầy dép gì, mùa hè đi chân đất, mùa đông đi guốc gỗ, chân không chịu được rét, đỏ ửng lên...","cat":"world"},{"id":"co-dau-dich-thuc","url":"https://truyencotich.top/doc-truyen/co-dau-dich-thuc","title":"Cô dâu đích thực","summary":"Ngày xửa ngày xưa có một cô gái trẻ xinh đẹp, nhưng mẹ mất sớm. Dì ghẻ kiếm mọi cớ để hành hạ cô. Việc gì nặng nhọc, khó khăn thì mẹ kế bắt cô làm, cô gắng hết sức mình làm cho xong việc, nhưng không bao giờ người dì ghẻ độc ác đó bằng lòng...","cat":"world"},{"id":"ba-chiec-la-ran","url":"https://truyencotich.top/doc-truyen/ba-chiec-la-ran","title":"Ba chiếc lá rắn","summary":"Xưa có một người đàn ông nghèo đến nỗi không nuôi nổi đứa con trai duy nhất của mình...","cat":"world"},{"id":"con-quy-va-ba-noi","url":"https://truyencotich.top/doc-truyen/con-quy-va-ba-noi","title":"Con quỷ và bà nội","summary":"Hồi ấy chiến tranh liên miên, nhà vua chiêu nạp rất nhiều binh sĩ. Quân lương thì ít mà lính thì nhiều nên binh lính sống rất khổ cực...","cat":"world"},{"id":"con-duc-ba-maria","url":"https://truyencotich.top/doc-truyen/con-duc-ba-maria","title":"Con đức bà Maria","summary":"Xưa có vợ chồng người tiều phu sống trong một khu rừng lớn, họ chỉ có mỗi một người con gái lên ba tuổi. Họ nghèo lắm, nghèo đến nỗi bánh ăn hàng ngày cũng không có, không biết lấy gì để nuôi con...","cat":"world"},{"id":"su-tich-hoa-cam-chuong","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-cam-chuong","title":"Sự tích hoa cẩm chướng","summary":"Đã nhiều năm trôi qua mà hoàng hậu vẫn chưa có con, vì thế sáng nào hoàng hậu cũng ra vườn thượng uyển quay về phía mặt trời cầu xin thượng đế rộng lòng thương cho một mụn con, dù đó là con trai hay con gái...","cat":"world"},{"id":"bac-nong-dan-ngheo-kho","url":"https://truyencotich.top/doc-truyen/bac-nong-dan-ngheo-kho","title":"Bác nông dân nghèo khó","summary":"Ngày xưa ở làng kia, cả làng giàu có, duy chỉ có một người nghèo. Cả làng gọi bác nông dân nghèo kia là Nhà Nông. Bác ta nghèo tới mức không có lấy một con bò, mà tiền để mua bò bác cũng không có nốt...","cat":"world"},{"id":"anh-frieder-than-yeu","url":"https://truyencotich.top/doc-truyen/anh-frieder-than-yeu","title":"Anh Frieder thân yêu","summary":"Ngày xưa có chàng trai tên là Frieder và cô gái tên là Katherlieschen. Họ lấy nhau và sống trong cảnh hạnh phúc của vợ chồng trẻ...","cat":"world"},{"id":"roland-yeu-dau","url":"https://truyencotich.top/doc-truyen/roland-yeu-dau","title":"Roland yêu dấu","summary":"Ngày xưa có một người đàn bà, vốn là một mụ phù thủy. Mụ có hai người con gái, nhưng mụ chỉ quý đứa con riêng của mụ, nó vừa xấu lại gian ác. Đứa con riêng của chồng vừa đẹp người lại tốt bụng thì mụ rất ghét...","cat":"world"},{"id":"anh-chang-danh-trong","url":"https://truyencotich.top/doc-truyen/anh-chang-danh-trong","title":"Anh chàng đánh trống","summary":"Một buổi tối kia, anh chàng đánh trống đi lang thang một mình ở giữa cánh đồng, tới bên bờ hồ, anh thấy có ba chiếc áo trắng...","cat":"world"},{"id":"ba-anh-em","url":"https://truyencotich.top/doc-truyen/ba-anh-em","title":"Ba anh em","summary":"Ngày xưa, có một người cha có ba người con trai, gia tài của ông vỏn vẹn chỉ là căn nhà ông đang ở. Kể ra, sau khi ông chết mỗi người con đều cần một căn nhà...","cat":"world"},{"id":"ba-chiec-long-chim","url":"https://truyencotich.top/doc-truyen/ba-chiec-long-chim","title":"Ba chiếc lông chim","summary":"Ngày xưa có một ông vua. Nhà vua có ba người con trai. Hai người con đầu thông minh, sáng trí. Người con thứ ba ít nói và đần độn nên mọi người gọi là thằng ngốc...","cat":"world"},{"id":"ba-chu-pho-nho","url":"https://truyencotich.top/doc-truyen/ba-chu-pho-nho","title":"Ba chú phó nhỏ","summary":"Ngày xưa có ba chú phó nhỏ hẹn ước luôn luôn cùng nhau làm việc trong một thành phố. Có thời gian cả ba đều không có việc. Họ chẳng còn có gì để ăn, quần áo cũng bắt đầu sờn rách...","cat":"world"},{"id":"ba-con-chim-nho","url":"https://truyencotich.top/doc-truyen/ba-con-chim-nho","title":"Ba con chim nhỏ","summary":"Cũng phải cách đây mấy nghìn năm rồi, ở vùng rộng mênh mông này có rất nhiều ông vua nhỏ. Trong số đó có ông vua núi Coitơ rất thích đi săn...","cat":"world"},{"id":"ba-hat-ho-dao","url":"https://truyencotich.top/doc-truyen/ba-hat-ho-dao","title":"Ba hạt hồ đào","summary":"Ngày xửa ngày xưa có một ông vua. Nhà vua có một người con trai còn nhỏ. Theo sao chiếu mệnh thì hoàng tử sẽ bị một con hươu húc chết khi tròn mười sáu tuổi...","cat":"world"},{"id":"nguoi-tho-san-va-con-mu-chan","url":"https://truyencotich.top/doc-truyen/nguoi-tho-san-va-con-mu-chan","title":"Người thợ săn và con mụ chằn","summary":"Ngày xưa có một người thợ săn trẻ tuổi. Như lệ thường, một hôm anh vào rừng sâu săn thú. Mải đuổi theo một con hươu, không ngờ anh lạc vào một nơi chân mình chưa bước tới bao giờ....","cat":"world"},{"id":"nang-cong-chua-ban-than","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-ban-than","title":"Nàng công chúa bán than","summary":"Ngày xưa có một ông vua sinh được ba nàng công chúa. Ba nàng đều xinh đẹp như nhau, nhưng tính tình lại rất khác nhau. Hai công chúa lớn chỉ sống ỷ lại. Cả hai đều lấy được chồng con nhà quan, giàu có...","cat":"world"},{"id":"nguoi-giau-nguoi-ngheo-va-ba-dieu-uoc-cua-chua","url":"https://truyencotich.top/doc-truyen/nguoi-giau-nguoi-ngheo-va-ba-dieu-uoc-cua-chua","title":"Người giàu người nghèo và ba điều ước của Chúa","summary":"Ngày xửa ngày xưa, khi Chúa còn sống chung với con người ở dưới trần gian. Một hôm, Người chưa về tới nhà thì trời đã sập tối. Trong lúc mệt mỏi, Người đứng trước hai căn nhà đối diện nhau...","cat":"world"},{"id":"chiec-hop-sat-biet-noi","url":"https://truyencotich.top/doc-truyen/chiec-hop-sat-biet-noi","title":"Chiếc hộp sắt biết nói","summary":"Hồi ấy, có một hoàng tử bị một mụ phù thủy bắt cóc đem nhốt trong một chiếc lò sưởi. Đã nhiều năm trôi qua, nhưng chưa có ai đến giải thoát cho chàng....","cat":"world"},{"id":"nuoc-truong-sinh","url":"https://truyencotich.top/doc-truyen/nuoc-truong-sinh","title":"Nước trường sinh","summary":"Xưa có một ông vua ốm thập tử nhất sinh, không ai tin là ông sẽ tai qua nạn khỏi. Nhà vua có ba người con trai, cả ba anh em đều buồn rầu về chuyện đó, kéo nhau ra vườn thượng uyển ngồi khóc...","cat":"world"},{"id":"con-chim-khach-mau-nhiem","url":"https://truyencotich.top/doc-truyen/con-chim-khach-mau-nhiem","title":"Con chim khách màu nhiệm","summary":"Vào một ngày xa xưa, có hai anh em con một nhà quan nọ một hôm đi chơi thấy có một nhà đạo sĩ ngồi bên vệ đường. Trước mặt đạo sĩ có đặt một cái lồng, trong có một con chim khách....","cat":"world"},{"id":"ba-bo-rom-nep","url":"https://truyencotich.top/doc-truyen/ba-bo-rom-nep","title":"Ba bó rơm nếp","summary":"Ngày xửa, ngày xưa ớ thành phố Naha thuộc hòn đáo Okinaoa có hai mẹ con người đàn bà nọ sống ớ đó. Khi cậu bé lên bảy thì người mẹ thường hay ốm yếu...","cat":"world"},{"id":"nguoi-thoi-sao-thanh-hamelin","url":"https://truyencotich.top/doc-truyen/nguoi-thoi-sao-thanh-hamelin","title":"Người thổi sáo thành Hamelin","summary":"Hamelin là một thành phố bên sông Weser bang Niedersachsen nằm trong vùng tây bắc nước Cộng hòa Liên bang Đức...","cat":"world"},{"id":"vua-chich-choe-va-nang-cong-chua-kieu-ngao","url":"https://truyencotich.top/doc-truyen/vua-chich-choe-va-nang-cong-chua-kieu-ngao","title":"Vua chích chòe và nàng công chúa kiêu ngạo","summary":"Nhà vua chỉ có một người con gái. Công chúa đẹp tuyệt trần, nhưng vì vậy công chúa kiêu ngạo và ngông cuồng, không một ai vừa lòng nàng cả. Nàng chối từ hết người này đến người khác, không những vậy lại còn chế giễu, nhạo báng họ...","cat":"world"},{"id":"cay-thong-non","url":"https://truyencotich.top/doc-truyen/cay-thong-non","title":"Cây thông non","summary":"Thông mọc chỗ có nắng và quang đãng. Khắp chung quanh có nhiều cây thông khác lớn hơn. Thông non ta cũng muốn lớn bằng những cây ấy...","cat":"world"},{"id":"claus-lon-va-claus-nho","url":"https://truyencotich.top/doc-truyen/claus-lon-va-claus-nho","title":"Claus lớn và Claus nhỏ","summary":"Trong một làng kia có hai người trùng tên nhau tên là Claus. Nhưng có một người có bốn con ngựa, còn người kia chỉ có độc nhất một con thôi . Bởi thế, dân làng gọi người có bốn con ngựa là Claus Lớn, và người có một con ngựa là Claus Nhỏ...","cat":"world"},{"id":"chuyen-con-lung-va-con-cao-thach-do-nhau","url":"https://truyencotich.top/doc-truyen/chuyen-con-lung-va-con-cao-thach-do-nhau","title":"Chuyện con lửng và con cáo thách đố nhau","summary":"Ngày xưa tại một hòn đảo xa xôi ở vùng Sađô (Sado) có một con lửng [1] tên là ĐăngXaBuRô (Densabouro). Trong số những con thú sống ở đảo này, nó là một con vật được đánh giá cao, vì không những nó lanh lợi oai nghiêm, mà còn rất khôn ngoan nữa...","cat":"world"},{"id":"nhung-cuon-kinh-linh-ung","url":"https://truyencotich.top/doc-truyen/nhung-cuon-kinh-linh-ung","title":"Những cuộn kinh linh ứng","summary":"Ngày xưa, một nông dân nghèo có đến sáu người con. Mảnh ruộng nhỏ nhoi của gia đình, mà sau này sẽ về tay người con cả TaRô(TaRô), thật khó mà nuôi nổi cả một gia đình đông đúc...","cat":"world"},{"id":"co-gai-khong-co-tay","url":"https://truyencotich.top/doc-truyen/co-gai-khong-co-tay","title":"Cô gái không có tay","summary":"Ngày xưa, tại một làng kia có hai vợ chồng nọ sống với nhau rất hạnh phúc. Họ có một cô con gái xinh đẹp, kháu khỉnh. Nhưng khi cô được bốn tuổi thì mẹ cô qua đời. Một thời gian sau cha cô lấy người vợ khác...","cat":"world"},{"id":"cai-tai-co-phep-la","url":"https://truyencotich.top/doc-truyen/cai-tai-co-phep-la","title":"Cái tai có phép lạ","summary":"Vùng nọ, có một tràng trai tốt bụng. Môt lần có một chàng trai trẻ đang đi dạo trên bờ biển. Anh dừng lại trước một vũng nước vì nhìn thấy một con cá tráp biển nhỏ dang bị một con cá lớn hơn đuổi bắt...","cat":"world"},{"id":"vua-midas-vi-hoang-de-tai-lua","url":"https://truyencotich.top/doc-truyen/vua-midas-vi-hoang-de-tai-lua","title":"Vua Midas - Vị hoàng đế tai lừa","summary":"Từ lâu trị vì trên đất nước Phrygie là 1 nhà vua hết lòng ngưỡng mộ thần Dionysos, vị thần rượu. Đức vua rất giàu có và ở trong 1 cung điện hết sức lộng lẫy...","cat":"world"},{"id":"bo-quan-ao-moi-cua-hoang-de","url":"https://truyencotich.top/doc-truyen/bo-quan-ao-moi-cua-hoang-de","title":"Bộ quần áo mới của hoàng đế","summary":"Ngày xưa, có một vị hoàng đế giàu sang và quyền lực thích quần áo mới đến nỗi ngài luôn muốn mình phải là người đầu tiên sở hữu những bộ quần áo mới nhất, đẹp nhất, và độc đáo nhất trong thiên hạ...","cat":"world"},{"id":"bach-tuyet-va-hoa-hong","url":"https://truyencotich.top/doc-truyen/bach-tuyet-va-hoa-hong","title":"Bạch Tuyết và Hoa Hồng","summary":"Ngày xưa, có một người đàn bà góa nghèo khó sống cô quạnh trong một túp lều tranh. Trước lều tranh là một cái vườn có hai cây hồng, một cây ra hoa hồng trắng, còn cây kia lại ra hoa hồng đỏ...","cat":"world"},{"id":"chu-be-ngheo-duoi-nam-mo","url":"https://truyencotich.top/doc-truyen/chu-be-ngheo-duoi-nam-mo","title":"Chú bé nghèo dưới nấm mồ","summary":"Xưa có một chú bé chăn dê nghèo, bố mẹ đều chết cả, quan trên đưa chú cho một nhà giàu nuôi dạy. Song vợ chồng nhà này rất cay nghiệt...","cat":"world"},{"id":"su-tich-chi-hang-nga","url":"https://truyencotich.top/doc-truyen/su-tich-chi-hang-nga","title":"Sự tích chị Hằng Nga","summary":"Ngày xửa ngày xưa, có một dịp kia, trên trời xuất hiện mười ông mặt trời, cùng chiếu sáng làm đất nóng đến bốc khói, biển hồ khô cạn, người dân cũng không thể sống nổi...","cat":"world"},{"id":"chu-be-jack-va-cay-dau-than","url":"https://truyencotich.top/doc-truyen/chu-be-jack-va-cay-dau-than","title":"Chú bé Jack và cây đậu thần","summary":"Ngày xửa ngày xưa, có một cậu bé tên là Jack. Cậu sống với mẹ ở một ngôi nhà nhỏ trong làng. Gia đình Jack rất nghèo, tài sản duy nhất họ có là một con bò, mà nó đã già đến mức chẳng cho sữa được nữa...","cat":"world"},{"id":"nang-ngon-ut","url":"https://truyencotich.top/doc-truyen/nang-ngon-ut","title":"Nàng Ngón Út","summary":"Xưa có một nhà nọ, tuy hai vợ chồng tuổi đã ngoài bốn mươi nhưng không con. Hai người rất lấy làm buồn phiền về sự hẩm hiu của mình...","cat":"world"},{"id":"cai-gia-cua-su-thong-thai","url":"https://truyencotich.top/doc-truyen/cai-gia-cua-su-thong-thai","title":"Cái giá của sự thông thái","summary":"Rất lâu rồi, có một nhà vua muốn hiểu biết thật nhiều nhưng lại lười. Một ngày nọ nhà vua triệu tập tất cả những nhà thông thái của vương quốc lại và ra lệnh cho họ phải thu thập tất cả những hiểu biết và sự thông thái trên thế gian...","cat":"world"},{"id":"chiec-hom-bay","url":"https://truyencotich.top/doc-truyen/chiec-hom-bay","title":"Chiếc hòm bay","summary":"Ngày xưa, có một lão lái buôn giàu đến nỗi có thể lấy bạc ra trát kín cả phố lão đang ở và có lẽ còn lát thêm được một cái ngõ nữa. Nhưng lão ta chẳng dại gì mà chơi ngông thế, lão có lắm cách dùng tiền có ích hơn nhiều...","cat":"world"},{"id":"duoi-bong-lieu-gia","url":"https://truyencotich.top/doc-truyen/duoi-bong-lieu-gia","title":"Dưới bóng liễu già","summary":"Đất đai quanh thị trấn Kgiôêgiê trên đảo Xilen rất là trơ trụi. Thị trấn này ở bên bờ biển. Biển cả bao giờ cũng đẹp. Nhưng có thể nói là bãi biển Kgiôêgiê còn đẹp hơn tất cả các nơi khác...","cat":"world"},{"id":"chang-khong-lo-tre-tuoi","url":"https://truyencotich.top/doc-truyen/chang-khong-lo-tre-tuoi","title":"Chàng khổng lồ trẻ tuổi","summary":"Xưa có một bác nông dân có đứa con giai nhỏ bằng ngón tay cái, nuôi mấy năm trời mà không lớn lên được chút nào...","cat":"world"},{"id":"ba-co-chi","url":"https://truyencotich.top/doc-truyen/ba-co-chi","title":"Ba Cô Chị","summary":"Ngày xưa có một ông vua rất giàu, vua giàu đến nỗi tưởng là của cải của mình không bao giờ hết được. Vua sống xa hoa, chơi bàn cờ bằng vàng, con ki bằng bạc...","cat":"world"},{"id":"ba-lao-chan-ngong","url":"https://truyencotich.top/doc-truyen/ba-lao-chan-ngong","title":"Bà lão chăn ngỗng","summary":"Ngày xưa có một bà già nua, sống cùng đàn ngỗng tại một nơi hẻo lánh giữa núi rừng. Bà ở trong một căn nhà nhỏ...","cat":"world"},{"id":"nguu-lang-chuc-nu","url":"https://truyencotich.top/doc-truyen/nguu-lang-chuc-nu","title":"Ngưu Lang – Chức Nữ","summary":"Ngày xưa, ở làng Ngưu Gia nằm ở phía tây Nam Dương có một chàng trai thông minh, trung hậu, tên là Ngưu Lang, vì cha mẹ qua đời sớm, Ngưu Lang đành phải sống cùng với anh trai và chị dâu...","cat":"world"},{"id":"chim-ung-than","url":"https://truyencotich.top/doc-truyen/chim-ung-than","title":"Chim ưng thần","summary":"Ngày xưa có một ông vua trị vì vào thời nào, tên là gì, tôi không nhớ rõ nữa. Vua không có con trai, chỉ có độc một cô con gái, luôn luôn đau ốm, không thầy thuốc nào chữa khỏi được...","cat":"world"},{"id":"vua-qua","url":"https://truyencotich.top/doc-truyen/vua-qua","title":"Vua Quạ","summary":"Ngày xưa có một ông vua sinh được một cô con gái đẹp tuyệt trần, nhưng kiêu căng ngạo ngược. Ai đến hỏi cô làm vợ, cô cũng chê bai giễu cợt. Một hôm, vua mở tiệc mời tất cả những ai muốn làm phò mã đến và xếp đặt chỗ ngồi theo thứ bậc...","cat":"world"},{"id":"vua-nui-vang","url":"https://truyencotich.top/doc-truyen/vua-nui-vang","title":"Vua Núi Vàng","summary":"Một người lái buôn có hai con, một gái một trai đều nhỏ, chưa biết đi. Bác trang bị hai chiếc tàu, đầy đủ hàng hóa quý giá, tất cả gia tài, của cải đều ở đó...","cat":"world"},{"id":"nguoi-tho-san","url":"https://truyencotich.top/doc-truyen/nguoi-tho-san","title":"Người thợ săn","summary":"Ngày xưa có một vị Hoàng tử yêu vợ chưa cưới tha thiết. Một hôm, chàng đang ngồi bên nàng rất đỗi sung sướng thì nhận được tin cha ốm sắp chết muốn gặp mặt chàng trước khi nhắm mắt...","cat":"world"},{"id":"a-greten-thong-minh","url":"https://truyencotich.top/doc-truyen/a-greten-thong-minh","title":"Ả Grêten thông minh","summary":"Ngày xưa có một cô ả nấu bếp tên là Grêten. Ả thường đi giày gót đỏ khi dạo chơi, ả ngó đông ngó tây, thích chí nghĩ bụng mình cũng vào loại xinh đấy chứ...","cat":"world"},{"id":"chu-hanxo-sung-suong","url":"https://truyencotich.top/doc-truyen/chu-hanxo-sung-suong","title":"Chú Hanxơ Sung Sướng","summary":"Hanxơ đi ở đã được bảy năm. Một hôm, chú thưa với chủ: Thưa ông, tôi ở với ông đã hết hạn rồi, xin ông trả tiền công cho tôi để tôi về nhà với mẹ...","cat":"world"},{"id":"chiec-bat-lua-than","url":"https://truyencotich.top/doc-truyen/chiec-bat-lua-than","title":"Chiếc bật lửa thần","summary":"Một anh lính đang đi trên đường cái. Một, hai! Một, hai! Bọc đồ trên lưng và gươm cạnh sườn, anh vừa tham chiến về, đang trên đường trở lại quê hương. Dọc đường, anh bỗng gặp một mụ phù thuỷ già...","cat":"world"},{"id":"ba-trieu-ba-tram-ba-muoi-ba-ngan-ba-tram-sau-muoi-ba-qua-soi","url":"https://truyencotich.top/doc-truyen/ba-trieu-ba-tram-ba-muoi-ba-ngan-ba-tram-sau-muoi-ba-qua-soi","title":"Ba triệu, ba trăm ba mươi ba ngàn, ba trăm sáu mươi ba quả sồi","summary":"Ngày xưa trong ngôi làng nọ, một người cha có ba đứa con. Người con cả và người con thứ rất siêng năng cần mẫn, luôn tay luôn chân, không bao giờ nghỉ ngơi một phút...","cat":"world"},{"id":"quy-da-xoa","url":"https://truyencotich.top/doc-truyen/quy-da-xoa","title":"Quỷ dạ xoa","summary":"Ngày xưa, trong một ngôi làng nằm cheo leo trên núi cao, có một thanh niên thừa hưởng gia sản của cha mẹ để lại gồm ngôi nhà nhỏ và một con ngựa đẹp...","cat":"world"},{"id":"vi-than-cua-dan-ngheo","url":"https://truyencotich.top/doc-truyen/vi-than-cua-dan-ngheo","title":"Vị thần của dân nghèo","summary":"Ngày xưa tại vùng ven thành phố Ôxaka (Osaka) có một người sống bằng nghề lượm đồ phế thải, anh ta tên là GôHây (Gohei), ở trong một túp lều rách nát...","cat":"world"},{"id":"thien-dang-cua-meo","url":"https://truyencotich.top/doc-truyen/thien-dang-cua-meo","title":"Thiên đàng của mèo","summary":"Ngày xửa ngày xưa, trong một làng nọ, có một người đàn bà con nhà quý tộc, tính tình rất kiêu căng và độc ác...","cat":"world"},{"id":"anh-hay-lay-toi-di","url":"https://truyencotich.top/doc-truyen/anh-hay-lay-toi-di","title":"Anh hãy lấy tôi đi!","summary":"Ngày xửa ngày xưa, xưa lắm, trong một làng hẻo lánh nọ, có ba anh em trai cùng sống chung một nhà. Họ cùng nhau cày cấy mảnh ruộng cha mẹ để lại, hoa màu làm ra không nuôi sống đủ ba thanh niên lực lưỡng...","cat":"world"},{"id":"giang-bi-thit","url":"https://truyencotich.top/doc-truyen/giang-bi-thit","title":"Giăng bị thịt","summary":"Ở giữa vùng thôn quê, có một cái lâu đài cổ, trong lâu đài có một ông hoàng già và hai cậu con trai. Các cậu này thông thái đến nỗi người khác chỉ cần hiểu biết bằng một nửa các cậu cũng đã khá uyên bác rồi...","cat":"world"},{"id":"su-tich-cai-yen-ngua","url":"https://truyencotich.top/doc-truyen/su-tich-cai-yen-ngua","title":"Sự tích cái yên ngựa","summary":"Ngày xưa có một vị quan tên là Hồ Lưu rất hung ác. Năm 62 tuổi, ông ta chết. Diêm chúa lật sổ ra thấy tội trạng còn quá nặng nên bắt buộc ông ta đầu thai làm con ngựa...","cat":"world"},{"id":"hem-nui-nguoi-gia","url":"https://truyencotich.top/doc-truyen/hem-nui-nguoi-gia","title":"Hẻm núi người già","summary":"Hẻm núi người già là truyện cổ tích Nhật Bản có ý nghĩa sâu sắc, câu chuyện nhắc nhở chúng ta phải luôn kính trọng và chăm sóc người già, bởi người già là những người khôn ngoan, hiểu biết và nhiều kinh nghiệm...","cat":"world"},{"id":"doi-giay-bat-ket-tu-di-duoc","url":"https://truyencotich.top/doc-truyen/doi-giay-bat-ket-tu-di-duoc","title":"Đôi giày bát-kết tự đi được","summary":"Có một lần, đôi giày bát kết tự bước đi. Đã từ lâu đôi giày vốn của nhà vô địch chạy đua. Một hôm anh ta vứt vào sọt rác...","cat":"world"},{"id":"cao-su-tu-va-ngua","url":"https://truyencotich.top/doc-truyen/cao-su-tu-va-ngua","title":"Cáo, Sư Tử và Ngựa","summary":"Ngày xưa có một bác nông dân có một con ngựa trung thành. Đến khi ngựa đã già, không còn giúp được việc gì nữa, chủ nó không muốn cho nó ăn uống gì cả...","cat":"world"},{"id":"co-quan-tai-thuy-tinh","url":"https://truyencotich.top/doc-truyen/co-quan-tai-thuy-tinh","title":"Cỗ quan tài thuỷ tinh","summary":"Xưa có một anh thợ may, dáng người nhanh nhẹn, tính tình dễ thương. Anh đi tập nghề, đến cánh rừng kia vì không biết đường nên bị lạc...","cat":"world"},{"id":"cong-chua-ma-ca-rong","url":"https://truyencotich.top/doc-truyen/cong-chua-ma-ca-rong","title":"Công chúa Ma Cà Rồng","summary":"Một ông vua nọ có cô con gái duy nhất, rất đẹp nhưng hơi kỳ dị. Cô nói rất ít và đi lang thang trong cung điện. Càng lớn, cô càng ngủ nhiều. Đến nỗi một buổi sáng, không có cách gì đánh thức cô dậy dược...","cat":"world"},{"id":"cau-be-chan-cuu-va-cay-da-co-thu","url":"https://truyencotich.top/doc-truyen/cau-be-chan-cuu-va-cay-da-co-thu","title":"Cậu bé chăn cừu và cây đa cổ thụ","summary":"Ngày xửa ngay xưa, xưa lắm rồi khi mà muôn thú, cây cỏ, con người còn trò chuyện được với nhau. Trên đồng cỏ rậm ven khu làng có một loài cây gọi là cây đa...","cat":"world"},{"id":"meo-cai-va-nha-su","url":"https://truyencotich.top/doc-truyen/meo-cai-va-nha-su","title":"Mèo cái và nhà sư","summary":"Ngày xưa, có một nhà sư hành ngoại, ông đi khắp nơi từ mùa xuân cho tới mùa đông, khi thì hái cỗ thuốc trong rừng, khi thì cầu nguyện ở các đám tang, và khi thì đi bắt mạch khám bệnh, mà việc chữa bệnh của ông rất thành công...","cat":"world"},{"id":"rau-lua","url":"https://truyencotich.top/doc-truyen/rau-lua","title":"Rau Lừa","summary":"Xưa có một người thợ săn trẻ tuổi vào rừng rình thú. Lòng anh phơi phới. Anh vừa đi vừa thổi kèn bằng lá, bỗng gặp một bà lão già nua, xấu xí...","cat":"world"},{"id":"con-chim-hoa-mi","url":"https://truyencotich.top/doc-truyen/con-chim-hoa-mi","title":"Con chim họa mi","summary":"Ở Trung Quốc, nơi mà Hoàng đế là một người Trung Quốc và tất cả quần thần cũng là người Trung Quốc, các bạn hẳn cũng biết điều đó, đã có một câu chuyện. Câu chuyện này xảy ra lâu lắm rồi, nhưng chính vì thế mà phải kể lại...","cat":"world"},{"id":"con-lon-ong-tien","url":"https://truyencotich.top/doc-truyen/con-lon-ong-tien","title":"Con lợn ống tiền","summary":"Căn phòng của trẻ con đầy những đồ chơi là đồ chơi.Trên mặt cái tủ nhiều ngăn kéo có một cái ống tiền bằng sành, hình con lợn...","cat":"world"},{"id":"con-quy-su-cua-ong-hang-tap-hoa","url":"https://truyencotich.top/doc-truyen/con-quy-su-cua-ong-hang-tap-hoa","title":"Con quỷ sứ của ông hàng tạp hóa","summary":"Ngày xưa có một anh chàng sinh viên nghèo, thật thà, ngay thẳng, sống trong một căn gác xép, chẳng có lấy một tí gì...","cat":"world"},{"id":"cay-lua-mach","url":"https://truyencotich.top/doc-truyen/cay-lua-mach","title":"Cây lúa mạch","summary":"Nếu bạn đi qua cánh đồng lúa mạch sau cơn bão bạn sẽ thấy lúa đen như thể là bị cháy. Tôi sẽ kể cho bạn nguyên nhân lúa bị đen, qua câu chuyện một chú chim sẻ...","cat":"world"},{"id":"nang-tien-ca","url":"https://truyencotich.top/doc-truyen/nang-tien-ca","title":"Nàng tiên cá","summary":"Tít ngoài biển khơi kia, nước xanh hơn cánh đồng hoa mua biếc nhất, trong vắt như pha lê, nhưng sâu thăm thẳm, sâu đến nỗi neo buông không tới đáy, phải chồng chất vô số ngọn núi đá mới lên tới mặt nước...","cat":"world"},{"id":"nha-vua-hi-lap-va-thay-thuoc-douban","url":"https://truyencotich.top/doc-truyen/nha-vua-hi-lap-va-thay-thuoc-douban","title":"Nhà vua Hi Lạp và thầy thuốc Douban","summary":"Ngày xưa ở xứ Zouman quốc gia Ba Tư có một ông vua mà thần dân vốn là gốc người Hi Lạp. Ông vua này bị bệnh phong. Những ngự y sau khi đã dùng đủ các loại thuốc để chữa trị cho vua của họ nhưng không đem lại kết quả gì cả.","cat":"world"},{"id":"nguoi-di-khap-the-gian","url":"https://truyencotich.top/doc-truyen/nguoi-di-khap-the-gian","title":"Người đi khắp thế gian","summary":"Xưa có một anh chàng nghề gì cũng giỏi. Khi ra trận thì chiến đấu anh dũng, hết thời chinh chiến, anh bị thải về, được phát có ba đồng tiền làm lộ phí...","cat":"world"},{"id":"su-tich-con-su-tu","url":"https://truyencotich.top/doc-truyen/su-tich-con-su-tu","title":"Sự tích con Sư Tử","summary":"Thuở xưa, có một hoàng tử mới mới lên ngôi hoàng đế. Ngay lập tức chàng muốn đi học phép thuật để củng cố đất nước. Chàng đi tìm một ông thầy bùa chú rất nổi tiếng về phép thuật để học...","cat":"world"},{"id":"su-tich-hoa-phong-lan","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-phong-lan","title":"Sự tích hoa Phong Lan","summary":"Ở một miền xa xôi, khí hậu ấm áp và đất đai trù phú có một bộ lạc tên là Aruaki may mắn hơn các bộ lạc khác vì họ sai khiến được loài chim Oócchít chuyên đẻ những quả trứng bằng vàng...","cat":"world"},{"id":"su-tich-hoa-xuyen-chi","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-xuyen-chi","title":"Sự tích hoa xuyến chi","summary":"Ngày xửa ngày xưa, ở vùng nọ có một người con gái rất xinh đẹp. Ai mới nhìn cô lần đầu thôi là không thể quên được khuôn mặt rạng ngời như ánh trăng rằm, nụ cười như hoa ban sớm...","cat":"world"},{"id":"su-tich-hoa-hue-tay","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-hue-tay","title":"Sự tích hoa Huệ Tây","summary":"Những giọt nước mắt nào có giúp được gì! Giắc sẽ phải lên đường chinh chiến ở một xứ xa lạ, đành bỏ lại Lilia, người vợ chưa cưới của mình trên đất Pháp...","cat":"world"},{"id":"chiec-kim-tho","url":"https://truyencotich.top/doc-truyen/chiec-kim-tho","title":"Chiếc kim thô","summary":"Một hôm có một cái kim thô dùng để lược quần áo, tự cho là thanh tú lắm, nên cứ tưởng mình là một cái kim khâu...","cat":"world"},{"id":"dua-con-vang","url":"https://truyencotich.top/doc-truyen/dua-con-vang","title":"Đứa con vàng","summary":"Xưa có hai vợ chồng nhà kia rất nghèo. Của cải chỉ có độc một túp lều nhỏ. Ngày ngày hai người đi bắt cá, làm chẳng đủ ăn. Bỗng một hôm, người chồng thả lưới xuống nước cất lên được một con cá toàn vàng...","cat":"world"},{"id":"hoang-anh-va-gau","url":"https://truyencotich.top/doc-truyen/hoang-anh-va-gau","title":"Hoàng Anh và Gấu","summary":"Một ngày hè, gấu và sói đi dạo chơi trong rừng. Gấu nghe có tiếng chim hót véo von, liền hỏi bạn: - Sói này, chim gì mà hót hay thế hở mày?","cat":"world"},{"id":"jorindo-va-jorigon","url":"https://truyencotich.top/doc-truyen/jorindo-va-jorigon","title":"Jôrinđơ và Jôrigơn","summary":"Ngày xưa, có một bà già sống một mình trong một tòa lâu đài cổ giữa một khu rừng bao la, rậm rạp. Đó là một mụ phù thủy cừ khôi. Ban ngày, mụ hóa thành mèo hoặc cú vọ...","cat":"world"},{"id":"cay-cu-cai","url":"https://truyencotich.top/doc-truyen/cay-cu-cai","title":"Cây Củ Cải","summary":"Ngày xưa có hai anh em đều đi lính. Anh thì giàu, em thì nghèo. Người em không muốn sống nghèo khổ mãi, bỏ lính về làm nông dân. Anh cuốc một vạt đất ở đầu cánh đồng và gieo hạt củ cải...","cat":"world"},{"id":"con-nam-o-ao","url":"https://truyencotich.top/doc-truyen/con-nam-o-ao","title":"Con nam ở ao","summary":"Xưa có hai vợ chồng người thợ xay bột sống rất sung sướng. Họ có tiền của, mỗi năm lại sung túc thêm. Nhưng hoạn nạn thường đến bất ngờ. Của đến mau, của cũng đi mau, rút cục đến cái nhà xay bác ở vị tất đã còn là của bác...","cat":"world"},{"id":"con-tho-bien","url":"https://truyencotich.top/doc-truyen/con-tho-bien","title":"Con Thỏ Biển","summary":"Ngày xửa ngày xưa, một nàng công chúa có một tòa lâu đài. Ở trên nóc tháp có một cái phòng có mười hai cửa sổ trông ra mọi hướng. Lên đó, nhìn xuống, công chúa thấy toàn bộ đất nước bao la...","cat":"world"},{"id":"do-bo-xo","url":"https://truyencotich.top/doc-truyen/do-bo-xo","title":"Đồ bỏ xó","summary":"Ngày xưa, có một người xay bột nghèo mà lại có một cô con gái xinh đẹp. Có lần, bác ta tình cờ được nói chuyện với nhà vua. Để tự đề cao, bác ta tâu vua: - Tâu bệ hạ, tôi có một đứa con gái kéo được rơm thành vàng...","cat":"world"},{"id":"ngoi-nha-trong-rung","url":"https://truyencotich.top/doc-truyen/ngoi-nha-trong-rung","title":"Ngôi nhà trong rừng","summary":"Có một bác tiều phu nghèo sống với vợ và ba con gái trong túp lều nhỏ ven một khu rừng hẻo lánh. Một buổi sớm, lúc sắp đi làm bác dặn vợ: - &quot;Trưa nay mình để đứa lớn mang thức ăn vào rừng cho ta nhé, tôi về sợ làm không hết việc&quot;...","cat":"world"},{"id":"ngon-den-xanh","url":"https://truyencotich.top/doc-truyen/ngon-den-xanh","title":"Ngọn đèn xanh","summary":"Ngày xưa, có một người lính tận tụy với nhà vua bao nhiêu năm trời ròng rã. Hết thời chinh chiến, người ấy bị thương nhiều, không phụng sự được nữa...","cat":"world"},{"id":"nguoi-bay-toi-trung-thanh","url":"https://truyencotich.top/doc-truyen/nguoi-bay-toi-trung-thanh","title":"Người bầy tôi trung thành","summary":"Xưa có một ông vua tuổi già lâm bệnh, nghĩ bụng: &quot;Ta chết đến nơi mất rồi&quot;. Vua cho đòi &quot;bác Jôhannơt trung thành&quot; tới. Bác là người hầu được vua yêu nhất. Bác đã suốt đời tận tụy với vua. Vì vậy mà vua gọi bác là &quot;bác Jôhannơt trung thành&quot;...","cat":"world"},{"id":"doi-giay-ung-da-trau-va-nguoi-linh-gia-can-dam","url":"https://truyencotich.top/doc-truyen/doi-giay-ung-da-trau-va-nguoi-linh-gia-can-dam","title":"Đôi giày ủng da trâu và người lính già can đảm","summary":"Một người lính đã chẳng sợ gì thì cũng chẳng bận tâm đến việc gì cả. Xưa có một người lính như vậy bị thải hồi. Bác ta không học được nghề gì nên không kiếm tiền được, đành đi lang thang ăn xin thiên hạ...","cat":"world"},{"id":"nguoi-tho-san-tai-gioi","url":"https://truyencotich.top/doc-truyen/nguoi-tho-san-tai-gioi","title":"Người thợ săn tài giỏi","summary":"Xưa có một gã con trai học nghề thợ khóa. Một hôm anh thưa cha, muốn ra ngoài thiên hạ để thi thố tài năng. Người cha bảo: - Được con ạ, cha cũng bằng lòng thôi...","cat":"world"},{"id":"nhung-nguoi-khon","url":"https://truyencotich.top/doc-truyen/nhung-nguoi-khon","title":"Những người khôn","summary":"Một hôm, một bác nông dân rút ở xó nhà ra chiếc gậy gỗ trăn rồi bảo vợ: - Này nhà ạ, tôi đi ba ngày nữa mới về đấy. Nếu lái bò có đến mua ba con bò nhà ta, thì nhà bán rẻ cũng được, nhưng phải lấy hai trăm đồng, kém thì đừng có bán nghe chưa...","cat":"world"},{"id":"qua-cua-nguoi-ty-hon","url":"https://truyencotich.top/doc-truyen/qua-cua-nguoi-ty-hon","title":"Quà của người tý hon","summary":"Một bác thợ may và một bác thợ vàng cùng đi với nhau. Một hôm, mặt trời vừa lặn sau núi, họ thấy xa xa có tiếng nhạc, càng đến gần nghe càng rõ. Tiếng nhạc kỳ lạ du dương khiến họ quên cả mệt mỏi rảo bước đi về phía đó...","cat":"world"},{"id":"tho-va-nhim","url":"https://truyencotich.top/doc-truyen/tho-va-nhim","title":"Thỏ và Nhím","summary":"Chuyện này kể ra nghe có vẻ như chuyện bịa, các cháu ạ. Nhưng quả là có thật, vì truyện do ông tôi kể lại, mà kể một cách thích thú lắm...","cat":"world"},{"id":"nam-con-ma","url":"https://truyencotich.top/doc-truyen/nam-con-ma","title":"Năm con ma","summary":"Đêm đã buông xuống mà chàng kỵ sĩ cũng không biết mình sẽ ngủ đâu, chàng là võ sĩ Dôsinari (yoshinari). Một mình trước trời nước bao la, chàng đi qua một cánh đồng cỏ, đưa mắt nhìn bốn phía với hy vọng tìm ra một ngôi làng...","cat":"world"},{"id":"ty-ba-quan","url":"https://truyencotich.top/doc-truyen/ty-ba-quan","title":"Tỳ bà quán","summary":"Tại thành phố Xakai (Sakai) có ba người bạn trẻ làm nghề buôn bán tên là Kuêmông (Kouemong), Xaxukê (Sasouké) và Subê (Tsoubé). Họ đồng ý cùng nhau đi lễ đầu xuân ở Xumisôchi (Souíyouchi)...","cat":"world"},{"id":"cay-de-tra-on","url":"https://truyencotich.top/doc-truyen/cay-de-tra-on","title":"Cây dẻ trả ơn","summary":"Ngày xưa, trong một làng đánh cá, có một người đàn bà góa sống với cô con gái duy nhất. Hai mẹ con mới đến làng này cách đây mấy năm thôi. Khi người chồng chưa mất thì cả gia đình sống hạnh phúc trong cảnh sung túc...","cat":"world"},{"id":"tien-hac-den-on","url":"https://truyencotich.top/doc-truyen/tien-hac-den-on","title":"Tiên hạc đền ơn","summary":"Thuở xưa, tại một thôn làng nhỏ bé dưới chân núi Phú-Sĩ-Sơn, có một cặp vợ chồng rất nghèo. Chồng làm nghề săn bắn, còn vợ làm nghề dệt lụa. Tài năng của hai người rất giới hạn, tuổi cũng đã cao cho nên đời sống vật chất của họ rất chật vật...","cat":"world"},{"id":"co-trung-gian-gioi-cung-chang-loi-quai-gi","url":"https://truyencotich.top/doc-truyen/co-trung-gian-gioi-cung-chang-loi-quai-gi","title":"Có trung gian giỏi cũng chẳng lợi quái gì","summary":"Vào thời thật xa xưa, khi ấy thế giới có diện mạo khác xa với bây giờ. Cỏ thì mọc cao đến tận trời, còn cây thì chỉ ngang đến đầu gối thôi. Thời ấy rắn chưa có mắt, nhưng ngược lại, nó có giọng hát nam trung thật tuyệt vời...","cat":"world"},{"id":"chiec-guong-cua-matsuyama","url":"https://truyencotich.top/doc-truyen/chiec-guong-cua-matsuyama","title":"Chiếc gương của Matsuyama","summary":"Ngày xưa ở vùng xa xôi của nước Nhật có một đôi vợ chồng cùng cô con gái nhỏ tên là Matsu Yama sinh sống. Cô con gái được bố mẹ yêu quý và cực kì cưng chiều. Một lần người chồng phải lên Kyoto xa xôi để làm việc...","cat":"world"},{"id":"su-tich-mua-xuan","url":"https://truyencotich.top/doc-truyen/su-tich-mua-xuan","title":"Sự tích mùa xuân","summary":"Bé có biết tại sao khi mùa Xuân về, ngoài vườn ngoài phố lại có nhiều hoa khoe sắc thế không? Ngày xửa ngày xưa, không có mùa Xuân đâu bé ạ. Một năm chỉ có ba mùa thôi nhé, mùa Hạ, mùa Thu, và mùa Đông...","cat":"world"},{"id":"cau-chuyen-bon-mua","url":"https://truyencotich.top/doc-truyen/cau-chuyen-bon-mua","title":"Câu chuyện bốn mùa","summary":"Vào một ngày đầu năm, bốn nàng tiên Xuân, Hạ, Thu, Đông gặp nhau ở vườn đào. Các chị em ai cũng phấn khởi vì được gặp lại nhau, họ nói cười vô cùng vui vẻ...","cat":"world"},{"id":"su-gia-mua-xuan","url":"https://truyencotich.top/doc-truyen/su-gia-mua-xuan","title":"Sứ giả mùa xuân","summary":"Xưa thật là xưa, có bốn nàng tiên làm nữ hoàng của các mùa: Xuân, Hạ, Thu và Đông. Mỗi nàng có một cung điện lộng lẫy trên một ngọn núi cao. Chỉ khi đến mùa, các nàng mới xuất hiện. Năm ấy, không hiểu sao mùa Đông kéo dài lê thê...","cat":"world"},{"id":"truyen-co-tich-ve-bong-dem","url":"https://truyencotich.top/doc-truyen/truyen-co-tich-ve-bong-dem","title":"Truyện cổ tích về Bóng Đêm","summary":"Ngày xưa, xưa thật là xưa, khi Bóng Đêm chiếm toàn bộ trái đất, Bóng Đêm tự cho mình là độc tôn, là duy nhất. Thời gian dần trôi, bên cạnh Bóng Đêm còn có Ánh Sáng mặt trời, Ánh Sáng của những vì sao le lói...","cat":"world"},{"id":"muoi-hai-nguoi-tho-san","url":"https://truyencotich.top/doc-truyen/muoi-hai-nguoi-tho-san","title":"Mười hai người thợ săn","summary":"Ngày xưa có một vị Hoàng tử yêu vợ chưa cưới tha thiết. Một hôm, chàng đang ngồi bên nàng rất đỗi sung sướng thì nhận được tin cha ốm sắp chết muốn gặp mặt chàng trước khi nhắm mắt...","cat":"world"},{"id":"su-tich-hoa-anh-dao","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-anh-dao","title":"Sự tích hoa anh đào","summary":"Ngày xưa ở xứ Phù tang chưa có hoa anh đào như bây giờ. Tại một ngôi làng xinh xinh ven núi Phú Sĩ ,có một chàng trai khôi ngô tuấn tú dũng cảm khác thường...","cat":"world"},{"id":"lam-cho-cong-chua-noi-duoc","url":"https://truyencotich.top/doc-truyen/lam-cho-cong-chua-noi-duoc","title":"Làm cho công chúa nói được","summary":"Ngày xưa có một nàng công chúa con một ông vua nước nọ nổi tiếng xinh đẹp, nhưng có điều đặc biệt là nàng vốn ít điều ít lời, thường rất hà tiện lời nói. Trừ những lúc thật cần thiết, còn ít khi nàng chịu mở miệng nói ra...","cat":"world"},{"id":"truyen-thuyet-ve-trai-dao","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-ve-trai-dao","title":"Truyền thuyết về trái Đào","summary":"Lâu lắm rồi ở miền Bắc Trung Quốc nọ có một làng nhỏ nằm heo hút trên một ngọn núi cao chỉ vài gia đình sống ở đó.Trong làng ấy có một chàng trai dũng cảm với trái tim tấm lòng nhân hậu tên là Đào Tử...","cat":"world"},{"id":"mot-dong-tien-vang","url":"https://truyencotich.top/doc-truyen/mot-dong-tien-vang","title":"Một đồng tiền vàng","summary":"Ngày xưa, có hai vợ chồng giàu có nọ sinh được một người con trai. Vì quá đổi yêu thương con nên bà mẹ hầu như cả ngày chẳng để cậu ta đụng đến việc gì, dần dần cậu con trai trở nên lười ơi là lười, đến nỗi một đồng xu cũng không kiếm nỗi...","cat":"world"},{"id":"con-than-ma","url":"https://truyencotich.top/doc-truyen/con-than-ma","title":"Con thần mã","summary":"Ngày xưa, có một khu rừng đen, rất nhiều thú dữ, rắn độc, thường ra bắt người ăn thịt. Người qua lại đều phải đi vòng quanh rất xa. Các thợ đi săn xa gần đều không ai dám đến săn bắn ở rừng đen...","cat":"world"},{"id":"chang-danh-ca-urasima","url":"https://truyencotich.top/doc-truyen/chang-danh-ca-urasima","title":"Chàng đánh cá URaSiMa","summary":"Ngày xưa có một chàng đánh cá tên là URaSiMa (Ourachima), cùng ở với cha mẹ trong một ngôi làng nhỏ. Căn nhà của họ nằm ở cách xa làng một chút, khuất dưới vách đá cao chồm ra mặt biển...","cat":"world"},{"id":"chuyen-phieu-luu-cua-nguoi-dan-chieu","url":"https://truyencotich.top/doc-truyen/chuyen-phieu-luu-cua-nguoi-dan-chieu","title":"Chuyện phiêu lưu của người đan chiếu","summary":"Ngày xưa, trong một thành phố nọ, có rất nhiều người sinh sống, giàu có, nghèo có, thợ lành nghề có, thương gia ngay thẳng có, nhưng cũng có nhiều người lười biếng, vô căn vô cội như trong bất kỳ thành phố nào khác...","cat":"world"},{"id":"lay-oan-tra-on","url":"https://truyencotich.top/doc-truyen/lay-oan-tra-on","title":"Lấy oán trả ơn","summary":"MôRôXuKê (Morosouké) đang trên đường đi đến một vùng xa xôi của nước Nhật. Anh ta còn trẻ, cha mẹ mất hết, tứ cố vô thân, bạn bè cũng không, cho nên không có ai dìu dắt anh ở nơi kinh kỳ, hay giúp anh xây dựng một cơ ngơi để sinh sống...","cat":"world"},{"id":"co-tich-giang-sinh","url":"https://truyencotich.top/doc-truyen/co-tich-giang-sinh","title":"Cổ tích Giáng Sinh","summary":"Có một cô bé mồ côi cha sống với mẹ tại một vùng quê hẻo lánh. Nhà rất nghèo, hai mẹ con phải làm việc quần quật cả ngày mới kiếm đủ ăn. Cô bé không có bạn bè, không có đồ chơi nhưng cô không bao giờ cảm thấy buồn và cô đơn...","cat":"world"},{"id":"chuyen-phieu-luu-cua-thay-ky-tokybay","url":"https://truyencotich.top/doc-truyen/chuyen-phieu-luu-cua-thay-ky-tokybay","title":"Chuyện phiêu lưu của thầy ký TôKyBây","summary":"Ngày xưa có một thương gia rất giàu, đến nỗi các ông hoàng thế lực nhất trong vương quốc cũng đến mượn tiền của ông ta...","cat":"world"},{"id":"chin-vi-tu-si","url":"https://truyencotich.top/doc-truyen/chin-vi-tu-si","title":"Chín vị tu sĩ","summary":"Kakiêmông (kakiémon) người gốc Oxaka (osaka), còn trẻ, nhưng khi gia đình sa sút mà lại trơ trọi một mình, nên anh quyết định đến thử thời vận ở đất kinh kỳ Êđô (edo) ra sao...","cat":"world"},{"id":"phat-cua-khi","url":"https://truyencotich.top/doc-truyen/phat-cua-khi","title":"Phật của khỉ","summary":"Ngày xưa có hai vợ chồng già nọ, nếu không có lũ chim phá hoại hoa màu thì chắc họ đã sống sung sướng rồi. Ông già rất thích làm việc ngoài đồng...","cat":"world"},{"id":"chim-seu-trang","url":"https://truyencotich.top/doc-truyen/chim-seu-trang","title":"Chim sếu trắng","summary":"Ngày xưa có một đôi vợ chồng già chỉ có một cậu con trai độc nhất tên là Kôtarô (kotaro). Kôtarô lo cày xới mảnh ruộng nhỏ của gia đình, và khi hết việc đồng áng anh lại vào rừng kiếm củi để mang ra chợ bán...","cat":"world"},{"id":"long-mi-cua-cho-soi","url":"https://truyencotich.top/doc-truyen/long-mi-cua-cho-soi","title":"Lông mi của chó sói","summary":"Ngày xưa trong một ngôi làng nọ có một người thợ rèn giàu có, ông ta sống với cô con gái độc nhất, tên là Akiko (Akikô). Vợ của ông thợ rèn chết sau khi sinh con và người chồng lấy vợ hai, vì ông cần có người trông nom nhà cứa...","cat":"world"},{"id":"ong-gia-lam-cay-no-hoa","url":"https://truyencotich.top/doc-truyen/ong-gia-lam-cay-no-hoa","title":"Ông già làm cây nở hoa","summary":"Dưới chân ngọn núi nọ, có một con sông nhỏ uốn khúc chảy qua. Tại đây có hai gia đình sống cạnh nhau đã lâu đời lắm rồi. Một gia đình ở thượng nguồn và một gia đình ở hạ nguồn, do đó người ta gọi họ là gia đình ở trên và gia đình ở dưới...","cat":"world"},{"id":"cai-chuong-ma-bac","url":"https://truyencotich.top/doc-truyen/cai-chuong-ma-bac","title":"Cái chuông mạ bạc","summary":"Ngày xưa có một nhà sư già hiền từ trụ trì trong một ngôi chùa ở một thành phố nhỏ gần biển. Nhà sư thích nhất là được ngồi trên hành lang để ngắm sóng biển...","cat":"world"},{"id":"chu-linh-chi-dung-cam","url":"https://truyencotich.top/doc-truyen/chu-linh-chi-dung-cam","title":"Chú lính chì dũng cảm","summary":"Ngày xưa, có hai mươi lăm anh lính chì, họ là anh em ruột, vì họ được đúc ra từ một cái muỗng chì cũ. Họ mang trên vai mỗi người một cây súng trường, mặc bộ quân phục xanh nẹp đỏ rất oai vệ...","cat":"world"},{"id":"ho-nhiep-gap-ma","url":"https://truyencotich.top/doc-truyen/ho-nhiep-gap-ma","title":"Họ Nhiếp gặp ma","summary":"Xưa có người họ Nhiếp. Một năm vào mùa đông dịp trước Tết, ông vào núi sâu viếng mộ trở về, do trời rét ngày ngắn, lúc này cả bầu trời âm u nặng nề, thời gian cũng đã khá muộn rồi...","cat":"world"},{"id":"choi-kham-kieu-ga-vit","url":"https://truyencotich.top/doc-truyen/choi-kham-kieu-ga-vit","title":"Chơi khăm kiểu gà vịt","summary":"Gà trống nói với gà mái: - Giờ đang mùa hạt dẻ, chúng ta hãy cùng nhau lên núi ăn một bữa hạt dẻ thật thỏa thuê, kẻo chậm chân lũ sóc chúng ăn hết...","cat":"world"},{"id":"nhung-nhac-si-thanh-bremen","url":"https://truyencotich.top/doc-truyen/nhung-nhac-si-thanh-bremen","title":"Những nhạc sĩ thành Bremen","summary":"Ngày xưa, bác nông dân ở vùng nọ có một con lừa. Bao năm nay lừa kéo xe chở lúa đến nhà xay không hề biết mệt. Nhưng giờ đây sức lừa đã kiệt, không thể dùng kéo xe được nữa...","cat":"world"},{"id":"mot-ba-me","url":"https://truyencotich.top/doc-truyen/mot-ba-me","title":"Một bà mẹ","summary":"Một bà mẹ đang ngồi bên đứa con thơ. Bà rất buồn vì đang lo đứa con bà chết mất. Đứa bé xanh rớt đã nhắm nghiền đôi mắt và đang thoi thóp...","cat":"world"},{"id":"con-ca-vang-va-nang-lang-quen","url":"https://truyencotich.top/doc-truyen/con-ca-vang-va-nang-lang-quen","title":"Con cá vàng và nàng lãng quên","summary":"Ngày xửa ngày xưa, tại gia đình nọ có bảy chị em gái. Cô cả xinh đẹp, nhưng cô hai còn xinh hơn và cô thứ ba thì xinh nhất. Cô thứ tư biết đi mây về gió, cô thứ năm có tài ngủ mà như không ngủ...","cat":"world"},{"id":"sau-nguoi-ky-tai","url":"https://truyencotich.top/doc-truyen/sau-nguoi-ky-tai","title":"Sáu người kỳ tài","summary":"Xưa có một nữ vương, vốn là một mụ phù thủy. Con gái mụ xinh đẹp tuyệt trần không ai sánh bằng. Mụ chẳng nghĩ gì khác ngoài cách lôi kéo mọi người vào vòng khổ ải, chết chóc...","cat":"world"},{"id":"co-be-ti-hon","url":"https://truyencotich.top/doc-truyen/co-be-ti-hon","title":"Cô bé tí hon","summary":"Ngày xưa có một bà hiếm hoi, mong có một đứa con mà mãi không được. Bà phải tìm đến một mụ phù thủy để nhờ giúp...","cat":"world"},{"id":"johannes-trung-thanh","url":"https://truyencotich.top/doc-truyen/johannes-trung-thanh","title":"Johannes trung thành","summary":"Johannes suốt đời trung thành, tận tụy với nhà vua, được nhà vua yêu quý, cũng vì vậy mà có cái tên Iôhanét trung thành...","cat":"world"},{"id":"nang-maleen","url":"https://truyencotich.top/doc-truyen/nang-maleen","title":"Nàng Maleen","summary":"Ngày xửa ngày xưa, hoàng tử nước kia muốn xin cưới nàng Maleen đẹp tuyệt trần, con gái vua một nước hùng cường. Vì nhà vua định gả nàng cho một người khác nên lời hỏi của hoàng tử bị khước từ...","cat":"world"},{"id":"ong-lao-danh-ca-ngheo-kho","url":"https://truyencotich.top/doc-truyen/ong-lao-danh-ca-ngheo-kho","title":"Ông lão đánh cá nghèo khổ","summary":"Tâu bệ hạ, ngày xưa có một ông lão đánh cá già nua, nghèo khổ đến nỗi không sao có thể nuôi sống được gia đình gồm một vợ và ba con nhỏ...","cat":"world"},{"id":"co-gai-thong-minh","url":"https://truyencotich.top/doc-truyen/co-gai-thong-minh","title":"Cô gái thông minh","summary":"Ngày xưa có hai anh em, một người thì nghèo, một người thì giàu. Người em nghèo đến cả cái bát ăn cơm, cái vá múc canh, cái chén uống nước cũng chẳng có...","cat":"world"},{"id":"nang-cong-chua-mat-troi","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-mat-troi","title":"Nàng công chúa mặt trời","summary":"Ngày xửa ngày xưa, có một nhà vua và một bà hoàng hậu sống bên kia chín ngọn núi và chín cánh rừng. Họ sinh hạ được một cậu con trai mà họ yêu thương da diết...","cat":"world"},{"id":"bon-anh-em-tai-gioi","url":"https://truyencotich.top/doc-truyen/bon-anh-em-tai-gioi","title":"Bốn anh em tài giỏi","summary":"Ngày xưa, có một người đàn ông nghèo sinh được bốn người con trai...","cat":"world"},{"id":"chang-hoang-tu-khong-biet-so","url":"https://truyencotich.top/doc-truyen/chang-hoang-tu-khong-biet-so","title":"Chàng hoàng tử không biết sợ","summary":"Ngày xửa ngày xưa có một hoàng tử không thích sống ru rú ở trong hoàng cung. Chàng chẳng biết sợ là gì...","cat":"world"},{"id":"su-tich-mat-trang","url":"https://truyencotich.top/doc-truyen/su-tich-mat-trang","title":"Sự tích mặt trăng","summary":"Đất nước này có từ hồi mới khai thiên lập địa, ở đây ban đêm trời tối đen như mực, vì chẳng có trăng, sao chiếu sáng, bầu trời như một tấm thảm đen bao trùm khắp đất nước...","cat":"world"},{"id":"truyen-thuyet-hoa-phu-dung","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-hoa-phu-dung","title":"Truyền thuyết hoa Phù Dung","summary":"Ngày xưa trên thiên cung có 1 nàng tiên nương , tánh tình hiền lành tốt bụng nhưng nét mặt lúc nào cũng buồn rầu ưu uất. Pháp hiệu là &quot;Phù Dung Tiên Nữ&quot; sống trong cõi tiên nhưng không làm sao vui được...","cat":"world"},{"id":"chuot-nhat-chim-se-va-doi-nuong","url":"https://truyencotich.top/doc-truyen/chuot-nhat-chim-se-va-doi-nuong","title":"Chuột nhắt, chim sẻ và dồi nướng","summary":"Ngày xửa ngày xưa, có một con chuột nhắt sống chung với chim sẻ và dồi nướng. Chúng sống chung với nhau rất hòa thuận, ăn nên làm ra...","cat":"world"},{"id":"hen-xui","url":"https://truyencotich.top/doc-truyen/hen-xui","title":"Hên xui","summary":"Bác nông dân đem bò ra chợ và bán được bảy Taler. Dọc đường về, bác đi qua một cái chuôm, bác nghe tiếng ếch kêu: &quot;Ắc, ắc, ắc&quot;...","cat":"world"},{"id":"nguoi-nhac-si-lang-thang","url":"https://truyencotich.top/doc-truyen/nguoi-nhac-si-lang-thang","title":"Người nhạc sĩ lang thang","summary":"Ngày xưa có một nhạc sĩ lang thang, ông đi thơ thẩn ở trong rừng, một mình đi giữa cánh rừng rộng ông thấy lòng mình trống trải...","cat":"world"},{"id":"chiec-tu-va-biet-hat","url":"https://truyencotich.top/doc-truyen/chiec-tu-va-biet-hat","title":"Chiếc tù và biết hát","summary":"Ngày xửa ngày xưa, ở đất nước kia có nạn lợn rừng. Với hai chiếc răng nanh dài nhọn nó xục ủi hết cả ruộng đồng hoa màu, lúa má của nông dân, không những thế nó còn húc chết nhiều người...","cat":"world"},{"id":"ran-va-bo-cho","url":"https://truyencotich.top/doc-truyen/ran-va-bo-cho","title":"Rận và bọ chó","summary":"Rận và bọ chó cùng nhau nấu bia bằng vỏ trứng. Rận té ngã vào lửa và bị chết thiêu. Bọ chó lăn ra khóc thương bạn...","cat":"world"},{"id":"else-lau-ca","url":"https://truyencotich.top/doc-truyen/else-lau-ca","title":"Else láu cá","summary":"Xưa có một người đàn ông, bác có một người con gái tên là Else láu cá. Khi con gái đã đến tuổi trưởng thành, bác nói: Cha sẽ gả chồng cho con...","cat":"world"},{"id":"cay-do-tung","url":"https://truyencotich.top/doc-truyen/cay-do-tung","title":"Cây đỗ tùng","summary":"Câu chuyện xảy ra cách đây đã lâu, có tới hai nghìn năm. Một người đàn ông giầu có, vợ xinh đẹp dịu dàng nên họ sống với nhau rất êm ấm, nhưng họ lại không có con...","cat":"world"},{"id":"ba-trude","url":"https://truyencotich.top/doc-truyen/ba-trude","title":"Bà Trude","summary":"Ngày xửa ngày xưa, có một cô bé bướng bỉnh và hiếu động. Cô không nghe lời cha mẹ, các bạn có biết cô bé như thế nào không? Mời các bạn nghe câu chuyện sau...","cat":"world"},{"id":"chang-re-tuong-lai","url":"https://truyencotich.top/doc-truyen/chang-re-tuong-lai","title":"Chàng rể tương lai","summary":"Ngày xưa có một người thợ xay bột, ông có một người con gái xinh đẹp và mong gả cô cho một người khá giả để đỡ khổ...","cat":"world"},{"id":"ong-korbs","url":"https://truyencotich.top/doc-truyen/ong-korbs","title":"Ông Korb&#039;s","summary":"Ngày xửa ngày xưa có một con gà trống và một con gà mái rủ nhau đi chu du thiên hạ. Gà trống đóng một chiếc xe thật đẹp, bốn bánh xe sơn màu đỏ và do bốn con chuột kéo...","cat":"world"},{"id":"cho-sultan-trung-thanh","url":"https://truyencotich.top/doc-truyen/cho-sultan-trung-thanh","title":"Chó Sultan trung thành","summary":"Bác nông dân có con chó tên là Sultan, nó rất trung thành với chủ. Nhưng giờ nó đã già nua, răng rụng hết chẳng còn chiếc này nên chẳng cắn và tha mồi được..","cat":"world"},{"id":"be-fundevogel","url":"https://truyencotich.top/doc-truyen/be-fundevogel","title":"Bé Fundevogel","summary":"Ngày xửa ngày xưa có một người lục lâm vào trong rừng đi săn. Vừa mới đi được một quãng thì bác nghe thấy có tiếng trẻ con khóc...","cat":"world"},{"id":"chiec-tui-det-chiec-mu-cai-tu-va-bang-sung","url":"https://truyencotich.top/doc-truyen/chiec-tui-det-chiec-mu-cai-tu-va-bang-sung","title":"Chiếc túi dết, chiếc mũ, cái tù và bằng sừng","summary":"Ngày xửa ngày xưa có ba anh em nhà kia, cảnh nhà cứ mỗi ngày một nghèo túng hơn...","cat":"world"},{"id":"allerleirauh-hay-la-cong-chua-lom-dom","url":"https://truyencotich.top/doc-truyen/allerleirauh-hay-la-cong-chua-lom-dom","title":"Allerleirauh hay là công chúa lốm đốm","summary":"Ngày xửa ngày xưa có một ông vua. Hoàng hậu tóc vàng xinh đẹp tới mức chẳng có ai trên trần gian này có thể so sánh nổi. Lần ấy hoàng hậu ốm và biết rằng mình chẳng sống bao lâu nữa...","cat":"world"},{"id":"con-qua","url":"https://truyencotich.top/doc-truyen/con-qua","title":"Con quạ","summary":"Ngày xửa ngày xưa có một hoàng hậu. Hoàng hậu có một người con gái. Công chúa còn nhỏ, nhưng ương bướng. Tuy được bế ẵm, nhưng công chúa vẫn khóc hờn...","cat":"world"},{"id":"bac-tho-may-len-troi","url":"https://truyencotich.top/doc-truyen/bac-tho-may-len-troi","title":"Bác thợ may lên trời","summary":"Có lần vào ngày đẹp trời, Chúa cùng tất cả các thần thánh cùng đi chơi, chỉ còn mỗi thánh Petrus ở lại canh cổng. Chúa dặn trong lúc chúa vắng mặt không được cho ai vào...","cat":"world"},{"id":"hai-chu-ti-hon","url":"https://truyencotich.top/doc-truyen/hai-chu-ti-hon","title":"Hai chú tí hon","summary":"Xưa có bác thợ giày, chẳng tội tình gì mà làm ăn cứ ngày một sa sút, gia sản cuối cùng còn lại là miếng da chỉ vừa đủ đóng một đôi giày. Tối bác ngồi đo cắt, định sáng hôm sau sẽ khâu thành giày...","cat":"world"},{"id":"co-nguoi-o-di-do-de","url":"https://truyencotich.top/doc-truyen/co-nguoi-o-di-do-de","title":"Cô người ở đi đỡ đẻ","summary":"Ngày xửa ngày xưa có một cô người ở nghèo, cô rất siêng năng và sạch sẽ. Ngày nào cũng như ngày nào, quét xong nhà cô hốt rác đổ ra đống rác to trước nhà...","cat":"world"},{"id":"tro-va-thay","url":"https://truyencotich.top/doc-truyen/tro-va-thay","title":"Trò và thầy","summary":"Ông Jan muốn cho con theo học nghề. Ông tới nhà thờ cầu khẩn. Người trông coi việc tế lễ của nhà thờ đứng sau bàn thờ, nghe tiếng cầu khẩn, ông ta liền nói nho nhỏ: Học nghề ăn trộm, học nghề ăn trộm...","cat":"world"},{"id":"ba-nguoi-so-do","url":"https://truyencotich.top/doc-truyen/ba-nguoi-so-do","title":"Ba người số đỏ","summary":"Ngày xưa, có một người đàn ông có ba con trai. Một hôm, ông gọi ba con trai đến, cho con cả con gà trống, con thứ hai cái hái, đứa con út con mèo...","cat":"world"},{"id":"cho-soi-va-nguoi","url":"https://truyencotich.top/doc-truyen/cho-soi-va-nguoi","title":"Chó sói và người","summary":"Một lần cáo kể cho sói nghe về sức mạnh ghê gớm của con người, không có vật nào địch nổi. Để bảo vệ thân mình loài vật chỉ còn cách dùng mưu trí...","cat":"world"},{"id":"cay-dan-ky-dieu","url":"https://truyencotich.top/doc-truyen/cay-dan-ky-dieu","title":"Cây đàn kỳ diệu","summary":"Cách nay đã lâu có một nam tước với ba cô con gái. Hai cô gái lớn không đẹp, nhưng cô gái út rất kiều diễm. Cô gái lớn tên Suzon...","cat":"world"},{"id":"kalo-dant-da-toi-the-gioi-thu-bay-bang-cach-nao","url":"https://truyencotich.top/doc-truyen/kalo-dant-da-toi-the-gioi-thu-bay-bang-cach-nao","title":"Kalo Dant đã tới thế giới thứ bảy bằng cách nào","summary":"Ngày xưa có một thanh niên Di-gan tên Kalo Dant. Từ ngày ra đời, anh đã theo bộ lạc của mình đi khắp thế giới. Suốt thời thơ ấu, anh đã lần lượt đi thăm từng xứ lạ...","cat":"world"},{"id":"charkagne-lam-chuyen-dai-dot","url":"https://truyencotich.top/doc-truyen/charkagne-lam-chuyen-dai-dot","title":"Charkagne làm chuyện dại dột","summary":"Khi trang trại Di-gan người ta biết Kalo Dant đi du lịch bảy thế giới phía trên đã trở về, mọi người đổ xô tới đón anh..","cat":"world"},{"id":"con-ga-mai-den","url":"https://truyencotich.top/doc-truyen/con-ga-mai-den","title":"Con gà mái đen","summary":"Từ đó Kalo Dant trở nên giàu có. Người ta còn nói rằng anh giàu hơn cả vua của người Di-gan. Và người ta biết rằng anh trở nên giàu có nhờ đã đuổi một con rồng đi khỏi một vùng xa xôi và cứu được một công chúa xinh đẹp..","cat":"world"},{"id":"mot-cuoc-chien-tranh-khong-nhu-nhung-cuoc-chien-tranh-khac","url":"https://truyencotich.top/doc-truyen/mot-cuoc-chien-tranh-khong-nhu-nhung-cuoc-chien-tranh-khac","title":"Một cuộc chiến tranh không như những cuộc chiến tranh khác","summary":"Cách nay đã lâu, qua khỏi những dãy núi rất xa, giữa hai ông vua có chuyện xung đột và ông vua nước mạnh đã tuyên chiến với ông vua láng giềng...","cat":"world"},{"id":"nua-nguoi","url":"https://truyencotich.top/doc-truyen/nua-nguoi","title":"Nửa người","summary":"Ngày xưa có một người thợ rèn Di-gan. Ông có ba đứa con trai. Hai đứa con đầu cao lớn và khôi ngô, nhưng đứa thứ ba không được lực lưỡng lắm...","cat":"world"},{"id":"dilino-va-con-quy","url":"https://truyencotich.top/doc-truyen/dilino-va-con-quy","title":"Dilino và con quỷ","summary":"Ngày xưa có một gia đình Di-gan làm nghề đốt than gồm cha, mẹ và ba đứa con trai. Hai đứa con lớn khôn lanh và khéo léo, nhưng đứa con thứ ba vụng về và ngốc nghếch...","cat":"world"},{"id":"bon-anh-em","url":"https://truyencotich.top/doc-truyen/bon-anh-em","title":"Bốn anh em","summary":"Ngày xưa có một ông vua Di-gan với ba người con trai. Khi các hoàng tử này tới tuổi trưởng thành, hoàng hậu sinh thêm đứa con trai thứ tư được đặt tên là Mitrache. Ít lâu sau, hoàng hậu qua đời...","cat":"world"},{"id":"randache-va-youache","url":"https://truyencotich.top/doc-truyen/randache-va-youache","title":"Randache và Youache","summary":"Chuyện tôi kể cho các bạn nghe đây xảy ra lâu lắm rồi, nhưng ngày nay người Di-gan vẫn còn nhắc lại...","cat":"world"},{"id":"thua-dat-cua-quy","url":"https://truyencotich.top/doc-truyen/thua-dat-cua-quy","title":"Thửa đất của quỷ","summary":"Ngày xưa có một người Di-gan làm ăn kiếm được một số tiền. Anh quyết định cất một ngôi nhà. Anh muốn tìm một chỗ vừa ý từ lâu rồi nhưng chưa tìm được...","cat":"world"},{"id":"cong-chua-nui-bang","url":"https://truyencotich.top/doc-truyen/cong-chua-nui-bang","title":"Công chúa núi băng","summary":"Ở bên kia bảy dãy núi và bảy con sông, có hai vợ chồng một trại chủ giàu nhưng không con. Bà vợ nhờ một nữ pháp sư Di-gan giúp đỡ nên cuối cùng đã có một đứa con trai...","cat":"world"},{"id":"nu-phu-thuy","url":"https://truyencotich.top/doc-truyen/nu-phu-thuy","title":"Nữ phù thủy","summary":"Một bà già Di-gan có một đứa con gái trẻ đẹp. Nhưng đó là một nữ phù thủy. Người ta không học làm phù thủy như học nghề đồ sắt hay thợ rèn...","cat":"world"},{"id":"angulimala-khung-khiep","url":"https://truyencotich.top/doc-truyen/angulimala-khung-khiep","title":"Angulimala khủng khiếp","summary":"Ngày xưa có một chú bé Di-gan tên Nalou. Đó là một đứa con trai tò mò hạng nhất. Cha mẹ và bà con của chú lắm khi bối rối vì chú không ngớt hỏi họ đủ thứ chuyện...","cat":"world"},{"id":"thanh-guom-cua-ori","url":"https://truyencotich.top/doc-truyen/thanh-guom-cua-ori","title":"Thanh gươm của Ori","summary":"Ngày xưa có một nước nhỏ đến nỗi không ai biết tới và nghèo đến nỗi không ai muốn nhìn nhận. Những người giàu ở xứ này có thể đếm trên đầu ngón tay, trong khi người nghèo thì đông như ruồi mùa hạ...","cat":"world"},{"id":"co-gai-lua-doi-va-hon-da-dau-kho","url":"https://truyencotich.top/doc-truyen/co-gai-lua-doi-va-hon-da-dau-kho","title":"Cô gái lừa dối và hòn đá đau khổ","summary":"Có một gia đình giàu sang và quyền quý. Họ có một con gái và yêu quý cô hơn tất cả mọi thứ trên đời...","cat":"world"},{"id":"mot-hop-xuong","url":"https://truyencotich.top/doc-truyen/mot-hop-xuong","title":"Một hộp xương","summary":"Có đôi vợ chồng thương gia trẻ, giầu có. Họ có một cậu con trai nhưng không được thông minh bằng người. Khi cậu con đã đến tuổi trưởng thành, người vợ bảo chồng hãy cho cậu học lấy nghề...","cat":"world"},{"id":"chuyen-ve-mot-pho-ma","url":"https://truyencotich.top/doc-truyen/chuyen-ve-mot-pho-ma","title":"Chuyện về một phò mã","summary":"Một lần vua và quan cận thần đóng giả thường dân để đi xem tình hình dân sống ra sao. Họ đi qua một cánh đồng và bỗng họ thấy từ xa trên một quả đồi một ông lão râu dài...","cat":"world"},{"id":"hoang-hau-phu-thuy","url":"https://truyencotich.top/doc-truyen/hoang-hau-phu-thuy","title":"Hoàng hậu phù thủy","summary":"Ngày xưa có một ông vua rất yêu quý thần dân trong vương quốc của mình. Ông chỉ băn khoăn một điều, cứ đến tối thì hoàng hậu lại kêu mệt, còn ban ngày bà ta luôn khỏe mạnh...","cat":"world"},{"id":"co-gai-cua-noe","url":"https://truyencotich.top/doc-truyen/co-gai-cua-noe","title":"Cô gái của Nôê","summary":"Nôê có ba người con trai và một người con gái. Cô con gái nổi tiếng là người xinh đẹp, thông minh và tốt bụng. Cả thế gian cũng không tìm đâu ra một người con gái như thế...","cat":"world"},{"id":"ai-cuu-cong-chua","url":"https://truyencotich.top/doc-truyen/ai-cuu-cong-chua","title":"Ai cứu công chúa","summary":"Ngày xưa có ba anh em nhà kia, cha chết sớm, chẳng để lại cho gia sản gì. Họ không thể sống mãi trong túng thiếu được...","cat":"world"},{"id":"chang-tho-san-va-nang-cong-chua-xinh-dep","url":"https://truyencotich.top/doc-truyen/chang-tho-san-va-nang-cong-chua-xinh-dep","title":"Chàng thợ săn và nàng công chúa xinh đẹp","summary":"Ngày xưa có hai vợ chồng người thợ săn đã già mà chưa có một mụn con. Họ rất buồn vì điều đó và mong mỏi có một đứa con biết chừng nào...","cat":"world"},{"id":"ba-anh-em-truyen-co-israel","url":"https://truyencotich.top/doc-truyen/ba-anh-em-truyen-co-israel","title":"Ba anh em - Truyện cổ Israel","summary":"Ngày xưa, một ông vua có ba người con trai. Họ sống trong cung điện nguy nga với khu vườn đẹp bao quanh. Trong khu vườn có cây táo cho những quả táo bằng vàng...","cat":"world"},{"id":"hoang-tu-hanh-phuc","url":"https://truyencotich.top/doc-truyen/hoang-tu-hanh-phuc","title":"Hoàng tử hạnh phúc","summary":"Cao cao phía trên thành phố, trên một cái cột ngay quảng trường sừng sững bức tượng của Hoàng tử Hạnh Phúc. Khắp người Hoàng tử được thếp bằng những lá vàng mười, đôi mắt là hai viên xa phia rực sáng...","cat":"world"},{"id":"ai-dem-den-giau-co-va-danh-vong","url":"https://truyencotich.top/doc-truyen/ai-dem-den-giau-co-va-danh-vong","title":"Ai đem đến giàu có và danh vọng","summary":"Có một hoàng tử khôi ngô tuấn tú đang chăm chú nhìn hai con rắn quấn chặt lấy nhau. Bỗng nhiên một con rắn thò đầu về phía hoàng tử và nói với giọng nài nỉ: Xin hoàng tử hãy cứu tôi thoát khỏi kẻ kình địch. Tôi không đủ sức trườn ra được nữa...","cat":"world"},{"id":"muoi-con-ran","url":"https://truyencotich.top/doc-truyen/muoi-con-ran","title":"Mười con rắn","summary":"Có một người mồ côi nghèo, anh ta rất cần cù và ngay thẳng. Một đêm, trong giấc mơ, anh thấy một ông lão hiện ra trước mặt, đặt viên kim cương vào tay anh ta và nói: Có viên kim cương này anh sẽ trở nên giàu có...","cat":"world"},{"id":"ong-tho-xay-va-con-trai-nguoi-thuong-gia","url":"https://truyencotich.top/doc-truyen/ong-tho-xay-va-con-trai-nguoi-thuong-gia","title":"Ông thợ xay và con trai người thương gia","summary":"Cách đây đã lâu ở miền đất nọ có cuộc hỗn chiến khủng khiếp xảy ra. Người dân ở đó không có gì để ăn. Lúc đó có một thương gia sắp qua đời...","cat":"world"},{"id":"to-tien-nguoi-do-thai-va-hai-con-cho","url":"https://truyencotich.top/doc-truyen/to-tien-nguoi-do-thai-va-hai-con-cho","title":"Tổ tiên người Do Thái và hai con chó","summary":"Người Do Thái gặp một ông lão có khuôn mặt phúc hậu và đôi mắt sáng lấp lánh. Ông lão tiết lộ rằng ông chính là tổ tiên người Do Thái, vì vậy có ước ao gì thì cứ nói để ông ban cho...","cat":"world"},{"id":"bo-cau-ran-va-nguoi-dan-ong","url":"https://truyencotich.top/doc-truyen/bo-cau-ran-va-nguoi-dan-ong","title":"Bồ câu, rắn và người đàn ông","summary":"Có một người rất giàu. Khi ông ta già yếu sắp lìa cõi đời, ông ta trăng trối với con trai: Con hãy thương loài vật chứ đừng thương những thằng đàn ông...","cat":"world"},{"id":"cam-on-vua-hay-cam-on-chua","url":"https://truyencotich.top/doc-truyen/cam-on-vua-hay-cam-on-chua","title":"Cảm ơn vua hay cảm ơn Chúa","summary":"Có hai người hành khất lang thang trên hè phố để xin ăn. Trên đường, họ thường đi qua cung điện của vua và vẫn nhận được lòng từ thiện. Một trong hai người xin ăn hay cầu nguyện cho vua vì lòng tốt và sự độ lượng của Người...","cat":"world"},{"id":"su-tu-la-ai","url":"https://truyencotich.top/doc-truyen/su-tu-la-ai","title":"Sư tử là ai","summary":"Có một ông vua rất hiếu sắc. Chẳng cô gái trẻ đẹp nào thoát khỏi ông ta. Gần cung điện vua có một người Do Thái khôn ngoan cùng cô vợ rất xinh...","cat":"world"},{"id":"dip-may-bien-mat-roi","url":"https://truyencotich.top/doc-truyen/dip-may-bien-mat-roi","title":"Dịp may biến mất rồi !","summary":"Một người thợ may rất siêng năng chăm chỉ. Anh ngồi may từ sáng tới đêm khuya. Vậy mà vẫn chưa giàu có. Suốt cả ngày anh ta lẩm bẩm mỗi một câu: “Dịp may của ta đâu? Dịp may của ta đâu?”","cat":"world"},{"id":"hai-anh-chong","url":"https://truyencotich.top/doc-truyen/hai-anh-chong","title":"Hai anh chồng","summary":"Ở thành phố phía đông có một người đàn bà thông minh tên là Saphica. Chị ta có một anh chồng đần độn tên là Hanga. Saphica là một người nội trợ đảm đang, hiểu biết và khéo léo...","cat":"world"},{"id":"nguoi-hanh-khat-va-con-lua","url":"https://truyencotich.top/doc-truyen/nguoi-hanh-khat-va-con-lua","title":"Người hành khất và con lừa","summary":"Người hành khất có một con lừa. Con lừa này là tất cả gia sản của ông nên ông rất quý nó. Nhưng thật không may con vật lại chết. Người hành khất rất buồn...","cat":"world"},{"id":"an-ngon-mieng","url":"https://truyencotich.top/doc-truyen/an-ngon-mieng","title":"Ăn ngon miệng","summary":"Xưa có một người sống bằng nghề khuân vác. Bữa cơm nào anh ta cũng ăn ngon miệng. Khi có thời gian anh ta thường đi vào phố ăn ở một tiệm nhất định. Tiệm ăn đó đối diện với ngôi nhà của một người giàu có...","cat":"world"},{"id":"su-tich-cho-soi","url":"https://truyencotich.top/doc-truyen/su-tich-cho-soi","title":"Sự tích chó sói","summary":"Ngày xưa, sau khi Thượng đế tạo ra Trái Đất và muôn loài, ngài liền cho gọi Quỷ sứ đến và hỏi nó: Ngươi xem, công việc của ta có đáng tự hào không ?","cat":"world"},{"id":"doi-giay-hanh-phuc","url":"https://truyencotich.top/doc-truyen/doi-giay-hanh-phuc","title":"Đôi giày hạnh phúc","summary":"Trong một ngôi nhà, cạnh Hoàng trường mới, phố Đông, thành Côpenhagơ, chủ nhà đang tiếp khách. Khác hôm ấy rất đông, chủ nhà vốn là hiếu khách, hơn nữa là để được mời lại...","cat":"world"},{"id":"ba-cau-hoi","url":"https://truyencotich.top/doc-truyen/ba-cau-hoi","title":"Ba câu hỏi","summary":"Đó là chuyện ba câu hỏi khó của một nhà vua, do nhà văn hào Leo Tolstoy kể lại.Nhà vua ấy, Tolstoy không biết tên. Một hôm đức Vua nghĩ rằng, giá mà vua trả lời được ba câu hỏi ấy thì vua sẽ không bao giờ bị thất bại trong bất cứ công việc nào...","cat":"world"},{"id":"co-dau-den-va-co-dau-trang","url":"https://truyencotich.top/doc-truyen/co-dau-den-va-co-dau-trang","title":"Cô dâu đen và cô dâu trắng","summary":"Bà mẹ cùng hai cô con gái ra đồng cắt cỏ cho bò. Trong hai cô có một cô là con đẻ, còn cô kia là con riêng của chồng. Họ đang đi thì gặp một người đàn ông nghèo đi qua hỏi đường đi: Có phải đường này là đường vào làng phải không bà ?","cat":"world"},{"id":"con-chim-vang","url":"https://truyencotich.top/doc-truyen/con-chim-vang","title":"Con chim vàng","summary":"Ngày xưa có một ông vua cho trồng một vườn hoa ở phía sau cung điện của mình để làm nơi tản bộ vui chơi. Trong vườn hoa ấy có một cây táo kết quả vàng...","cat":"world"},{"id":"su-tich-con-ca-hoi","url":"https://truyencotich.top/doc-truyen/su-tich-con-ca-hoi","title":"Sự tích con Cá Hồi","summary":"Chuyện rằng, ngày xưa xưa lắm, lúc các vị thần còn đến mặt đất vui đùa thưởng ngoạn và cũng như con người, các thần dù bất tử cũng tham lam, cũng ngu si và đầy tham vọng...","cat":"world"},{"id":"ga-khong-lo-va-nguoi-tho-may","url":"https://truyencotich.top/doc-truyen/ga-khong-lo-va-nguoi-tho-may","title":"Gã khổng lồ và người thợ may","summary":"Có một anh thợ may nổi tiếng khắp vùng về nói khoác và về tính khất lần mỗi khi mắc nợ. Một hôm anh ta nảy ra ý định đi dạo một chút để ngắm cảnh trời đất. Anh vội vã rời cửa hàng...","cat":"world"},{"id":"su-tich-sam-set","url":"https://truyencotich.top/doc-truyen/su-tich-sam-set","title":"Sự tích sấm sét","summary":"Ngày xửa ngày xưa, đã lâu lắm rồi chằn Ramasua và nàng tiên Mêkhala cùng theo học phép thần thông của một đạo sĩ. Cả hai đều chăm học nên chẳng bao lâu họ đều lĩnh hội được nhiều phép kỳ tài...","cat":"world"},{"id":"qua-cau-pha-le","url":"https://truyencotich.top/doc-truyen/qua-cau-pha-le","title":"Quả cầu pha lê","summary":"Ngày xưa có một mụ phù thủy có ba người con trai, ba anh em rất mực thương yêu nhau. Mụ không tin con nào cả và nghĩ chúng định đoạt pháp thuật của mụ, thế rồi mụ hóa phép biến con trai cả thành chim đại bàng, nó sống ở trên núi đá cao...","cat":"world"},{"id":"ong-gia-rinkrank","url":"https://truyencotich.top/doc-truyen/ong-gia-rinkrank","title":"Ông già Rinkrank","summary":"Ngày xửa ngày xưa có một ông vua cho đắp một ngọn núi thủy tinh, nhà vua hứa gả công chúa cho ai trèo qua được ngọn núi thủy tinh mà không ngã sẽ được làm phò mã...","cat":"world"},{"id":"ngoi-mo","url":"https://truyencotich.top/doc-truyen/ngoi-mo","title":"Ngôi mộ","summary":"Một hôm, người nông dân giàu có kia đứng giữa sân nhìn cảnh ruộng vườn của mình: ngoài đồng lúa trĩu bông, trong vườn cây trĩu quả. Vào trong nhà, bác ta thấy lúa đầy vựa, nhiều đến nỗi dầm gỗ lún cong xuống...","cat":"world"},{"id":"chang-trai-hieu-loai-vat-noi","url":"https://truyencotich.top/doc-truyen/chang-trai-hieu-loai-vat-noi","title":"Chàng trai hiểu loài vật nói","summary":"Ngày xưa có một bá tước già, ông ta có một người con trai duy nhất nhưng lại đần độn hết chỗ nói...","cat":"world"},{"id":"ong-chua","url":"https://truyencotich.top/doc-truyen/ong-chua","title":"Ong chúa","summary":"Ngày xửa ngày xưa… có hai hoàng tử thích phiêu lưu, lâu dần quen sống hoang dã nên không trở về nhà nữa. Người em út thường gọi là &quot;chú Ngốc,&quot; lên đường đi tìm hai anh...","cat":"world"},{"id":"cao-lam-cha-do-dau","url":"https://truyencotich.top/doc-truyen/cao-lam-cha-do-dau","title":"Cáo làm cha đỡ đầu","summary":"Sói cái sinh con trai, cho mời cáo đến làm cha đỡ đầu. Mụ nói: Bác ta là chỗ bà con họ hàng gần của mình, rất thông minh, nhanh trí, khéo léo mọi bề. Bác ấy mà dạy dỗ con mình thì nó ra đời mới nở mày nở mặt được với thiên hạ...","cat":"world"},{"id":"cao-va-meo","url":"https://truyencotich.top/doc-truyen/cao-va-meo","title":"Cáo và mèo","summary":"Câu chuyện xảy ra như sau: mèo gặp cáo trong rừng, mèo nghĩ: &quot;Ông cáo là người biết điều và từng trải, thiên hạ đều kính nể&quot;...","cat":"world"},{"id":"dam-tang-chi-ga-mai","url":"https://truyencotich.top/doc-truyen/dam-tang-chi-ga-mai","title":"Đám tang chị gà mái","summary":"Hồi ấy, ở trên núi có một gà trống và một con gà mái, chúng hứa sẽ chia ngọt sẻ bùi với nhau mỗi khi có mồi ngon. Có lần, con gà mái thấy một hạt dẻ lớn, nó mổ và nuốt hạt dẻ, nhưng hạt dẻ lớn quá nên nằm mắc lại ở cổ...","cat":"world"},{"id":"luong-son-ba-chuc-anh-dai","url":"https://truyencotich.top/doc-truyen/luong-son-ba-chuc-anh-dai","title":"Lương Sơn Bá - Chúc Anh Đài","summary":"Chuyện kể rằng, cô gái trẻ ham học Chúc Anh Đài người Chiết Giang, cải trang thành con trai tới Hàng Châu học tập tại một trường dành cho nam sinh. Trên đường, cô đã gặp và cảm mến Lương Sơn Bá, một chàng trai đến từ Cối Kê...","cat":"world"},{"id":"con-cu","url":"https://truyencotich.top/doc-truyen/con-cu","title":"Con cú","summary":"Hồi đó cách đây khoảng mấy trăm năm, khi con người còn chưa tinh khôn, ranh mãnh như chúng ta ngày nay, ở thị trấn kia đã xảy ra một chuyện lạ kỳ như sau...","cat":"world"},{"id":"buc-tranh-gam","url":"https://truyencotich.top/doc-truyen/buc-tranh-gam","title":"Bức tranh gấm","summary":"Xưa kia, trong một vùng cằn cỗi dưới chân núi, có một bà góa nghèo sống cùng ba người con trai. Người con cả là một tên vô tích sự, người con thứ hai chẳng hơn gì, duy chỉ có người con út là thương người và siêng năng, thường cố sức mình giúp mẹ...","cat":"world"},{"id":"thay-tu-va-anh-tho-moc","url":"https://truyencotich.top/doc-truyen/thay-tu-va-anh-tho-moc","title":"Thầy tu và anh thợ mộc","summary":"Ngày xửa ngày xưa, xưa đến không không ai còn nhớ nữa, tại một vương quốc nọ có một anh thợ mộc và một lão thầy tu. Lão thầy tu là một kẻ độc ác và hám tiền...","cat":"world"},{"id":"hoa-si-touo-lan-ka","url":"https://truyencotich.top/doc-truyen/hoa-si-touo-lan-ka","title":"Họa sĩ Touo-lan-ka","summary":"Rất xa ở miền nam Trung Quốc, nới những người Tai sinh sống, có một thôn làng vây quanh bởi những bãi trồng cọ. Không xa ngoài rìa làng, bên bờ một con sông nước trong vắt, sừng sững một cái chòi cũ nát, bằng tre ken lại với nhau...","cat":"world"},{"id":"co-gai-co-hoa-de-trang","url":"https://truyencotich.top/doc-truyen/co-gai-co-hoa-de-trang","title":"Cô gái có hoa dẻ trắng","summary":"Gần con sông lớn Tsangpo, trong một vùng đầy thú dữ có một người thợ săn chỉ có một con trai độc nhất tên là Losang. vốn khéo léo và dũng cảm, chàng được cha cho đi săn từ khi còn là một chú bé...","cat":"world"},{"id":"bien-tien-vang","url":"https://truyencotich.top/doc-truyen/bien-tien-vang","title":"Biển tiền vàng","summary":"Đó là \u001dngày thứ mười lăm của tuần trăng thứ tám, trên mặt đất xảy ra những điều kỳ diệu lạ lùng và cái không thể trở thành có thể. Trên trời, một vầng trăng vàng lớn lơ lửng...","cat":"world"},{"id":"may-trang-tim-chong","url":"https://truyencotich.top/doc-truyen/may-trang-tim-chong","title":"Mây trắng tìm chồng","summary":"Biển Jou mênh mông và cồn sóng. Hiếm khi gió để cho biển lặng. Nhưng dẫu gió quất biển mạnh như thế nào, rạch sóng sâu như thế nào, chưa bao giờ người ta nhìn thấy đáy biển, đến tận ngày nay cũng vậy...","cat":"world"},{"id":"ngoc-hoang-trung-tri-thoi-tham-nhung-nhu-the-nao","url":"https://truyencotich.top/doc-truyen/ngoc-hoang-trung-tri-thoi-tham-nhung-nhu-the-nao","title":"Ngọc hoàng trừng trị thói tham nhũng như thế nào","summary":"Một phật tử tập tu khán nguyên trong một ngôi đèn gỗ nơi có bốn pho tượng bà vãi và một pho tượng Thần Hộ Thành. Chợt anh nghe có tiếng bước chân đến gần. Anh ngẩng lên và thấy một bóng đàn ông...","cat":"world"},{"id":"chuyen-chang-nhan","url":"https://truyencotich.top/doc-truyen/chuyen-chang-nhan","title":"Chuyện chàng Nhân","summary":"Ngày xửa ngày xưa, khi con người sống rải rác khắp thế gian, nhà nọ cách nhà kia hàng ngàn dặm, có một vật thể lạ sáng lấp lánh xuất hiện trên bầu trời. Khi vật thể đến gần trái đất, người ta nhận ra đó là một ngôi sao chổi sáng rực...","cat":"world"},{"id":"nguoi-tho-deo-da","url":"https://truyencotich.top/doc-truyen/nguoi-tho-deo-da","title":"Người thợ đẽo đá","summary":"Ngày xưa có một người thợ đẽo đá ngay thẳng, chăm chỉ và có nhiều ý tưởng thông minh. Phú hộ trong vùng nghe tiếng bèn cho gọi anh đến giao cho một số việc lặt vặt...","cat":"world"},{"id":"hai-vi-than","url":"https://truyencotich.top/doc-truyen/hai-vi-than","title":"Hai vị thần","summary":"Chót vót cao trên núi, nơi tiếng người không vọng lên được, xưa kia có một ngôi đền nhỏ làm bằng những xà gỗ gần mục ruỗng, nơi trú ngụ của vị Thần Núi hùng mạnh. Đó là một vị thần kiêu căng...","cat":"world"},{"id":"anh-ngheo-va-anh-giau","url":"https://truyencotich.top/doc-truyen/anh-ngheo-va-anh-giau","title":"Anh nghèo và anh giàu","summary":"Ngày xửa ngày xưa có hai anh hàng xóm, một anh nghèo và một anh giàu. Anh giàu rất sùng đạo. Chẳng thế mà có lần anh ta bỏ ra ba ngày liền chúi mũi vào một quyển sách lễ, đọc tất cả những quy tắc lễ nghi, không bỏ sót một lời cầu khấn nào...","cat":"world"},{"id":"sao-mai-va-hoa-mi","url":"https://truyencotich.top/doc-truyen/sao-mai-va-hoa-mi","title":"Sao mai và Họa mi","summary":"Cao lắm là núi mấy không có đường lên. Trước núi sừng sững hai khối đá vững chãi, dưới chân mỗi khối đá tuôn ra một nguồn nước nhỏ, mảnh mai và trong vắt như pha lê. Hai nguồn nước chảy uốn khúc qua vùng đất như hai dải ruy-băng bằng bạc..","cat":"world"},{"id":"frene-chang-trai-dung-cam","url":"https://truyencotich.top/doc-truyen/frene-chang-trai-dung-cam","title":"Frêne, chàng trai dũng cảm","summary":"Bên kia ngọn núi thứ bảy, con sông thứ bảy, cái hồ thứ bảy, nơi những dải rừng già thâm u trải dài ngút tầm mắt, xưa kia, giữa một vạt rừng thưa, có một túp lều tranh nho nhỏ nơi một người cha sống cùng cô con gái...","cat":"world"},{"id":"cherab-lanh-loi-khon-ngoan","url":"https://truyencotich.top/doc-truyen/cherab-lanh-loi-khon-ngoan","title":"Cherab lanh lợi khôn ngoan","summary":"Trong một vương quốc nọ xưa kia có một chàng trai tên là Cherab rất lanh lợi, khôn ngoan. Đã làm gì chàng đều làm đến nơi đến chốn và biết thoát khỏi mọi tình huống khó khăn...","cat":"world"},{"id":"chang-mo-coi-va-con-gai-vua-rong","url":"https://truyencotich.top/doc-truyen/chang-mo-coi-va-con-gai-vua-rong","title":"Chàng Mồ côi và con gái vua Rồng","summary":"Xưa kia có một chàng trai không còn ai thân thích trên đời. Chàng lớn lên giữa những người xa lạ, không ai biết tên chàng là gì. Vì thế người ta gọi chàng đơn giản là chàng Mồ côi. Thật buồn phải sống cô độc trên đời, thêm nữa lại nghèo...","cat":"world"},{"id":"hai-con-ma-troi","url":"https://truyencotich.top/doc-truyen/hai-con-ma-troi","title":"Hai con ma trơi","summary":"Trong một vùng đất u ám không mến khách, nơi ngay cây táo dại cũng không nở hoa bao giờ mà chỉ có toàn những loài cỏ độc. Tại một mảnh đất sình lầy, có một người đàn ông góa vợ.Ông ta chẳng bận tâm đến bản thân...","cat":"world"},{"id":"co-xa-cu","url":"https://truyencotich.top/doc-truyen/co-xa-cu","title":"Cô Xà cừ","summary":"Xưa kia, trong một gia đình nọ có ba người con gái, ba cô thiếu nữ tên gọi: Cô Kim, cô Ngân và cô Xà cừ. Cả ba cô đều tuyệt đẹp. Quanh vùng không có chàng trai nào là không muốn lấy được một trong ba cô làm vợ...","cat":"world"},{"id":"sa-norbou-truyen-co-tay-tang","url":"https://truyencotich.top/doc-truyen/sa-norbou-truyen-co-tay-tang","title":"Sa-Norbou - Truyện cổ Tây Tạng","summary":"Ngày xưa, cách nay đã lâu lắm, có một thủ lãnh hùng mạnh ngự trị một vùng rộng lớn. Ông thích điều khiển và lúc nào cũng muốn giành phần tốt nhất cho mình. Cũng ở trong xứ đó, có một pháp sư, khôn ngoan và rất nhân từ...","cat":"world"},{"id":"thien-dinh","url":"https://truyencotich.top/doc-truyen/thien-dinh","title":"Thiên đình","summary":"Nhân gian chìn trong tăm tối, sương mù và ủ ê. Thượng đế ngủ lơ mơ, quấn mình trong màn sương mù, gối đầu trên một chiếc gối mây. Chợt ông cựa mình và mở mắt. Ông nhìn xuống. Dưới chân ông, sương lan tỏa, sương bò tới tận mũi...","cat":"world"},{"id":"gioi-gioi","url":"https://truyencotich.top/doc-truyen/gioi-gioi","title":"Giỏi! Giỏi!","summary":"Xưa có một ngừoi nghèo khổ nai lưng ra làm lụng, làm lụng cật lực mà không kiếm được một xu dính túi. Một mùa đông, tuyết phủ ngập đồng quê, gió lạnh căm căm thổi lộng trên khắp mặt đất bỏ hoang...","cat":"world"},{"id":"nang-tien-rung","url":"https://truyencotich.top/doc-truyen/nang-tien-rung","title":"Nàng tiên Rừng","summary":"Ngày xửa ngày xưa có một lái buôn giàu có sống trong một thành phố nọ. Ông có ba người con trai. Người con cả và người con thứ đã tìm được vị hôn thê giàu có. Riêng người con út hình như chẳng nghĩ đến lấy vợ bao giờ...","cat":"world"},{"id":"con-rong-vang","url":"https://truyencotich.top/doc-truyen/con-rong-vang","title":"Con rồng vàng","summary":"Ngày xửa ngày xưa, trong một ngôi làn nọ có một cô gái trẻ. Cô chẳng còn ai trên đời chăm lo cho nên phải đến hầu hạ trong nhà một tên địa chủ giàu có...","cat":"world"},{"id":"thay-tu-giup-do-dan-ngheo-nhu-the-nao","url":"https://truyencotich.top/doc-truyen/thay-tu-giup-do-dan-ngheo-nhu-the-nao","title":"Thầy tu giúp đỡ dân nghèo như thế nào","summary":"Ngày xưa có một thầy tu nghèo, nghèo đến nỗi người khác hếch mũi lên mỗi khi ông đến tu viện. Nếu không có chiếc áo thầy tu bạc phếch, dải đai màu cam thì không ai nhận ra vị thầy tu qua con người cùng khổ đó...","cat":"world"},{"id":"chiec-ao-long-trang","url":"https://truyencotich.top/doc-truyen/chiec-ao-long-trang","title":"Chiếc áo lông trắng","summary":"Ngày xửa ngày xưa, tại một miền xa xôi có một cô gái trẻ xinh đẹp. Mẹ cô đã qua đời nhiều năm, cô chỉ còn lại trên đời một người mẹ ghẻ. Như thói thường người mẹ ghẻ này không ưa con chồng, chỉ nghĩ làm sao tống khứ được cô đi cho sớm...","cat":"world"},{"id":"cai-ho-can","url":"https://truyencotich.top/doc-truyen/cai-ho-can","title":"Cái hồ cạn","summary":"Ngày xửa ngày xưa, tại một làng nó có một bà mẹ sống cùng một người con trai và một người con gái. Bà chịu khó còng lưng làm thuê từ sáng sớm đến tối khuya trên ruộng đất của người khác mà chẳng đủ ăn...","cat":"world"},{"id":"a-hiou-lau-ca","url":"https://truyencotich.top/doc-truyen/a-hiou-lau-ca","title":"A-hiou láu cá","summary":"Ngày xưa, có một chàng trai tên là A-Hiou. Chàng trai khôi ngô tuấn tú đến mức mọi cô gái phải chú mục, và thông minh đến mức hầu như làm được mọi việc trên đời. Hoàng đế nghe đồn bèn cho vời chàng đến giao xây một cung điện mới...","cat":"world"},{"id":"co-cong","url":"https://truyencotich.top/doc-truyen/co-cong","title":"Cô công","summary":"Vua Bahkeladir trị vì một vương quốc giàu đẹp, nhiều đồng cỏ, hồ và rừng, ông đã đứng tuổi mà vẫn chưa có con. Cho đến một ngày cả triều đình xôn xao...","cat":"world"},{"id":"con-ngua-da","url":"https://truyencotich.top/doc-truyen/con-ngua-da","title":"Con ngựa đá","summary":"Ngày xửa ngày xưa, trên đỉnh đồi, nơi nhô lên thị trấn nhỏ Laling, có một con ngựa đá đứng sừng sững. Người ta gọi nó bằng cái tên “Gemme” Ngựa đá rất kỳ lạ. Bất kể ai muốn vào trong vùng cũng phải được phép của Gemme...","cat":"world"},{"id":"con-khi","url":"https://truyencotich.top/doc-truyen/con-khi","title":"Con khỉ","summary":"Một con khỉ trèo lên một cái cây quan sát xung quanh. Nó thấy một vườn đào bên kia sông. Những quả đào chín mọng khiến nó thèm ứa nước miếng...","cat":"world"},{"id":"florisec","url":"https://truyencotich.top/doc-truyen/florisec","title":"Florisec","summary":"Chuyện này xảy ra lâu lắn rồi, lâu đến nỗi, từ đó đến nay thế giới đã hoàn toàn thay đổi. Năm ấy trời làm một trận hạn hán kinh hoàng. Đất đai khô cằn, nứt nẻ, cây cối chết hết. Có một đôi vợ chồng luống tuổi, tóc đã điểm bạc từ lâu...","cat":"world"},{"id":"nguoi-vo-yeu-thuong-va-cong-chua-rong","url":"https://truyencotich.top/doc-truyen/nguoi-vo-yeu-thuong-va-cong-chua-rong","title":"Người vợ yêu thương và công chúa Rồng","summary":"Không xa thành phố nơi một viên quan độc ác sinh sống, trong một làng nhỏ, một người đàn ông có người vợ vô cùng xinh đẹp. Tiếng đồn về sắc đẹp của người vợ đến tai viên quan...","cat":"world"},{"id":"hai-ngoi-sao","url":"https://truyencotich.top/doc-truyen/hai-ngoi-sao","title":"Hai ngôi sao","summary":"Xưa kia một bà goá có hai cô con gái xinh xắn, hay lam hay làm. Từ sáng chí tối các cô phải làm lụng trên cánh đồng của một chủ trại keo kiệt...","cat":"world"},{"id":"cai-chum-va-ba-con-khi","url":"https://truyencotich.top/doc-truyen/cai-chum-va-ba-con-khi","title":"Cái chum và ba con khỉ","summary":"Ngày xưa có hai người bạn thân tên là Yeche và Kunk. Một bận Yeché có việc phải vắng nhà ít hôm. Anh đến tìm anh bạn Kunka...","cat":"world"},{"id":"ba-hoang-tu","url":"https://truyencotich.top/doc-truyen/ba-hoang-tu","title":"Ba hoàng tử","summary":"Xưa kia có một ông vua xinh được ba chàng hoàng tử. Một hôm ông gọi cả ba đến bảo: Các con, ta đã già rồi, ta cảm thấy những giờ cuối cùng của ta đang đến gần. Các con đã lớn, đã đến lúc ta giao lại vương quốc của ta cho một trong ba con...","cat":"world"},{"id":"con-ngua-go-nho","url":"https://truyencotich.top/doc-truyen/con-ngua-go-nho","title":"Con ngựa gỗ nhỏ","summary":"Ngày xửa ngày xưa, xa xưa lắm kinh thành có hai thợ thủ công vô cùng nổi tiếng, một bác thợ rèn và một bác thợ mộc. Một hôm, tỉnh cờ hai bác thợ ấy gặp nhau và lân la trò chuyện trong quán trọ Quả đào hồng...","cat":"world"},{"id":"tuong-phat-biet-noi","url":"https://truyencotich.top/doc-truyen/tuong-phat-biet-noi","title":"Tượng phật biết nói","summary":"Xưa kia một chủ trại giàu sang có một người con gái độc nhất. Đó là một thiếu nữ vô cùng xinh đẹp, tươi mát như đóa hoa nhài, với đôi mắt lấp lánh và mái tóc đen như cánh quạ, bện thành hai bím dài...","cat":"world"},{"id":"con-trau-mot-sung","url":"https://truyencotich.top/doc-truyen/con-trau-mot-sung","title":"Con trâu một sừng","summary":"Xưa kia có một chàng trai sông giữa những quả núi cao nứt nẻ, dẫn đến nơi ấy chỉ có một con đường mòn mảnh như một sợi chỉ. Anh chẳng còn ai thân thích trên đời nên sống thui thủi một mình trong một túp lều nhỏ lợp bằng tre...","cat":"world"},{"id":"hao-tam","url":"https://truyencotich.top/doc-truyen/hao-tam","title":"Hảo tâm","summary":"Ngày xưa, cách nay rất lâu, khi người ta còn sống rời rạc ở khắp nơi và nhà cửa cách nhau hàng ngàn dặm, có một vật sáng chói lạ thường xuất hiện trên bầu trời. Khi vật đó tới gần mặt đất, ngươi ta nhận ra một sao chổi sáng rực...","cat":"world"},{"id":"co-nen","url":"https://truyencotich.top/doc-truyen/co-nen","title":"Cỏ nến","summary":"Qua khỏi dãy núi thứ bảy, con sông thứ bảy và hồ nước thứ bảy, từ đó những khu rừng sâu tăm tối trải dài mút mắt, giữa một khoảng rừng thưa, có một người thợ săn sống với đứa con gái trong một túp lều tranh...","cat":"world"},{"id":"soi-day-nuoc-mat","url":"https://truyencotich.top/doc-truyen/soi-day-nuoc-mat","title":"Sợi dây nước mắt","summary":"Ngày xưa có một anh con trai mồ côi, và vì anh sống một mình như một con chim rơi khỏi tổ nên người ta gọi anh là Chim Non. Mồ côi buồn thật! Có sự sỉ nhục và hắt hủi nào mà anh không phải chịu...","cat":"world"},{"id":"a-hieu","url":"https://truyencotich.top/doc-truyen/a-hieu","title":"A Hiếu","summary":"Ngày xưa có một thanh niên tên A Hiếu. Anh rất xinh trai nên cô gái nào cũng nhìn anh, và rất thông minh nên hầu như có thể làm bất cứ việc gì trên đời. Vì thế hoàng đế cho gọi anh tới, bảo anh xây một cung điện mới...","cat":"world"},{"id":"khi-va-lac-da","url":"https://truyencotich.top/doc-truyen/khi-va-lac-da","title":"Khỉ và lạc đà","summary":"Một con khỉ ngồi vắt vẻo trên ngọn cây quan sát xung quanh. Nó nhìn thấy một vườn đào ở bờ bên kia sông. Nó phải nuốt nước giãi, vì nhìn thấy quả ngọt làm nó thèm rỏ giãi...","cat":"world"},{"id":"hoa-kho","url":"https://truyencotich.top/doc-truyen/hoa-kho","title":"Hoa Khô","summary":"Chuyện này xảy ra cách nay đã lâu, lâu đến nỗi từ đó tới nay thế gian đã hoàn toàn thay đổi, không còn giống như xưa. Năm đó hạn hán vô cùng tai hại. Đất khô nứt, cây cối chết hết. Thời đó có một đôi vợ chồng già nhưng không có con...","cat":"world"},{"id":"ibrahim-va-nguoi-lai-buon","url":"https://truyencotich.top/doc-truyen/ibrahim-va-nguoi-lai-buon","title":"Ibrahim và người lái buôn","summary":"Tương truyền một hôm quốc vương triệu Ibrahim al-Mahđi tới và hỏi: Người hãy kể cho ta nghe một câu chuyện ly kỳ...","cat":"world"},{"id":"ke-nghien-thuoc","url":"https://truyencotich.top/doc-truyen/ke-nghien-thuoc","title":"Kẻ nghiện thuốc","summary":"Tương truyền có một lần những người hành hương ngoan đạo đã đi vòng quanh tòa thánh Kaba. Bỗng nhiên họ thấy một người quỳ phục xuống nền tòa thánh, và vừa hôn đất ông ta vừa điên cuồng cầu thánh Ala...","cat":"world"},{"id":"nguoi-tho-dong-giay","url":"https://truyencotich.top/doc-truyen/nguoi-tho-dong-giay","title":"Người thợ đóng giày","summary":"Ngày xửa ngày xưa có một người thợ đóng giày tên là Marouf. Vợ của anh ta ta vừa xấu xí lại vừa độc ác, vì vậy mọi người gọi mụ ta là mụ Guenon. Hàng ngày, mụ ta lê la khắp nơi nói xấu hết người này đến người khác...","cat":"world"},{"id":"cay-hoa-than","url":"https://truyencotich.top/doc-truyen/cay-hoa-than","title":"Cây hoa thần","summary":"Một hôm Marouf nói với người bạn: Chúng ta đã già cả rồi. Ơ tuổi này chúng ta có quyền ao ước. Nếu như tôi vẫn còn một chiếc nhẫn thần và nếu như tôi có một điều ước duy nhất thì đố ông biết tôi ao ước điều gì?","cat":"world"},{"id":"nguoi-danh-ca-va-nhung-con-ca-sac-so","url":"https://truyencotich.top/doc-truyen/nguoi-danh-ca-va-nhung-con-ca-sac-so","title":"Người đánh cá và những con cá sặc sỡ","summary":"Ngày xửa ngày xưa cớ một vị vua rất hùng mạnh tên là Souleymane. Một hôm ông ta mơ thấy thánh Allah hiện về và tặng cho ông ta một chiếc đũa thần. Chiếc đũa này có thể mang đến cho Souleymane sự thông thái, sức mạnh và giàu có...","cat":"world"},{"id":"ba-phep-thuat-cua-thuy-nu","url":"https://truyencotich.top/doc-truyen/ba-phep-thuat-cua-thuy-nu","title":"Ba phép thuật của thủy nữ","summary":"Ngày xửa ngày xưa, bên bờ một con sông có một người đánh cá rất xấu xí sinh sống. Thế mà vợ của anh ta lại là một nàng thuỷ nữ cực kì xinh đẹp. Họ yêu nhau vô cùng, không muốn rời xa nhau nửa bước...","cat":"world"},{"id":"hoang-tu-salaydin-va-mu-vo-doc-ac","url":"https://truyencotich.top/doc-truyen/hoang-tu-salaydin-va-mu-vo-doc-ac","title":"Hoàng tử Salaydin và mụ vợ độc ác","summary":"Ngày xửa ngày xưa, có vị hoàng đế nọ có tới bảy người con trai: Ngài cho các hoàng tử kết hôn cùng bảy công chúa của nước lân bang. Một hôm, để thử lòng con trai, ngài ra lệnh cho họ phải cạo trọc đầu các công chúa...","cat":"world"},{"id":"con-lac-da-mau-trang","url":"https://truyencotich.top/doc-truyen/con-lac-da-mau-trang","title":"Con lạc đà màu trắng","summary":"Ranim và Chawan được sinh ra trong một gia đình nghèo khó. Một hôm, hai anh em rời nhà cha mẹ để đi tìm vận may. Chàng anh cả Ranim mang theo hai con chó còn cậu út Chawan chỉ đi một mình...","cat":"world"},{"id":"chang-hoang-tu-bi-bien-thanh-khi","url":"https://truyencotich.top/doc-truyen/chang-hoang-tu-bi-bien-thanh-khi","title":"Chàng hoàng tử bị biến thành khỉ","summary":"Ngày xửa ngày xưa, đã lâu lắm rồi, ở đất nước vùng phương Đông xa xôi nọ có chàng hoàng tử tên là Khusraoushah. Cha của chàng là quốc vương của Đế chế Ba Tư hùng mạnh. Ngài muốn người con trai duy nhất của mình phải được học hành tử tế...","cat":"world"},{"id":"abdurrahnan-va-hai-nguoi-anh-trai","url":"https://truyencotich.top/doc-truyen/abdurrahnan-va-hai-nguoi-anh-trai","title":"Abdurrahnan và hai người anh trai","summary":"Đức vua Haroun, trị vì đế chế Thổ Nhĩ Kỳ, đã sai vị tể tướng của mình đến đất Siri. Ngài muốn xem tiểu vương Abdurrahnan đã cai quản đất đai của mình như thế nào đồng thời cũng muốn tể tướng đến đó thu cống phẩm, thuế má mà Abdurrahnan phải nộp...","cat":"world"},{"id":"cay-hoa-hat","url":"https://truyencotich.top/doc-truyen/cay-hoa-hat","title":"Cây hoa hát","summary":"Ali, hãy nhìn xem - Maroy thì thầm vào tai bạn - những du khách đang lắng nghe cây hoa kỳ diệu của chúng ta. Họ không hề nhúc nhích, nín thở lại, má họ đỏ lựng lên vì bị kích thích kìa...","cat":"world"},{"id":"chuyen-hasan-va-con-cho-trang","url":"https://truyencotich.top/doc-truyen/chuyen-hasan-va-con-cho-trang","title":"Chuyện Hasan và con chó trắng","summary":"Xưa, đã lâu lắm rồi, trong thành Bát – đa có một vị vua tốt bụng và anh minh. Ngài có ba người con trai, con cả tên là Aladin, người con thứ hai là Madjidin và cậu út tên là Hasan...","cat":"world"},{"id":"nang-landja-xinh-dep","url":"https://truyencotich.top/doc-truyen/nang-landja-xinh-dep","title":"Nàng Landja xinh đẹp","summary":"Chưa bao giờ trên đời này lại có cô gái nào xinh đẹp như Landja. Chỉ thoáng nhìn cũng đủ làm ta lóa mắt, chính vì thế mà tất cả đám thanh niên trai tráng đều không kháng cự được trước vẻ quyến rũ của nàng...","cat":"world"},{"id":"khu-vuon-ngoc-trai","url":"https://truyencotich.top/doc-truyen/khu-vuon-ngoc-trai","title":"Khu vườn ngọc trai","summary":"Xưa kia, trong thành Khaleb có một vị vua có khu vườn rất kỳ lạ: Hàng năm, cây cối trong vườn không ra hoa, kết quả mà cho những viên ngọc trai thật đẹp...","cat":"world"},{"id":"ba-dieu-uoc-truyen-co-a-rap","url":"https://truyencotich.top/doc-truyen/ba-dieu-uoc-truyen-co-a-rap","title":"Ba điều ước - Truyện cổ A-rập","summary":"Xưa đã lâu lắm rồi, ở nước nọ có một chàng nông dân rất nghèo, chàng nghèo đến nỗi của cải chẳng có gì ngoài một con lừa. Con vật rất lười biếng và vô tích sự. Người chẳng thể cưỡi nó được vì vóc dáng bé nhỏ của nó...","cat":"world"},{"id":"nhung-cuoc-phieu-luu-cua-hasan","url":"https://truyencotich.top/doc-truyen/nhung-cuoc-phieu-luu-cua-hasan","title":"Những cuộc phiêu lưu của Hasan","summary":"Ngày xưa, gần vương quốc của các vị thần Sa mạc, có một vị vua bất hạnh vì ngài chẳng có con cái. Những tưởng ngài sẽ chết mà không có ai kế vị thì may sao lại sinh được một cậu bé. Ngài đặt tên con là Hasan...","cat":"world"},{"id":"dieu-uoc-cua-hai-anh-em-muon-cuoi-cung-mot-ngay","url":"https://truyencotich.top/doc-truyen/dieu-uoc-cua-hai-anh-em-muon-cuoi-cung-mot-ngay","title":"Điều ước của hai anh em muốn cưới cùng một ngày","summary":"Khi viên tể tướng già của mình chết đi, vua xứ Syria cho gọi hai con trai của ông ta là Abdullatif và Abdurrbaman tới để giao cho họ trọng trách công việc triều chính của cha mình...","cat":"world"},{"id":"cay-hoa-cua-sa-mac","url":"https://truyencotich.top/doc-truyen/cay-hoa-cua-sa-mac","title":"Cây hoa của sa mạc","summary":"Mặt trời vẫn chiếu sáng trên cao, nhưng cây hoa thần đã ngừng lời kể về câu chuyện. của hai anh em trai có ước muốn đã được thánh thần chấp thuận. Những người đánh lạc đà, thương gia, lữ khách tới sa mạc, La Mecque hay nước Trung Hoa xa xôi...","cat":"world"},{"id":"bac-nong-dan-va-con-gau","url":"https://truyencotich.top/doc-truyen/bac-nong-dan-va-con-gau","title":"Bác nông dân và con gấu","summary":"Ngày xửa ngày xưa, có một bác nông dân vào rừng khai hoang cày quốc kiếm sống. Một hôm, bác đang phát quang một khu đất màu mỡ thì từ đâu có một con gấu to chạy đến...","cat":"world"},{"id":"chim-en-co-phep-mau","url":"https://truyencotich.top/doc-truyen/chim-en-co-phep-mau","title":"Chim én có phép màu","summary":"Ngày xưa, ở một tỉnh phía nam của Triều Tiên, có một ông già sinh được hai người con trai, đứa lớn là Nonbu, đứa nhỏ là Hungbu. Hai anh em hoàn toàn khác nhau về tính cách...","cat":"world"},{"id":"su-tich-cay-nhan-sam-han-quoc","url":"https://truyencotich.top/doc-truyen/su-tich-cay-nhan-sam-han-quoc","title":"Sự tích cây nhân sâm hàn quốc","summary":"Ngày xửa ngày xưa, có một cậu bé hiếu thảo họ Kang, mồ côi cha từ nhỏ, sống với mẹ tại một ngôi làng nọ ở chân núi. Không bao lâu sau mẹ cậu bị ốm nặng, cậu bé vô cùng lo lắng vì không biết làm sao chữa khỏi bệnh cho mẹ...","cat":"world"},{"id":"mo-vua-davit","url":"https://truyencotich.top/doc-truyen/mo-vua-davit","title":"Mộ vua Đavít","summary":"Tám mươi năm trước đây tại một làng thuộc Ba Lan có hai học trò mắc lỗi và họ mong có dịp chuộc lỗi lầm. Hai trò đều khát khao được đến vùng Eret Ixraen, mảnh đất của Chúa...","cat":"world"},{"id":"chiec-khan-theu","url":"https://truyencotich.top/doc-truyen/chiec-khan-theu","title":"Chiếc khăn thêu","summary":"Ngày xửa ngày xưa trên thế gian này có một ông vua tên là Xulaimansakh. Ngài cưới vợ và một năm sau, hoàng hậu trẻ tuổi sinh hạ cho ngài một cậu con trai, mà trên trán có những dấu hiệu của sự cao sang và hạnh phúc...","cat":"world"},{"id":"giozep-that-tha","url":"https://truyencotich.top/doc-truyen/giozep-that-tha","title":"Giôzép thật thà","summary":"Một trăm năm trước ở là Pêkin có một người đàn ông Do Thái tên là Giôzép. Anh ta là một người thật thà và tốt bụng. Anh đi theo con đường của Chúa một cách thành tâm. Hai vợ chồng anh sống bằng nghề nông như mọi cư dân trong làng...","cat":"world"},{"id":"vi-sao-mui-lon-lai-ngan","url":"https://truyencotich.top/doc-truyen/vi-sao-mui-lon-lai-ngan","title":"Vì sao mũi lợn lại ngắn ?","summary":"Ngày xửa, ngày xưa một hôm Ngọc Hoàng cho triệu Gà, Chó và Lợn lên thiên đình. Khi ba con vật nghe được tin này chúng rất lo lắng. Trên đường lên thiên đình, mỗi con đều suy nghĩ lại về những công việc mình đã làm...","cat":"world"},{"id":"ba-lao-hai-nhi","url":"https://truyencotich.top/doc-truyen/ba-lao-hai-nhi","title":"Bà lão hài nhi","summary":"Ngày xửa ngày xưa, có một người đàn ông sống hiền lành bên người vợ trong một làm hẻo lánh trên núi cao. Hai vợ chồng đã rất già, lại không có con cái. Mỗi ngày trôi qua, họ lại càng cảm thấy cuộc sống khó khăn hơn...","cat":"world"},{"id":"co-be-chan-cuu-va-chu-tho-nao-ong-khoi","url":"https://truyencotich.top/doc-truyen/co-be-chan-cuu-va-chu-tho-nao-ong-khoi","title":"Cô bé chăn cừu và chú thợ nạo ống khói","summary":"Các bạn đã bao giờ trông thấy một cái tủ cổ, đen nhánh và chạm trổ đủ các kiểu lá cây chưa? Trong căn phòng lớn của gia đình chúng tôi có một cái tủ như vậy đấy. Vật ấy là của gia bảo, từ thời cụ kỵ chúng tôi để lại...","cat":"world"},{"id":"su-that-cua-con-nhen","url":"https://truyencotich.top/doc-truyen/su-that-cua-con-nhen","title":"Sự thật của con nhện","summary":"Xưa kia, loài vật cũng sống trong làng giống như người. Một ôm nắng hạn ghê gớm, mọi người cùng muôn vật gần như chết khát. Con nhện và bầy con của nó cũng gần chết khát. Nhện bèn quyết định phải làm cái gì đó...","cat":"world"},{"id":"hoang-tu-lua","url":"https://truyencotich.top/doc-truyen/hoang-tu-lua","title":"Hoàng tử lừa","summary":"Ngày xửa ngày xưa, có một ông vua và hoàng hậu sống trong giàu sang tới mức, muốn gì cũng có, chỉ duy một nỗi không có con. Hoàng hậu than thở ngày đêm và nói - Mình như thửa ruộng không có cây mọc...","cat":"world"},{"id":"nguoi-ban-nhiet-tinh","url":"https://truyencotich.top/doc-truyen/nguoi-ban-nhiet-tinh","title":"Người bạn nhiệt tình","summary":"Một buổi sáng nọ, chuột nước già nua ló đầu ra ngoài hang. Mắt lão tròn sáng, ria mép cứng màu xám, đuôi nom như một đoạn cao su dài màu đen. Lũ vịt con đang bơi lội tung tăng khắp mặt ao, nom hệt như bầy chim hoàng yến màu vàng...","cat":"world"},{"id":"truyen-nang-pha-ti-ma","url":"https://truyencotich.top/doc-truyen/truyen-nang-pha-ti-ma","title":"Truyện nàng Pha-ti-ma","summary":"Ngày xưa, có một cô gái xinh đẹp tên là Pha-ti-ma. Cô chẳng những xinh đẹp mà còn rất thông minh. Mọi người trong vùng ai ai cũng đều yêu mến Pha-ti-ma...","cat":"world"},{"id":"con-coc-khong-vang-loi","url":"https://truyencotich.top/doc-truyen/con-coc-khong-vang-loi","title":"Con cóc không vâng lời","summary":"Một con Cóc nhỏ sống với mẹ trong một cái ao rộng. Là một đứa trẻ ương ngạnh bướng bỉnh, nó chằng bao giờ nghe theo lời mẹ khiến cho mẹ nó rất buồn...","cat":"world"},{"id":"su-tich-cay-xoai","url":"https://truyencotich.top/doc-truyen/su-tich-cay-xoai","title":"Sự tích cây xoài","summary":"Ngày xưa, có một gia đình bác nông dân nghèo sinh được một cậu con trai. Cậu bé ngoan ngoãn, thật thà tốt bụng. Nhà tuy nghèo nhưng bố mẹ và cậu bé luôn giúp đỡ mọi người từ miếng cơm manh áo...","cat":"world"},{"id":"su-tich-hoa-cuc-tay","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-cuc-tay","title":"Sự tích hoa cúc tây","summary":"Ngày xưa, thế giới các thiên thần và loài người tồn tại song hành nhưng họ sống hoàn toàn cách biệt. Các thiên thần ngự trên những tầng mây trắng xa xôi nhất, vô cùng xinh đẹp với đôi cánh lông vũ gắn trên lưng...","cat":"world"},{"id":"qua-tao-vang","url":"https://truyencotich.top/doc-truyen/qua-tao-vang","title":"Quả táo vàng","summary":"Ngày xưa có một ông vua rất lười biếng, không hề nhìn ngó đến việc nước. Ông ta thường xuyên buồn, chán. Một ngày nọ vua muốn giải trí, phái sứ giả đi khắp xứ sở, từ thành phố đến nông thôn, để loan báo...","cat":"world"},{"id":"vua-chuot-ken-re","url":"https://truyencotich.top/doc-truyen/vua-chuot-ken-re","title":"Vua Chuột kén rể","summary":"Ngày xưa có một con chuột tự xưng là vua của loài chuột. Con gái của vua chuột là một công chúa Chuột rất xinh đẹp sống cùng vua và hoàng hậu trong một cánh đồng rộng...","cat":"world"},{"id":"bac-nong-dan-va-con-quy","url":"https://truyencotich.top/doc-truyen/bac-nong-dan-va-con-quy","title":"Bác nông dân và con quỷ","summary":"Ngày xưa đất đai đều bị loài quỷ chiếm mất cả. Một hôm, có người nông dân vào rừng trồng củ cải. Anh đang cuốc đất thì có một con quỷ chạy lại và quát lên - Anh kia, ai cho vào rừng của ta?… Anh muốn chết à?","cat":"world"},{"id":"su-tich-hoa-moc-lan","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-moc-lan","title":"Sự tích hoa mộc lan","summary":"Ngày xửa ngày xưa, trong những ngày xuân ấm áp, có một tiên nữ đã lẻn xuống trần gian. Điều không may là nàng đã bị thương. Khi nàng biết không trông cậy vào ai, một chàng trai chồng hoa trẻ tuổi đã cứu nàng...","cat":"world"},{"id":"cao-tho-va-gau","url":"https://truyencotich.top/doc-truyen/cao-tho-va-gau","title":"Cáo, Thỏ và Gấu","summary":"Cáo, Thỏ và Gấu cùng ở chung với nhau trong một khu rừng. Mùa đông đến gần, một số cây rừng đã bắt đầu rụng lá...","cat":"world"},{"id":"co-gai-toc-dai","url":"https://truyencotich.top/doc-truyen/co-gai-toc-dai","title":"Cô gái tóc dài","summary":"Ngày xưa, vùng Đẩu Cao ở Trung Quốc rất thiếu nước. Mọi người phải đi gánh nước ở một con sông nhỏ, cách đấy hơn bảy dặm đường. Trong một thôn xóm gần núi Đẩu Cao có một cô gái. Tóc cô đen mượt, dài xuống tận gót chân...","cat":"world"},{"id":"cong-chua-toc-vang","url":"https://truyencotich.top/doc-truyen/cong-chua-toc-vang","title":"Công chúa tóc vàng","summary":"Ngày xưa có một chàng trai thông minh, dũng cảm và tốt bụng tên là Aroka. Một hôm Aroka câu được một con cá hình thù lì dị. Anh không biết làm gì, liền thả cá xuống nước...","cat":"world"},{"id":"chiec-thoi-vang","url":"https://truyencotich.top/doc-truyen/chiec-thoi-vang","title":"Chiếc thoi vàng","summary":"Ngày trước có hai chị em mồ côi cha mẹ, người chị thì lười còn người em lại rất siêng năng. Cô chị cậy mình lớn, việc gì cũng sai em làm. Cô em làm đủ mọi việc lại còn chăm lo dệt vải...","cat":"world"},{"id":"chang-re-thong-minh","url":"https://truyencotich.top/doc-truyen/chang-re-thong-minh","title":"Chàng rể thông minh","summary":"Vua A-bíp có một nàng công chúa đã lớn mà chưa chịu lấy chồng. Đã có hàng trăm chàng trai, con các gia đình quyền quý đến cầu hôn nhưng nàng đều từ chối...","cat":"world"},{"id":"khoa-phu-duoi-mat-troi","url":"https://truyencotich.top/doc-truyen/khoa-phu-duoi-mat-troi","title":"Khoa Phụ đuổi mặt trời","summary":"Thời xưa, có một người khổng lồ thuộc dòng họ Khoa Phụ, thấy mặt trời ngày ngày mọc ở phương Đông rồi lại lặn ở phương Tây, đến sáng hôm sau lại thấy mặt trời mọc ở phương Đông thì rất ngạc nhiên, tự hỏi không rõ tối đến mặt trời trốn ở đâu?","cat":"world"},{"id":"than-lua-a-nhi","url":"https://truyencotich.top/doc-truyen/than-lua-a-nhi","title":"Thần Lửa A Nhi","summary":"Thần Lửa A Nhi (Agni) là một trong những vị thần lớn nhất và lâu đời nhất của Ấn Độ. Thần rất cao lớn, da thịt đỏ au, có bảy cánh tay màu sắc như cầu vồng, lưỡi dài và lanh lẹ lạ thường...","cat":"world"},{"id":"bac-danh-ca-va-ga-hung-than","url":"https://truyencotich.top/doc-truyen/bac-danh-ca-va-ga-hung-than","title":"Bác đánh cá và gã hung thần","summary":"Ngày xưa, có một bác đánh cá đã cao tuổi. Một hôm bác ra biển quăng lưới, kiên nhẫn đợi cho lưới sa xuống tuận đáy biển mới kéo lên. Nhưng lần nào bác cũng chỉ cất lên toàn những thứ đáng vứt đi...","cat":"world"},{"id":"cong-chua-ech","url":"https://truyencotich.top/doc-truyen/cong-chua-ech","title":"Công chúa ếch","summary":"Ngày xửa ngày xưa, có một vị quốc vương già. Ngài có ba người con trai. Ba chàng hoàng tử đều rất khôi ngô tuấn tú. Họ còn rất giỏi cưỡi ngựa, săn bắn, đặc biệt là bắn cung, cho dù chim có bay cao bay xa đến thế nào, họ cũng bắn trúng...","cat":"world"},{"id":"tinh-no","url":"https://truyencotich.top/doc-truyen/tinh-no","title":"Tính nợ","summary":"Ngày xưa có một anh nông dân nghèo mua chịu một con gà luộc của một quán hàng. Ít lâu sau, anh đến quán hàng trả nợ. Lão chỉ quán lấy bàn tính ra, loay hoay tính mãi...","cat":"world"},{"id":"tai-sao-ga-trong-co-mao-do","url":"https://truyencotich.top/doc-truyen/tai-sao-ga-trong-co-mao-do","title":"Tại sao gà trống có mào đỏ?","summary":"Ngày xửa ngày xưa, cách đây lâu lắm rồi, khi trời đất vừa hình thành, thay vì có một mặt trời toả ánh nắng ấm áp xuống trần gian như bây giờ thì có sáu mặt trời chiếu sáng trên bầu trời. Vào một ngày mùa xuân nọ, khi những người nông dân...","cat":"world"},{"id":"khi-an-trom-ngo","url":"https://truyencotich.top/doc-truyen/khi-an-trom-ngo","title":"Khỉ ăn trộm ngô","summary":"Ngày xưa, có một năm trời làm hạn hán nặng, đất đai khô nứt nẻ, suối khô kiệt nước, cây cối héo rũ ra vì thiếu nước. Con người và muông thú có nguy cơ chết đói, đâu đâu cũng nhìn thấy cảnh muôn loài nháo nhác đi kiếm cái ăn...","cat":"world"},{"id":"cau-than-chu-truyen-co-tich-an-do","url":"https://truyencotich.top/doc-truyen/cau-than-chu-truyen-co-tich-an-do","title":"Câu thần chú - Truyện cổ tích Ấn Độ","summary":"Chuyện này xảy ra đã lâu lắm rồi, từ khi vua Bơ-ha-đua còn trị vì xứ Kác-mi-rơ. Một hôm, vua dạo chơi trong vườn thượng uyển cùng với một viên quan đại thần. Ngoài vua và quan đại thần, không ai được bén mảng vào khu vườn tuyệt đẹp đó...","cat":"world"},{"id":"chiec-binh-vang","url":"https://truyencotich.top/doc-truyen/chiec-binh-vang","title":"Chiếc bình vàng","summary":"Xưa kia, đã lâu lắm rồi, có một ông vua rất độc ác. Vua chỉ sợ mỗi một điều, đó là tuổi già. Ngày nào cũng vậy, vua ngồi hàng giờ trước gương soi, ngắm nghía mình. Thoáng thấy một sợi tóc bạc, vua nhuộm đen ngay...","cat":"world"},{"id":"truyen-cong-chua-la-habana","url":"https://truyencotich.top/doc-truyen/truyen-cong-chua-la-habana","title":"Truyện công chúa La Habana","summary":"Cổng thành vừa mở thì một thanh niên tuấn tú, mặt hoa da phấn, cưỡi ngựa mang cung phóng vút ra. Đó là công chúa Habana, nàng dũng sĩ!","cat":"world"},{"id":"tran-da-de","url":"https://truyencotich.top/doc-truyen/tran-da-de","title":"Trận đá dế","summary":"Ngày xửa ngày xưa, có một chú dế nhỏ được gọi là Dế Chiến. Chú sống cùng với các anh trai sau những tảng đá trên cánh đồng. Cái tên Dế Chiến của chú không phải do cha mẹ đặt ra, mà nó có sau khi chú trở thành một chú dế đá nổi tiếng...","cat":"world"},{"id":"su-hoa-than-cua-gau-va-lon-loi","url":"https://truyencotich.top/doc-truyen/su-hoa-than-cua-gau-va-lon-loi","title":"Sự hoá thân của Gấu và Lợn Lòi","summary":"Vào một ngày mùa xuân ấm áp, trên cuộc hành trình của mình lợn lòi nhìn thấy có một con gấu nâu đang mệt mỏi nằm nghỉ trên một tảng đá rêu phủ lên êm ái...","cat":"world"},{"id":"su-tich-con-cua","url":"https://truyencotich.top/doc-truyen/su-tich-con-cua","title":"Sự tích con cua","summary":"Ngày xưa, có một cô gái xinh đẹp, nết na, mồ côi mẹ lúc chưa đầy tháng. Người cha lấy vợ kế được một thời gian, không hiểu sao ông sinh bệnh chết, để lại cô con gái bé bỏng. Cô bé phải sống với mẹ kế và con riêng của bà ta...","cat":"world"},{"id":"thanh-xa-bach-xa","url":"https://truyencotich.top/doc-truyen/thanh-xa-bach-xa","title":"Thanh Xà - Bạch Xà","summary":"Truyền thuyết kể rằng, Lã Động Tân (một vị trong Bát Tiên) hạ phàm giả làm người bán thuốc ở cầu Đoạn Kiều tại Tây Hồ. Lúc đó cậu bé Hứa Tiên đi ngang có thử mua một viên thuốc về uống, kết quả lại không ăn uống gì được...","cat":"world"},{"id":"con-soi-doi","url":"https://truyencotich.top/doc-truyen/con-soi-doi","title":"Con sói đói","summary":"Một ngày kia, trên thung lũng Tây Tạng, có một con sói đói đang lảng vảng trên cánh đồng để tìm thức ăn. Đúng lúc đó, nó bắt gặp một chú lừa đang nhởn nhơ gặm cỏ. Ngay lập tức nó mon men lại gần chú lừa, nghĩ rằng mình đã có một bưa ăn ngon lành...","cat":"world"},{"id":"truyen-thuyet-ve-dat-nuoc-trieu-voi","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-ve-dat-nuoc-trieu-voi","title":"Truyền thuyết về đất nước Triệu Voi","summary":"Ngày xưa, ở nước Lào, có nàng Am-ma-la xinh đẹp, hoàng tử Phôn-xa-nga, con trai của Trời, xin cưới nàng làm vợ. Nhưng vua cha ngăn cấm. Hoàng tử bèn trốn xuống hạ giới để kết hôn với nàng Am-ma-la...","cat":"world"},{"id":"cuoc-tranh-luan-cua-cao-tho-va-coc","url":"https://truyencotich.top/doc-truyen/cuoc-tranh-luan-cua-cao-tho-va-coc","title":"Cuộc tranh luận của Cáo, Thỏ và Cóc","summary":"Vào một ngày đẹp trời nọ, có một con cáo, một con thỏ và một con cóc đang ngồi nghỉ dưới gốc cây trong rừng. Chúng nói chuyện rất lâu, tranh luận về rất nhiều vấn đề. Cuối cùng chúng tranh luận về đề tài tổ tiên của ai có mặt sớm nhất...","cat":"world"},{"id":"mot-nha-tho-chan-chinh","url":"https://truyencotich.top/doc-truyen/mot-nha-tho-chan-chinh","title":"Một nhà thơ chân chính","summary":"Ở một vương quốc nọ, có một ông vua tàn bạo. Dưới triều đại của nhà vua, nhân dân sống lầm than và khổ cực. Người ta truyền nhau một bài hát về sự tham lam và độc ác của quốc vương, và bài hát đến tai vua...","cat":"world"},{"id":"su-tich-cay-nam","url":"https://truyencotich.top/doc-truyen/su-tich-cay-nam","title":"Sự tích cây nấm","summary":"Truyện xưa kể rằng, trong một lần chinh phạt xuống phía nam, đạo quân tiên phong của Tần Thủy Hoàng vị hoàng đế tàn bạo nhất trong lịch sử Trung Hoa, bị lạc vào một khe núi hiểm trở...","cat":"world"},{"id":"con-voi-trang","url":"https://truyencotich.top/doc-truyen/con-voi-trang","title":"Con voi trắng","summary":"Ngày xửa ngày xưa, trong khu rừng rậm của dãy núi cao kia có con voi trắng. Nó sống đã rất nhiều năm và có một đôi ngà dài cong vút. Hơn nữa voi trắng lại rất thông minh và tốt bụng....","cat":"world"},{"id":"tinh-ban-ho-va-heo","url":"https://truyencotich.top/doc-truyen/tinh-ban-ho-va-heo","title":"Tình bạn Hổ và Heo","summary":"Trong một khu rừng rậm, có một con cọp con đang nhảy tung tăng, nó vui sướng đùa nghịch vì mẹ nó đang ngủ nên không cấm nó được. Thế rồi bỗng dưng trời tối xầm lại, sấm chớp ầm ầm, mưa như trút nước...","cat":"world"},{"id":"cau-be-thong-minh-thanh-bagdad","url":"https://truyencotich.top/doc-truyen/cau-be-thong-minh-thanh-bagdad","title":"Cậu bé thông minh thành Bagdad","summary":"Ngày xưa, ở thành Bagdad có một tên trọc phú. Hắn tuy giàu nhưng rất dốt về khoa học, lại thường tự cho mình là giỏi. Một hôm hắn vẽ một kiểu nhà đặc biệt và bắt những người nô lệ phải xây xong trong vòng một tháng...","cat":"world"},{"id":"chang-ngoc-va-lu-quy","url":"https://truyencotich.top/doc-truyen/chang-ngoc-va-lu-quy","title":"Chàng ngốc và lũ quỷ","summary":"Ngày xưa ở một làng kia có hai anh em trai đều có gia đình riêng. Người anh vốn khôn ngoan lại chăm chỉ làm ăn nên chẳng bao lâu đã giàu có. Trái lại người em vừa kém suy tính, lại vừa lười biếng nên càng nghèo...","cat":"world"},{"id":"chuyen-ve-nang-a-thi-ma-truyen-co-tich-trung-quoc","url":"https://truyencotich.top/doc-truyen/chuyen-ve-nang-a-thi-ma-truyen-co-tich-trung-quoc","title":"Chuyện về nàng A Thi Mã -  Truyện cổ tích Trung Quốc","summary":"Ngày xửa ngày xưa, ở một thảo nguyên rộng lớn tên là A Chiêu Đế, gia đình nghèo khổ Cách Lộ Nhật Minh sinh được một cô con gái rất xinh đẹp. Bố mẹ đặt tên nàng là A Thi Mã. Nàng A Thi Mã lớn dần và trở nên xinh đẹp như một đóa hoa...","cat":"world"},{"id":"nang-coi","url":"https://truyencotich.top/doc-truyen/nang-coi","title":"Nàng Cói","summary":"Vào thời Minh, có một cô gái tên là Mộc Định được gả cho một người nông dân nọ. Nàng Mộc Định là một người vợ tốt, hiểu biết hơn người, thẳng thắn trung thực và rất cẩn thận...","cat":"world"},{"id":"noi-chao-duong","url":"https://truyencotich.top/doc-truyen/noi-chao-duong","title":"Nồi cháo đường","summary":"Ngày xửa ngày xưa có một cô gái nhà nghèo, tính tình nết na, cô sống một mình với người mẹ già. Một ngày kia trong nhà hết cả đồ ăn, cô đi vào trong rừng thì gặp một bà cụ già...","cat":"world"},{"id":"la-don-ki-la","url":"https://truyencotich.top/doc-truyen/la-don-ki-la","title":"Lá đơn kì lạ","summary":"Ngày xưa, ở làng nọ, có một bác nông dân nghèo khổ, nhà ngay cạnh trang trại của chúa đất. Gia tài của bác chỉ có một con bò cái. Có lần, con bò chui vào bãi cỏ của chúa đất, chúa đất bèn bắt giết thịt...","cat":"world"},{"id":"chuyen-con-nit","url":"https://truyencotich.top/doc-truyen/chuyen-con-nit","title":"Chuyện con nít","summary":"Tại nhà ông lái buôn giàu có nhất trong tỉnh tụ tập một đám trẻ, con cái các gia đình giàu có và quyền quý. Ông lái buôn là người có học, cũng đã thi cử và đỗ đạt...","cat":"world"},{"id":"con-ga-trong-chan-chi","url":"https://truyencotich.top/doc-truyen/con-ga-trong-chan-chi","title":"Con gà trống chân chì","summary":"Con gà trống ấy có đôi chân chì, lông ở cánh đen mượt như nhung, lông ở ngực vàng thắm, cái mào trên đầu thì đỏ chói, vắt qua vắt lại. Tiếng nó hay ồ ồ, vang rất xa. Nó sống với bà già cô đơn trong một túp lều nát...","cat":"world"},{"id":"ong-vua-sau-muon","url":"https://truyencotich.top/doc-truyen/ong-vua-sau-muon","title":"Ông vua sầu muộn","summary":"Ngày xưa, tại vương quốc Thái Lan có một ông vua sầu muộn. Ngài không bao giờ mở miệng vười với ai, dù người đó là hoàng hậu. Đất nước thái bình thịnh vượng, dân chúng yêu mến đức vua và mong ngài vui vẻ...","cat":"world"},{"id":"con-gai-nguoi-chan-cuu","url":"https://truyencotich.top/doc-truyen/con-gai-nguoi-chan-cuu","title":"Con gái người chăn cừu","summary":"Có một ông vua nước Ba Tư sinh được một hoàng tử. Hoàng tử này yêu cô con gái của một người chăn cừu và muốn lấy cô ta làm vợ...","cat":"world"},{"id":"con-ngua-mu","url":"https://truyencotich.top/doc-truyen/con-ngua-mu","title":"Con ngựa mù","summary":"Ngày xưa lâu lắm rồi, trên đất nước Nga có một thành phố buôn bán sầm uất ở gần cửa biển. Ở thành phố ấy có một thương nhân rất giàu có. Thuyền ông ta chở hàng đi khắp bốn biển năm châu nên ông ta thu được nhiều bạc vàng...","cat":"world"},{"id":"mu-ay-hu-hong","url":"https://truyencotich.top/doc-truyen/mu-ay-hu-hong","title":"Mụ ấy hư hỏng","summary":"Ông thị trưởng đang đứng ở cửa sổ. Ông ta diện một áo sơ-mi mỏng thêu hoa, có lá sen bằng đăng ten trước ngực, trên đó lóng lánh một chiếc kim đầu bằng kim cương....","cat":"world"},{"id":"cau-chuyen-thien-tinh","url":"https://truyencotich.top/doc-truyen/cau-chuyen-thien-tinh","title":"Câu chuyện Thiên tinh","summary":"Giữa một khu vườn có một cây hồng nở đầy hoa. Trong một bông hoa đẹp nhất có một chú thiên tinh. Chú xinh xắn, bé nhỏ đến nỗi mắt người ta không thấy được. Tuy thế, người chú cân đối, đẹp và đáng yêu như tình yêu đẹp đẽ nhất của trẻ thơ...","cat":"world"},{"id":"nguoi-phu-nu-lot-da","url":"https://truyencotich.top/doc-truyen/nguoi-phu-nu-lot-da","title":"Người phụ nữ lột da","summary":"Xưa kia, bên cạnh tòa lâu đài của nhà vua có hai chị em già nua nghèo khổ. Sự tàn nhẫn của thời gian đã lấy đi mọi thứ từ họ,tuổi già khiến cho xương của cả hai vặn vẹo biến dạng, các nếp nhăn phủ kín cơ thể và mái tóc đã rụng gần hết...","cat":"world"},{"id":"nguoi-vo-ngoc-nghech","url":"https://truyencotich.top/doc-truyen/nguoi-vo-ngoc-nghech","title":"Người vợ ngốc nghếch","summary":"Bác nông dân nọ lấy phải bà vợ không được tinh khôn như người thường, ai nói gì cũng tin, đến nỗi người ta lừa cho mà không biết...","cat":"world"},{"id":"su-tich-hoa-phung-tien","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-phung-tien","title":"Sự tích hoa Phụng Tiên","summary":"Niềm vui duy nhất trong đời của bà thợ cày Mađara là cô con gái Rôta. Rôta quả là một cô gái hiếm thấy – nước da rám nắng, hay lam hay làm, tính tình vui vẻ. Mới sáng ra nàng đã gặt được gần nửa cánh đồng lúa...","cat":"world"},{"id":"su-tich-con-bo-than-kapin","url":"https://truyencotich.top/doc-truyen/su-tich-con-bo-than-kapin","title":"Sự tích con bò thần Kapin","summary":"Ngày xửa ngày xưa, không rõ xa xưa đến thế nào, chỉ biết rằng đã rất lâu rồi, từ thời cụ kị của ông cha kể lại, ngày ấy, ở một làng nọ có hai vợ chồng người tiều phu tuy nghèo đói, khổ cực nhưng rất thương yêu nhau....","cat":"world"},{"id":"tuoi-tho-con-nguoi","url":"https://truyencotich.top/doc-truyen/tuoi-tho-con-nguoi","title":"Tuổi thọ con người","summary":"Thượng đế sinh ra muôn loài và ngài cũng muốn ban tuổi thọ cho chúng. Con lừa bước tới hỏi – Xin tâu Thượng đế, con sống bao nhiêu năm?","cat":"world"},{"id":"dong-silinh-bac","url":"https://truyencotich.top/doc-truyen/dong-silinh-bac","title":"Đồng silinh bạc","summary":"Ngày xưa có một đồng silinh (đồng tiền xu của nước Anh). Khi ở nhà tiền ra, nó sáng loáng. Nó nhảy lên kêu leng keng: “Ái chà chà, thế là ta đã xông ra thế giới bao la!” Và quả nhiên, nó sẽ chu du rất lắm xứ sở...","cat":"world"},{"id":"chuyen-cay-hoa-gai","url":"https://truyencotich.top/doc-truyen/chuyen-cay-hoa-gai","title":"Chuyện cây hoa gai","summary":"Trước cửa lâu đài sang trọng của một chúa đất có một vườn hoa đẹp, được chăm sóc cẩn thận, trồng đầy những cây và hoa lạ. Khách đến chơi với chủ nhân đều hết lời ca ngợi những khóm cây mang từ các nước phương xa tới...","cat":"world"},{"id":"nguoi-tho-det-tham-truyen-co-tich-an-do","url":"https://truyencotich.top/doc-truyen/nguoi-tho-det-tham-truyen-co-tich-an-do","title":"Người thợ dệt thảm - Truyện cổ tích Ấn Độ","summary":"Tại một thành phố ở miền nam Ấn Độ có một người thợ dệt thảm [1] tên là Xa-ca. Anh dệt rất khéo, nhưng cả năm mới dệt xong được một tấm, vì thế mà nghèo lắm...","cat":"world"},{"id":"su-tich-con-thien-nga-truyen-co-tich-nga","url":"https://truyencotich.top/doc-truyen/su-tich-con-thien-nga-truyen-co-tich-nga","title":"Sự tích con Thiên Nga - Truyện cổ tích Nga","summary":"Ngày xưa, có một cô bé người Nanai tên là Aioga. Cô bé rất xinh. Mọi người đều yêu cô. Thậm chí có người nói rằng không một làng nào trong vùng có người xinh hơn cô cả....","cat":"world"},{"id":"chu-be-thanh-that-truyen-co-tich-trieu-tien","url":"https://truyencotich.top/doc-truyen/chu-be-thanh-that-truyen-co-tich-trieu-tien","title":"Chú bé thành thật - Truyện cổ tích Triều Tiên","summary":"Ngày xưa, ở một nước nọ có một ông vua rất đỗi hiền từ và thương dân. Ngày đêm nhà vua chăm lo việc nước nên đất nước phồn vinh, muôn dân sung sướng. Được người dân kính mến nhưng vua luôn mang một nỗi buồn trong lòng...","cat":"world"},{"id":"ba-gia-trong-qua-bau","url":"https://truyencotich.top/doc-truyen/ba-gia-trong-qua-bau","title":"Bà già trong quả bầu","summary":"Thuở ấy, rừng rậm còn lan rộng mới tới đồng bằng, thú rừng còn biết nói tiếng người. Ở một làng quê hẻo lánh nọ, có hai mẹ con nhà bà góa sống với nhau rất đầm ấm. Cô gái đã đến tuổi lấy chồng, nhưng quanh vùng chẳng có một chàng trai nào vừa ý...","cat":"world"},{"id":"mot-cap-tinh-nhan","url":"https://truyencotich.top/doc-truyen/mot-cap-tinh-nhan","title":"Một cặp tình nhân","summary":"Một chú Quay và một ả Bóng cùng ở cạnh nhau trong một hộp đựng đồ chơi. Quay bảo Bóng – Chúng ta cùng phải sống suốt đời bên nhau, sao lại không đính hôn với nhau nhỉ?","cat":"world"},{"id":"chiec-mu-than-ky","url":"https://truyencotich.top/doc-truyen/chiec-mu-than-ky","title":"Chiếc mũ thần kỳ","summary":"Ngày xưa, có một người lái buôn trẻ thường hay đi xa và cứ mỗi lần ra thành phố bằng xe thổ mộ là anh trả hẳn tiền vé cả đi lẫn về. Anh khâu hình vẽ và chữ ký của mình vào bên trong mũ rồi khi đi xe lượt về, anh chỉ nhấc cái mũ ra...","cat":"world"},{"id":"su-tich-con-chim-se-bi-cat-luoi","url":"https://truyencotich.top/doc-truyen/su-tich-con-chim-se-bi-cat-luoi","title":"Sự tích con chim sẻ bị cắt lưỡi","summary":"Ngày xửa, ngày xưa có hai vợ chồng ông lão sống ở một làng nọ. Một lần, ông lên núi để kiếm củi. Ông treo bữa trưa của ông trên một cành cây. Một con chim sẻ đến và ăn hết bữa trưa của ông...","cat":"world"},{"id":"con-ca-hai-dang","url":"https://truyencotich.top/doc-truyen/con-ca-hai-dang","title":"Con cá hải đăng","summary":"Ngày xửa ngày xưa, ở một làng kia có đôi vợ chồng già nghèo khổ và không có con cái. Hàng ngày, hai vợ chồng phải vào khu rừng bên cạnh làng để kiếm củi ra chợ bán lấy tiền mua bánh mì sống lần hồi qua ngày...","cat":"world"},{"id":"nha-vua-va-2-ten-cuop","url":"https://truyencotich.top/doc-truyen/nha-vua-va-2-ten-cuop","title":"Nhà vua và 2 tên cướp","summary":"Ở thủ đô nước nọ, bọn cướp hoành hành suốt một thời gian dài. Nhà vua tìm mọi cách mà vẫn không sao chấm dứt được t��nh trạng đó...","cat":"world"},{"id":"ong-than-ngheo","url":"https://truyencotich.top/doc-truyen/ong-than-ngheo","title":"Ông thần nghèo","summary":"Ngày xửa, ngày xưa, ở nơi nọ, có một gia đình bốn người gồm ông lão, bà lão và vợ chồng cậu con trai chung sống với nhau. Trong gia đình ấy, ai cũng như ai, đều rất lười biếng...","cat":"world"},{"id":"chiec-bao-than-ky","url":"https://truyencotich.top/doc-truyen/chiec-bao-than-ky","title":"Chiếc bao thần kỳ","summary":"Ngày xửa ngày xưa, có một người nông dân, một hôm gieo hạt lúa mì trên cánh đồng. Vừa làm việc, chàng trai vừa hát vui vẻ. Ở gần cánh đồng, có những vị thần mê âm nhạc, vội vàng kéo đến chỗ chàng trai đang làm việc...","cat":"world"},{"id":"su-tich-hoa-tuyet","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-tuyet","title":"Sự tích Hoa Tuyết","summary":"Khi bà Chúa Tuyết sinh hạ được một cô con gái, bà phải suy nghĩ rất lâu rồi mới quyết định đặt tên con gái là Xnhedinca...","cat":"world"},{"id":"su-tich-banh-trung-thu","url":"https://truyencotich.top/doc-truyen/su-tich-banh-trung-thu","title":"Sự tích bánh Trung Thu","summary":"Chuyện kể rằng, ngày xưa, trên trời có một nàng tiên nữ tên là Hằng Nga, nàng rất xinh đẹp và chăm chỉ cai quản cả một Vầng Trăng sáng lung linh. Nàng rất yêu trẻ con nên mơ ước của nàng là được ghé xuống trần gian chơi đùa cùng các em...","cat":"world"},{"id":"su-tich-hoa-hong-vang","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-hong-vang","title":"Sự tích hoa hồng vàng","summary":"Truyền thuyết kể rằng: Ngày xưa , khi thần Zeus – chúa tể thần linh, trong 1 chuyến rong chơi đã phải lòng 1 thiếu nữ trần gian và hạ sinh 1 cô con gái, đặt tên là Elisa...","cat":"world"},{"id":"su-tich-hoa-tu-dinh-huong","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-tu-dinh-huong","title":"Sự tích hoa Tử Đinh Hương","summary":"Chuyện xảy ra vào thời mà muôn loài đều vô cùng sợ hãi rồng và phù thuỷ. Cứ chiều chiều, khi gió bắt đầu thổi ù ù vào các ống máng đầu hồi, tức là lúc có dấu hiệu rồng sai phái mụ phù thuỷ gieo tai hoạ xuống đầu một người nào đó...","cat":"world"},{"id":"chiec-non-la-cua-jizo-sama","url":"https://truyencotich.top/doc-truyen/chiec-non-la-cua-jizo-sama","title":"Chiếc nón lá của Jizo – Sama","summary":"Ngày xửa ngày xưa, ở một ngôi làng nọ, có một đôi vợ chồng già sống cùng nhau. Họ nghèo đến nỗi không có nổi một cọng rơm để lợp mái nhà. Năm ấy, dù sắp đến Tết nhưng trong nhà chẳng còn một hạt gạo...","cat":"world"},{"id":"chuyen-co-tich-hoa-huong-duong","url":"https://truyencotich.top/doc-truyen/chuyen-co-tich-hoa-huong-duong","title":"Chuyện cổ tích Hoa hướng dương","summary":"Thuở xa xưa khi trái đất còn ngập chìm trong đêm tối hoang sơ, những bông hoa ủ rũ nép bên nhau để tìm hơi ấm. Không gian luôn chìm trong một màn đêm u tối, vắng lặng không một tiếng chim ca.","cat":"world"},{"id":"vi-sao-doi-ngu-chuc-dau-xuong-dat","url":"https://truyencotich.top/doc-truyen/vi-sao-doi-ngu-chuc-dau-xuong-dat","title":"Vì sao Dơi ngủ chúc đầu xuống đất?","summary":"Ngày xưa, Dơi sống hòa hợp với mọi vật. Nhưng mà không ai yêu mến nó. Ai cũng cho nó là xấu xí vì nó không giống bất cứ loài vật nào, không phải là chim có mỏ, cũng không phải là thú bốn chân, cứ nửa nọ, nửa kia…","cat":"world"},{"id":"nguoi-vo-bep-xep","url":"https://truyencotich.top/doc-truyen/nguoi-vo-bep-xep","title":"Người vợ bép xép","summary":"Ngày xửa ngày xưa, có anh nông dân nọ có chị vợ miệng bép xép như miệng sáo. Không chuyện gì chị ta giữ kín dược, cứ ngứa ngáy phải nói cho hàng xóm láng giềng biết mới chịu thôi...","cat":"world"},{"id":"chiec-coi-vang","url":"https://truyencotich.top/doc-truyen/chiec-coi-vang","title":"Chiếc cối vàng","summary":"Ngày xửa ngày xưa, có một người nông dân nọ, bác ta có một cô con gái rất thông minh. Một hôm, khi đang đi khai khẩn đất hoang bác nông dân và cô con gái đào được một chiếc cối vàng còn lành lặn...","cat":"world"},{"id":"chang-hiep-si-go","url":"https://truyencotich.top/doc-truyen/chang-hiep-si-go","title":"Chàng hiệp sĩ gỗ","summary":"Ở góc cái hòm của một ông già múa rối có một chàng hiệp sĩ bằng gỗ. Đó là một chàng trai môi đỏ, cằm vuông, mắt xếch, đầu đội mũ võ sinh màu trắng, mình bận chiến bào lụa màu lục, lưng thắt dây xanh, chân dận ủng tía...","cat":"world"},{"id":"ong-vua-va-anh-tho-giay","url":"https://truyencotich.top/doc-truyen/ong-vua-va-anh-tho-giay","title":"Ông vua và anh thợ giày","summary":"Ngày xưa, tại kinh đô một nước nọ, có một người thợ đóng giày rất nghèo. Anh khâu vá giày suốt ngày mà chỉ đủ ăn...","cat":"world"},{"id":"bo-xuong-biet-mua","url":"https://truyencotich.top/doc-truyen/bo-xuong-biet-mua","title":"Bộ xương biết múa","summary":"Có hai người làm bạn với nhau. Một người tên là Kami Sichibe, còn người kia tên là Simo Sichibe. Họ rủ nhau đến một nơi xa nhà để kiếm sống.","cat":"world"},{"id":"hoang-tu-gau-trang","url":"https://truyencotich.top/doc-truyen/hoang-tu-gau-trang","title":"Hoàng tử gấu trắng","summary":"Ngày xửa ngày xưa, có một gia đình vô cùng nghèo khổ, cơm không đủ ăn, áo không đủ mặc. Chẳng còn cách nào khác, bố mẹ buộc lòng phải bán cô con gái bé bỏng của mình cho Gấu trắng...","cat":"world"},{"id":"hai-nguoi-tro-lai-hai-minh","url":"https://truyencotich.top/doc-truyen/hai-nguoi-tro-lai-hai-minh","title":"Hại người trở lại hại mình","summary":"Thuở xưa, trong hàng Bà La Môn có một người dâm phụ đương lúc tuổi còn xuân xanh, sắc duyên đằm thắm, mà trong lòng đã mang một khối tình rất lai láng.","cat":"world"},{"id":"con-ho-co-la-gan-chuot-nhat","url":"https://truyencotich.top/doc-truyen/con-ho-co-la-gan-chuot-nhat","title":"Con Hổ có lá gan Chuột nhắt","summary":"Có một con Quạ tha một chú Chuột nhắt bay qua một cánh rừng. Chẳng may nó đánh rơi chú Chuột. Chuột ta rơi vào một nhà ông lão có phép lạ. Ông lão cho nó ở cùng, cho ăn, cho uống cẩn thận. Chuột ta lấy làm hể hả lắm.","cat":"world"},{"id":"chich-che-chich-che-che","url":"https://truyencotich.top/doc-truyen/chich-che-chich-che-che","title":"Chích chè! Chích chè che!","summary":"Xưa ở nước Nga xa xôi, có một đôi vợ chồng già nghèo khổ lắm. Nghèo đến nỗi có lúc củi cũng không có đủ tiền mua.","cat":"world"},{"id":"issun-boshi-chang-vo-si-ti-hon","url":"https://truyencotich.top/doc-truyen/issun-boshi-chang-vo-si-ti-hon","title":"Issun boshi – Chàng võ sĩ tí hon","summary":"Ngày xửa ngày xưa, có đôi vợ chồng nọ, sống bên nhau vô cùng hạnh phúc nhưng không may chẳng có lấy một mụn con nào.","cat":"world"},{"id":"nang-cong-chua-chan-ngong","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-chan-ngong","title":"Nàng công chúa chăn ngỗng","summary":"Ngày xưa có một bà hoàng hậu tuổi đã cao. Đức vua chết đã lâu. Bà có một cô con gái rất xinh đẹp. Khi lớn lên, nàng được hứa hôn với một chàng Hoàng tử con vua một nước xa xôi.","cat":"world"},{"id":"chi-gai-alenushka-va-em-trai-ivanushka","url":"https://truyencotich.top/doc-truyen/chi-gai-alenushka-va-em-trai-ivanushka","title":"Chị gái Alenushka và em trai Ivanushka","summary":"Ngày xưa, ở một cánh rừng thưa, trong một ngôi nhà gỗ nhỏ, có hai chị em Alyonushka và cậu em bé nhỏ Ivanushka sống ở đó. Cha mẹ họ đều đã chết cả. Hàng ngày, Alyonushka đi làm ở ngoài đồng cỏ và dẫn theo em trai...","cat":"world"},{"id":"nang-vasilisa","url":"https://truyencotich.top/doc-truyen/nang-vasilisa","title":"Nàng Vasilisa","summary":"Ngày xửa ngày xưa, trong một căn nhà nọ có hai vợ chồng cùng cô con gái Vasilisa. Dù không giàu có nhưng gia đình sống rất hạnh phúc bên nhau.","cat":"world"},{"id":"ac-gia-ac-bao","url":"https://truyencotich.top/doc-truyen/ac-gia-ac-bao","title":"Ác giả ác báo","summary":"Núi non không giáp mặt nhau được, nhưng con người ta, dù là kẻ xấu hay người tốt, thế nào cũng có lúc gặp nhau. Trên đường đi chu du hành nghề có lần bác thợ giày và bác thợ may lại gặp nhau.","cat":"world"},{"id":"momotaro-cau-be-qua-dao","url":"https://truyencotich.top/doc-truyen/momotaro-cau-be-qua-dao","title":"Momotaro - Cậu bé quả đào","summary":"Ngày xửa ngày xưa, tại một vùng quê hẻo lánh ở Nhật Bản có cặp vợ chồng già sinh sống. Họ không có con cái nên cuộc sống rất buồn tẻ. Hằng ngày, ông lão lên rừng đốn củi còn bà thì giặt giũ bên bờ sông.","cat":"world"},{"id":"gia-dinh-nha-co-truyen-co-andersen","url":"https://truyencotich.top/doc-truyen/gia-dinh-nha-co-truyen-co-andersen","title":"Gia đình nhà cò - Truyện cổ Andersen","summary":"Đằng sau một ngôi nhà trong làng có một tổ cò. Cò mẹ nằm với bốn chú cò con đang chõ lên những cái mỏ đen chưa đủ ngày ngả sang màu đỏ.","cat":"world"},{"id":"dua-tre-trong-mo-truyen-co-andersen","url":"https://truyencotich.top/doc-truyen/dua-tre-trong-mo-truyen-co-andersen","title":"Đứa trẻ trong mồ - Truyện cổ Andersen","summary":"Tang tóc và buồn phiền tràn ngập nhà cửa và tâm can của mọi người: đứa con út, một em bé vừa đầy bốn tuổi, niềm vui và niềm hy vọng của cha mẹ em, vừa chết.","cat":"world"},{"id":"con-thien-nga-be-bong","url":"https://truyencotich.top/doc-truyen/con-thien-nga-be-bong","title":"Con thiên nga bé bỏng","summary":"Ở vùng núi heo hút kia có vợ chồng ông lão nghèo sống cô độc, không có lấy một mụn con. Ngày ngày ông bà vào rừng đốn củi mang ra chợ bán.","cat":"world"},{"id":"con-cho-co-nghia","url":"https://truyencotich.top/doc-truyen/con-cho-co-nghia","title":"Con chó có nghĩa","summary":"Câu chuyện này xảy ra dưới triều đình nhà Thanh, tại một huyện lị có tên là Trung Mâu. Ngày hôm đó quan huyện đang thăng đường làm việc, đột nhiên một con chó từ bên ngoài xông thắng vào nằm phục dưới đất.","cat":"world"},{"id":"de-nho-va-ngua-mu","url":"https://truyencotich.top/doc-truyen/de-nho-va-ngua-mu","title":"Dế nhỏ và ngựa mù","summary":"Ngày xưa, có một lần Thượng đế bảo một vị thiên thần nhỏ, đứng hầu bên cạnh người: Này, Thiên thần nhỏ, hãy đeo chiếc trông xinh xắn của ngươi xuống ngay dưới mặt đất, đánh trống báo hiệu lên...","cat":"world"},{"id":"ba-nang-cong-chua","url":"https://truyencotich.top/doc-truyen/ba-nang-cong-chua","title":"Ba nàng công chúa","summary":"Đức vua San-ta có ba cô con gái vừa xinh đẹp vừa giỏi giang. Công chúa cả có giọng hát mê li: gọi hoa – hoa nở, gọi trăng – trăng tròn. Công chúa ba có tài kể chuyện hấp dẫn không ai sánh bằng.","cat":"world"},{"id":"khi-chong-o-nha","url":"https://truyencotich.top/doc-truyen/khi-chong-o-nha","title":"Khi chồng ở nhà","summary":"Có bác nông dân kia, một hôm đi làm đồng về mệt quá, nhăn nhó kêu ca. Người vợ bảo: Mình đừng phàn nàn nữa. Tôi ở nhà còn mệt hơn.","cat":"world"},{"id":"bao-cong-va-vu-an-con-trau","url":"https://truyencotich.top/doc-truyen/bao-cong-va-vu-an-con-trau","title":"Bao Công và vụ án con trâu","summary":"Lưu Toàn là người thuộc phủ Khai Phong (Trung Quốc), sống bằng nghề làm ruộng, gia đình vào loại khá giả. Tính tình anh hiền hậu, chịu khó làm ăn, không có điều tiếng gì với xóm giềng.","cat":"world"},{"id":"soi-rau-ho","url":"https://truyencotich.top/doc-truyen/soi-rau-ho","title":"Sợi râu hổ","summary":"Ngày xửa ngày xưa, có người vợ trẻ tên Yun Ok. Trước chiến tranh, chồng cô là người hết mực yêu thương cô. Nhưng từ khi trở về từ chiến trận, ông trở nên cau có, dễ tức giận vô cớ.","cat":"world"},{"id":"ba-la-bua","url":"https://truyencotich.top/doc-truyen/ba-la-bua","title":"Ba lá bùa","summary":"Ngày xưa, ở ngôi chùa trên núi nọ, có một vị hòa thượng và một chú tiểu tên là Trúc Lâm. Vì mùa đông đã đến gần nên một ngày nọ, hòa thượng gọi chú tiểu đến bảo...","cat":"world"},{"id":"chuot-gia-banh-giay","url":"https://truyencotich.top/doc-truyen/chuot-gia-banh-giay","title":"Chuột giã bánh giầy","summary":"Ngày xửa ngày xưa, ở một nơi nọ, có hai vợ chồng ông lão tính tình ngay thẳng sống với nhau rất hạnh phúc. Một ngày, cụ ông đang đốn củi phầm phập trên núi thì trông thấy từ trong hang, một chú chuột lăng xăng chui ra.","cat":"world"},{"id":"con-meo-va-cai-nap-binh-bang-sat","url":"https://truyencotich.top/doc-truyen/con-meo-va-cai-nap-binh-bang-sat","title":"Con mèo và cái nắp bình bằng sắt","summary":"Ngày xưa, ở ngôi làng nọ, có một ngôi nhà cổ đã ba đời rất nổi tiếng. Trong nhà có nuôi một con mèo tam thể già, được cả ba đời chủ rất mực cưng chiều.","cat":"world"},{"id":"tho-san-dang-dong-va-tho-san-dang-tay","url":"https://truyencotich.top/doc-truyen/tho-san-dang-dong-va-tho-san-dang-tay","title":"Thợ săn đằng Đông và thợ săn đằng Tây","summary":"Ngày xưa, nước Tosa có hai người thợ săn nổi tiếng ở hai đằng, đằng Đông và đằng Tây. Một hôm, người thợ săn lừng danh đằng Tây tìm đến người thợ săn đằng Đông và mời đi săn.","cat":"world"},{"id":"an-thit-ong-ke","url":"https://truyencotich.top/doc-truyen/an-thit-ong-ke","title":"Ăn thịt ông kẹ","summary":"Ngày xưa, ở ngôi làng nọ, có một ông kẹ thường xuyên xuất hiện đe dọa dân làng khiến mọi người rất sợ hãi. Không ai lên núi mà toàn mạng trở về.","cat":"world"},{"id":"loi-chi-day-cua-tien-ong-truyen-co-tich-nhat-ban","url":"https://truyencotich.top/doc-truyen/loi-chi-day-cua-tien-ong-truyen-co-tich-nhat-ban","title":"Lời chỉ dạy của tiên ông - Truyện cổ tích Nhật Bản","summary":"Ngày xửa ngày xưa, ở nơi nọ, có chàng thanh niên sống cùng người mẹ mù lòa. Hàng ngày, chàng bện dép rơm đem đi bán và mua những món mẹ thích.","cat":"world"},{"id":"ho-duong-da-ho","url":"https://truyencotich.top/doc-truyen/ho-duong-da-ho","title":"Họ Đường đả hổ","summary":"Xưa kia, tỉnh An Huy có một thôn ở cạnh một hòn núi nhỏ, dân cư ở đây chừng trăm nóc nhà, nhà nhà sống về nghề nông, đốn củi, họ ăn no mặc ấm, cuộc sống kể ra cũng thảnh thơi. Chẳng dè năm nọ có một con hổ dữ xuật hiện...","cat":"world"},{"id":"say-ba-va-con-ngua-cua-vua-iran","url":"https://truyencotich.top/doc-truyen/say-ba-va-con-ngua-cua-vua-iran","title":"Sây-ba và con ngựa của vua Iran","summary":"Ngày xưa, ở nước Iran có một ông quan có tài xử kiện nổi tiếng tên là Sây-ba. Một hôm, vua Iran nói với các quan trong triều: Ta phải đích thân đến tận nơi, thử xem Sây-ba tài giỏi như thế nào?","cat":"world"},{"id":"ong-gia-lam-gi-cung-dung","url":"https://truyencotich.top/doc-truyen/ong-gia-lam-gi-cung-dung","title":"Ông già làm gì cũng đúng","summary":"Bác kể cho cháu nghe một câu chuyện bác được nghe từ hồi bác còn nhỏ. Về sau, cứ mỗi lần nhớ đến, bác lại thấy câu chuyện ấy càng hay hơn...","cat":"world"},{"id":"truyen-thuyet-ve-shahmaran","url":"https://truyencotich.top/doc-truyen/truyen-thuyet-ve-shahmaran","title":"Truyền thuyết về Shahmaran","summary":"Trong thần thoại Ba Tư, Shahmaran là nữ hoàng của loài rắn. Tuy có đuôi rắn, nhưng nửa thân trên, nàng lại là một mỹ nhân vạn người mê. Shahmaran có khả năng trường sinh bất lão, thọ ngang trời đất.","cat":"world"},{"id":"lao-ngay-dai-truyen-co-trung-quoc","url":"https://truyencotich.top/doc-truyen/lao-ngay-dai-truyen-co-trung-quoc","title":"Lão ngày dài - Truyện cổ Trung Quốc","summary":"Tại một vùng quê nọ, có một lão địa chủ cực kỳ gian tham. Của cải của hắn nhiều như nước, nhưng lòng tham vô đáy luôn luôn xui khiến hắn tìm mọi cách làm giàu thật ráo riết.","cat":"world"},{"id":"than-ru-ngu","url":"https://truyencotich.top/doc-truyen/than-ru-ngu","title":"Thần Ru ngủ","summary":"Trên đời này chẳng ai biết nhiều chuyện bằng Thần Ru ngủ. Ở Đan Mạch người ta gọi là Thần Ôle Ru ngủ. Đúng đấy! Thần mà kể chuyện thì có thể mê đi được...","cat":"world"},{"id":"ba-co-nhuc-rang","url":"https://truyencotich.top/doc-truyen/ba-co-nhuc-rang","title":"Bà cô nhức răng","summary":"Tôi quen một anh chàng bán thịt, con một bác bán thực phẩm, xuất thân từ một nhà nghèo, sinh ra ở dưới hầm, do làm ăn phấn chấn nên anh đã có một cửa hàng.","cat":"world"},{"id":"giac-mo-cuoi-cung-cua-cay-soi","url":"https://truyencotich.top/doc-truyen/giac-mo-cuoi-cung-cua-cay-soi","title":"Giấc mơ cuối cùng của cây sồi","summary":"Trong rừng, gần bờ biển, trên chốc vách đá hiểm trở, vươn lên một cây sồi cổ thụ. Sồi sống được ba trăm sáu mươi lăm năm, nhưng quãng thời gian ấy đối với sồi cũng chẳng hơn gì chúng ta sống ba trăm sáu mươi lăm ngày.","cat":"world"},{"id":"ngoi-nha-co","url":"https://truyencotich.top/doc-truyen/ngoi-nha-co","title":"Ngôi nhà cổ","summary":"Ở đầu phố, có một ngôi nhà cổ, cổ lắm, xây từ ba trăm năm nay. Người ta đọc thấy điều đó trên một cái xà lớn có ghi ngày tháng xây dựng ngôi nhà và đã bị uất kim hương và dây hốt bố phủ kín.","cat":"world"},{"id":"chang-chan-cuu-cua-vua-machas","url":"https://truyencotich.top/doc-truyen/chang-chan-cuu-cua-vua-machas","title":"Chàng chăn cừu của Vua Machas","summary":"Vua Machas nổi tiếng là một nhà vua công minh, sáng suốt và yêu sự thật của vương quốc Hungary. Vua có một chàng chăn cừu rất được yêu thương vì chàng không bao giờ nói dối.","cat":"world"},{"id":"su-tich-dieu-mua-cong-nuoc-lao","url":"https://truyencotich.top/doc-truyen/su-tich-dieu-mua-cong-nuoc-lao","title":"Sự tích điệu múa công nước lào","summary":"Ngày xưa, ở nước Lào có một hoàng tử tên là Phôn-na-vông, rất đẹp trai, tài giỏi và có đạo đức. Vua và hoàng hậu rất yêu quý. Khi hoàng tử đã đến tuổi trưởng thành, các quan trong triều ai có con gái lớn cũng muốn gả cho chàng.","cat":"world"},{"id":"su-tich-tet-nguyen-tieu","url":"https://truyencotich.top/doc-truyen/su-tich-tet-nguyen-tieu","title":"Sự tích tết nguyên tiêu","summary":"Rằm tháng Giêng hay còn gọi là “Tết Nguyên Tiêu” là ngày lễ lớn trong phong tục của người Việt Nam và Trung Quốc. Đã có nhiều giai thoại tương truyền về nguồn gốc ra đời của ngày Tết này.","cat":"world"},{"id":"su-tich-tet-han-thuc","url":"https://truyencotich.top/doc-truyen/su-tich-tet-han-thuc","title":"Sự tích tết hàn thực","summary":"Tương truyền, Tết Hàn thực ở Việt Nam bắt nguồn từ một điển tích của Trung Quốc mà vẫn được lưu truyền cho tới ngày nay.","cat":"world"},{"id":"chu-be-chan-cuu-va-bon-cuop","url":"https://truyencotich.top/doc-truyen/chu-be-chan-cuu-va-bon-cuop","title":"Chú bé chăn cừu và bọn cướp","summary":"Ngày xưa có một chú bé chăn cừu, cho đàn cừu của mình gặm cỏ trên cánh đồng quanh vùng Cam. Buổi chiều, nó đánh cừu về chuồng, ăn một ít bánh mì và phô mai, nằm dài ra trên đống rơm và ngủ.","cat":"world"},{"id":"de-va-lon","url":"https://truyencotich.top/doc-truyen/de-va-lon","title":"Dê và Lợn","summary":"Ở một cái trại kia, có một chú Dê trẻ tuổi. Cái đuôi thì ngắn củn, râu ria thì xồm xoàm gớm ghê. Trông vào cái mặt, chỉ thấy có chỏm mũi đen bóng nhoáng. Hai con mắt le lé, một vẻ gian ác.","cat":"world"},{"id":"nguoi-thoi-sao-va-nhung-chiec-xe","url":"https://truyencotich.top/doc-truyen/nguoi-thoi-sao-va-nhung-chiec-xe","title":"Người thổi sáo và những chiếc xe","summary":"NGÀY XƯA, CÓ MỘT NGƯỜI THỔI SÁO thần kỳ... Mọi người đều biết câu chuyện xưa đó. Câu chuyện nói về một đô thị bị tấn công và chàng trai với chiếc sáo thần kỳ, lôi kéo chuột ra sông để dìm chết chúng.","cat":"world"},{"id":"thay-boi-nong-dan","url":"https://truyencotich.top/doc-truyen/thay-boi-nong-dan","title":"Thầy bói nông dân","summary":"QUỐC VƯƠNG BỊ MẤT MỘT CHIẾC NHẪN quý giá. Tìm hoài chẳng thấy, nhà vua liền ra thông báo: &quot;Nếu thầy bói nào có thể bói ra chiếc nhẫn ở đâu thì người đó được hưởng vinh hoa phú quý&quot;.","cat":"world"},{"id":"su-tich-hoa-sao-bang","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-sao-bang","title":"Sự tích hoa sao băng","summary":"Mặt trời vừa lên, tất cả các đoá hoa đều nở. Những bông hoa là những người thích đẹp nhất, chúng thường rộ lên vào ban ngày và cùng nhau khoe sắc.","cat":"world"},{"id":"chim-se-me-va-bon-chim-se-con","url":"https://truyencotich.top/doc-truyen/chim-se-me-va-bon-chim-se-con","title":"Chim sẻ mẹ và bốn chim sẻ con","summary":"Chim sẻ đẻ được bốn con nuôi trong tổ của chim én. Khi chim non mới biết bay thì ngày kia có lũ trẻ tinh nghịch trèo lên phá tổ. Bốn con chim non bay tán loạn, may mà chúng bay thoát được.","cat":"world"},{"id":"cho-nha-di-san","url":"https://truyencotich.top/doc-truyen/cho-nha-di-san","title":"Chó nhà đi săn","summary":"Ngày xưa có một ông cụ. Và ông cụ có một con chó. Chó chán ở với ông cụ: Chẳng có gì để canh phòng, cái ăn lại ít. Chó bỏ nhà vào rừng đi săn. Chó nhà gặp chó sói. Hai bên trò chuyện.","cat":"world"},{"id":"chu-meo-tran-vang","url":"https://truyencotich.top/doc-truyen/chu-meo-tran-vang","title":"Chú mèo trán vàng","summary":"Ngày xưa có hai ông bà già. Nhà nghèo đến mức chẳng có gì để ăn, chẳng còn gì để nấu. Đến nước ấy, bà cụ bảo ông cụ: Ông ơi, ông lấy rìu vào rừng chặt lấy cây sồi chở ra chợ bán lấy tiền mua bột về làm bánh.","cat":"world"},{"id":"cong-chua-tina-va-hoang-tu-ech","url":"https://truyencotich.top/doc-truyen/cong-chua-tina-va-hoang-tu-ech","title":"Công chúa Tina và hoàng tử Ếch","summary":"Ngày xửa, ngày xưa có một ông vua sống cùng ba cô công chúa trong một lâu đài trên một vùng đất xa. Một ngày nọ, trong khi vua cha đang suy nghĩ về ba cô con gái, ông nẩy ra một dự định tìm chồng cho họ.","cat":"world"},{"id":"nguoi-tieu-phu-va-nha-tu-hanh","url":"https://truyencotich.top/doc-truyen/nguoi-tieu-phu-va-nha-tu-hanh","title":"Người tiều phu và nhà tu hành","summary":"Nhiều năm trước đây trên đồng bằng Suruga cằn cỗi, có người tiều phu tên là Visu sinh sống. Ông có vóc người cao lớn khác thường và sống trong một túp lều với vợ và các con.","cat":"world"},{"id":"hai-anh-em-va-vang","url":"https://truyencotich.top/doc-truyen/hai-anh-em-va-vang","title":"Hai anh em và vàng","summary":"Ngày xưa có hai anh em ruột sống cách Ieruxalem không xa. Người anh là Aphanaxi, còn người em là Ioan. Họ ở trên núi, cách không xa thành phố và sống bằng của bố thí mọi người cho.","cat":"world"},{"id":"vien-thi-ve-sura","url":"https://truyencotich.top/doc-truyen/vien-thi-ve-sura","title":"Viên thị vệ Sura","summary":"Ngày xửa ngày xưa, ở Indonesia có một ông vua chỉ cần nhìn mặt người nào là đoán ngay được tương lai của người đó.","cat":"world"},{"id":"loai-vat-co-ich","url":"https://truyencotich.top/doc-truyen/loai-vat-co-ich","title":"Loài vật có ích","summary":"THUỞ XƯA, có hai cha con nhà nọ. Người cha chỉ có một túp lều tranh nho nhỏ. Một hôm, nhà không còn một hạt lúa mì, một chút nhét vào kẽ răng cũng không có. Cha mới bảo con trai cầm một trăm rúp ra chợ mua ít lúa mì.","cat":"world"},{"id":"su-tich-cho-soi-so-tieng-chuong","url":"https://truyencotich.top/doc-truyen/su-tich-cho-soi-so-tieng-chuong","title":"Sự tích chó sói sợ tiếng chuông","summary":"Ngày xưa có một con cáo hầu hạ cho tên cảnh sát. Con cáo làm phận sự của mình hết sức mẫn cán. Nó quơ sạch các chuồng gà của hàng xóm láng giềng. Được bao nhiêu nó mang về dâng cho cảnh sát.","cat":"world"},{"id":"chu-du-thien-ha","url":"https://truyencotich.top/doc-truyen/chu-du-thien-ha","title":"Chu du thiên hạ","summary":"Ngày xưa có một bà già nghèo khó có một người con trai. Một hôm anh ta nói với mẹ là muốn đi chu du thiên hạ, bà mẹ nói: Con làm sao mà đi được, mẹ nghèo không có tiền cho con làm lộ phí.","cat":"world"},{"id":"su-tich-hoa-hong-xanh","url":"https://truyencotich.top/doc-truyen/su-tich-hoa-hong-xanh","title":"Sự tích hoa hồng xanh","summary":"Ngày xửa ngày xưa ở vương quốc hoa hồng có một thằng ngốc tên Stupid. Thằng ngốc may mắn được nhà vua giao cho chăm sóc vườn hoa hồng. Nhà vua có một cô công chúa rất xinh tên Rose.","cat":"world"},{"id":"co-gai-giam-len-banh-mi","url":"https://truyencotich.top/doc-truyen/co-gai-giam-len-banh-mi","title":"Cô gái giẫm lên bánh mì","summary":"Hẳn là bạn đã nghe nói về một cô gái đã xéo lên ổ bánh mì để khỏi phải bẩn giầy và về sau cô ta khốn khổ như thế nào. Câu chuyện được viết lại và cũng đã được in ra.","cat":"world"},{"id":"cai-bong","url":"https://truyencotich.top/doc-truyen/cai-bong","title":"Cái bóng","summary":"Ở các xứ nóng, ánh nắng gay gắt hơn ở nước chúng ta nhiều lắm. Dân cư da dẻ đỏ sẫm như màu gỗ gụ. Ở xứ nóng hơn nữa, họ còn bị hun cháy đến nỗi đen xì cả người ra.","cat":"world"},{"id":"trong-thanh-co-ma-troi","url":"https://truyencotich.top/doc-truyen/trong-thanh-co-ma-troi","title":"Trong thành có ma trơi","summary":"Ngày xưa có một người trước kia biết rất nhiều truyện cổ tích, nhưng về sau ông ta bảo với mọi người rằng ông đã quên hết cả rồi, vì Truyện, xưa kia hay đến thăm ông, nay chẳng thấy đến gõ cửa nhà ông nữa.","cat":"world"},{"id":"bac-lam-vuon-va-nha-chu","url":"https://truyencotich.top/doc-truyen/bac-lam-vuon-va-nha-chu","title":"Bác làm vườn và nhà chủ","summary":"Cách thủ đô chừng một dặm đường có một toà lâu đài tường dày, các chòi đều có lỗ châu mai và mái nhọn. Đó là một lâu đài cổ hùng vĩ.","cat":"world"},{"id":"mot-chuyen-dau-long","url":"https://truyencotich.top/doc-truyen/mot-chuyen-dau-long","title":"Một chuyện đau lòng","summary":"Chúng tôi đang ở trong một lâu đài thuộc nơi thôn dã. Chủ nhân đang vắng nhà mấy ngày. Một bà sang trọng, vợ goá ông chủ xưởng thuộc da ở thành phố cạnh đấy, đến chơi. Bà dắt theo một con chó, loại chó ngắn mõm.","cat":"world"},{"id":"ip-va-co-be-crixtin","url":"https://truyencotich.top/doc-truyen/ip-va-co-be-crixtin","title":"Ip và cô bé Crixtin","summary":"Con sông Guđơna xinh đẹp và trong vắt chảy qua miền Bắc bán đảo Jutland, chạy dọc theo một cánh rừng bát ngát, rải sâu vào hậu phương. Đất nhô lên hình lưng lừa nom như một bờ lũy xuyên qua rừng.","cat":"world"},{"id":"con-trai-nguoi-gac-cong","url":"https://truyencotich.top/doc-truyen/con-trai-nguoi-gac-cong","title":"Con trai người gác cổng","summary":"Quan Đại tướng ở trên gác, người gác cổng ở dưới nhà hầm. Hai gia đình sống rất xa cách nhau, trước hết là tầng dưới nhà ngăn biệt họ, sau nữa là do sự khác nhau về đẳng cấp.","cat":"world"},{"id":"huong-moc-tinh","url":"https://truyencotich.top/doc-truyen/huong-moc-tinh","title":"Hương mộc tinh","summary":"Ngày xưa có một cậu bé bị cảm, vì đi chơi giẫm chân xuống nước, nhưng sao cậu lại giẫm chân xuống nước được thì không ai hiểu, vì hôm ấy trời rất khô ráo.","cat":"world"},{"id":"nang-cong-chua-di-guoc","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-di-guoc","title":"Nàng công chúa đi guốc","summary":"Ngày xưa có một ông vua và một bà hoàng hậu sinh được một người con gái đẹp tuyệt trần. Bây giờ không ai còn nhớ được tên cô gái, mà chỉ có những cụ già lụ khụ nhớ lại rằng ở lâu đài mọi người đều gọi cô là “Công chúa đi guốc”.","cat":"world"},{"id":"vi-than-diem-dam","url":"https://truyencotich.top/doc-truyen/vi-than-diem-dam","title":"Vị thần Điềm Đạm","summary":"Tích xưa theo thần thoại Nhật Bản, các vị thần ở trên cõi trời, có một khi cùng tranh nhau quyền bá chú thế gian. Bất kỳ là vị nào, cũng đều cho mình là quyền lực trên hết tất cả Trời Đất.","cat":"world"},{"id":"hai-vi-than-mui-dai","url":"https://truyencotich.top/doc-truyen/hai-vi-than-mui-dai","title":"Hai vị thần mũi dài","summary":"Ngày xưa, đã lâu lắm có hai vị thần mũi dài sống trên đỉnh núi cao miền Bắc Nhật Bản, một vị thần áo xanh, vị kia áo đỏ. Hai vị có thể vươn cái mũi dài tới bất kỳ nơi nào. Vị nào cũng cho rằng chiếc mũi của mình duyên dáng hơn cả.","cat":"world"},{"id":"nguoi-an-xin-lam-vua","url":"https://truyencotich.top/doc-truyen/nguoi-an-xin-lam-vua","title":"Người ăn xin làm vua","summary":"Ngày ấy, có một người sống bằng nghề ăn xin từ thuở nhỏ, ở bậc thềm nhà thờ. Thấy y trai tráng mà không chịu làm ăn, ít người bố thí cho.","cat":"world"},{"id":"banh-mi-va-muoi","url":"https://truyencotich.top/doc-truyen/banh-mi-va-muoi","title":"Bánh mì và muối","summary":"Ngày xửa ngày xưa, quốc vương nọ có ba cô con gái. Cô chị cả, cô chị thứ hai hết sức kiêu căng, hợm hĩnh. Chỉ có cô em út là lương thiện, đáng yêu. Quốc vương tuổi đã cao, có ý định đem chia tài sản cho các con.","cat":"world"},{"id":"cay-vi-cam-co-phep-la","url":"https://truyencotich.top/doc-truyen/cay-vi-cam-co-phep-la","title":"Cây vĩ cầm có phép lạ","summary":"Ngày xửa ngày xưa, một nam tước giàu có có ba cô con gái, hai cô chị xấu xí nhưng cô em lại đẹp mê hồn. Cô chị cả tên là Su-dông, cao và gầy như một cái cọc, răng to và lỗ mũi thì như một chiếc móc.","cat":"world"},{"id":"hat-luu-cua-nguoi-do-thai","url":"https://truyencotich.top/doc-truyen/hat-luu-cua-nguoi-do-thai","title":"Hạt lựu của người Do Thái","summary":"Tại một vương quốc nọ, có một cộng đồng người Do Thái nhỏ bé sinh sống, vốn có nguồn gốc từ Giê-ru-sa-lem. Nhà vua và các cận thần luôn tỏ ra bất đắc dĩ khi để họ trú ngụ nên chỉ dành cho họ khu nhà tồi tàn ở ngoại vi thủ đô.","cat":"world"},{"id":"hoang-tu-ivan-va-con-chim-lua","url":"https://truyencotich.top/doc-truyen/hoang-tu-ivan-va-con-chim-lua","title":"Hoàng tử Ivan và con chim lửa","summary":"Ngày xửa ngày xưa, ở một vương quốc xa xôi, có vị sa hoàng sở hữu một cây táo vàng quý hiếm. Mỗi mùa thu, cây lại trĩu quả sáng lấp lánh như mặt trời.","cat":"world"},{"id":"cong-rom-kho","url":"https://truyencotich.top/doc-truyen/cong-rom-kho","title":"Cọng rơm khô","summary":"Ngày xửa ngày xưa, tại một ngôi làng nhỏ ở Nhật Bản, có một chàng trai nghèo tên là Yosaku. Chàng nghèo đến mức không có ruộng đất, không có nhà cửa, chỉ sống nhờ làm thuê làm mướn.","cat":"world"},{"id":"nui-thuy-tinh","url":"https://truyencotich.top/doc-truyen/nui-thuy-tinh","title":"Núi thuỷ tinh","summary":"Ngày sửa ngày xưa, có một vị hoàng đế có một cô con gái xinh đẹp và vô cùng thông minh. Khi công chúa lớn lên, đến tuổi chọn phò mã, vị hoàng đế đột nhiên nảy ra một ý định rất kỳ lạ...","cat":"world"},{"id":"loi-hua-cua-nha-vua","url":"https://truyencotich.top/doc-truyen/loi-hua-cua-nha-vua","title":"Lời hứa của nhà vua","summary":"Ngày xưa, ở một vương quốc xa xôi, có một vị vua sống cùng hoàng hậu trong cung điện nguy nga, nhưng trong lòng luôn canh cánh một nỗi buồn: hai người mãi vẫn chưa có con nối dõi.","cat":"world"},{"id":"su-tich-quoc-dao-singapore","url":"https://truyencotich.top/doc-truyen/su-tich-quoc-dao-singapore","title":"Sự tích quốc đảo Singapore","summary":"Ngày xưa, trên đảo Sumatra có một vị vua trẻ tuổi nung nấu ý định xây dựng một thành phố mới. Ông triệu viên tể tướng đến và nói rằng muốn cùng ông đi dọc bờ biển để tìm một vùng đất thích hợp. Tể tướng lập tức nhận lệnh và xin được theo hầu.","cat":"world"},{"id":"jorinda-va-joringel","url":"https://truyencotich.top/doc-truyen/jorinda-va-joringel","title":"Jorinda và Joringel","summary":"Thuở xưa, xưa lắm, sâu trong khu rừng tăm tối, ảm đạm có một tòa lâu đài cổ kính. Sống trong lâu đài là một mụ phù thủy già cô độc.","cat":"world"},{"id":"nang-tien-bien","url":"https://truyencotich.top/doc-truyen/nang-tien-bien","title":"Nàng Tiên Biển","summary":"Ngày xửa ngày xưa, có một chàng trai làm nghề đánh cá nhưng luôn gặp vận rủi. Nhiều đêm liền, chàng vất vả thả câu từ tối tới sáng mà vẫn không bắt được nổi một con cá.","cat":"world"},{"id":"cau-be-binkie","url":"https://truyencotich.top/doc-truyen/cau-be-binkie","title":"Cậu bé Binkie","summary":"Ngày xưa, có một cậu bé tên là Binkie. Thân hình cậu nhỏ bé như bao đứa trẻ khác, nhưng trí óc lại thông minh khác thường...","cat":"world"},{"id":"chim-son-ca-cua-hoang-de","url":"https://truyencotich.top/doc-truyen/chim-son-ca-cua-hoang-de","title":"Chim Sơn ca của Hoàng đế","summary":"Ngày xửa ngày xưa, ở đất nước Trung Hoa xa xôi, có một vị hoàng đế sống trong cung điện đẹp nhất trần gian...","cat":"world"},{"id":"su-tich-nui-dan-ba-va-nui-dan-ong","url":"https://truyencotich.top/doc-truyen/su-tich-nui-dan-ba-va-nui-dan-ong","title":"Sự Tích Núi Đàn Bà và Núi Đàn Ông","summary":"Ngày xửa ngày xưa, ở đất nước Cambodia có một vị nữ hoàng nổi tiếng khắp nơi vì sắc đẹp và tài trị nước. Nàng tên là Srey Aktea, lên ngôi khi vừa tròn hai mươi tuổi...","cat":"world"},{"id":"vua-nam","url":"https://truyencotich.top/doc-truyen/vua-nam","title":"Vua Nấm","summary":"Ngày xửa ngày xưa, có một nhóm người vào rừng hái nấm. Trong lúc tìm kiếm, họ phát hiện một cây nấm khổng lồ chưa từng thấy...","cat":"world"},{"id":"than-ma","url":"https://truyencotich.top/doc-truyen/than-ma","title":"Thần Mã","summary":"Ngày xửa ngày xưa, có một khu rừng tên là Rừng Đen. Nơi ấy đầy rẫy hổ báo, mãng xà và những loài thú dữ hung ác. Chúng thường xuyên ra khỏi rừng bắt người ăn thịt khiến dân làng vô cùng khiếp sợ...","cat":"world"},{"id":"con-thien-nga-do-tham","url":"https://truyencotich.top/doc-truyen/con-thien-nga-do-tham","title":"Con thiên nga đỏ thắm","summary":"Ngày xửa ngày xưa, trong một bộ tộc người da đỏ sống giữa những cánh rừng bạt ngàn, có một vị tù trưởng già nổi tiếng khôn ngoan và dũng cảm...","cat":"world"},{"id":"su-tich-con-than-ma","url":"https://truyencotich.top/doc-truyen/su-tich-con-than-ma","title":"Sự tích con Thần Mã","summary":"Ngày xửa ngày xưa, có một khu rừng đen, rất nhiều thú dữ, rắn độc, thường ra bắt người ăn thịt. Người qua lại đều phải đi vòng quanh rất xa...","cat":"world"},{"id":"nhung-ten-trom-thua-cuoc","url":"https://truyencotich.top/doc-truyen/nhung-ten-trom-thua-cuoc","title":"Những tên trộm thua cuộc","summary":"Trong làng nọ có hai vợ chồng nghèo sinh sống. Họ chỉ có một cậu con trai duy nhất, một cậu bé tinh nghịch, sáng nào cũng đi kiếm củi trong rừng về cho mẹ nấu nướng.","cat":"world"},{"id":"truyen-ngu-ngon-rua-va-tho","url":"https://truyencotich.top/doc-truyen/truyen-ngu-ngon-rua-va-tho","title":"Truyện ngụ ngôn Rùa và Thỏ","summary":"Ngày xửa ngày xưa, có một con Rùa và một con Thỏ cãi nhau xem ai nhanh hơn. Chúng quyết định giải quyết việc tranh luận bằng một cuộc thi chạy đua...","cat":"fable"},{"id":"ech-ngoi-day-gieng","url":"https://truyencotich.top/doc-truyen/ech-ngoi-day-gieng","title":"Ếch ngồi đáy giếng","summary":"Có một con ếch sống lâu ngày trong một giếng nọ. Xung quanh nó chỉ có vài con nhái, cua, ốc bé nhỏ. Từ dưới đáy giếng nhìn lên, ếch ta chỉ thấy một khoảng trời bé bằng cái vung...","cat":"fable"},{"id":"con-cao-va-chum-nho","url":"https://truyencotich.top/doc-truyen/con-cao-va-chum-nho","title":"Con cáo và chùm nho","summary":"Một ngày nọ, Cáo ta xuống triền núi và phát hiện ra phía trước có một vườn nho. Dưới tán lá xanh, từng chùm nho căng tròn mọng nước, dưới ánh sáng mặt trời trông lại càng hấp dẫn...","cat":"fable"},{"id":"thay-boi-xem-voi","url":"https://truyencotich.top/doc-truyen/thay-boi-xem-voi","title":"Thầy bói xem voi","summary":"Nhân buổi ế hàng, năm ông thầy bói nói chuyện với nhau. Thầy nào cũng phàn nàn không biết hình thù con voi nó như thế nào. Chợt nghe người ta nói có voi đi qua, năm thầy chung nhau tiền biếu người quản voi, xin cho voi dừng lại để cùng xem...","cat":"fable"},{"id":"con-qua-thong-minh","url":"https://truyencotich.top/doc-truyen/con-qua-thong-minh","title":"Con quạ thông minh","summary":"Một con quạ đang khát nước. Nó bay rất lâu để tìm nước nhưng chẳng thấy một giọt nước nào.","cat":"fable"},{"id":"truyen-ngu-ngon-cao-va-co","url":"https://truyencotich.top/doc-truyen/truyen-ngu-ngon-cao-va-co","title":"Truyên ngụ ngôn Cáo và Cò","summary":"Ngày xửa ngày xưa, có một con cáo rất xảo quyệt và tinh nghịch. Nó thường giả vờ thân thiện sau đó chơi khăm những con vật khác...","cat":"fable"},{"id":"dai-bang-va-bo-canh-cung","url":"https://truyencotich.top/doc-truyen/dai-bang-va-bo-canh-cung","title":"Đại Bàng Và Bọ Cánh Cứng","summary":"Có lần một con Bọ Cánh Cứng năn nỉ Đại Bàng xin tha mạng cho một con thỏ bị Đại Bàng rượt chạy đến nó xin che chở. Nhưng Đại Bàng vẫn vồ lấy con mồi, sức vỗ mạnh của đôi cánh của nó hất văng Bọ Cánh Cứng ra xa đến cả chục thước.","cat":"fable"},{"id":"hai-con-de-qua-cau","url":"https://truyencotich.top/doc-truyen/hai-con-de-qua-cau","title":"Hai con dê qua cầu","summary":"Ngày xưa có một con dê đang ăn cỏ trên đoạn dốc đầy cỏ của ngọn đồi gần một con suối. Nó quyết định thưởng thức mùi vị cỏ trên ngọn đồi bên kia. Một lối đi hẹp dài được làm như một chiếc cầu bắc ngang qua con suối...","cat":"fable"},{"id":"kien-va-ve-sau","url":"https://truyencotich.top/doc-truyen/kien-va-ve-sau","title":"Kiến và Ve sầu","summary":"Ngày hè đỏ lửa, ve sầu lười biếng nằm duỗi chân dưới tán cây. Thỉnh thoảng ve sầu lại nhấm nháp một giọt mật ong thượng hạng, lim dim hưởng thụ thì bất chợt thấy bác kiến thân thể nhớp nháp mồ hôi hì hục vác một hạt gạo...","cat":"fable"},{"id":"chan-tay-tai-mat-mieng","url":"https://truyencotich.top/doc-truyen/chan-tay-tai-mat-mieng","title":"Chân, Tay, Tai, Mắt, Miệng","summary":"Cô Mắt, cậu Chân, cậu Tay, bác Tai, lão Miệng từ xưa vẫn sống với nhau rất thân thiết. Bỗng một hôm, cô Mắt đến than thở với cậu Chân, cậu Tay...","cat":"fable"},{"id":"truyen-ngu-ngon-kien-va-voi","url":"https://truyencotich.top/doc-truyen/truyen-ngu-ngon-kien-va-voi","title":"Truyện ngụ ngôn Kiến và Voi","summary":"Ngày xưa, trong một khu rừng rậm có một con Voi rất hung dữ. Gặp bất kỳ loài vật nào, Voi cũng dùng đôi ngà ghê gớm của mình húc.","cat":"fable"},{"id":"chu-cho-tham-an-va-cai-bong","url":"https://truyencotich.top/doc-truyen/chu-cho-tham-an-va-cai-bong","title":"Chú chó tham ăn và cái bóng","summary":"Trên một con đường của ngôi làng nọ, có một chú chó hung dữ lững thững đi dạo trên đường. Bỗng nhiên, một mùi thơm từ đâu bay tới đánh thức cơn đói cồn cào trong bụng nó...","cat":"fable"},{"id":"meo-lai-hoan-meo","url":"https://truyencotich.top/doc-truyen/meo-lai-hoan-meo","title":"Mèo lại hoàn mèo","summary":"Ngày xưa có một người nuôi một con mèo. Nghĩ con mèo của mình khôn ngoan, tài giỏi không có loài nào hơn nữa, mới đặt tên cho nó là “Trời”.","cat":"fable"},{"id":"cau-chuyen-bo-dua","url":"https://truyencotich.top/doc-truyen/cau-chuyen-bo-dua","title":"Câu chuyện bó đũa","summary":"Ngày xưa, ở một làng nọ có một người nhà rất giàu. Ông ta sinh được những năm người con. Vì quá giàu có nên những người con của ông ta có một đời sống sung sướng thừa thãi về vật chất...","cat":"fable"},{"id":"deo-cay-giua-duong","url":"https://truyencotich.top/doc-truyen/deo-cay-giua-duong","title":"Đẽo cày giữa đường","summary":"Chuyện kể rằng có một bác nông dân rất nghèo, cả đời sống bằng nghề đồng áng, bác muốn làm một cái cày thật tốt để làm công việc đồng áng năng suất và đỡ vất vả hơn...","cat":"fable"},{"id":"deo-nhac-cho-meo","url":"https://truyencotich.top/doc-truyen/deo-nhac-cho-meo","title":"Đeo nhạc cho mèo","summary":"Vì mèo mà cuộc sống họ nhà chuột trở nên khó khăn. Ngày nào chuột cũng bị mèo săn bắt...","cat":"fable"},{"id":"con-muoi-va-con-bo-duc","url":"https://truyencotich.top/doc-truyen/con-muoi-va-con-bo-duc","title":"Con muỗi và con bò đực","summary":"Trên đồng cỏ bao la, một con muỗi đang bay qua bay lại nhiều vòng tìm đồ ăn. Hồi lâu muỗi ta mỏi cánh nên quyết định nghỉ ngơi trên sừng của một con bò đực. Sau khi nghỉ ngơi, con muỗi nhỏ bé quyết định rời đi...","cat":"fable"},{"id":"vet-va-chau-chau","url":"https://truyencotich.top/doc-truyen/vet-va-chau-chau","title":"Vẹt và châu chấu","summary":"Khoa La là tên một con vẹt, mỏ nó vừa đẹp vừa linh hoạt. Nó có thể mổ châu chấu trong các bụi cỏ rất chi là tự nhiên.","cat":"fable"},{"id":"nguoi-di-buon-va-con-lua","url":"https://truyencotich.top/doc-truyen/nguoi-di-buon-va-con-lua","title":"Người đi buôn và con lừa","summary":"Người lái buôn phải thường xuyên vào thành để mua đồ, và chất lên vai Lừa để trở về nhà. Con Lừa của người lái buôn nghĩ rằng mình rất thông minh, lúc nào cũng thích động não, nghĩ mọi cách để có thể khiến cho đồ mình phải chở càng nhẹ càng tốt.","cat":"fable"},{"id":"con-huou-trong-chuong-bo","url":"https://truyencotich.top/doc-truyen/con-huou-trong-chuong-bo","title":"Con hươu trong chuồng bò","summary":"Có một con Hươu đang dạo chơi trong rừng, không cẩn thận lạc vào một thôn làng đông người sinh sống. Một con chó săn phát hiện ra, liền sủa dữ dội “Gâu, gâu gâu!” và xông về phía Hươu.","cat":"fable"},{"id":"rua-hoc-bay","url":"https://truyencotich.top/doc-truyen/rua-hoc-bay","title":"Rùa học bay","summary":"Trong lùm cỏ, một chú Rùa đang ra sức tập bay. Một chú chim Sẻ bay ngang qua thấy thế liền hỏi: Anh Rùa ơi, anh đang làm gì thế ?","cat":"fable"},{"id":"dieu-uoc-mong-cuoi-cung","url":"https://truyencotich.top/doc-truyen/dieu-uoc-mong-cuoi-cung","title":"Điều ước mong cuối cùng","summary":"Sói quyết định thắt cổ tự tử rồi loan báo cho cả rừng biết...","cat":"fable"},{"id":"tham-an","url":"https://truyencotich.top/doc-truyen/tham-an","title":"Tham ăn","summary":"Ngày xưa, ở vương quốc Thái Lan, có một ngôi chùa rất lớn và đẹp, trụ trì ngôi chùa này là một ông sư còn trẻ nhưng lại nổi tiếng tham lam và ích kỷ.","cat":"fable"},{"id":"su-tu-va-lua","url":"https://truyencotich.top/doc-truyen/su-tu-va-lua","title":"Sư tử và lừa","summary":"Một hôm Sư tử kiêu hãnh đi xuống một cánh rừng, các loài thú vật nhìn thấy đều kính cẩn nhường đường cho sư tử, nhưng một con lừa be be buông lời ra một lời nhận xét đầy khinh thị...","cat":"fable"},{"id":"mat-ca-dan-ga","url":"https://truyencotich.top/doc-truyen/mat-ca-dan-ga","title":"Mất cả đàn gà","summary":"Cáo và chó sói đều là những kẻ phá hoại. Những việc chúng làm đều là việc xấu, cho nên người ta không ai muốn làm bạn với chúng.","cat":"fable"},{"id":"chuyen-ngu-ngon-thoi-hien-dai","url":"https://truyencotich.top/doc-truyen/chuyen-ngu-ngon-thoi-hien-dai","title":"Chuyện ngụ ngôn thời hiện đại","summary":"Ngày xửa ngày xưa, có một con rùa và một con thỏ cãi nhau xem ai nhanh hơn. Chúng quyết định giải quyết việc tranh luận bằng một cuộc thi chạy.","cat":"fable"},{"id":"chien-ma-va-con-lua","url":"https://truyencotich.top/doc-truyen/chien-ma-va-con-lua","title":"Chiến mã và con lừa","summary":"Một con chiến mã – đã sẵn sàng ra chiến trường với bộ yên cương lục lạc tuyệt đẹp trên mình – đang phi nước kiệu trên đường, tiếng vó ngựa phi trên đường nghe như tiếng sấm dội.","cat":"fable"},{"id":"nguoi-cha-va-bo-ten","url":"https://truyencotich.top/doc-truyen/nguoi-cha-va-bo-ten","title":"Người cha và bó tên","summary":"Có một người cha trước khi chết gọi ba người con trai đến bên giường, đưa cho họ một bó tên và bảo:","cat":"fable"},{"id":"tin-tot-lanh-nhat-trong-ngay","url":"https://truyencotich.top/doc-truyen/tin-tot-lanh-nhat-trong-ngay","title":"Tin tốt lành nhất trong ngày","summary":"Một anh sinh viên vừa tốt nghiệp đại học đang tìm việc làm đã tham dự một cuộc thi sáng tạo chuyên ngành do liên hiệp các trường đại học trong cả nước tổ chức...","cat":"fable"},{"id":"truyen-ngu-ngon-thieu-nhi","url":"https://truyencotich.top/doc-truyen/truyen-ngu-ngon-thieu-nhi","title":"Truyện ngụ ngôn thiếu nhi","summary":"Một Bà Lão tìm thấy một bình rượu không trước đây đựng đầy rượu ngon lâu năm mà vẫn còn lưu lại được mùi hương thơm ngát của rượu ngon ấy.","cat":"fable"},{"id":"hai-con-ngua","url":"https://truyencotich.top/doc-truyen/hai-con-ngua","title":"Hai con ngựa","summary":"Một con Ngựa trắng rất đẹp, nó được người chủ giàu có cho ăn uống đầy đủ, suốt ngày chẳng làm gì. Con Ngựa trắng thấy con Ngựa đen làm việc vất vả bèn bảo:","cat":"fable"},{"id":"chuot-nha-va-chuot-dong","url":"https://truyencotich.top/doc-truyen/chuot-nha-va-chuot-dong","title":"Chuột nhà và chuột đồng","summary":"Chuột nhà và Chuột đồng là bạn thân của nhau. Chuột đồng sống ở nông thôn, ngày ngày ra đồng ăn thóc, cuộc sống rất vui vẻ, hạnh phúc.","cat":"fable"},{"id":"nguoi-chan-cuu-va-qua","url":"https://truyencotich.top/doc-truyen/nguoi-chan-cuu-va-qua","title":"Người chăn cừu và quạ","summary":"Người chăn cừu nuôi cả nghìn con cừu trong nông trường, ông ta và các con đều sống ở đó. Người chăn cừu có hai người hàng xóm, Chim Ưng và Quạ...","cat":"fable"},{"id":"doi-chim-va-ho-nha-thu","url":"https://truyencotich.top/doc-truyen/doi-chim-va-ho-nha-thu","title":"Dơi, chim và họ nhà thú","summary":"Họ hàng các loài chim chóc và họ hàng các loài thú cãi vã nhau kịch liệt. Khi hai bên dàn quân chuẩn bị đánh nhau, dơi lưỡng lự chẳng biết theo bên nào.","cat":"fable"},{"id":"seu-cua-va-bay-ca","url":"https://truyencotich.top/doc-truyen/seu-cua-va-bay-ca","title":"Sếu, Cua và bầy cá","summary":"Ở ven hồ kia, có một con sếu rất tinh ma xảo quyệt. Hằng ngày sếu kiếm ăn quanh quẩn trong hồ, hễ con cá nào vừa nhô lên mặt nước hoặc rơi vào bờ là sếu mổ chết ngay.","cat":"fable"},{"id":"heo-rung-va-tho","url":"https://truyencotich.top/doc-truyen/heo-rung-va-tho","title":"Heo rừng và Thỏ","summary":"Có con Heo rừng đang ăn đêm trong nương khoai thì bị mắc bẫy. Một chân sau của nó bị vòng bẫy treo lơ lửng khỏi mặt đất, nhưng càng giẫy giụa thì vòng bẫy càng thắt chặt vào.","cat":"fable"},{"id":"mua-giay","url":"https://truyencotich.top/doc-truyen/mua-giay","title":"Mua giày","summary":"Một người ở nước Trịnh, anh ta định mua cho mình một đôi giày để đi. Trước khi đi, anh ta đo vẽ kích thước chân mình, rồi để bản vẽ mẫu lên bàn...","cat":"fable"},{"id":"dan-kien-den-on","url":"https://truyencotich.top/doc-truyen/dan-kien-den-on","title":"Đàn kiến đền ơn","summary":"Trong khu rừng nọ, một đàn kiến sa vào vũng nước. Ở trên cành cây gần bên, có một chú chim nhỏ vừa ra khỏi tổ, thấy động lòng thương, chú bay vụt ra nhặt mấy cọng rác thả xuống làm cầu cho đàn kiến đi qua.","cat":"fable"},{"id":"con-lua-va-hai-bo-con","url":"https://truyencotich.top/doc-truyen/con-lua-va-hai-bo-con","title":"Con lừa và hai bố con","summary":"Đi được một quãng đường nữa, họ gặp ba người lái buôn đi qua. “Sao bất hiếu thế,” họ la lên, “phải biết kính trọng tuổi già chứ!” Mặc dù chẳng mệt, nhưng ông chủ cũng bảo con trai xuống và ông leo lên cưỡi, để khỏi phải giải thích với họ.","cat":"fable"},{"id":"cha-va-con-gai","url":"https://truyencotich.top/doc-truyen/cha-va-con-gai","title":"Cha và con gái","summary":"Người cha nọ có 2 cô con gái. Ông vô cùng yêu quý 2 cô con gái của mình, luôn cầu xin ông trời cho các cô con gái sống hạnh phúc.","cat":"fable"},{"id":"vuong-quoc-khi","url":"https://truyencotich.top/doc-truyen/vuong-quoc-khi","title":"Vương quốc Khỉ","summary":"Có hai người nọ rất thích đi du lịch, một người chỉ nói thật còn một kẻ toàn nói dối. Một lần, họ cùng nhau đi du lịch đến vương quốc Khỉ.","cat":"fable"},{"id":"cu-meo-va-chau-chau","url":"https://truyencotich.top/doc-truyen/cu-meo-va-chau-chau","title":"Cú mèo và châu chấu","summary":"Cú mèo có thói quen luôn ngủ vào ban ngày. Vào lúc mặt trời lặn xuống, khi chút ánh sáng hoàng hôn còn lại phía chân trời đang dần tắt và bóng đêm từ từ bao phủ lấy cánh rừng, cú mèo mới bắt đầu xù lông, chớp mắt bay ra...","cat":"fable"},{"id":"bai-hoc-nho-doi","url":"https://truyencotich.top/doc-truyen/bai-hoc-nho-doi","title":"Bài học nhớ đời","summary":"Gấu lớn cứ bắt nạt Thỏ nhỏ. Chẳng chi cả mà nó cứ tóm lấy Thỏ rồi bạt tai đến nỗi một bên tai Thỏ vẹo hẳn xuống.","cat":"fable"},{"id":"lon-di-cho","url":"https://truyencotich.top/doc-truyen/lon-di-cho","title":"Lợn đi chợ","summary":"Ông chủ lùa một con Lợn béo, một con Dê và một con Cừu lên xe ngựa mang ra chợ...","cat":"fable"},{"id":"truyen-ngu-ngon-cay-but-chi","url":"https://truyencotich.top/doc-truyen/truyen-ngu-ngon-cay-but-chi","title":"Truyện ngụ ngôn cây bút chì","summary":"Một người thợ làm bút chì để nó qua 1 bên trước khi đặt vào hộp. “Có 5 điều ngươi cần nhớ trước khi ta đem ngươi ra thế giới bên ngoài”.","cat":"fable"},{"id":"con-nhim-va-bay-ran","url":"https://truyencotich.top/doc-truyen/con-nhim-va-bay-ran","title":"Con nhím và bầy rắn","summary":"Một ngày nọ, một con nhím lang thang đi tìm nơi trú ngụ. Nó tìm thấy gia đình nhà rắn đang sống trong một cái hang ấm áp và đã đề nghị được cho vào ở cùng.","cat":"fable"},{"id":"nha-vua-va-con-vet","url":"https://truyencotich.top/doc-truyen/nha-vua-va-con-vet","title":"Nhà vua và con vẹt","summary":"Nhà vua và hoàng tử mỗi người nuôi một con Vẹt. Hai con Vẹt ấy cũng là hai cha con.","cat":"fable"},{"id":"bung-va-cac-bo-phan-khac-cua-co-the","url":"https://truyencotich.top/doc-truyen/bung-va-cac-bo-phan-khac-cua-co-the","title":"Bụng và các bộ phận khác của cơ thể","summary":"Vào một ngày đẹp trời, các bộ phận của cơ thể bỗng nghĩ ra rằng chúng phải làm tất cả mọi việc trong khi cái bụng chẳng làm gi mà lại được ăn hết mọi thứ.","cat":"fable"},{"id":"su-tu-giac","url":"https://truyencotich.top/doc-truyen/su-tu-giac","title":"Sự tự giác","summary":"Xưa thật là xưa, có một ông Vua nọ, một hôm ông ta sai quân lính đặt một tảng đá lớn nằm chắn ngang đường đi. Xong, ông nấp vào một bụi cây gần đấy và theo dõi.","cat":"fable"},{"id":"cao-bi-roi-xuong-gieng","url":"https://truyencotich.top/doc-truyen/cao-bi-roi-xuong-gieng","title":"Cáo bị rơi xuống giếng","summary":"Có một con Cáo không may bị rơi xuống giếng. Nó cố gắng mãi để trèo lên mà không làm sao lên được...","cat":"fable"},{"id":"mat-bua","url":"https://truyencotich.top/doc-truyen/mat-bua","title":"Mất búa","summary":"Có một anh chàng tiều phu làm mất cây búa, anh ta nghi ngờ cậu bé nhà hàng xóm ăn cắp. Cho nên mỗi cử chỉ đi đứng của cậu bé anh ta đều nghĩ rằng đó là cử chỉ ăn cắp...","cat":"fable"},{"id":"hai-nguoi-du-khach-va-chiec-vi","url":"https://truyencotich.top/doc-truyen/hai-nguoi-du-khach-va-chiec-vi","title":"Hai người du khách và chiếc ví","summary":"Hai người khách bộ hành đang đi cùng nhau trên một con đường thì một người bỗng nhặt được một chiếc ví đầy cứng...","cat":"fable"},{"id":"co-gai-vat-sua","url":"https://truyencotich.top/doc-truyen/co-gai-vat-sua","title":"Cô gái vắt sữa","summary":"Ở trang trại nọ có một cô gái vắt sữa nhan sắc bình thường. Công việc hàng ngày của cô là cho bò sữa ăn và vắt sữa cho chúng...","cat":"fable"},{"id":"tho-va-nhen-nhen","url":"https://truyencotich.top/doc-truyen/tho-va-nhen-nhen","title":"Thỏ và Nhền Nhện","summary":"Thỏ và Nhền Nhện thường đi kiếm ăn cùng nhau, chúng phân phối rất ăn ý nên lần nào cũng được no say...","cat":"fable"},{"id":"lua-va-la","url":"https://truyencotich.top/doc-truyen/lua-va-la","title":"Lừa và La","summary":"Lừa và La cùng đi đường. Hai con cùng chở hàng bằng nhau. Lừa càu nhàu là La cũng mang bằng nó nhưng nhận phần thức ăn gấp đôi.","cat":"fable"},{"id":"nhung-con-hac-vang","url":"https://truyencotich.top/doc-truyen/nhung-con-hac-vang","title":"Những con hạc vàng","summary":"Ngày xưa, ở rất xa đây, cách Xứ Lắm Ruộng hàng nghìn ngày đường, có đàn chim hạc lớn lông vàng. Một hôm, Thần Ðại Linh gọi Latakini, con chim đầu đàn đến và nói rằng :","cat":"fable"},{"id":"dong-thi","url":"https://truyencotich.top/doc-truyen/dong-thi","title":"Đông thi","summary":"Thời Xuân Thu, ở nước Việt có một cô gái vô cùng xinh đẹp tên là Tây Thi. Nàng được người đời sau coi là một trong tứ đại mỹ nhân của Trung Quốc cổ đại.","cat":"fable"},{"id":"thay-tu-rom","url":"https://truyencotich.top/doc-truyen/thay-tu-rom","title":"Thầy tu rởm","summary":"Xưa có một con Sói rừng vừa hung ác vừa gian giảo. Một hôm nó nghe tin ở làng bên có một chú bé bị ốm liền nghĩ ra một kế độc để ăn thịt thằng bé...","cat":"fable"},{"id":"ong-lao-va-con-lua","url":"https://truyencotich.top/doc-truyen/ong-lao-va-con-lua","title":"Ông lão và con lừa","summary":"Ông lão nhà quê và đứa cháu bàn nhau đem con lừa ra hội chợ bán. Để con lừa khỏi mệt mỏi hầu có thể bán được giá cao, họ buộc chân lừa lại và hai ông cháu khệ nệ gánh con lừa đi.","cat":"fable"},{"id":"con-cho-xau-tinh","url":"https://truyencotich.top/doc-truyen/con-cho-xau-tinh","title":"Con chó xấu tính","summary":"Có một con chó nọ cứ hay lao vào tấn công bất cứ ai mà nó gặp, nhưng nó làm điều này rất bất ngờ đến mức không ai nghĩ là sẽ bị nó làm đau cho đến khi nó cắn vào gót chân họ.","cat":"fable"},{"id":"chim-ung-va-cao","url":"https://truyencotich.top/doc-truyen/chim-ung-va-cao","title":"Chim ưng và Cáo","summary":"Chim ưng và Cáo quyết định sống với nhau như bạn bè và thoả thuận ở gần nhau cho tình bạn thêm bền chặt nhờ tình láng giềng. Chim ưng xây tổ trên ngọn cây cao còn Cáo đào hang đẻ con ngay trong những bụi cây dưới đất...","cat":"fable"},{"id":"ba-chu-chuot-an-vung-mo","url":"https://truyencotich.top/doc-truyen/ba-chu-chuot-an-vung-mo","title":"Ba chú chuột ăn vụng mỡ","summary":"Trong một hang chuột có ba con chuột cùng chung sống. Một hôm, phát hiện dưới đáy liễn mỡ của nhà nọ vẫn còn một ít mỡ, chúng đều muốn nếm thử. Nhưng chiếc liễn quá cao, nếu đẩy nó rơi xuống thì mỡ sẽ đổ tung tóe...","cat":"fable"},{"id":"chay-nha-hang-xom","url":"https://truyencotich.top/doc-truyen/chay-nha-hang-xom","title":"Cháy nhà hàng xóm","summary":"Trong làng nọ có nhà bị cháy. Cả làng đổ ra, kẻ thùng, người chậu, ai nấy ra sức tìm cách dập đám cháy. Riêng có một người nhà ở ngay bên cạnh vẫn trùm chăn, bình chân như vại...","cat":"fable"},{"id":"bo-quan-ao-may-do","url":"https://truyencotich.top/doc-truyen/bo-quan-ao-may-do","title":"Bộ quần áo may đo","summary":"Tôi định đi may đo một bộ quần áo mới cho thật vừa vặn. Tôi đến cửa hàng may đo nổi tiếng với cái tên hấp dẫn: “Sẵn sàng phục vụ”.","cat":"fable"},{"id":"mua-xuong-ngua","url":"https://truyencotich.top/doc-truyen/mua-xuong-ngua","title":"Mua xương ngựa","summary":"Ngày xưa, có một ông vua rất thích ngựa thiên lý. Vua đã phái người đi khắp nơi để tìm kiếm, nhưng suốt 3 năm trôi qua mà vẫn không tìm được một con ngựa thiên lý nào...","cat":"fable"},{"id":"cuu-va-heo","url":"https://truyencotich.top/doc-truyen/cuu-va-heo","title":"Cừu và heo","summary":"Một hôm, một người chăn cừu phát hiện ra một con heo mập trên cánh đồng anh ta đang thả cừu cho ăn. Anh ta nhanh chóng bắt lấy heo, nó rống hết sức kêu eng éc vang cả cánh rừng khi người chăn cừu mới chạm tay vào nó...","cat":"fable"},{"id":"lao-ha-tien","url":"https://truyencotich.top/doc-truyen/lao-ha-tien","title":"Lão hà tiện","summary":"Ngày xửa ngày xưa, có một lão hà tiện yêu tiền hơn yêu cuộc sống của mình. Ông ta có một đứa con mười tuổi và rất nhiều nô bộc trong nhà...","cat":"fable"},{"id":"con-lua-va-nguoi-chu","url":"https://truyencotich.top/doc-truyen/con-lua-va-nguoi-chu","title":"Con lừa và người chủ","summary":"Một con lừa đang được chủ dong đi trên đường ở triền núi, bỗng dưng nó nảy ra ý nghĩ ngu ngốc là phải chọn lấy con đường đi cho riêng mình.","cat":"fable"},{"id":"doi-bo-va-cap-banh-xe","url":"https://truyencotich.top/doc-truyen/doi-bo-va-cap-banh-xe","title":"Đôi bò và cặp bánh xe","summary":"Một đôi bò ra sức kéo một chiếc xe chất đầy hàng qua một con đường quê lầy lội. Chúng phải lấy hết sức lực mới kéo nổi chiếc xe, nhưng không hề phàn nàn kêu ca...","cat":"fable"},{"id":"nhen-va-gian","url":"https://truyencotich.top/doc-truyen/nhen-va-gian","title":"Nhện và gián","summary":"Có con nhện và con gián cùng sống trong một ngôi nhà. Một hôm nhện bực bội bảo:","cat":"fable"},{"id":"ech-va-bo","url":"https://truyencotich.top/doc-truyen/ech-va-bo","title":"Ếch và Bò","summary":"Môt con bò đi xuống một đầm lầy đầy lau sậy để uống nước. Khi đưa chân xuống ao làm văng nước tung tóe, nó đạp bẹp một con ếch con xuống dưới buồn...","cat":"fable"},{"id":"lua-doi-lot-su-tu","url":"https://truyencotich.top/doc-truyen/lua-doi-lot-su-tu","title":"Lừa đội lốt Sư tử","summary":"Có một con Lừa luôn tự cho mình là thông minh. Nó ao ước làm được một chuyện kinh thiên động địa.","cat":"fable"},{"id":"con-cao-kiem-an","url":"https://truyencotich.top/doc-truyen/con-cao-kiem-an","title":"Con cáo kiếm ăn","summary":"Một con cáo đi kiếm ăn, sau khi đi một hồi nó mừng rỡ vì phát hiện một chuồng gà, nó toan chui vào thì nhìn thấy hàng rào quá bé, không thể chui lọt với cái bụng quá to của mình.","cat":"fable"},{"id":"ga-go-va-nguoi-bay-chim","url":"https://truyencotich.top/doc-truyen/ga-go-va-nguoi-bay-chim","title":"Gà gô và người bẫy chim","summary":"Một người săn chim bắt được một con gà gô và chuẩn bị làm thịt nó.","cat":"fable"},{"id":"cai-bay-chuot","url":"https://truyencotich.top/doc-truyen/cai-bay-chuot","title":"Cái bẫy chuột","summary":"Cái bẫy chuột, tưởng chừng như chỉ có hại đến con chuột, nhưng không phải thế. Chắc chắn đấy! Hãy đọc câu truyện ngụ ngôn cực kì hay và thâm thúy sau, bạn sẽ biết, vì sao lại không phải thế?","cat":"fable"},{"id":"con-cao-va-cai-bong","url":"https://truyencotich.top/doc-truyen/con-cao-va-cai-bong","title":"Con cáo và cái bóng","summary":"Một con cáo tinh thần đang vui vẻ thèm ăn rời hang đi tìm mồi. Khi nó chạy, nắng chiều chiếu xuống trên lưng nó làm bóng nó đổ dài trên mặt đất, nhìn y như là nó cao lớn hơn mọi hôm gấp nhiều lần.","cat":"fable"},{"id":"cao-trong-dua-trong-dau","url":"https://truyencotich.top/doc-truyen/cao-trong-dua-trong-dau","title":"Cáo trồng dưa, trồng đậu","summary":"Mùa xuân tới, cáo tới mảnh vườn nhỏ ném mấy hạt đậu, lấy chân khỏa đất lên trong mưa xuân lun phun, ấm áp...","cat":"fable"},{"id":"de-con-nhanh-tri","url":"https://truyencotich.top/doc-truyen/de-con-nhanh-tri","title":"Dê con nhanh trí","summary":"Trong ngôi nhà kia có Dê mẹ và một chú Dê con. Một hôm, trước khi ra đồng cỏ, Dê mẹ dặn Dê con:","cat":"fable"},{"id":"tro-dua-cua-nhen-nhen","url":"https://truyencotich.top/doc-truyen/tro-dua-cua-nhen-nhen","title":"Trò đùa của nhền nhện","summary":"Một con Khỉ được mời tới nhà vị hôn thê chơi, nó vui vẻ mời cả bạn Nhện Tây Ðạt cùng đi. Khỉ ta rất ưa bóng bẩy, trước khi đi nó đeo một đôi mắt giả vừa to vừa sáng vào.","cat":"fable"},{"id":"dieu-hau-va-cu-meo","url":"https://truyencotich.top/doc-truyen/dieu-hau-va-cu-meo","title":"Diều hâu và cú mèo","summary":"Diều Hâu và Cú Mèo lúc nào cũng gây sự với nhau, không con nào chịu nhịn con nào. Một hôm, chúng quyết định sẽ không gây sự với nhau nữa, mà sẽ thân thiện với nhau, từ kẻ thù trở thành bạn tốt và hứa sẽ không ăn thịt con cái của nhau.","cat":"fable"},{"id":"nguoi-ban-tham-lam","url":"https://truyencotich.top/doc-truyen/nguoi-ban-tham-lam","title":"Người bạn tham lam","summary":"Hai người đang đi bộ cùng nhau trên một con đường thì một người bỗng nhặt được một cái túi tiền đầy cứng.Người nhặt được túi tiền nói:Ngay khi đó họ nghe thấy tiếng quát to:Dân làng xúm lại bắt người nhặt được túi tiền và dẫn về làng để xử tội...","cat":"fable"},{"id":"bo-ngua-bat-ve-sau-chim-se-rinh-sau-lung","url":"https://truyencotich.top/doc-truyen/bo-ngua-bat-ve-sau-chim-se-rinh-sau-lung","title":"Bọ ngựa bắt ve sầu, chim sẻ rình sau lưng","summary":"Thời Xuân Thu, Ngô Vương là một vị vua vô cùng ngang ngược, các vị đại thần đều khó mà thuyết phục được ông.","cat":"fable"},{"id":"truyen-ngu-ngon-ve-loai-vat","url":"https://truyencotich.top/doc-truyen/truyen-ngu-ngon-ve-loai-vat","title":"Truyện ngụ ngôn về loài vật","summary":"Hươu non bị chết tươi vì ăn phải bã độc. Sư tử và Gấu nhìn thấy xác Hươu liền tranh nhau miếng mồi. Hai con mãi đánh nhau nên không thấy Cáo cũng mò đến...","cat":"fable"},{"id":"ba-gio-khoai-lang","url":"https://truyencotich.top/doc-truyen/ba-gio-khoai-lang","title":"Ba giỏ khoai lang","summary":"Ngày xưa, có một lần Gấu, Thỏ và Khỉ rủ nhau cùng tới thăm nhà bác Dê. Trước khi về, bác Dê bảo chúng - Ðây là ba giỏ khoai lang, mỗi cháu mang về một giỏ. Bằng giờ sang năm, đưa lại cho bác số khoai lang cũng như thế...","cat":"fable"},{"id":"mot-cau-tra-loi","url":"https://truyencotich.top/doc-truyen/mot-cau-tra-loi","title":"Một câu trả lời","summary":"Một hôm, chú Gà Con cứ bám riết lấy anh Gà Trống to tướng mà hỏi: – Tại sao mỏ chị Diệc dài và hai chân chị ấy cao kều, còn của em lại nhỏ xíu ?","cat":"fable"},{"id":"chim-ung-con-dieu-va-dan-bo-cau","url":"https://truyencotich.top/doc-truyen/chim-ung-con-dieu-va-dan-bo-cau","title":"Chim ưng, con diều và đàn bồ câu","summary":"Sự xuất hiện thường xuyên của một con diều làm cho đàn bồ câu rất hoảng sợ nên chúng đã gọi chim ưng đến bảo vệ cho mình...","cat":"fable"},{"id":"con-ngua-luoi-bieng","url":"https://truyencotich.top/doc-truyen/con-ngua-luoi-bieng","title":"Con ngựa lười biếng","summary":"Có một người nuôi hai con ngựa. Một hôm, người chủ ngựa đặt những đồ vật buôn bán lên hai chiếc xe ngựa, mỗi một con ngựa kéo một xe. Trên đường, một con ngựa tụt dần lại phía sau...","cat":"fable"},{"id":"rua-va-bo-cap","url":"https://truyencotich.top/doc-truyen/rua-va-bo-cap","title":"Rùa và bọ cạp","summary":"Ngày xửa, ngày xưa Rùa và Bọ Cạp kết bạn với nhau. Một lần chúng rủ nhau đi chu du.","cat":"fable"},{"id":"cau-chuyen-nhung-ngon-tay","url":"https://truyencotich.top/doc-truyen/cau-chuyen-nhung-ngon-tay","title":"Câu chuyện những ngón tay","summary":"Một hôm, những ngón tay tranh luận với nhau xem những ngón nào là quan trọng hơn cả. Thoạt tiên, ngón tay giữa nói:","cat":"fable"},{"id":"truyen-loai-vat","url":"https://truyencotich.top/doc-truyen/truyen-loai-vat","title":"Truyện loài vật","summary":"Một hôm, Hươu gặp lại kẻ thù cũ của nó là con Cáo đang bị mắc bẫy nằm lăn giữa rừng. Hươu mon men đến gần, giơ cao chân giận dữ nện mạnh cuống đầu Cáo...","cat":"fable"},{"id":"nang-cong-chua-mau-lon","url":"https://truyencotich.top/doc-truyen/nang-cong-chua-mau-lon","title":"Nàng Công Chúa Mau Lớn","summary":"Ngày xưa có một ông vua sinh được một nàng công chúa nhỏ xíu. Nhà vua yêu quý con gái lắm và mong cho cô lớn ngay lập tức, biết chạy chơi trong cung điện.","cat":"fable"},{"id":"toi-muon-huc","url":"https://truyencotich.top/doc-truyen/toi-muon-huc","title":"Tôi muốn húc","summary":"Đó là một chú Dê con với một đôi sừng bé tẹo tèo teo nhưng lại hay cà khịa. Chú chẳng biết làm gì nên cứ hay di cà khịa với mọi người...","cat":"fable"},{"id":"mot-ke-hom-hinh","url":"https://truyencotich.top/doc-truyen/mot-ke-hom-hinh","title":"Một kẻ hợm hĩnh","summary":"Anh Gà Trống bay lên đậu trên hàng rào rồi rướn cao đầu lên trời...","cat":"fable"},{"id":"vit-va-ca-ro","url":"https://truyencotich.top/doc-truyen/vit-va-ca-ro","title":"Vịt và Cá rô","summary":"Cá rô lóc lách lên bờ, đến khi nước rút, bị mắc cạn trên một vũng khô. Tưởng mình sắp chết, may mắn thấy bầy vịt đi qua, Cá rô bèn năn nỉ:","cat":"fable"},{"id":"tho-thay-rang","url":"https://truyencotich.top/doc-truyen/tho-thay-rang","title":"Thỏ thay răng","summary":"Trong một khu rừng nọ có một chú Thỏ rất nhát gan. Cứ nhìn thấy bóng dáng của Cáo là Thỏ vội quay đầu bỏ chạy.","cat":"fable"},{"id":"cu-va-chim-gay","url":"https://truyencotich.top/doc-truyen/cu-va-chim-gay","title":"Cú và chim Gáy","summary":"Một con chim Gáy gặp một con Cú Mèo.","cat":"fable"},{"id":"chi-meo-nhan-ho","url":"https://truyencotich.top/doc-truyen/chi-meo-nhan-ho","title":"Chị Mèo nhận họ","summary":"Nghe người ta nói Hổ và Báo cũng thuộc họ nhà Mèo, chị Mèo hí hửng lắm:","cat":"fable"},{"id":"cho-nha-va-cho-soi","url":"https://truyencotich.top/doc-truyen/cho-nha-va-cho-soi","title":"Chó nhà và chó sói","summary":"Dưới ánh trăng, Sói đói mèm đánh hơi khắp nơi để tìm đồ ăn, rồi nó cũng gặp một con Chó nhà trông rất oai vệ. Sói nói:","cat":"fable"},{"id":"nguoi-tieu-phu-va-than-hermes","url":"https://truyencotich.top/doc-truyen/nguoi-tieu-phu-va-than-hermes","title":"Người tiều phu và thần Hermes","summary":"Một hôm, người tiều phu ra bờ sông chặt củi. Bỗng anh ta bị tuột tay, làm chiếc rìu rơi tõm xuống sông.","cat":"fable"},{"id":"cau-be-va-buc-tranh-su-tu","url":"https://truyencotich.top/doc-truyen/cau-be-va-buc-tranh-su-tu","title":"Cậu bé và bức tranh sư tử","summary":"Ngày xửa ngày xưa, có một người thợ săn cùng đứa con trai độc nhất sống ở ven một khu rừng đẹp. Người thợ săn vô cùng thương yêu con mình nên luôn lo lắng thú hoang sẽ hại cậu bé.","cat":"fable"},{"id":"tinh-lam","url":"https://truyencotich.top/doc-truyen/tinh-lam","title":"Tính lầm","summary":"Ngày xửa ngày xưa có một anh Sói lười. Nhà cửa của anh, anh chẳng bao giờ quét dọn, sửa sang.","cat":"fable"},{"id":"tho-va-em-be","url":"https://truyencotich.top/doc-truyen/tho-va-em-be","title":"Thỏ và em bé","summary":"Đến một khu rừng, Thỏ gặp một em bé chăn trâu đang ngồi khóc. Thỏ động lòng thương, bước lại gần, hỏi:","cat":"fable"},{"id":"rua-va-vit","url":"https://truyencotich.top/doc-truyen/rua-va-vit","title":"Rùa và vịt","summary":"Rùa đi đến đâu cũng cõng ngôi nhà theo trên lưng. Mặc dù đã cố gắng hết sức, nhưng nó cũng không thể ra được khỏi nhà. Người ta bảo rằng thần Jupiter phạt nó như thế, vì nó là kẻ lười biếng lúc nào cũng nằm ở nhà...","cat":"fable"},{"id":"ten-trom-va-ba-me","url":"https://truyencotich.top/doc-truyen/ten-trom-va-ba-me","title":"Tên trộm và bà mẹ","summary":"Có một đứa trẻ từ nhỏ đã thích ăn trộm. Một hôm, nó đi học về, trong cặp có thêm một chiếc bảng học sinh.","cat":"fable"},{"id":"soi-va-de","url":"https://truyencotich.top/doc-truyen/soi-va-de","title":"Sói và Dê","summary":"Một con Dê bị tụt phía sau đàn, bị con Sói theo đuổi sát. Dê quay lại, nói với Sói: Thưa ngài, tôi biết thân phận mình phải hiến dâng cho ngài. Nhưng để ngài thưởng thức món ăn đựơc ngon, ngài hãy thổi sáo và tôi múa nhảy cho mà xem...","cat":"fable"},{"id":"chim-son-ca","url":"https://truyencotich.top/doc-truyen/chim-son-ca","title":"Chim Sơn Ca","summary":"Bụi trường xuân vừa ra hoa, Sơn Ca lập tức đoán ra ngay cái nguy cơ rình rập loài có lông vũ. Tập hợp các loài chim lại, nó lên tiếng thuyết phục chúng:","cat":"fable"},{"id":"cuoc-kiem-nghiem","url":"https://truyencotich.top/doc-truyen/cuoc-kiem-nghiem","title":"Cuộc kiểm nghiệm","summary":"Có một anh Vẹt sau khi học được vài ba tiếng Người thì lấy làm hãnh diện và tự phụ lắm. Anh ta tuyên bố:","cat":"fable"},{"id":"nai-va-cho-soi","url":"https://truyencotich.top/doc-truyen/nai-va-cho-soi","title":"Nai và chó sói","summary":"Một hôm, tất cả những sói trong vùng tụ tập trên bờ con sông Nát để trao đổi tin tức và tiêu khiển. Có mặt ở đó những sói con, những sói trưởng thành lớn khỏe, một vài sói già cô độc như Sói Xám.","cat":"fable"},{"id":"cao-va-de-con","url":"https://truyencotich.top/doc-truyen/cao-va-de-con","title":"Cáo và dê con","summary":"Ngày xưa có một chú dê con đang nhú sừng nghĩ rằng mình đã lớn và có thể tự lo cho mình được. Thế nên vào một buổi chiều, khi đàn dê từ đồng cỏ bắt đầu quay về chuồng thì dê mẹ gọi, nhưng dê con chẳng thèm nghe và cứ kiếm cỏ non gặm tiếp.","cat":"fable"},{"id":"cao-cut-duoi","url":"https://truyencotich.top/doc-truyen/cao-cut-duoi","title":"Cáo cụt đuôi","summary":"Một con Cáo bị mắc bẫy, sau nhiều lần giật mạnh đau đớn vùng vẫy thoát ra được, bèn chạy đi. Nhưng nó phải bỏ lại cái đuôi đẹp đẽ của nó lại trong bẫy...","cat":"fable"},{"id":"dai-bang-va-con-chim-se","url":"https://truyencotich.top/doc-truyen/dai-bang-va-con-chim-se","title":"Đại Bàng và Con Chim Sẻ","summary":"Ở khu rừng nọ có một con đại bàng huênh hoang hợm hĩnh . Gặp bất cứ con chim nào , đại bàng cũng khoe khoang rằng nó là chúa tể của các loài chim , rằng nó khỏe nhất , kêu to nhất , bay cao nhất .","cat":"fable"},{"id":"than-mercury-va-bac-tieu-phu","url":"https://truyencotich.top/doc-truyen/than-mercury-va-bac-tieu-phu","title":"Thần Mercury và Bác Tiều Phu","summary":"Một Bác Tiều Phu nghèo chặt cây gần một vũng nước sâu trong rừng. Trời đã gần tối và Bác Tiều cũng đã mệt mỏi.","cat":"fable"},{"id":"nguoi-xen-long-cuu","url":"https://truyencotich.top/doc-truyen/nguoi-xen-long-cuu","title":"Người xén lông cừu","summary":"Bố mẹ của Molis để lại cho cậu rất nhiều của cải: một lâu đài đẹp đẽ, ruộng đất phì nhiêu, hàng nghìn con cừu và mấy trăm cửa tiệm. Số tài sản này đủ để cho cậu hưởng thụ nhiều đời...","cat":"fable"},{"id":"lua-va-hai-cau","url":"https://truyencotich.top/doc-truyen/lua-va-hai-cau","title":"Lừa và Hải Cẩu","summary":"Một cái cây đẹp mọc ngay giữa đồng. Bác Lừa ta chạy băng đồng, mải nhìn ngang nhìn ngửa nên đâm bổ vào, nẩy đom đóm mắt.","cat":"fable"},{"id":"an-gio","url":"https://truyencotich.top/doc-truyen/an-gio","title":"Ăn giỗ","summary":"Một hôm, họ nhà Khỉ có giỗ nên mời Heo và Bò tới nhà ăn cỗ.","cat":"fable"},{"id":"lua-va-ho","url":"https://truyencotich.top/doc-truyen/lua-va-ho","title":"Lừa và hổ","summary":"Thời xưa, ở vùng Quý Châu không có Lừa. Có một người hay làm việc tốt đã chở một con lừa đến đây bằng thuyền.","cat":"fable"},{"id":"gia-tri-thuc-su","url":"https://truyencotich.top/doc-truyen/gia-tri-thuc-su","title":"Giá trị thực sự","summary":"Một lần nọ, cáo và báo cãi nhau xem ai đẹp hơn. Báo khoe từng cái đốm trên khắp bộ da của mình. Còn cáo vốn tự hào về trí khôn của nó hơn là vẻ ngoài, sau cùng đã cắt ngang sự khoe khoang của báo bằng một câu nói...","cat":"fable"},{"id":"ve-dep","url":"https://truyencotich.top/doc-truyen/ve-dep","title":"Vẻ đẹp","summary":"Gấu và Sói ngồi nói chuyện trên trời dưới đất. Cạnh đó có một chị Bướm đang bay lượn. Chị bay từ cây này sang cây khác. Nhìn thấy chị Bướm, bác Gấu đưa mắt ngắm nghía...","cat":"fable"},{"id":"than-gio-va-mat-troi","url":"https://truyencotich.top/doc-truyen/than-gio-va-mat-troi","title":"Thần Gió và Mặt Trời","summary":"Sau khi gây ra thiên tai, bão táp làm đổ sập nhà cửa, cây cối, Thần Gió càng lúc càng tỏ ra ngạo mạn. Một hôm Thần Gió tranh cãi với Mặt Trời xem ai là kẻ mạnh nhất.","cat":"fable"},{"id":"de-con-va-cao","url":"https://truyencotich.top/doc-truyen/de-con-va-cao","title":"Dê con và cáo","summary":"Một con dê con được người chăn dê để lại trên mái lá của chuồng dê để tránh cho nó khỏi bị nguy hiểm bởi thú dữ. Dê con đang chạy nhảy ra gần rìa mái lá thì bỗng nó nhìn thấy một con cáo và bắt đầu chế giễu cáo...","cat":"fable"},{"id":"sang-ba-toi-bon","url":"https://truyencotich.top/doc-truyen/sang-ba-toi-bon","title":"Sáng ba tối bốn","summary":"Ở Tống Quốc có một người rất thích nuôi khỉ, nên người ta đặt cho anh ta cái tên là Vượn Công. Anh ta nuôi hàng đàn khỉ, biết rõ tâm tính từng con, đàn khỉ cũng hiểu được tiếng nói của chủ mình.","cat":"fable"},{"id":"chu-be-chan-cuu-va-con-cao","url":"https://truyencotich.top/doc-truyen/chu-be-chan-cuu-va-con-cao","title":"Chú bé chăn cừu và con cáo","summary":"Một chú bé chăn cừu cho chủ thả cừu gần một khu rừng rậm cách làng không xa lắm. Chăn cừu được ít lâu, chú cảm thấy cuộc đời chăn cừu thực nhàm chán.","cat":"fable"},{"id":"bay-tho","url":"https://truyencotich.top/doc-truyen/bay-tho","title":"Bầy thỏ","summary":"Trong một khu rừng sâu, xanh mát và yên tĩnh có một bầy thỏ đang trú ngụ.","cat":"fable"},{"id":"lua-va-ngua","url":"https://truyencotich.top/doc-truyen/lua-va-ngua","title":"Lừa và ngựa","summary":"Có chú Lừa đi cùng một con Ngựa trông sang trọng bảnh bao lắm. Trên lưng ngựa chỉ có bộ yên thồ hàng, còn trên lưng Lừa lại chồng chất hàng hoá nặng đến mức nó không chịu nổi...","cat":"fable"},{"id":"ech-va-chuot","url":"https://truyencotich.top/doc-truyen/ech-va-chuot","title":"Ếch Và Chuột","summary":"Một con chuột nhắt phiêu lưu chạy dọc theo bờ ao ở đó có một con ếch sinh sống...","cat":"fable"},{"id":"chim-khach-va-qua","url":"https://truyencotich.top/doc-truyen/chim-khach-va-qua","title":"Chim Khách và Quạ","summary":"Chim Khách đến đậu ở cổng một nhà kia, kêu lên mấy tiếng. Chủ nhà nghe thấy, mừng rỡ bảo con: Này, Chim Khách kêu là nhà sắp có khách quý đấy...","cat":"fable"},{"id":"chu-khi-luu-manh","url":"https://truyencotich.top/doc-truyen/chu-khi-luu-manh","title":"Chú khỉ lưu manh","summary":"Thuở xa xưa, có một con Mèo và một con Khỉ chơi với nhau rất thân. Lúc nào chúng cũng đùa nghịch chọc ghẹo nhau.","cat":"fable"},{"id":"ong-va-than-jupiter","url":"https://truyencotich.top/doc-truyen/ong-va-than-jupiter","title":"Ong và thần Jupiter","summary":"Một con ong ở núi Hymettus, là ong chúa của đàn, bay lên đỉnh Olympus để dâng thần Jupiter một ít mật mà nó đã lấy được.","cat":"fable"},{"id":"ga-keo-kiet","url":"https://truyencotich.top/doc-truyen/ga-keo-kiet","title":"Gã Keo Kiệt","summary":"Một gã keo kiệt chôn vàng ở một nơi bí mật trong vườn nhà. Hàng ngày, gã ra chỗ đó, đào vàng lên và đếm từng thỏi một để kiểm tra xem có còn đủ hay không...","cat":"fable"},{"id":"nguoi-dan-ba-xau-xi","url":"https://truyencotich.top/doc-truyen/nguoi-dan-ba-xau-xi","title":"Người đàn bà xấu xí","summary":"Ngày xửa ngày xưa, có một người đàn bàn xấu xí đến nỗi ngay một con quỷ khốn khổ nhất, xấu xa nhất cũng không màng...","cat":"fable"},{"id":"mon-qua-cho-nguoi-an-xin","url":"https://truyencotich.top/doc-truyen/mon-qua-cho-nguoi-an-xin","title":"Món quà cho người ăn xin","summary":"Ngày xưa, có hai người ăn xin đã nhận được món quà: một chiếc cần câu và một rổ cá lớn. Một người lấy rổ cá lơn và một người còn lại thì đã lấy chiếc cần câu, sau đó hai người chia tay nhau rời đi...","cat":"fable"},{"id":"noi-com-ban","url":"https://truyencotich.top/doc-truyen/noi-com-ban","title":"Nồi cơm bẩn","summary":"Khi một học sinh của Khổng Tử đang nấu cháo, anh ta phát hiện có một thứ bẩn nào đó đã rơi vào nồi cháo. Anh ta vội vàng dùng muỗng múc nó ra, nhưng đột nhiên anh ta nghĩ, có một hạt cơm hạt gạo cũng không dễ dàng gì...","cat":"fable"},{"id":"con-ech-bi-diec","url":"https://truyencotich.top/doc-truyen/con-ech-bi-diec","title":"Con ếch bị điếc","summary":"Có một đàn ếch thi xem ai có thể leo lên đỉnh của một cái tháp. Trò chơi bắt đầu, một nhóm ếch nhìn thấy tháp cao chót vót liền đưa ra nhiều ý kiến &quot;Thật sự quá là khó! Chúng ta chắc chắn không thể làm được&quot;...","cat":"fable"},{"id":"muoi-va-su-tu","url":"https://truyencotich.top/doc-truyen/muoi-va-su-tu","title":"Muỗi và Sư tử","summary":"Một con Muỗi rất muốn trở thành Chúa sơn lâm, bèn nghĩ: “Trong khu rừng này Sư tử là Chúa sơn lâm, như vậy chắc hẳn là người mạnh nhất. Nếu mình có thể đánh bại nó, thế thì mình có thể đường đường chính chính làm Chúa sơn lâm rồi”...","cat":"fable"},{"id":"con-luon-va-con-ca-ro","url":"https://truyencotich.top/doc-truyen/con-luon-va-con-ca-ro","title":"Con Lươn và con Cá Rô","summary":"Xưa con Lươn và con Cá Rô là một đôi bạn thân, thường năng đi lại với nhau. Một hôm, Rô đi kiếm ăn, qua chỗ Lươn ở, thấy Lươn đương nằm chơi trong lờ...","cat":"fable"},{"id":"than-lan-trom-chan","url":"https://truyencotich.top/doc-truyen/than-lan-trom-chan","title":"Thằn lằn trộm chân","summary":"Xưa có hai vợ chồng con Thằn lằn cùng ở dưới nước với hai vợ chồng con Lươn. Mà Lươn thì có chân, Thằn lằn thì không có. Thằn lằn vẫn định lấy trộm chân của Lươn, nhưng chỉ sợ nó đánh, không dám lấy...","cat":"fable"},{"id":"cong-va-ga","url":"https://truyencotich.top/doc-truyen/cong-va-ga","title":"Công và Gà","summary":"Xưa có một nhà nuôi một con Công, lấy làm trân trọng lắm. Nhà ấy ngày nào cũng bỏ ra bao nhiêu tiền mua ngô, mua gạo cho Công ăn. Còn đàn Gà, trước kia chăn nuôi bao nhiêu thì bây giờ hình như lại muốn bỏ mặc...","cat":"fable"},{"id":"con-cong-va-lang-chim","url":"https://truyencotich.top/doc-truyen/con-cong-va-lang-chim","title":"Con Công và làng chim","summary":"Một hôm làng chim hội họp cùng nhau nhất định cất một người lên làm đàn anh để chủ trương mọi việc trong làng...","cat":"fable"},{"id":"coc-thi-tai-voi-voi","url":"https://truyencotich.top/doc-truyen/coc-thi-tai-voi-voi","title":"Cóc thi tài với Voi","summary":"Một hôm, Cóc gặp Voi, đánh đố Voi rằng: &quot;Tôi với anh, hai ta thử tài nhau xem nào&quot;...","cat":"fable"},{"id":"ba-rua-ay","url":"https://truyencotich.top/doc-truyen/ba-rua-ay","title":"Bà Rùa ấy","summary":"Bà Rùa ấy đã chọn một cái nghề mà công việc có thể nhởn nhơ: nghề khâu vá mướn. Một buổi sáng chủ nhật, bà Rùa đang nhấm nháp con Sên non, bỗng nghe tiếng chuông reo bên nhà bác Thỏ láng giếng...","cat":"fable"},{"id":"su-tu-va-nguoi-tho-rung","url":"https://truyencotich.top/doc-truyen/su-tu-va-nguoi-tho-rung","title":"Sư Tử và người thợ rừng","summary":"Sư Tử lại đi về phía rừng, đủng đỉnh bước một, không nôn nóng như lúc nãy nữa. Đến cửa rừng, Sư Tử thấy một cái xe chất đầy củi và gần đấy có hai con trâu mộng, dáng to lớn...","cat":"fable"},{"id":"bo-long-muon","url":"https://truyencotich.top/doc-truyen/bo-long-muon","title":"Bộ lông mượn","summary":"Vua loài chim là Phượng Hoàng ăn mừng sinh nhật. Trăm loài chim kéo nhau đến chúc mừng. Con nào con nấy lông óng mượt, lộng lẫy. Chỉ chú chim Cút là nghèo nàn, mặc bộ nâu sồng xơ xác...","cat":"fable"},{"id":"lang-chim-khuyet-chan-ly-truong","url":"https://truyencotich.top/doc-truyen/lang-chim-khuyet-chan-ly-truong","title":"Làng chim khuyết chân lý trưởng","summary":"Làng chim khuyết chân Lý trưởng. Quan huyện bèn gọi làng chim lên, truyền phải bầu một người đủ tư cách làm việc quan....","cat":"fable"},{"id":"bo-chet-va-nguoi-dan-ong","url":"https://truyencotich.top/doc-truyen/bo-chet-va-nguoi-dan-ong","title":"Bọ chét và người đàn ông","summary":"Một con bọ chét cắn một người đàn ông cho đến khi anh ta không thể chịu đựng thêm được nữa. Anh ta tìm khắp người và cuối cùng cũng tóm được nó...","cat":"fable"},{"id":"con-vet-a-ra","url":"https://truyencotich.top/doc-truyen/con-vet-a-ra","title":"Con vẹt A-ra","summary":"Trưởng phòng Ni-rép đã có đủ mọi thứ. Trong nhà có lẽ chỉ còn thiếu mỗi con vẹt.","cat":"fable"},{"id":"cho-va-nguoi-dau-bep","url":"https://truyencotich.top/doc-truyen/cho-va-nguoi-dau-bep","title":"Chó và người đầu bếp","summary":"Một người nhà giàu mở tiệc lớn, anh ta mời nhiều bạn bè và những người quen biết. Nhân dịp này con chó của anh ta cũng tự cho mình quyền được mời một con chó lạ là bạn nó...","cat":"fable"},{"id":"suy-bung-ta-ra-bung-nguoi","url":"https://truyencotich.top/doc-truyen/suy-bung-ta-ra-bung-nguoi","title":"Suy bụng ta ra bụng người","summary":"Có con quạ tha được xác một con chuột thối về ngồi trên cây rỉa mồi. Diều từ trên cao ngó thấy liền hạ cánh xuống...","cat":"fable"},{"id":"san-long-giup-do","url":"https://truyencotich.top/doc-truyen/san-long-giup-do","title":"Sẵn lòng giúp đỡ","summary":"Chạy khắp rừng thấm mệt, anh Nai muốn nghỉ ngơi chút đỉnh. Anh nằm xuống bãi cỏ rồi nhờ Thỏ:","cat":"fable"},{"id":"kho-bau","url":"https://truyencotich.top/doc-truyen/kho-bau","title":"Kho báu","summary":"Xưa có một chàng thích giàu có, cứ luôn miệng nói: Nếu như tôi có nhiều của thì tốt quá!","cat":"fable"},{"id":"gio-bac-va-mat-troi","url":"https://truyencotich.top/doc-truyen/gio-bac-va-mat-troi","title":"Gió Bắc Và Mặt Trời","summary":"Gió Bắc và Mặt Trời cãi nhau ai cũng cho mình là người mạnh mẽ hơn. Khi họ đang cãi nhau, sức nóng tỏa ra hầm hập và gió nổi lên ào ào, lúc đó có một người khách lạ đi trên đường mặc một chiếc áo khoác.","cat":"fable"},{"id":"nhung-ngon-tay","url":"https://truyencotich.top/doc-truyen/nhung-ngon-tay","title":"Những ngón tay","summary":"Một hôm, những ngón tay tranh luận với nhau xem những ngón nào là quan trọng hơn cả. Thoạt tiên, ngón tay giữa nói:","cat":"fable"},{"id":"cua-me-va-cua-con","url":"https://truyencotich.top/doc-truyen/cua-me-va-cua-con","title":"Cua mẹ và cua con","summary":"Trên một bãi biển ấm áp, có một con cua mẹ và cua con...","cat":"fable"},{"id":"gau-va-dan-ong","url":"https://truyencotich.top/doc-truyen/gau-va-dan-ong","title":"Gấu và đàn ong","summary":"Gấu cứ chúi mũi vào khúc gỗ để cẩn thận quan sát xem bầy ong có đang ở nhà hay không. Ngay lúc đó, bầy ong từ cánh đồng hoa trở về mang theo rất nhiều mật.","cat":"fable"},{"id":"voi-ngua-dua-nhau","url":"https://truyencotich.top/doc-truyen/voi-ngua-dua-nhau","title":"Voi ngựa đua nhau","summary":"Xưa con Ngựa thấy con Voi chậm chạp có ý khinh lờn. Ngựa đòi thi tài với Voi xem ai chạy giỏi.","cat":"fable"},{"id":"cheo-beo-va-ac-la","url":"https://truyencotich.top/doc-truyen/cheo-beo-va-ac-la","title":"Chèo bẻo và Ác Là","summary":"Ngày xưa, cứ theo sổ bạ làng chim, thì Ác là vốn là bậc hương hào ở trên, oai quyền hách dịch, còn Chèo bẻo thì chỉ là một cùng đinh ở mãi dưới, không chút địa vị nào.","cat":"fable"},{"id":"con-ngong-de-trung-vang","url":"https://truyencotich.top/doc-truyen/con-ngong-de-trung-vang","title":"Con ngỗng đẻ trứng vàng","summary":"Hai vợ chồng nhà nọ có một tài sản rất quý, đó là một con ngỗng mà mỗi ngày nó đẻ ra một quả trứng vàng.","cat":"fable"},{"id":"doc-truyen-om-cay-doi-tho","url":"https://truyencotich.top/doc-truyen/doc-truyen-om-cay-doi-tho","title":"Đọc truyện Ôm cây đợi thỏ","summary":"Một người nước Tống đang cày ruộng. Giữa ruộng có một cây to. Có con thỏ đồng từ đâu chạy lại đâm vào gốc cây, đập đầu chết.","cat":"fable"},{"id":"to-100-do-la-duoi-san-truong","url":"https://truyencotich.top/doc-truyen/to-100-do-la-duoi-san-truong","title":"Tờ 100 đô-la dưới sân trường","summary":"Một hôm vị giáo sư chuyên giảng thuyết EMT cùng đi dạo với một cậu sinh viên MBA trẻ tuổi.","cat":"fable"},{"id":"ngon-giao-dam-loi-noi-doi","url":"https://truyencotich.top/doc-truyen/ngon-giao-dam-loi-noi-doi","title":"Ngọn giáo đâm lời nói dối","summary":"Ngày xưa, có ba chàng trai sống ở ba vùng Wakayama, Nagoya và Mito gặp nhau, và cùng khoe khoang về nơi ở của mình.","cat":"fable"},{"id":"tang-da-giua-duong","url":"https://truyencotich.top/doc-truyen/tang-da-giua-duong","title":"Tảng đá giữa đường","summary":"Ngày xưa có một vị vua, ông lấy một hòn đá to và ông để nó cản lối đi trên một con đường. Sau đó ông núp vào một chỗ kín để quan sát xem có người nào dời hòn đá to ấy đi chỗ khác hay không.","cat":"fable"},{"id":"khi-va-rua","url":"https://truyencotich.top/doc-truyen/khi-va-rua","title":"Khỉ và Rùa","summary":"Ðể chào mừng một ngày lễ lớn, một hôm Khỉ ta mời tất cả bạn bè đến nhà chơi. Rùa đen cũng đến. Ðầu tiên Khỉ ta nói lời chúc mừng sau đó mời các bạn vào bàn tiệc. Chúng ăn uống thoả thích, hết chạm cốc lại gắp thịt rất chi là ồn ào.","cat":"fable"},{"id":"hai-con-ga-trong","url":"https://truyencotich.top/doc-truyen/hai-con-ga-trong","title":"Hai con gà trống","summary":"Có hai con gà cùng một gà mẹ sinh ra và nuôi dưỡng. Khi lớn lên, đủ lông đủ cánh trở thành hai con gà trống, chúng lại hay cãi vã nhau. Con nào cũng tự cho mình đẹp đẽ, oai phong hơn, có quyền làm Vua của Nông Trại.","cat":"fable"},{"id":"con-lua-va-cai-ao","url":"https://truyencotich.top/doc-truyen/con-lua-va-cai-ao","title":"Con lừa và cái áo","summary":"Lão nhà giàu nọ ra chợ mua được một con Lừa rất khỏe. Lão liền chất lên lưng nó bao nhiêu hàng hóa và trở về làng. Dọc đường thấy sẵn củi, lão lại chặt luôn mấy vác buộc vào hai bên sườn nó.","cat":"fable"},{"id":"tai-ong-that-ma","url":"https://truyencotich.top/doc-truyen/tai-ong-that-ma","title":"Tái ông thất mã","summary":"Xưa có ông lão tên là Tái Ông sinh sống ở vùng biên giới phía bắc Trung Quốc. Ông rất giỏi việc nuôi ngựa. Ngày kia ngựa của Tái Ông xổng chuồng chạy sang nước Hồ lân cận. Hàng xóm láng giềng hay tin đã đến an ủi...","cat":"fable"},{"id":"ngu-ong-dac-loi","url":"https://truyencotich.top/doc-truyen/ngu-ong-dac-loi","title":"Ngư ông đắc lợi","summary":"Bên bờ sông Dịch Thủy, một con trai đang há miệng phơi nắng. Lúc đó một con cò đáp xuống, thấy thịt trai có vẻ ngon, thò mỏ mổ vào thịt trai, con trai lập tức khép chặt miệng lại, kẹp cứng mỏ cò. Hai con trì níu nhau một hồi lâu.","cat":"fable"},{"id":"hai-anh-em-di-san-va-chu-tho-trong-rung","url":"https://truyencotich.top/doc-truyen/hai-anh-em-di-san-va-chu-tho-trong-rung","title":"Hai anh em đi săn và chú thỏ trong rừng","summary":"Ngày xưa, có hai anh em nhà nọ đi săn trong rừng sâu, họ nhìn thấy một chú thỏ con đang tung tăng gặm cỏ.","cat":"fable"},{"id":"nha-thong-thai-va-nguoi-nong-dan","url":"https://truyencotich.top/doc-truyen/nha-thong-thai-va-nguoi-nong-dan","title":"Nhà thông thái và người nông dân","summary":"Một nhà thông thái nghĩ mình đã biết hết mọi việc trên đời. Có lần, ông gặp một bác nông dân trông thật là chân chất.","cat":"fable"},{"id":"cho-gay-va-meo","url":"https://truyencotich.top/doc-truyen/cho-gay-va-meo","title":"Chó gầy và mèo","summary":"CÓ MỘT CON CHÓ ĐÓI lang thang trong núi. Nó gặp Sói, Sói nói: Chó kia, ta sẽ ăn thịt mi!","cat":"fable"},{"id":"bay-khi-di-du-lich","url":"https://truyencotich.top/doc-truyen/bay-khi-di-du-lich","title":"Bầy khỉ đi du lịch","summary":"TRONG VƯỜN THÚ, có một bầy khỉ đông đúc, tính tình vui nhộn. Một hôm, một con khỉ bảo cả bầy: Chúng ta hãy cùng đi du lịch để mở mang kiến thức đi!","cat":"fable"},{"id":"ech-va-bo-cap","url":"https://truyencotich.top/doc-truyen/ech-va-bo-cap","title":"Ếch và bọ cạp","summary":"Có một chú bò cạp đang di chuyển chầm chậm bên bờ sông, thình lình chú nhìn sang bên kia bờ sông, thấy cả đàn bò cạp dòng họ của chú đang hoản loạn vì một đám cháy ở gần đó, chú rất lo lắng...","cat":"fable"},{"id":"dam-thuyen","url":"https://truyencotich.top/doc-truyen/dam-thuyen","title":"Đắm thuyền","summary":"Những người đánh cá đi trên một con thuyền. Bỗng trời nổi dông bão. Những người đánh cá sợ hãi. Họ gác cả chèo lại và bắt đầu cầu khấn Thượng đế để Thượng đế cứu giúp họ.","cat":"fable"},{"id":"dai-bang-qua-va-nguoi-chan-cuu","url":"https://truyencotich.top/doc-truyen/dai-bang-qua-va-nguoi-chan-cuu","title":"Đại bàng, quạ và người chăn cừu","summary":"Bầy cừu tha thẩn ăn cỏ trên đồng. Một con đại bàng không hiểu từ đâu bay tới lao xuống quắp một chú cừu mang đi. Quạ nhìn thấy thế cũng đâm thèm chén thịt.","cat":"fable"},{"id":"ngua-duc-ngua-cai","url":"https://truyencotich.top/doc-truyen/ngua-duc-ngua-cai","title":"Ngựa đực, ngựa cái","summary":"Ngựa cái ngày đêm không làm lụng gì hết và chỉ tha thẩn trên cánh đồng, còn ngựa đực đêm đêm mới được thả đi ăn, ban ngày phải cày đất.","cat":"fable"},{"id":"su-tu-va-chuot-nhat","url":"https://truyencotich.top/doc-truyen/su-tu-va-chuot-nhat","title":"Sư Tử và Chuột Nhắt","summary":"Một con Sư Tử ngủ say trong rừng. Chuột Nhắt chạy qua, không may đụng phải làm Sư Tử tỉnh giấc. Sư Tử giận dữ, giơ chân chộp lấy Chuột Nhắt. Chuột van lạy: Xin ông tha cho tôi. Tôi bé nhỏ thế này, ông ăn chẳng bõ dính răng.","cat":"fable"},{"id":"tom-hum-va-oc-anh-vu","url":"https://truyencotich.top/doc-truyen/tom-hum-va-oc-anh-vu","title":"Tôm Hùm và Ốc Anh Vũ","summary":"Một hôm, Tôm Hùm và Ốc Anh Vũ gặp nhau nơi biển sâu. Ốc Anh Vũ nhìn thấy Tôm Hùm đang lột lớp vỏ cứng trên người, để lộ ra cơ thể non nớt.","cat":"fable"},{"id":"muu-tri-ho-ly","url":"https://truyencotich.top/doc-truyen/muu-tri-ho-ly","title":"Mưu trí Hồ Ly","summary":"Cọp rừng là loài quái ác, đi đến đâu muôn thú đều sợ. Một con Cọp rừng bắt đuoc con Hồ Ly. Hồ Ly mưu trí liền dọa: Này, anh không được đụng đến tôi. Thượng đế cử tối xuống khu rừng này để thống soái muôn loài.","cat":"fable"},{"id":"cao-va-qua","url":"https://truyencotich.top/doc-truyen/cao-va-qua","title":"Cáo và Quạ","summary":"Một con Quạ đang đứng trên một cành cây, mỏ ngậm miếng pho mát. Trong khi đó, có một con Cáo đang theo dõi, nó lập kế hoạch để chiếm miếng pho mát đó.","cat":"fable"},{"id":"con-nai-va-bac-tho-san","url":"https://truyencotich.top/doc-truyen/con-nai-va-bac-tho-san","title":"Con nai và bác thợ săn","summary":"Trong một khu rừng nọ, có một con nai đang uống nước suối và ngắm nhìn bộ gạc trên đầu. Sau đó, con nai bắt đầu nghĩ về bộ móng guốc và nó ước rằng móng guốc của mình có thể lớn và đồ sộ như nhánh gạc.","cat":"fable"},{"id":"doi-long-can-dam","url":"https://truyencotich.top/doc-truyen/doi-long-can-dam","title":"Đổi lòng can đảm","summary":"Có một con Thỏ rất nhát gan, luôn bị những kẻ trong rừng lừa gạt, ức hiếp. Nó thường nghĩ giá như có được gan của Báo thì tốt biết mấy. Vì thế nó tìm đến gặp Báo và nói: Anh Báo, anh đổi lòng can đảm của anh cho tôi được không?","cat":"fable"},{"id":"hai-cai-noi","url":"https://truyencotich.top/doc-truyen/hai-cai-noi","title":"Hai cái nồi","summary":"Có hai cái nồi, một cái làm bằng đồng và một cái làm bằng đất nung, đứng cùng nhau trên mặt bếp. Một ngày nọ, cái nồi đồng rủ cái nồi đất nung nên cùng nhau đi ra ngoài khám phá thế giới xung quanh.","cat":"fable"},{"id":"nha-chiem-tinh","url":"https://truyencotich.top/doc-truyen/nha-chiem-tinh","title":"Nhà chiêm tinh","summary":"Ngày xửa ngày xưa, có một người đàn ông tin rằng mình có thể đọc được tương lai thông qua những ngôi sao trên trời. Ông dành phần lớn thời gian của mình để nhìn ngắm nhìn và nghiên cứu bầu trời...","cat":"fable"},{"id":"may-den-va-may-trang","url":"https://truyencotich.top/doc-truyen/may-den-va-may-trang","title":"Mây đen và mây trắng","summary":"Trên bầu trời cao rộng, mây đen và mây trắng đang rong ruổi theo gió. Mây trắng xốp, nhẹ, bồng bềnh như một chiếc gối bông xinh xắn. Mây đen vóc dóng nặng nề, đang sà xuống thấp.","cat":"fable"},{"id":"ba-chu-va-nguoi-di-cay","url":"https://truyencotich.top/doc-truyen/ba-chu-va-nguoi-di-cay","title":"Bà chủ và người đi cày","summary":"Xưa có một bà chủ, một hôm bảo người nhà đem trâu ra ruộng cày và dặn anh ta rằng: “Khi nào nghe thấy tiếng cốc kêu, thì hãy về nhé”.","cat":"fable"},{"id":"de-den-va-de-trang","url":"https://truyencotich.top/doc-truyen/de-den-va-de-trang","title":"Dê Đen và Dê Trắng","summary":"Dê đen và Dê trắng cùng sống trong một khu rừng. Hàng ngày, cả hai thường đến uống nước và tìm cái ăn ở trong khu rừng quen thuộc...","cat":"bedtime"},{"id":"bai-hoc-dau-tien-cua-gau-con","url":"https://truyencotich.top/doc-truyen/bai-hoc-dau-tien-cua-gau-con","title":"Bài học đầu tiên của Gấu con","summary":"Ngày chủ nhật Gấu con xin phép mẹ ra đường chơi cùng các bạn...","cat":"bedtime"},{"id":"cau-be-viet-thue","url":"https://truyencotich.top/doc-truyen/cau-be-viet-thue","title":"Cậu bé viết thuê","summary":"Đó là một cậu bé mười hai tuổi, tên là Giu-li-ô, con trai đầu của một nhân viên đường sắt. Người bố lương ít lại đông con nên đời sống rất chật vật. Ông phải kiếm việc làm thêm vào ban đêm.","cat":"bedtime"},{"id":"ai-ngoan-se-duoc-thuong","url":"https://truyencotich.top/doc-truyen/ai-ngoan-se-duoc-thuong","title":"Ai ngoan sẽ được thưởng","summary":"Một buổi sáng, Bác Hồ đến thăm trại nhi đồng. Vừa thấy Bác, các em nhỏ ùa ra đón Bác. Em nào cũng muốn đến thật gần Bác để nhìn Bác cho rõ. Có em cứ đi giật lùi phía trước Bác để luôn luôn được nhìn thấy Bác.","cat":"bedtime"},{"id":"dong-tien-vang","url":"https://truyencotich.top/doc-truyen/dong-tien-vang","title":"Đồng tiền vàng","summary":"Một hôm, vừa bước ra khỏi nhà, tôi gặp một cậu bé chừng mười hai, mười ba tuổi, ăn mặc tồi tàn, rách rưới, mặt mũi gầy gò, xanh xao, chìa những bao diêm khẩn khoản nhờ tôi mua giúp.","cat":"bedtime"},{"id":"ngua-trang-khong-nghe-loi-me","url":"https://truyencotich.top/doc-truyen/ngua-trang-khong-nghe-loi-me","title":"Ngựa Trắng không nghe lời mẹ","summary":"Có một chú Ngựa Trắng lúc nào cũng muốn làm trái với những điều đã được dặn.","cat":"bedtime"},{"id":"ba-co-gai","url":"https://truyencotich.top/doc-truyen/ba-co-gai","title":"Ba cô gái","summary":"Ngày xưa, có một người đàn bà nghèo sinh được ba cô con gái. Bà rất yêu thương các con, bà lo cho các con từng li từng tí. Nhà nghèo, bà phải làm lụng vất vả để nuôi các con nhưng bà không hề phàn nàn...","cat":"bedtime"},{"id":"qua-tao-cua-ai","url":"https://truyencotich.top/doc-truyen/qua-tao-cua-ai","title":"Quả táo của ai?","summary":"Trời về cuối thu. Từ lâu cây đã rụng lá. Cây táo giữa rừng chỉ còn mỗi một quả...","cat":"bedtime"},{"id":"en-con-va-chiec-la","url":"https://truyencotich.top/doc-truyen/en-con-va-chiec-la","title":"Én con và chiếc lá","summary":"Mùa thu sắp qua đi. Mùa đông sắp đến. Trên một ngọn cây cao, Én con cứ rúc rúc đầu vào tổ rồi lại nhìn ra ngoài trời...","cat":"bedtime"},{"id":"mot-giac-mo","url":"https://truyencotich.top/doc-truyen/mot-giac-mo","title":"Một giấc mơ","summary":"Có một cậu bé rất lười rửa mặt, tắm gội. Mẹ cậu rất buồn vì mỗi lần mẹ gọi ra rửa mặt hay gội đầu, tắm giặt là cậu lại đáp: “Con không rửa mặt đâu! Không tắm gội đâu!”.","cat":"bedtime"},{"id":"ba-chu-heo-con","url":"https://truyencotich.top/doc-truyen/ba-chu-heo-con","title":"Ba chú heo con","summary":"Ngày xưa có một bà mẹ heo sinh được ba chú heo con. Ba chú heo hay ăn nên lớn rất nhanh, khi thấy những đứa con của mình cũng đã lớn...","cat":"bedtime"},{"id":"mon-qua-sinh-nhat","url":"https://truyencotich.top/doc-truyen/mon-qua-sinh-nhat","title":"Món quà sinh nhật","summary":"Ngày kỉ niệm sinh nhật lần thứ 7 của bé Thủy, mẹ bé đưa con gái ra phố mua quà tặng. Mẹ bé bảo con thích đồ chơi nào thì mẹ mua cho, nhưng chỉ được mua một thứ thôi.","cat":"bedtime"},{"id":"con-cu-khon-ngoan","url":"https://truyencotich.top/doc-truyen/con-cu-khon-ngoan","title":"Con cú khôn ngoan","summary":"Ngày xửa ngày xưa, có một con cú già sống trên một cây sồi to. Mỗi ngày, nó đều phóng tầm mắt ra thật xa để quan sát những điều xảy ra xung quanh mình...","cat":"bedtime"},{"id":"con-cuu-den-keu-be-be","url":"https://truyencotich.top/doc-truyen/con-cuu-den-keu-be-be","title":"Con cừu đen kêu be be","summary":"Ngày xửa ngày xưa, có một con cừu đen sống trong một ngôi nhà nhỏ. Cứ đến mùa xuân, con cừu đen lại tự cạo sạch lông của mình và đem ra chợ bán cho những người muốn làm quần áo ấm...","cat":"bedtime"},{"id":"khi-va-ca-sau","url":"https://truyencotich.top/doc-truyen/khi-va-ca-sau","title":"Khỉ và cá sấu","summary":"Ngày xưa, có một con khỉ sống trên một cây cao lớn và làm bạn với một con cá sấu sống ở dòng sông gần đó. Mỗi ngày, con khỉ sẽ hái những quả táo ngon ở trên cây và đem tặng bạn cá sấu...","cat":"bedtime"},{"id":"ca-ro-ron-khong-vang-loi-me","url":"https://truyencotich.top/doc-truyen/ca-ro-ron-khong-vang-loi-me","title":"Cá Rô Ron không vâng lời mẹ","summary":"Con người có cái cần câu. Đầu cần câu buộc sợi dây cước. Đầu sợi dây cước buộc lưỡi câu. Lưỡi câu mắc con mồi ngon, thả xuống nước. Con cá nào tham mồi đớp phải, người ta giật lên là chết...","cat":"bedtime"},{"id":"bac-ho-la-the-day","url":"https://truyencotich.top/doc-truyen/bac-ho-la-the-day","title":"Bác Hồ là thế đấy","summary":"Thời chống Mỹ, một buổi trưa, Hồ Chủ tịch đang chuẩn bị nằm nghỉ thì cần vụ vào báo cáo là Bác có khách. Khách là một cụ già ở Hưng Yên. Cùng đi với cụ có một vị lãnh đạo tỉnh. Trên xe còn có một thùng cá khá nặng.","cat":"bedtime"},{"id":"nep-song-gian-di-cua-bac-ho","url":"https://truyencotich.top/doc-truyen/nep-song-gian-di-cua-bac-ho","title":"Nếp sống giản dị của Bác Hồ","summary":"Ở cương vị Chủ tịch nước, Chủ tịch Hồ Chí Minh sống rất giản dị. Bác không muốn Chính phủ dành một sự ưu đãi nào cho riêng mình.","cat":"bedtime"},{"id":"kien-va-chim-bo-cau","url":"https://truyencotich.top/doc-truyen/kien-va-chim-bo-cau","title":"Kiến và chim Bồ Câu","summary":"Vào một ngày mùa hè nóng bức, có một con kiến trên đường đi tìm nước uống. Sau khi đi dạo một lúc lâu, kiến thấy một dòng suối. Để có thể uống nước, kiến phải leo lên một ngọn cỏ cao. Trong lúc trèo, kiến bị sẩy chân và rơi xuống nước...","cat":"bedtime"},{"id":"con-gau-va-hai-nguoi-ban","url":"https://truyencotich.top/doc-truyen/con-gau-va-hai-nguoi-ban","title":"Con gấu và hai người bạn","summary":"Có hai người bạn cùng nhau đi dạo trên một con đường vắng. Con đường này dẫn đến một khu rừng rậm với những ngọn núi cao. Họ im lặng bước đi bên nhau. Một trong hai người vẫn còn trẻ, còn người kia thì già hơn...","cat":"bedtime"},{"id":"ngong-va-rua","url":"https://truyencotich.top/doc-truyen/ngong-va-rua","title":"Ngỗng và rùa","summary":"Hai vợ chồng ngỗng và rùa là những người bạn tốt. Mùa hè đến, trời bắt đầu nóng lên khiến hồ nước dần cạn kiệt. Vì vậy, chúng lên kế hoạch đi tìm một chỗ ở mới...","cat":"bedtime"},{"id":"nguoi-con-gai-hieu-thao","url":"https://truyencotich.top/doc-truyen/nguoi-con-gai-hieu-thao","title":"Người con gái hiếu thảo","summary":"Một bà mẹ sinh được bảy cô con gái. Một dạo bà đi thăm cậu con trại ở xa. Một tuần lễ sau, bà trở về nhà. Mới bước chân vào nhà, bà đã nghe các con gái lần lượt nói lên nỗi mong nhớ của mình...","cat":"bedtime"},{"id":"con-lua-hat","url":"https://truyencotich.top/doc-truyen/con-lua-hat","title":"Con lừa hát","summary":"Ngày xửa ngày xưa, có một người giặt đồ thuê nuôi một con lừa để giúp anh ta vận chuyển quần áo từ nhà ra bờ sông và ngược lại. Thế nhưng, con lừa này không thích những món ăn mà ông chủ cho nó...","cat":"bedtime"},{"id":"de-va-cao","url":"https://truyencotich.top/doc-truyen/de-va-cao","title":"Dê và cáo","summary":"Trong một khu rừng nọ, có một con sư tử rất hung bạo, sống trong một cái hang lớn và chứa nhiều thức ăn. Một hôm, con sư tử đi ra khỏi hang. Nhân lúc đó, một con cáo đã lẻn vào và ăn tất cả thức ăn có trong hang...","cat":"bedtime"},{"id":"cau-lac-bo-cac-ba-me","url":"https://truyencotich.top/doc-truyen/cau-lac-bo-cac-ba-me","title":"Câu lạc bộ các bà mẹ","summary":"Một ngày nọ, tất cả bà mẹ thú trong rừng tập hợp lại với nhau và bắt đầu so sánh xem con của ai là giỏi nhất và ai đẻ được nhiều con nhất. Mẹ nai nói rằng con mình là to lớn nhất...","cat":"bedtime"},{"id":"con-lua-khon-ngoan","url":"https://truyencotich.top/doc-truyen/con-lua-khon-ngoan","title":"Con lừa khôn ngoan","summary":"Một con lừa đang vui vẻ ăn cỏ trên một ngọn đồi mà không hề hay biết rằng có một con sói đang rình nó. Khi con lừa ăn xong và ngẩng đầu lên, nó ngỡ ngàng nhận ra con sói đang đứng nhìn mình...","cat":"bedtime"},{"id":"chu-oc-sen-thich-di-du-lich","url":"https://truyencotich.top/doc-truyen/chu-oc-sen-thich-di-du-lich","title":"Chú ốc sên thích đi du lịch","summary":"Dưới gốc cây ở một khu rừng nọ, có một chú Ốc sên sinh sống. Từ trước tới nay, Ốc sên chưa bao giờ đi xa cả nên nó không hề biết thế giới bên ngoài rộng lớn tới mức nào...","cat":"bedtime"},{"id":"cau-chuyen-cai-mu","url":"https://truyencotich.top/doc-truyen/cau-chuyen-cai-mu","title":"Câu chuyện cái mũ","summary":"Khu rừng nọ bị cháy, lại đang lúc gió to nên ngọn lửa bùng lên rất lớn, nhuộm đỏ rực cả một góc trời. Các loài động vật trong khu rừng hốt hoảng, lập tức chạy đi dập lửa. Người thì xách xô, người thì xách chậu, người múc nước, người tạt lửa...","cat":"bedtime"},{"id":"tuyet-chieu-cua-chuot","url":"https://truyencotich.top/doc-truyen/tuyet-chieu-cua-chuot","title":"Tuyệt chiêu của chuột","summary":"Mèo Hoa bắt chuột rất giỏi, ngày nào nó cũng bắt được một vài con chuột. Nhìn thấy cư dân của mình sắp bị mèo bắt ăn thịt hết, Quốc vương Chuột cảm thấy rất lo lắng. Nó gọi những con chuột còn lại trong bầy đến và mở một cuộc họp khẩn cấp...","cat":"bedtime"},{"id":"meo-vang-vao-thanh-pho","url":"https://truyencotich.top/doc-truyen/meo-vang-vao-thanh-pho","title":"Mèo Vàng vào thành phố","summary":"Trong vương quốc động vật, Sư tử Haker là Quốc vương. Một hôm, Quốc vương mở một cuộc họp khẩn cấp...","cat":"bedtime"},{"id":"chuyen-la-trong-rung","url":"https://truyencotich.top/doc-truyen/chuyen-la-trong-rung","title":"Chuyện lạ trong rừng","summary":"Tối hôm qua, trong khu rừng bỗng nhiên xảy ra rất nhiều chuyện kì lạ: Cái đuôi sặc sỡ của chim Công bỗng nhiên không còn. Cú mèo thì có một bộ mặt giống hệt như Chuột đồng, bộ lông mềm mượt của Khỉ vàng bỗng nhiên trở nên đen đúa...","cat":"bedtime"},{"id":"bo-hoa-dac-biet","url":"https://truyencotich.top/doc-truyen/bo-hoa-dac-biet","title":"Bó hoa đặc biệt","summary":"Vào mùa đông lạnh giá, bà nội của Chuột chũi bị ốm, phải nằm nghỉ trên giường. Bà nội nhìn ra bãi cỏ khô héo phía ngoài cửa sổ và nói: “Bà nhớ những bông hoa tươi trên bãi cỏ ngày nào quá!”...","cat":"bedtime"},{"id":"ga-trong-choai-thong-minh","url":"https://truyencotich.top/doc-truyen/ga-trong-choai-thong-minh","title":"Gà trống choai thông minh","summary":"Một hôm, Gà Trống choai và Chó mực cùng nhau đi chơi ở ngoại ô. Cả hai vừa đi vừa chơi đùa thật là vui vẻ, không biết trời đã tối từ lúc nào rồi...","cat":"bedtime"},{"id":"ech-me-may-quan-ao","url":"https://truyencotich.top/doc-truyen/ech-me-may-quan-ao","title":"Ếch mẹ may quần áo","summary":"Ếch mẹ ngồi bên bờ ao khóc thút thít, thì ra là những đứa con nhỏ của nó đã bị dòng nước cuốn đi mất rồi. Cóc mẹ nhìn thấy thế mới nói: Cô Ếch à, đừng khóc nữa, phải giữ gìn sức khỏe của mình nữa đấy...","cat":"bedtime"},{"id":"nhung-dua-tre-luoi-bieng","url":"https://truyencotich.top/doc-truyen/nhung-dua-tre-luoi-bieng","title":"Những đứa trẻ lười biếng","summary":"Mùa đông lạnh giá đã đến, phải ở nhà một mình, Thỏ con cảm thấy rất buồn chán. Đúng rồi, mình phải đi tìm bạn mới được - Thỏ con thầm nghĩ...","cat":"bedtime"},{"id":"la-rung","url":"https://truyencotich.top/doc-truyen/la-rung","title":"Lá rụng","summary":"Sóc Ngân và Sóc Khôi là hai chú Sóc con sinh đôi. Chúng được sinh ra vào mùa xuân, trải qua mùa hè nóng nực, bây giờ chúng đang háo hức mong chờ mùa thu tới. Sóc con nghe mẹ nói rằng, khi nào lá cây rụng xuống tức là mùa thu đã tới...","cat":"bedtime"},{"id":"mon-qua-cua-co-giao","url":"https://truyencotich.top/doc-truyen/mon-qua-cua-co-giao","title":"Món quà của cô giáo","summary":"Hôm thứ hai đầu tuần, cô giáo Hươu Sao nói với cả lớp mẫu giáo lớn: Các con sắp được nghỉ hè rồi. Tuần này ai được phiếu bé ngoan, cô sẽ tặng cho một món quà...","cat":"bedtime"},{"id":"ve-sau-di-hoc","url":"https://truyencotich.top/doc-truyen/ve-sau-di-hoc","title":"Ve sầu đi học","summary":"Trong khu vườn nọ có một gia đình nhà ve sầu. Một chú ve sầu con đang tuổi ham chơi. Suốt ngày chú là cà, lêu lổng lang thang khắp vườn. Chú làm quen được với một bạn dế mèn con. Cả hai quậy phá khắp nơi...","cat":"bedtime"},{"id":"chon-con-luoi-hoc","url":"https://truyencotich.top/doc-truyen/chon-con-luoi-hoc","title":"Chồn con lười học","summary":"Chồn mướp sống ở khu rừng thông, vì là con một nên cậu được cha mẹ cưng chiều vô cùng. Tới tuổi đi học rồi, nhưng chồn mướp vẫn không chịu đến trường, chỉ rong chơi mà thôi. Vì được nuông chiều quá, chồn mướp đâm ra bướng bỉnh...","cat":"bedtime"},{"id":"ong-khong-lo-ich-ky","url":"https://truyencotich.top/doc-truyen/ong-khong-lo-ich-ky","title":"Ông khổng lồ ích kỷ","summary":"Cứ sau mỗi buổi trưa, lúc ở trường ra về, bọn trẻ con thường có thói quen tới nô đùa trong khu vườn của ông Khổng lồ. Đó là một khu vườn rộng đẹp phủ đầy cỏ xanh mơn mởn...","cat":"bedtime"},{"id":"sau-xanh-choi-tron-tim","url":"https://truyencotich.top/doc-truyen/sau-xanh-choi-tron-tim","title":"Sâu Xanh chơi trốn tìm","summary":"Trên đồng cỏ, có một chú Sâu xanh với đôi mắt to tròn, những cái chân nhỏ nhắn, những sợi lông lưa thưa và cái bụng tròn căng, béo múp míp, trông mới đáng yêu làm sao. Khỉ con và Nhím con rất thích Sâu xanh...","cat":"bedtime"},{"id":"hai-nguoi-ban-tot","url":"https://truyencotich.top/doc-truyen/hai-nguoi-ban-tot","title":"Hai người bạn tốt","summary":"Một hôm, Cá Chình đang bơi lội một mình dưới đáy biển thì bỗng nhiên nhìn thấy một bông hoa rất đẹp ở trên một hòn đá phía xa, bông hoa đó có màu tím, màu xanh và cả màu vàng nữa, thật là đặc biệt...","cat":"bedtime"},{"id":"hat-mam-than-ky","url":"https://truyencotich.top/doc-truyen/hat-mam-than-ky","title":"Hạt mầm thần kỳ","summary":"Hôm nay là ngày cuối tuần, nhưng cả bố và mẹ đều phải đi làm nên An Đông phải ở nhà một mình. Trước khi đi, bố mẹ dặn - Con ở nhà chơi ngoan nhé, đừng nghịch đồ đạc linh tinh, không cẩn thận là sẽ gặp nguy hiểm đấy...","cat":"bedtime"},{"id":"chu-ong-luoi-bieng","url":"https://truyencotich.top/doc-truyen/chu-ong-luoi-bieng","title":"Chú Ong lười biếng","summary":"Xưa kia, có dòng họ nhà Ong sinh sống hòa thuận trên thảo nguyên, họ siêng năng, cần mẫn làm việc. Một trong những gia đình Ong đó có một cậu con trai đặt tên là Ong Cưng...","cat":"bedtime"},{"id":"doi-ban-tot","url":"https://truyencotich.top/doc-truyen/doi-ban-tot","title":"Đôi bạn tốt","summary":"Thím Vịt bận đi chợ xa đem con gởi đến bác Gà mái mẹ. Gà mái mẹ gọi con ra chơi với Vịt con. Gà con xin phép mẹ dẫn Vịt con ra vườn chơi và tìm giun dế ăn. Gà con nhanh nhẹn đi trước, Vịt con lạch bạch theo sau...","cat":"bedtime"},{"id":"lon-con-giam-beo","url":"https://truyencotich.top/doc-truyen/lon-con-giam-beo","title":"Lợn con giảm béo","summary":"Lợn con béo nhất trong số các con vật ở nông trại, chính vì thế mà nó hay bị các bạn trêu chọc nhất. Một hôm, Lợn con quyết định giảm béo bằng cách ăn kiêng...","cat":"bedtime"},{"id":"khi-con-va-su-tu","url":"https://truyencotich.top/doc-truyen/khi-con-va-su-tu","title":"Khỉ con và Sư Tử","summary":"Sư tử là chúa tể trị vì trong khu rừng nọ. Nó nổi tiếng là có tính khí hung tợn, dữ dằn và thường đưa ra những yêu cầu rất kì quái cho những động vật khác, nếu ai không đáp ứng được thì nó sẽ nổi giận...","cat":"bedtime"},{"id":"bo-ria-cua-meo-muop","url":"https://truyencotich.top/doc-truyen/bo-ria-cua-meo-muop","title":"Bộ ria của mèo mướp","summary":"Nhà Nhật Minh có nuôi một chú Mèo mướp. Một hôm, Nhật Minh vừa đi học về, vội vã chạy ra sân chơi đùa với Mèo mướp. Cậu bé nhìn thấy bộ râu của Mèo mướp thật là lộn xộn, sợi thì ngắn quá, sợi thì dài quá, bèn nghĩ...","cat":"bedtime"},{"id":"nhim-con-va-ngoi-nha-bi-do","url":"https://truyencotich.top/doc-truyen/nhim-con-va-ngoi-nha-bi-do","title":"Nhím con và ngôi nhà bí đỏ","summary":"Sau cơn mưa, Nhím con phát hiện trên bãi cỏ có một quả bí đỏ to ơi là to. Nó đi vòng quanh quả bí và sung sướng cười phá lên, “Cuối cùng mình cũng có nhà mới rồi!” Thế rồi Nhím con đẩy quả bí đỏ đến dưới một gốc cây...","cat":"bedtime"},{"id":"dau-tay-nho","url":"https://truyencotich.top/doc-truyen/dau-tay-nho","title":"Dâu tây nhỏ","summary":"Một quả dâu tây nhỏ mặc chiếc váy màu đỏ tươi, đội một cái mũ xanh đang chạy nhảy tung tăng trên bãi cỏ. Dế mèn nhìn thấy Dâu tây liền nói “Dâu tây mới xinh đẹp làm sao, tôi hát một bài cho bạn nghe nhé&quot;...","cat":"bedtime"},{"id":"qua-con-yeu-me","url":"https://truyencotich.top/doc-truyen/qua-con-yeu-me","title":"Quạ con yêu mẹ","summary":"Ở một khu rừng nọ, có những chú Quạ con rất đáng yêu sống cùng với mẹ. Hàng ngày Quạ mẹ bay đi bay lại rất vất vả. Ông Rùa già nói &quot;Quạ mẹ này, sao ngày nào chị cũng bận rộn thế? Ngồi xuống nghỉ một lát đi, chúng ta nói chuyện nhé&quot;...","cat":"bedtime"},{"id":"vit-con-xau-xi","url":"https://truyencotich.top/doc-truyen/vit-con-xau-xi","title":"Vịt con xấu xí","summary":"Trong một khu rừng nọ, có một cô Vịt mẹ đang ấp trứng, hồi hộp mong chờ đến ngày được gặp mặt những đứa con yêu quý của mình. Cuối cùng ngày đó cũng đến, từng quả trứng nở ra, những chú vịt con xinh xắn và đáng yêu lần lượt nhảy ra ngoài...","cat":"bedtime"},{"id":"dui-con-noi-sai-roi","url":"https://truyencotich.top/doc-truyen/dui-con-noi-sai-roi","title":"Dúi con nói sai rồi","summary":"Mùa xuân đã đến với khu rừng nhỏ, các loài động vật trong rừng đều đang bận rộn trang hoàng lại nhà cửa. Dúi con cũng tất tả đi mua gỗ lát sàn nhà, mua gạch men để làm đẹp cho ngôi nhà của mình...","cat":"bedtime"},{"id":"chiec-ban-ky-dieu","url":"https://truyencotich.top/doc-truyen/chiec-ban-ky-dieu","title":"Chiếc bàn kỳ diệu","summary":"Trong một khu rừng nọ, có rất nhiều loài động vật và thực vật đáng yêu cùng nhau sinh sống. Một hôm, trời vừa tạnh mưa, Thỏ trắng liền tung tăng chạy vào rừng để hái hoa. A, nó phát hiện một cây nấm rất to mọc dưới gốc cây dương cổ thụ...","cat":"bedtime"},{"id":"su-tu-va-lon-con","url":"https://truyencotich.top/doc-truyen/su-tu-va-lon-con","title":"Sư Tử và Lợn Con","summary":"Sư tử Ryan và Lợn con Picky là hàng xóm của nhau, hàng ngày, chúng đều rủ nhau cùng đi học. Ryan nói rất nhiều nên được mọi người đặt cho biệt danh là “Biết tuốt”. Còn Picky thì ít nói, nhưng rất lễ phép...","cat":"bedtime"},{"id":"cai-mieng-cua-ech-con","url":"https://truyencotich.top/doc-truyen/cai-mieng-cua-ech-con","title":"Cái miệng của Ếch con","summary":"Có một chú Ếch con sống trong một cái ao nọ. Chú ta có một cái miệng rất rộng và bắt mồi cũng rất giỏi. Ếch con và Én con là bạn thân của nhau. Một bạn thì biết bay và có thể bắt côn trùng trên cao...","cat":"bedtime"},{"id":"khi-con-va-nhim-con","url":"https://truyencotich.top/doc-truyen/khi-con-va-nhim-con","title":"Khỉ con và Nhím con","summary":"Trong số tất cả bạn bè của mình, người mà Khỉ con coi thường nhất chính là Nhím con. “Nhìn xem cậu ta xấu xí không kìa, khắp người toàn kim là kim, cái đầu thì vừa nhọn vừa nhỏ. Mỗi khi gặp nguy hiểm chỉ biết cuộn mình lại...&quot;","cat":"bedtime"},{"id":"be-xa-bong-di-dau-mat-roi","url":"https://truyencotich.top/doc-truyen/be-xa-bong-di-dau-mat-roi","title":"Bé Xà Bông đi đâu mất rồi?","summary":"Khỉ con ngày nào cũng leo trèo nghịch ngợm, hết sờ chỗ này lại mó chỗ kia nên mặt mũi tay chân đều lấm lem hết cả. Một hôm, Khỉ mẹ tặng cho Khỉ con một cục xà bông trong suốt rất đáng yêu. Khỉ con rất thích và gọi đó là Bé xà bông...","cat":"bedtime"},{"id":"soc-con-thich-di-du-lich","url":"https://truyencotich.top/doc-truyen/soc-con-thich-di-du-lich","title":"Sóc con thích đi du lịch","summary":"Trong rừng rậm, có một chú Sóc rất thích đi du lịch, nó đã từng đến rất nhiều nơi. Núi cao này, thảo nguyên này và cả biển nữa. Một hôm, Sóc con đến một thị trấn nhỏ, nơi con người sinh sống...","cat":"bedtime"},{"id":"hang-xom-cua-co-dui","url":"https://truyencotich.top/doc-truyen/hang-xom-cua-co-dui","title":"Hàng xóm của cô Dúi","summary":"Cô Dúi có ba người hàng xóm, đó là Ếch xanh, chị Rắn và chú Giun. Ếch xanh sống ở tầng dưới, là một ca sĩ nhạc Rock rất có cá tính. Buổi tối, Ếch thường khua chiêng đánh trống và hát rất to. Chị Rắn sống ở tầng trên là một cô giáo mầm non...","cat":"bedtime"},{"id":"mot-tri-khon-hon-tram-tri-khon","url":"https://truyencotich.top/doc-truyen/mot-tri-khon-hon-tram-tri-khon","title":"Một trí khôn hơn trăm trí khôn","summary":"Một buổi sáng trời quang mây tạnh, đôi bạn dạo chơi trên đồng cỏ. Chúng đi sóng đôi với nhau, nhởn nhơ ngắm trời ngắm đất. Ánh mặt trời chiếu trên thảm cỏ non làm cho những giọt sương long lanh như những hạt ngọc...","cat":"bedtime"},{"id":"co-chu-khong-biet-quy-tinh-ban","url":"https://truyencotich.top/doc-truyen/co-chu-khong-biet-quy-tinh-ban","title":"Cô chủ không biết quý tình bạn","summary":"Ngày xưa có một cô bé xinh xắn nuôi một con gà trống đẹp mã. Buổi sớm thức dậy, gà trống gáy – Ò ó o! Ò ó o! Xin chào cô chủ tí hon!","cat":"bedtime"},{"id":"hai-chu-gau-tham-an","url":"https://truyencotich.top/doc-truyen/hai-chu-gau-tham-an","title":"Hai chú gấu tham ăn","summary":"Ngày xửa ngày xưa, ở một khu rừng rậm nọ chưa từng có ai đặt chân đến, có một con gấu mẹ và hai chú gấu con. Gấu mẹ đã già rồi, nhưng hàng ngày vẫn phải cặm cụi đi kiếm ăn về nuôi hai con của mình...","cat":"bedtime"},{"id":"ban-tay-thom","url":"https://truyencotich.top/doc-truyen/ban-tay-thom","title":"Bàn tay thơm","summary":"Kem ngon quá, vừa ngọt vừa thơm. Gấu con đã ăn hết cả chiếc kem rồi mà vẫn còn liếm láp quanh miệng mình. Trên miệng hết vị ngọt rồi, nhưng ở bàn tay thì vẫn còn...","cat":"bedtime"},{"id":"lulu-khong-chiu-day","url":"https://truyencotich.top/doc-truyen/lulu-khong-chiu-day","title":"Lulu không chịu dậy","summary":"Ngày mai là một ngày rất quan trọng, ảo thuật gia nổi tiếng nhất thị trấn Xoài sẽ tặng cho mỗi bạn nhỏ trong thị trấn một món quà rất thú vị. Nhưng, ảo thuật gia cũng nói rằng, chỉ bạn nào đến sân nhà hát trước bảy giờ thì mới được nhận quà...","cat":"bedtime"},{"id":"xe-lu-va-xe-ca","url":"https://truyencotich.top/doc-truyen/xe-lu-va-xe-ca","title":"Xe Lu và Xe Ca","summary":"Một hôm, trên quãng đường kia, có chiếc xe lu lù rù chuyển bánh. Từ cột cây số này tới cột cây số kia, xe lu cứ vừa lăn vừa thở, mãi mới đến đích...","cat":"bedtime"},{"id":"chiec-xe-day-cua-chuot-dong","url":"https://truyencotich.top/doc-truyen/chiec-xe-day-cua-chuot-dong","title":"Chiếc xe đẩy của Chuột Đồng","summary":"Mùa thu đã tới, lúa mạch đã thơm, lúa mì đã vàng, củ cải đã đỏ. Chuột đồng đẩy chiếc xe cút kít mà bố vừa mới làm cho nó đến ruộng. “Hò dô ta, hò dô ta!” một đàn Kiến nhỏ đang khiêng một bông lúa mạch bước đi lặc lè trên ruộng...","cat":"bedtime"},{"id":"chiec-thuyen-giay-lang-thang","url":"https://truyencotich.top/doc-truyen/chiec-thuyen-giay-lang-thang","title":"Chiếc thuyền giấy lang thang","summary":"Trên một khúc sông nọ, có một chiếc thuyền giấy màu trắng đang trôi theo chiều gió, càng ngày càng xa. Thuyền giấy đi đâu vậy nhỉ? Ngay cả nó cũng không biết nữa...","cat":"bedtime"},{"id":"duong-dan-bai-su-hoc-nghe","url":"https://truyencotich.top/doc-truyen/duong-dan-bai-su-hoc-nghe","title":"Đường Dần bái sư học nghề","summary":"Đường Dần, tự Bá Hổ, từ nhỏ đã tỏ ra thông minh lanh lợi, tài học hơn người. Đường Dần đã từng bái ông tổ trường phái hội họa Ngô Môn là Thẩm Châu làm thầy, một năm sau, cậu bé Đường Dần đã thể hiện được tài năng hội họa xuất chúng...","cat":"bedtime"},{"id":"van-chua-ngu-day","url":"https://truyencotich.top/doc-truyen/van-chua-ngu-day","title":"Vẫn chưa ngủ dậy","summary":"Dumas là nhà văn nổi tiếng người Pháp. Một buổi tối nọ, Dumas và một người bạn là nhà biên kịch đến nhà hát lớn để xem kịch. Đúng hôm đó, nhà hát lại diễn một vở bi kịch do chính người bạn này biên soạn...","cat":"bedtime"},{"id":"chaplin-dau-tri-voi-ten-cuop","url":"https://truyencotich.top/doc-truyen/chaplin-dau-tri-voi-ten-cuop","title":"Chaplin đấu trí với tên cướp","summary":"Chaplin là một diễn viên hài nổi tiếng người Anh, ngoài đời thực, ông cũng rất hài hước và vô cùng thông minh. Một hôm, Chaplin có việc phải ra ngoài và mang theo một khoản tiền lớn...","cat":"bedtime"},{"id":"ai-ngheo-hon","url":"https://truyencotich.top/doc-truyen/ai-ngheo-hon","title":"Ai nghèo hơn","summary":"Cách đây rất lâu, thành phố Philadelphia của nước Mỹ thường xuyên xảy ra nạn cướp bóc. Khi ra đường, mọi người thường mang theo một ít tiền, để nếu có gặp cướp thì sẽ đưa cho chúng, nhằm bảo toàn tính mạng của mình...","cat":"bedtime"},{"id":"xena-va-bina","url":"https://truyencotich.top/doc-truyen/xena-va-bina","title":"Xena và Bina","summary":"Xena là một cô gái rất xinh đẹp và lương thiện, nàng có một người em gái cùng cha khác mẹ tên là Bina. Dì ghẻ và Bina thường xuyên ức hiếp Xena, nàng không thể chịu được sự ngược đãi của hai mẹ con dì ghẻ nên đã bỏ nhà ra đi...","cat":"bedtime"},{"id":"de-ta-xuong","url":"https://truyencotich.top/doc-truyen/de-ta-xuong","title":"Để ta xuống","summary":"Lần đầu tiên Ngụy Vương gặp Tôn Tẫn, rất muốn thử tài của ông. Sau khi đã yên vị trên ghế, Ngụy Vương nói với quần thần: Hôm nay, ta ngồi trên điện để xem trong các khanh, ai có thể làm ta phải đi xuống...","cat":"bedtime"},{"id":"in-chu-roi","url":"https://truyencotich.top/doc-truyen/in-chu-roi","title":"In chữ rời","summary":"Ngày xưa, những bản in đầu tiên được tạo ra bằng cách khắc chữ lên trên một tấm gỗ rồi mới in ra giấy. Tương truyền, Tất Thăng là người đầu tiên phát minh ra kĩ thuật in chữ rời, giúp cho hiệu quả in ấn được nâng lên gấp mấy chục lần...","cat":"bedtime"},{"id":"chang-trai-chan-trau-chu-nguyen-chuong","url":"https://truyencotich.top/doc-truyen/chang-trai-chan-trau-chu-nguyen-chuong","title":"Chàng trai chăn trâu Chu Nguyên Chương","summary":"Chuyện kể rằng, để kết giao với anh hùng hào kiệt khắp thiên hạ và thu thập lực lượng khởi nghĩa, Chu Nguyên Chương đã đóng giả thành một chàng trai chăn trâu đến Phúc Kiến. Một hôm, Chu Nguyên Chương lùa đàn trâu đến núi Linh Tú thì gặp...","cat":"bedtime"},{"id":"ban-sonate-anh-trang","url":"https://truyencotich.top/doc-truyen/ban-sonate-anh-trang","title":"Bản Sonate ánh trăng","summary":"Beethoven là nhạc sĩ thiên tài người Đức, ông đã sáng tác ra rất nhiều bản nhạc bất hủ. Trong số đó, có một bản sonate dành cho đàn piano vô cùng nổi tiếng tên là Bản sonate Ánh Trăng...","cat":"bedtime"},{"id":"gau-con-bi-sau-rang","url":"https://truyencotich.top/doc-truyen/gau-con-bi-sau-rang","title":"Gấu con bị sâu răng","summary":"Trong rừng có một chú Gấu con rất thích của ngọt. Mật ong, bánh gatô, các loại kẹo, chú ăn bao nhiêu cũng chẳng chán. Gấu con nhai kẹo suốt ngày. Nhiều hôm đi ngủ rồi mồm vẫn còn ngậm kẹo...","cat":"bedtime"},{"id":"bong-lua-mi","url":"https://truyencotich.top/doc-truyen/bong-lua-mi","title":"Bông lúa mì","summary":"Ngày xưa có hai chú chuột tên là Crúc và Véc sống chung với một chú Gà Trống. Một hôm Gà Trống quét sân thấy một bông lúa mì rơi trên mặt đất...","cat":"bedtime"},{"id":"dieu-hau-va-chich-choe","url":"https://truyencotich.top/doc-truyen/dieu-hau-va-chich-choe","title":"Diều hâu và Chích Choè","summary":"Ngày xưa trong khu rừng già nọ, có một con diều hâu luôn luôn huênh hoang, hợm hĩnh. Nó tự coi mình là chúa tể của muôn loài chim, tự hào về sức khoẻ vô địch của nó. Một hôm diều hâu tập hợp tất cả các loài chim lại và lên giọng thách thức...","cat":"bedtime"},{"id":"cay-den-bi-do","url":"https://truyencotich.top/doc-truyen/cay-den-bi-do","title":"Cây đèn bị đổ","summary":"Jean Baptiste Jolly sinh ra trong một gia đình nghèo ở thủ đô Paris (Pháp). Ngay từ khi mới 13 tuổi, cậu bé Jolly đã phải tìm việc làm để phụ giúp cha mẹ. Vì tuổi còn nhỏ nên không ai muốn thuê cậu bé làm cả...","cat":"bedtime"},{"id":"ten-cuop-that-ten-cuop-gia","url":"https://truyencotich.top/doc-truyen/ten-cuop-that-ten-cuop-gia","title":"Tên cướp thật - Tên cướp giả","summary":"Vào thời Tấn, có một vị quan huyện tên là Phù Dung, tư chất thông minh, tài trí hơn người khiến ai cũng trầm trồ, thán phục. Một buổi chiều nọ, có một bà lão đang trên đường về nhà thì gặp một tên cướp...","cat":"bedtime"},{"id":"cau-be-fulton-thich-suy-nghi","url":"https://truyencotich.top/doc-truyen/cau-be-fulton-thich-suy-nghi","title":"Cậu bé Fulton thích suy nghĩ","summary":"Robert Fulton (1765 - 1815) là một kĩ sư và nhà phát minh nổi tiếng người Mỹ, chính ông là người đã phát minh ra tàu thủy. Thuở nhỏ, cậu bé Fulton học hành không chăm chỉ, nhưng lại rất giỏi hội họa...","cat":"bedtime"},{"id":"bi-quyet-cua-balzac","url":"https://truyencotich.top/doc-truyen/bi-quyet-cua-balzac","title":"Bí quyết của Balzac","summary":"Balzac là nhà văn nổi tiếng của nước Pháp sống ở thế kỉ XIX. Những tác phẩm của ông khắc họa một cách chân thực cuộc sống của từ tầng lớp vương công quý tộc đến những người dân thường nghèo khổ...","cat":"bedtime"},{"id":"ba-nha-hoc-dan","url":"https://truyencotich.top/doc-truyen/ba-nha-hoc-dan","title":"Bá Nha học đàn","summary":"Vào thời Xuân Thu, có một người tên là Du Bá Nha theo Thành Liên tiên sinh học đàn. Chỉ một thời gian ngắn, Bá Nha đã thành thục các ngón đàn, nhưng thầy giáo của ông vẫn cho rằng Bá Nha biểu diễn chưa đủ cảm động lòng người...","cat":"bedtime"},{"id":"abraham-lincoln","url":"https://truyencotich.top/doc-truyen/abraham-lincoln","title":"Abraham Lincoln","summary":"Abraham Lincoln sinh ra trong một gia đình nông dân. Khi Lincoln còn nhỏ, gia đình cậu rất nghèo. Không có tiền đi học, ngày ngày Lincoln phải theo cha đi khai khẩn đất hoang và trồng trọt...","cat":"bedtime"},{"id":"kinh-lup-cua-cao-con","url":"https://truyencotich.top/doc-truyen/kinh-lup-cua-cao-con","title":"Kính lúp của Cáo con","summary":"Mấy hôm nay Hổ bị ốm nên nhờ Cáo cai quản giúp những động vật trong khu rừng. Cáo hí hửng ra mặt, nó thường xuyên đeo một cái kính lúp trước ngực và nghênh ngang đi lại trong rừng...","cat":"bedtime"},{"id":"kho-va-de","url":"https://truyencotich.top/doc-truyen/kho-va-de","title":"Khó và dễ","summary":"Sau khi Columbus tìm ra châu Mỹ, mọi người tổ chức một bữa tiệc để chúc mừng ông. Có một quý tộc nọ cho rằng phát hiện ra một châu lục là chuyện dễ dàng, ai cũng có thể làm được, không có gì là ghê gớm cả...","cat":"bedtime"},{"id":"mai-lan-phuong-luyen-nhan-luc","url":"https://truyencotich.top/doc-truyen/mai-lan-phuong-luyen-nhan-luc","title":"Mai Lan Phương luyện nhãn lực","summary":"Mai Lan Phương là diễn viên kinh kịch nổi tiếng Trung Quốc. Thuở nhỏ, Mai Lan Phương rất yếu ớt, ông còn bị cận thị nhẹ, hai mí mắt sụp xuống, hễ ra gió là chảy nước mắt, nhìn hai mắt ông rất dại, chứ không được tinh nhanh như những đứa trẻ khác...","cat":"bedtime"},{"id":"anh-em-ho-lo","url":"https://truyencotich.top/doc-truyen/anh-em-ho-lo","title":"Anh em Hồ Lô","summary":"Ngày xửa ngày xưa, trên núi Hồ Lô có một con Bọ Cạp Tinh và một con Xà Tinh. Một hôm, có một con Tê Tê không cẩn thận làm vỡ cửa động trên núi, thế là Bọ Cạp Tinh và Xà Tinh chạy ra khỏi hang...","cat":"bedtime"},{"id":"avanti-thong-minh","url":"https://truyencotich.top/doc-truyen/avanti-thong-minh","title":"Avanti thông minh","summary":"Avanti nổi tiếng là một người thông minh, giỏi đối đáp. Một hôm, Avanti mở một xưởng nhuộm, Bayi muốn chơi khăm Avanti, liền đến xưởng nhuộm và nói với ông: Avanti này, nghe nói tay nghề của ông rất giỏi, ông có thể giúp tôi...","cat":"bedtime"},{"id":"nang-tien-hoa-cuc","url":"https://truyencotich.top/doc-truyen/nang-tien-hoa-cuc","title":"Nàng tiên hoa cúc","summary":"Ngày xửa ngày xưa, có một chàng trai tên là A Ngưu sinh sống bên bờ sông Vận Hà. Nhà A Ngưu rất nghèo, năm bảy tuổi, cậu bé mồ côi cha, hai mẹ con cậu bé sống lay lắt qua ngày nhờ những đồng tiền dệt vải của mẹ...","cat":"bedtime"},{"id":"cay-gao-cong-mat-troi","url":"https://truyencotich.top/doc-truyen/cay-gao-cong-mat-troi","title":"Cây gạo cõng mặt trời","summary":"Dòng sông nhỏ chảy qua làm cánh đồng lúa bị tách làm đôi. Đường tách ấy, mùa hè nhuốm màu tím ngát của hoa bèo, mùa thu chuyển màu nước xanh biếc mây trời, mùa đông soi bóng những mảng lá vàng...","cat":"bedtime"},{"id":"pho-tuong-cua-nha-dieu-khac","url":"https://truyencotich.top/doc-truyen/pho-tuong-cua-nha-dieu-khac","title":"Pho tượng của nhà điêu khắc","summary":"Ngày xửa ngày xưa, tại thành phố nhỏ Đuyt-xen-đoóc ở nước Đức có một nhà điêu khắc nổi tiếng, tên gọi Gơ-ru-pen-lô. Tác phẩm của ông đẹp đến nỗi đức vua trị vì thời đó đã đặt nhà điêu khắc một bức chân dung...","cat":"bedtime"},{"id":"lua-loi-ma-noi","url":"https://truyencotich.top/doc-truyen/lua-loi-ma-noi","title":"Lựa lời mà nói","summary":"Một ngày kia, một ông lão loan truyền tin đồn rằng người hàng xóm của ông là một tên trộm. Kết quả là chàng trai trẻ hàng xóm bị cảnh sát bắt...","cat":"bedtime"},{"id":"ai-dang-khen-nhieu-hon","url":"https://truyencotich.top/doc-truyen/ai-dang-khen-nhieu-hon","title":"Ai đáng khen nhiều hơn","summary":"Một nhà kia, có hai anh em Thỏ ở với mẹ. Bố đi làm xa nên cậu nào cũng muốn tỏ ra là đứa bé ngoan, biết thương mẹ nhiều nhất.","cat":"bedtime"},{"id":"ai-biet-an-de","url":"https://truyencotich.top/doc-truyen/ai-biet-an-de","title":"Ai biết ăn dè?","summary":"Một hôm, các con vật nhỏ trong rừng tổ chức cuộc thi vui. Thi ăn.","cat":"bedtime"},{"id":"that-phien-khi-phai-trong-em","url":"https://truyencotich.top/doc-truyen/that-phien-khi-phai-trong-em","title":"Thật phiền khi phải trông em","summary":"Một buổi sáng đẹp trời, Chuột túi mẹ chuẩn bị sang phía rừng bên kia để hái những quả mâm xôi cho món tráng miệng tối nay.","cat":"bedtime"},{"id":"dan-kien-con-ngoan-qua","url":"https://truyencotich.top/doc-truyen/dan-kien-con-ngoan-qua","title":"Đàn kiến con ngoan quá","summary":"Bà kiến đã già, một mình ở trong cái tổ nhỏ dưới mô đất, vừa chật hẹp, vừa ẩm ướt. Mấy hôm nay, bà đau ốm cứ rên hừ hừ...","cat":"bedtime"},{"id":"em-co-xinh-khong","url":"https://truyencotich.top/doc-truyen/em-co-xinh-khong","title":"Em có xinh không?","summary":"Voi em thích mọc đẹp và thích được khen xinh. Ở nhà, voi em luôn hỏi anh: Em có xinh không?","cat":"bedtime"},{"id":"cai-trong-cua-soc","url":"https://truyencotich.top/doc-truyen/cai-trong-cua-soc","title":"Cái trống của Sóc","summary":"Sóc có một cái trống rất to, rất đẹp. Nhưng không vì thế mà Sóc giữ trống chơi một mình. Vào những đêm sáng trăng, Sóc mang trống ra đánh. Mọi vật trong rừng chạy đến, cùng nhảy múa, ca hát theo tiếng trống nhịp nhàng...","cat":"bedtime"},{"id":"cay-gao-ben-ho","url":"https://truyencotich.top/doc-truyen/cay-gao-ben-ho","title":"Cây gạo bên hồ","summary":"Bên bờ hồ có một cây Gạo xòe tán lá trên mặt nước. Một hôm, có hai chú chim đến đậu trên cành, một chú có bộ lông đỏ, một chú có bộ lông vàng...","cat":"bedtime"},{"id":"bac-mai-mo-va-dan-con","url":"https://truyencotich.top/doc-truyen/bac-mai-mo-va-dan-con","title":"Bác mái mơ và đàn con","summary":"Bác Mái Mơ dẫn đàn con ra vườn kiếm ăn. Được ra vườn, đàn gà con túa ra khắp các bụi chuối, các khóm dong riềng, các gốc cây...","cat":"bedtime"},{"id":"lon-con-sach-lam-roi","url":"https://truyencotich.top/doc-truyen/lon-con-sach-lam-roi","title":"Lợn con sạch lắm rồi","summary":"Trong khu rừng nọ có nhiều bạn nhỏ sinh sống: Gấu Con, Thỏ Con, Khỉ Con, Dê Con, Cún Con và Lợn Con...","cat":"bedtime"},{"id":"con-yeu-me","url":"https://truyencotich.top/doc-truyen/con-yeu-me","title":"Con yêu mẹ","summary":"Người mẹ mệt mỏi trở về từ cửa hàng sau một ngày làm việc dài đăng đẵng, kéo lê túi hàng trên sàn bếp. Đang chờ bà là đứa con trai tên David lên 8 tuổi, đang lo lắng kể lại những gì mà em nó đã làm ở nhà...","cat":"bedtime"},{"id":"chu-vet-tinh-khon","url":"https://truyencotich.top/doc-truyen/chu-vet-tinh-khon","title":"Chú vẹt tinh khôn","summary":"Một người lái buôn Ba Tư (Iran ngày nay) trong một chuyến vượt sang Trung Phi mang về một chú vẹt rất đẹp. Chú vẹt có cái mào đỏ và bộ lông xanh biếc óng ánh. Người lái buôn yêu vẹt lắm...","cat":"bedtime"},{"id":"dem-giang-sinh-cam-dong","url":"https://truyencotich.top/doc-truyen/dem-giang-sinh-cam-dong","title":"Đêm giáng sinh cảm động","summary":"Như thường lệ,mỗi mùa giáng sinh, tôi đều nhận được quà từ anh trai của tôi. Giáng sinh năm ấy tôi cảm thấy vui nhất không phải chỉ vì món quà anh tôi tặng-một chiếc xe hơi mà vì tôi đã học được một bài học rất thú vị vào cái đêm đông lạnh lẽo ấy...","cat":"bedtime"},{"id":"phep-tinh-chia","url":"https://truyencotich.top/doc-truyen/phep-tinh-chia","title":"Phép tính chia","summary":"Hương có hai chị em. Hương lên tám, là chị. Còn cậu em tên là Dũng, lên sáu. Bố Hương làm ở một viện khoa học. Còn mẹ Hương là giáo viên mẫu giáo...","cat":"bedtime"},{"id":"choi-hay-ghen-ti","url":"https://truyencotich.top/doc-truyen/choi-hay-ghen-ti","title":"Chổi hay ghen tị","summary":"Trong họ hàng nhà chổi thì có cô bé Chổi Rơm là loại xinh xắn nhất. Cô có chiếc váy vàng óng, không ai đẹp bằng. Áo của cô cũng bằng rơm thóc nếp vàng tươi, được tết săn lại, cuộn từng vòng quanh người, trông cứ như áo len vậy...","cat":"bedtime"},{"id":"nguoi-me-va-than-chet","url":"https://truyencotich.top/doc-truyen/nguoi-me-va-than-chet","title":"Người mẹ và Thần Chết","summary":"Bà mẹ chạy ra ngoài, hớt hải gọi con. Suốt mấy đêm ròng thức trông con ốm, bà vừa thiếp đi một lúc, Thần Chết đã bắt nó đi...","cat":"bedtime"},{"id":"chim-non-khong-ngoan","url":"https://truyencotich.top/doc-truyen/chim-non-khong-ngoan","title":"Chim Non không ngoan","summary":"Có một chú Chim Non sống cùng với mẹ trong một cái tổ nho nhỏ nằm ven rừng. Thật ra thì chú cũng đã lớn rồi. Hai bên cánh đã có những chiếc lông to, dài xen lẫn với đám lông tơ mọc lún phún...","cat":"bedtime"},{"id":"chiec-do-ca","url":"https://truyencotich.top/doc-truyen/chiec-do-ca","title":"Chiếc đó cá","summary":"Trời đã xế chiều, Tiến tha thẩn ra bờ mương chơi. Thấy trong người nóng bức, nó nhảy tùm xuống mương tắm. Đang vùng vẫy, chợt nó thấy lấp ló có chiếc đó của ai be vào mép bờ...","cat":"bedtime"},{"id":"hang-xom-cua-gau-con","url":"https://truyencotich.top/doc-truyen/hang-xom-cua-gau-con","title":"Hàng xóm của Gấu Con","summary":"Đằng sau nhà của Gấu con có một cái cây rất to, không biết từ lúc nào đã có một chú Chim bay đến làm tổ trên cái cây này...","cat":"bedtime"},{"id":"hoc-nhu-cuoc-keu-mua-he","url":"https://truyencotich.top/doc-truyen/hoc-nhu-cuoc-keu-mua-he","title":"Học như cuốc kêu mùa hè","summary":"Ngày xưa, Chích Chòe và Cuốc cùng học một lớp. Chích chòe tuy nhỏ nhưng ngoan ngoãn, chăm chỉ học hành nên được cô giáo yêu, các bạn mến, bố mẹ thương.","cat":"bedtime"},{"id":"meo-con-khong-biet-vang-loi","url":"https://truyencotich.top/doc-truyen/meo-con-khong-biet-vang-loi","title":"Mèo con không biết vâng lời","summary":"Đó là một con mèo tam thể rất đẹp, nhưng cũng rất bướng, không biết nghe lời. Nó còn nhỏ, không biết mẹ nó là ai, chỉ biết cô bé gái thường ôm vuốt ve nó và không bao giờ mắng nó cả.","cat":"bedtime"},{"id":"tai-ai-thinh-nhat","url":"https://truyencotich.top/doc-truyen/tai-ai-thinh-nhat","title":"Tai ai thính nhất?","summary":"Chim Họa Mi bèn lấy một chiếc lá sen to buộc chặt đôi tai của Thỏ lại. Rồi Họa Mi lấy một lá mía buộc chặt vào đầu Rắn, và lấy một lá cỏ buộc đầu Châu Chấu...","cat":"bedtime"},{"id":"mui-lao-xanh-trong-dam-nuoc","url":"https://truyencotich.top/doc-truyen/mui-lao-xanh-trong-dam-nuoc","title":"Mũi Lao Xanh trong đầm nước","summary":"Dưới gốc cây sen già trong đầm nước, Búp Sen đội bùn nhú lên. Nước sóng sánh tẩy sạch bùn nhơ để lộ một ngó sen trắng muốt. Làn mưa rào đầu hạ rắc lộp độp trên mặt đầm khiến búp nụ nôn nao.","cat":"bedtime"},{"id":"mot-cach-dem-thong-minh","url":"https://truyencotich.top/doc-truyen/mot-cach-dem-thong-minh","title":"Một cách đếm thông minh","summary":"Ngày nọ, hoàng đế Akbar đã hỏi các quan cận thần của mình một câu hỏi lạ khiến mọi người vô cùng ngạc nhiên. Không ai biết phải trả lời như thế nào cho đức vua cả...","cat":"bedtime"},{"id":"cai-co-di-don-con-mua","url":"https://truyencotich.top/doc-truyen/cai-co-di-don-con-mua","title":"Cái cò đi đón cơn mưa","summary":"Một hôm, Cò Trắng đang tha thẩn bên bãi sống thì gặp đàn Kiến cỏ. Ơ kìa, sao Kiến lại kéo nhau chạy ngược vào trong đê thế? Cò ngơ ngác hỏi một chị Kiến đang khênh bọc trứng.","cat":"bedtime"},{"id":"nha-buon-va-tho-cat-toc","url":"https://truyencotich.top/doc-truyen/nha-buon-va-tho-cat-toc","title":"Nhà buôn và thợ cắt tóc","summary":"Ngày xửa ngày xưa, có một nhà buôn nọ rất giàu có và tử tế. Thế nhưng, do một sự cố đáng tiếc, ông ta bị mất tất cả gia sản và trở nên nghèo khổ. Kể từ đó, không còn ai muốn làm bạn với ông ta nữa..","cat":"bedtime"},{"id":"dien-thanh-va-co-gung","url":"https://truyencotich.top/doc-truyen/dien-thanh-va-co-gung","title":"Điền thanh và Cỏ gừng","summary":"Vào một ngày mưa kia, ở giữa hai luống khoai lang mọc lên từng khóm cây lăn tăn, xanh rờn...","cat":"bedtime"},{"id":"sao-se-va-chich-bong","url":"https://truyencotich.top/doc-truyen/sao-se-va-chich-bong","title":"Sáo, Sẻ và Chích Bông","summary":"Từ thuở xa xưa, Sáo, Sẻ và Chích Bông cùng sống chung với nhau trong một khu vườn. Ba loài chim này thường cùng nhau đi, cùng đến và cùng làm ăn sinh sống với nhau.","cat":"bedtime"},{"id":"me-con-nha-chuoi","url":"https://truyencotich.top/doc-truyen/me-con-nha-chuoi","title":"Mẹ con nhà Chuối","summary":"Gió ào qua khu vườn. Chuối con run rẩy nép sát vào mẹ. Lớn tướng rồi mà nó vẫn chưa hết sợ cái lão Gió bấc có ngọn roi giá buốt này. Tấm áo mỏng tang trên mình nó chưa đủ che kín thân.","cat":"bedtime"},{"id":"thua-co-tu-nhien-no-nhu-the-day-a","url":"https://truyencotich.top/doc-truyen/thua-co-tu-nhien-no-nhu-the-day-a","title":"Thưa cô, tự nhiên nó như thế đấy ạ!","summary":"Khướu là một cậu học sinh lém lỉnh. Trong lớp, lẽ ra ngồi nghe cô giáo giảng bài và chăm chú theo dõi cô viết trên bảng thì cậu bé hết quay sang bên phải lại xoay sang trai ba hoa chuyện trò với bạn.","cat":"bedtime"},{"id":"mon-qua-tang-me","url":"https://truyencotich.top/doc-truyen/mon-qua-tang-me","title":"Món quà tặng mẹ","summary":"Tôi vội vã bước vào tiệm trong mall để sắm khẩn cấp mấy món qùa giáng sinh vào phút cuối cho đứa con gái. Kinh hãi nhìn đám đông, có lẽ tôi sẽ bị kẹt trong tiệm đến muôn đời, trong khi việc phải làm còn chồng chất...","cat":"bedtime"},{"id":"edison-va-ba-me","url":"https://truyencotich.top/doc-truyen/edison-va-ba-me","title":"Edison và bà mẹ","summary":"Hôm đó, Edison vừa đi ra ga thì mẹ ở nhà nổi cơn đau bụng dữ dội. Bố còn bận đi làm...","cat":"bedtime"},{"id":"ga-to-di-hoc","url":"https://truyencotich.top/doc-truyen/ga-to-di-hoc","title":"Gà Tơ đi học","summary":"Các bạn nhỏ dựng trại bên bờ hồ nước trong xanh và múa hát thật vui vẻ. Bỗng Cún Bông vểnh tai lắng nghe: hình như có tiếng ai khóc ở đâu đây… Cả lớp ùa đi tìm thì thấy Gà Tơ đang ngồi khóc thút thít bên bụi duối.","cat":"bedtime"},{"id":"bup-mang-non","url":"https://truyencotich.top/doc-truyen/bup-mang-non","title":"Búp Măng non","summary":"Bé đã bao giờ mhìn thấy tre chưa? Cây tre mọc thẳng, dáng cao cao, lá nhòn nhọn, trông rất đẹp. Bất kể trời gió lớn mưa to, tre vẫn thẳng vút, không bao giờ ngả nghiêng.","cat":"bedtime"},{"id":"do-dung-de-o-dau","url":"https://truyencotich.top/doc-truyen/do-dung-de-o-dau","title":"Đồ dùng để ở đâu?","summary":"Minh nhìn lên đồng hồ. Đã đến giờ đi học. Minh cuống cuồng tìm quần áo để mặc. Nhưng chú bé không thấy quần dài, không thấy áo, không thấy dép đâu cả.","cat":"bedtime"},{"id":"bong-sen-trong-gieng-ngoc","url":"https://truyencotich.top/doc-truyen/bong-sen-trong-gieng-ngoc","title":"Bông sen trong giếng ngọc","summary":"Ngày xưa, cách đây gần bảy trăm năm, có cậu bé Mạc Đĩnh chi con nhà nghèo, người đen đủi xấu xí. Tuy còn nhỏ, nhưng ngày nào Mạc Đĩnh Chi cũng vào rừng kiếm củi giúp đỡ cha mẹ.","cat":"bedtime"},{"id":"cau-chuyen-be-cham","url":"https://truyencotich.top/doc-truyen/cau-chuyen-be-cham","title":"Câu chuyện bé Chăm","summary":"Bé Chăm rất chăm làm nhưng cũng mau chán việc. Làm việc này chưa xong, em lại bỏ dở để làm việc khác.","cat":"bedtime"},{"id":"ngon-duoc-song-le-van-tam","url":"https://truyencotich.top/doc-truyen/ngon-duoc-song-le-van-tam","title":"Ngọn đuốc sống Lê Văn Tám","summary":"Được quân Anh che chở và giúp sức, ngày 23 tháng 9 năm 1945, giặc Pháp nổ súng ở Sài Gòn, hòng trở lại cướp nước ta. Nhân dân Sài Gòn sôi sục căm thù, xông lên đánh trả quân xâm lược.","cat":"bedtime"},{"id":"nha-bac-hoc-va-ba-cu","url":"https://truyencotich.top/doc-truyen/nha-bac-hoc-va-ba-cu","title":"Nhà bác học và bà cụ","summary":"Edison là một nhà bác học nổi tiếng người Mỹ, đã có nhiều phát minh khoa học lớn. Ông đã góp phần hoàn chỉnh máy điện báo, điện thoại, bóng đèn điện, đèn ống, máy ghi âm, xe điện, máy chiếu phim, v.v…","cat":"bedtime"},{"id":"chim-va-ga","url":"https://truyencotich.top/doc-truyen/chim-va-ga","title":"Chim và Gà","summary":"Tiếng hót dứt, đôi gà bay lên cửa sổ, gần chỗ lồng chim. Bằng giọng vừa khâm phục vừa ngượng nghịu của kẻ lần đầu làm quen thân với một nhân vật đầy tài năng...","cat":"bedtime"},{"id":"ga-va-cao","url":"https://truyencotich.top/doc-truyen/ga-va-cao","title":"Gà và Cáo","summary":"Lão Cáo đang đi chợt nghe tiếng Gà rừng con khóc lóc ven rừng! Hay quá! Lại được chén rồi!","cat":"bedtime"},{"id":"chim-son-ca-va-cu-cu","url":"https://truyencotich.top/doc-truyen/chim-son-ca-va-cu-cu","title":"Chim Sơn Ca và Cu Cu","summary":"Nghe vợ, nhớ cả lời bạn, hơn nữa thật khó phân biệt Sơn Ca với Cu Cu sơ sinh, vì thế lòng Sơn Ca chồng dịu lại.","cat":"bedtime"},{"id":"tieng-keu-cuu","url":"https://truyencotich.top/doc-truyen/tieng-keu-cuu","title":"Tiếng kêu cứu","summary":"Bác Gấu bứt quả trên cây, mấy người thợ săn tới. Đàn Gà Rừng, trước khi bay, còn “quác, quác, quác” báo hiệu, bác Gấu chạy thoát.","cat":"bedtime"},{"id":"ban-chan-ong-noi","url":"https://truyencotich.top/doc-truyen/ban-chan-ong-noi","title":"Bàn chân ông nội","summary":"Cu Sún nhìn hai bàn chân ông nội ngâm trong chậu nước ấm pha muối, nó ngạc nhiên quá đi mất. Tại sao bàn chân ông nội lại dài và to thế kia nhỉ?","cat":"bedtime"},{"id":"chiec-la-non","url":"https://truyencotich.top/doc-truyen/chiec-la-non","title":"Chiếc Lá Non","summary":"Buổi sáng cuối xuân, ánh nắng tơ hồng óng ánh trải xuống khắp khu vườn. Những cô Ong áo chẽn vàng đang mải miết lấy phấn hoa. Các cô vừa làm vừa hát...","cat":"bedtime"},{"id":"tieng-hat-cua-chau-chang","url":"https://truyencotich.top/doc-truyen/tieng-hat-cua-chau-chang","title":"Tiếng hát của Chẫu Chàng","summary":"Lớp học của cô Sẻ Nâu trên giàn mướp, bên cạnh một cái ao nhỏ. Học trò của cô nhiều lắm: Ong Bầu này, Ong Mật này, Bướm Vàng, Bướm Trắng này,… Ai cũng xinh đẹp, cũng ngoan ngoãn.","cat":"bedtime"},{"id":"nhung-chu-be-khong-chet","url":"https://truyencotich.top/doc-truyen/nhung-chu-be-khong-chet","title":"Những chú bé không chết","summary":"Phát xít Đức ồ ạt đưa quân sang xâm lược Liên Xô. Đến đâu, chúng cũng cướp phá, bắn giết hết sức tàn bạo…","cat":"bedtime"},{"id":"chuyen-cua-may","url":"https://truyencotich.top/doc-truyen/chuyen-cua-may","title":"Chuyện của mây","summary":"Trên trời có một đám mây xinh đẹp, suốt ngày nhởn nhơ bay lượn. Nhưng bay mãi một mình, mây cũng cảm thấy buồn. Mây chợt nhớ tới chị gió, vội bay đi tìm chị.","cat":"bedtime"},{"id":"ga-nau-va-vit-xam","url":"https://truyencotich.top/doc-truyen/ga-nau-va-vit-xam","title":"Gà nâu và Vịt xám","summary":"Gà nâu và Vịt xám là đôi bạn thân. Hàng ngày chúng ríu rít vượt sông cạn để kiếm ăn.","cat":"bedtime"},{"id":"ban-chan-ki-dieu","url":"https://truyencotich.top/doc-truyen/ban-chan-ki-dieu","title":"Bàn chân kì diệu","summary":"Một buổi sáng, trời đ���p, cô giáo Cương đến lớp sớm. Cô đang chuẩn bị để viết trước bài học vần lên bảng thì thấy một em bé thập thò ngoài cửa.","cat":"bedtime"},{"id":"con-chim-nho","url":"https://truyencotich.top/doc-truyen/con-chim-nho","title":"Con chim nhỏ","summary":"Seryozha (Xi-ri-ô-gia) mừng ngày sinh của mình. Em nhận được bao nhiêu là đồ chơi: chó sói, ngựa, tranh ảnh,… Nhưng thích nhất là chiếc lưới bẫy chim của người anh họ gửi cho.","cat":"bedtime"},{"id":"lac-dan","url":"https://truyencotich.top/doc-truyen/lac-dan","title":"Lạc đàn","summary":"Nhà Kiến ở ven sông, sâu trong một hẻm đá. Thật đông và vui. Hằng ngày, theo chân Kiến chúa, cả đàn rời tổ từ sáng sớm để tìm kiếm thức ăn. Dòng họ Kiến sống vốn có kỉ luật nên đi đâu cũng thành đàn thành lũ.","cat":"bedtime"},{"id":"oc-sen-gianh-giai-dac-biet","url":"https://truyencotich.top/doc-truyen/oc-sen-gianh-giai-dac-biet","title":"Ốc Sên giành giải đặc biệt","summary":"Cứ ba năm một lần, trong khu rừng lại tổ chức một cuộc thi chạy, cuộc thi năm nay đã là lần thứ bảy rồi đấy. Các động vật trong khu rừng đều tham gia thi chạy nên không khí cạnh tranh rất sôi nổi...","cat":"bedtime"},{"id":"ong-va-rua","url":"https://truyencotich.top/doc-truyen/ong-va-rua","title":"Ong và Rùa","summary":"Buổi sáng, ông Mặt Trời như chiếc mâm lửa từ từ nhô lên ở phía đằng đông.","cat":"bedtime"},{"id":"meo-vang-thi-hat","url":"https://truyencotich.top/doc-truyen/meo-vang-thi-hat","title":"Mèo Vàng thi hát","summary":"Cứ đến kỳ ông trăng trở lại trên bầu trời, như chiếc đĩa bằng bạc xinh xẻo, tỏa ánh sáng mát dịu trên làng mạc, cây cỏ, thì các con vật trong làng lại rủ nhau ra gốc đa thi hát.","cat":"bedtime"},{"id":"loi-hua-cua-sau-rom","url":"https://truyencotich.top/doc-truyen/loi-hua-cua-sau-rom","title":"Lời hứa của sâu róm","summary":"Lời đã nói ra, phải nhớ lấy mặc dù nó chỉ là sâu róm. Lập tức nó bò lên một cây cao, từ thân cây bò ra cành lớn, từ cành lớn bò ra cành nhỏ, từ cành nhỏ bò lên nhánh, từ nhánh bò ra lá.","cat":"bedtime"},{"id":"soc-nau-di-hoc","url":"https://truyencotich.top/doc-truyen/soc-nau-di-hoc","title":"Sóc Nâu đi học","summary":"Buổi sáng mùa thu hôm ấy, khu rừng nguyên sinh rộn ràng tiếng reo cười của chim muông hoa cỏ và thú rừng… Bởi hôm nay là lễ hội khai trường. Riêng Sóc Nâu đang ở trong một tâm trạng nôn nao khó tả vì đây là lần đầu tiên Sóc Nâu đi học.","cat":"bedtime"},{"id":"ngay-vui-cua-be","url":"https://truyencotich.top/doc-truyen/ngay-vui-cua-be","title":"Ngày vui của Bé","summary":"Cúc cúc cúc… úc… Bé vừa tròn môi gọi vừa rải nắm gạo ra sân cho bầy gà con quây tụ lại. Chỉ loáng một cái là gà mẹ đã tập hợp đàn con một cách đông đủ.","cat":"bedtime"},{"id":"ca-vuot-de","url":"https://truyencotich.top/doc-truyen/ca-vuot-de","title":"Cá vượt đẻ","summary":"Bà Ba cẩn thận xem lại đôi quang thúng, buộc chặt thùng dầu hoả, thùng nước mắm vào để quang, lắc lắc xem có bị xô nghiêng hay không. Mưa gió là việc của trời, nhưng việc kiếm cơm của các gia đình nghèo thì không ngừng được","cat":"bedtime"},{"id":"chu-vit-bau","url":"https://truyencotich.top/doc-truyen/chu-vit-bau","title":"Chú vịt bầu","summary":"Nhìn thân hình gầy guộc của mẹ, Mai muốn ứa nước mắt. Em biết mẹ nói thoái đi như thế cho mình yên tâm chứ không thuốc men thì làm sao khỏi bệnh được.","cat":"bedtime"},{"id":"ho-guong","url":"https://truyencotich.top/doc-truyen/ho-guong","title":"Hồ Gương","summary":"Có một hồ nước rộng, trông thấy đáy. Những khi gió nhẹ mặt hồ phẳng lặng như gương. Một chú Chim nhỏ bay qua thấy bóng mình dưới nước, bèn cất tiếng","cat":"bedtime"},{"id":"bua-tiec-trong-rung","url":"https://truyencotich.top/doc-truyen/bua-tiec-trong-rung","title":"Bữa tiệc trong rừng","summary":"Mùa thu đã về, bầu trời trong vắt, không một gợn mây. Không khí trong sạch, thơm ngát mùi hoa dại. Các con vật và chim muông trong rừng vui hẳn lên. Chúng rủ nhau mở hội mừng mùa quả chín.","cat":"bedtime"},{"id":"chiec-ruong-than","url":"https://truyencotich.top/doc-truyen/chiec-ruong-than","title":"Chiếc rương thần","summary":"Cái Vân nóng ruột đợi bố đi công tác về. Bố đã hứa kì này cái Vân đạt học sinh giỏi, bố sẽ thưởng một món quà thật dễ thương. Một con búp bê xinh xắn có váy hồng, hay một chú chó bông trắng muốt, mắt long lanh như hai viên bi.","cat":"bedtime"},{"id":"cau-be-va-ong-gia-cho-thue-sach","url":"https://truyencotich.top/doc-truyen/cau-be-va-ong-gia-cho-thue-sach","title":"Cậu bé và ông già cho thuê sách","summary":"Một buổi trưa… vào giờ tan tầm, bác thợ sửa xe đạp đầu phố thấy một cậu bé đạp xe đi tới đi lui mấy lần.","cat":"bedtime"},{"id":"khuat-phuc-ten-cuop-bien","url":"https://truyencotich.top/doc-truyen/khuat-phuc-ten-cuop-bien","title":"Khuất phục tên cướp biển","summary":"Tên chúa tàu ấy cao lớn, vạm vỡ, da lưng sạm như gạch nung. Trên má hắn có một vết sẹo chém dọc xuống, trắng bệch. Hắn uống lắm rượu đến nỗi nhiều đêm như lên cơn loạn óc, ngồi hát những bài ca man rợ.","cat":"bedtime"},{"id":"vien-gach-so-lua","url":"https://truyencotich.top/doc-truyen/vien-gach-so-lua","title":"Viên gạch sợ lửa","summary":"Đã lâu lắm rồi, chẳng ai nhớ nơi ấy là đâu nữa, có một cái lò nung gạch đứng giữa cánh đồng lúa, trông như một tòa thành cổ kính.","cat":"bedtime"},{"id":"be-nam-va-con-rua-ho-guom","url":"https://truyencotich.top/doc-truyen/be-nam-va-con-rua-ho-guom","title":"Bé Nam và con rùa Hồ Gươm","summary":"Bé Nam đang đứng tránh mưa trong một cái tháp nhỏ ở một góc bờ Hồ Gươm gần ngã tư đường Tràng Thi và đường Lê Thái Tổ...","cat":"bedtime"},{"id":"cuoc-hop-cua-chu-viet","url":"https://truyencotich.top/doc-truyen/cuoc-hop-cua-chu-viet","title":"Cuộc họp của chữ viết","summary":"Vừa tan học, các chữ cái và dấu câu đã ngồi lại họp. Bác Chữ A dõng dạc mở đầu.","cat":"bedtime"},{"id":"chuyen-o-vuon-hoa","url":"https://truyencotich.top/doc-truyen/chuyen-o-vuon-hoa","title":"Chuyện ở vườn hoa","summary":"Bé Ngân thích nhất là mỗi buổi chiều được ông nội cho đi đến câu lạc bộ hưu trí ở cạnh vườn hoa. Trong khi ông chơi cờ, đánh cầu lông thì Ngân tha hồ chơi đu quay, cầu trượt, bập bênh cùng các bạn.","cat":"bedtime"},{"id":"chu-bo-ba-bot","url":"https://truyencotich.top/doc-truyen/chu-bo-ba-bot","title":"Chú bò Ba Bớt","summary":"Ba Bớt là con bò đẹp. Ở nó hội đủ các tiêu chuẩn: mình thon, chân cao, mắt sáng, lông mượt, sừng khoẻ, dáng đi oai vệ. Giữa cái trán rộng màu hạt dẻ nổi lên ba cái bớt màu trắng, thế nên nó có tên là Ba Bớt.","cat":"bedtime"},{"id":"chiec-den-long","url":"https://truyencotich.top/doc-truyen/chiec-den-long","title":"Chiếc đèn lồng","summary":"Bác đom đóm già ngồi nhìn bầy đom đóm nhỏ tuổi rước đèn lồng làm sáng rực cả con đường. Trông chúng giống như những ngôi sao nhỏ lấp lánh.","cat":"bedtime"},{"id":"chu-do-con","url":"https://truyencotich.top/doc-truyen/chu-do-con","title":"Chú Đỗ con","summary":"Một chú Đỗ con ngủ khì trong cái chum khô ráo và tối om suốt một năm. Một hôm tỉnh dậy chú thấy mình nằm giữa những hạt đất li ti xôm xốp. Chợt có tiếng lộp độp bên ngoài.","cat":"bedtime"},{"id":"ca-map-va-ca-kiem","url":"https://truyencotich.top/doc-truyen/ca-map-va-ca-kiem","title":"Cá Mập và Cá Kiếm","summary":"Một hôm, Cá Kiếm mẹ đưa con đến một khe đá, bảo cá con ở yên một chỗ để cá mẹ đi kiếm ăn. Một lát sau, một con Cá Mập đến cửa khe đá, khóc lóc nói với cá con...","cat":"bedtime"},{"id":"cau-be-will-va-chiec-gay","url":"https://truyencotich.top/doc-truyen/cau-be-will-va-chiec-gay","title":"Cậu bé Will và chiếc gậy","summary":"Will là một cậu bé da đen nhút nhát. Cậu bé đã 7 tuổi rồi mà rất ít khi dám ra ngoài một mình.","cat":"bedtime"},{"id":"nguoi-ban-bi-an","url":"https://truyencotich.top/doc-truyen/nguoi-ban-bi-an","title":"Người bạn bí ẩn","summary":"Khi Thỏ con còn rất nhỏ, một năm nọ, vào mùa xuân, cây cối tươi tốt, Thỏ mẹ dẫn Thỏ con đến sườn núi chơi, Thỏ mẹ còn tự tay gieo một hạt giống cây xuống đất...","cat":"bedtime"},{"id":"bac-si-go-kien","url":"https://truyencotich.top/doc-truyen/bac-si-go-kien","title":"Bác sĩ Gõ Kiến","summary":"Bác sĩ Gõ Kiến là bạn của núi rừng. Bác sĩ đi đến đâu cũng râm ran tiếng chào hỏi.","cat":"bedtime"},{"id":"chim-sau-xu-an","url":"https://truyencotich.top/doc-truyen/chim-sau-xu-an","title":"Chim sâu xử án","summary":"Chim Sẻ kiện Chim Khuyên! Cái tin ấy bay đi như gió. Khắp vườn cây nhớn nhác cả lên.","cat":"bedtime"},{"id":"cun-con-di-lac","url":"https://truyencotich.top/doc-truyen/cun-con-di-lac","title":"Cún con đi lạc","summary":"Có một cậu bé bị mất con cún con yêu quý của mình và tìm kiếm xung quanh. Cậu bé đã tìm khắp căn nhà nhưng không thấy cún đâu cả. Cậu đi lang thang khắp nơi từ sáng đến tối nhưng vẫn không tìm thấy...","cat":"bedtime"},{"id":"chuyen-ke-ve-luong-the-vinh","url":"https://truyencotich.top/doc-truyen/chuyen-ke-ve-luong-the-vinh","title":"Chuyện kể về Lương Thế Vinh","summary":"Thủa nhỏ, Lương Thế Vinh trọ học ở phía nam kinh thành. Vinh rất thông minh, học hành chóng giỏi. Trong khi chơi đùa với các bạn, Vinh cũng tìm được nhiều trò chơi lí thú.","cat":"bedtime"},{"id":"chu-nga-co-dau-khong","url":"https://truyencotich.top/doc-truyen/chu-nga-co-dau-khong","title":"Chú ngã có đau không?","summary":"Vào đầu năm 1954, tiết trời đã sang xuân, nhưng ở Việt Bắc vẫn còn rét. Gió bấc thổi mạnh, mưa phùn lâm râm gây nên cái lạnh buốt, Bác vẫn làm việc rất khuya.","cat":"bedtime"},{"id":"hoa-ngu-sac-than-ki","url":"https://truyencotich.top/doc-truyen/hoa-ngu-sac-than-ki","title":"Hoa ngũ sắc thần kì","summary":"Ngày xửa ngày xưa, có một cô bé tên là Trân Trân. Cô bé thường ngắm nhìn chú mèo con nhà hàng xóm chơi đùa vui vẻ, nhưng thực ra cô bé lại chưa biết niềm vui là gì...","cat":"bedtime"},{"id":"niem-vui-bat-ngo","url":"https://truyencotich.top/doc-truyen/niem-vui-bat-ngo","title":"Niềm vui bất ngờ","summary":"Vào một buổi sáng nắng đẹp, cô giáo Mỹ dẫn các cháu mẫu giáo đi chơi vườn Bách thảo. Đi đến vườn Bách thảo phải đi qua Phủ Chủ tịch là nơi Bác Hồ sống và làm việc ở đấy.","cat":"bedtime"},{"id":"buc-tranh-cu-gia-ngoi-cau-ca","url":"https://truyencotich.top/doc-truyen/buc-tranh-cu-gia-ngoi-cau-ca","title":"Bức tranh cụ già ngồi câu cá","summary":"Vào đầu tháng 3 năm 1958, cửa hàng cụ Chinh bỗng dưng tấp nập hẳn lên. Khách đến mua tranh, đặt tranh không lúc nào ngớt. Ai cũng năn nỉ đòi mua cho kì được bức tranh “Cụ già câu cá”.","cat":"bedtime"},{"id":"chiec-vong-bac","url":"https://truyencotich.top/doc-truyen/chiec-vong-bac","title":"Chiếc vòng bạc","summary":"Do điều kiện công tác, sau hơn 2 năm, Bác Hồ mới có dịp trở lại Cao Bằng nơi Người từng sống và làm việc. Thấy Bác về, bà con già, trẻ, gái, trai khắp bản ùa ra đón Bác.","cat":"bedtime"},{"id":"bop-nat-qua-cam","url":"https://truyencotich.top/doc-truyen/bop-nat-qua-cam","title":"Bóp nát quả cam","summary":"Giặc Nguyên cho sứ thần sang giả vờ mượn đường để xâm chiếm nước ta. Thấy sứ giặc ngang ngược đủ điều, Trần Quốc Toản vô cùng căm giận.","cat":"bedtime"},{"id":"ech-xanh-tim-bac-si","url":"https://truyencotich.top/doc-truyen/ech-xanh-tim-bac-si","title":"Ếch xanh tìm bác sĩ","summary":"Ếch mẹ tìm thấy một thung lũng có phong cảnh rất đẹp, liền đẻ trứng xuống con suối nhỏ trong thung lũng, chờ đến khi những quả trứng nở thành nòng nọc, nó mới rời khỏi nơi đó...","cat":"bedtime"},{"id":"doi-ban-tay-vang","url":"https://truyencotich.top/doc-truyen/doi-ban-tay-vang","title":"Đôi bàn tay vàng","summary":"Tôn Thất Tùng sinh năm 1912 trong một gia đình thuộc hoàng tộc. Là một thanh niên đẹp trai và thông minh, được nhiều gia đình quý tộc săn đón, nhưng anh chỉ chuyên tâm học hành.","cat":"bedtime"},{"id":"nguoi-con-gai-mien-dat-do","url":"https://truyencotich.top/doc-truyen/nguoi-con-gai-mien-dat-do","title":"Người con gái miền đất đỏ","summary":"Buổi trưa năm 1947, giữa những lô cao su thẳng tắp, cô bé 14 tuổi Võ Thị Sáu úp mặt vào một thân cây khóc rưng rức. Sáng nay, giặc Pháp tràn qua Bà Rịa. Bọn giặc tàn ác vây chợ, đốt làng, giết hại bao người.","cat":"bedtime"},{"id":"nguoi-tho-san-va-nhung-chu-chim-bo-cau","url":"https://truyencotich.top/doc-truyen/nguoi-tho-san-va-nhung-chu-chim-bo-cau","title":"Người thợ săn và những chú chim bồ câu","summary":"Ở ngoài một ngôi làng nọ, có một cây đa rất lớn. Phía trên cây, có nhiều loại chim khác nhau làm tổ. Còn dưới những tán lá, khách bộ hành thường ngồi lại nghỉ ngơi sau khi đi một chặng đường dài...","cat":"bedtime"},{"id":"troi-biet-dat-biet-ta-biet","url":"https://truyencotich.top/doc-truyen/troi-biet-dat-biet-ta-biet","title":"Trời biết, đất biết, ta biết","summary":"Năm 1504, vua Lê Hiến Tông băng hà, di chiếu lập người con thứ ba tên là Thuần (tức vua Túc Tông sau này), chứ không lập con thứ hai là Tuấn (tức vua Uy Mục sau này), vì người con này bất tài, vô đạo.","cat":"bedtime"},{"id":"nhan-cach-quy-hon-tien-bac","url":"https://truyencotich.top/doc-truyen/nhan-cach-quy-hon-tien-bac","title":"Nhân cách quý hơn tiền bạc","summary":"Mạc Đĩnh Chi (1272 -1346) quê ở huyện Chí Linh, tỉnh Hải Dương, thi đỗ Trạng nguyên năm 1304. Mạc Đĩnh Chi làm quan trải qua ba triều nhà Trần. Ông thông minh, giỏi thơ văn và có tài đối đáp rất sắc bén.","cat":"bedtime"},{"id":"anh-hung-nho-tuoi-diet-xe-tang","url":"https://truyencotich.top/doc-truyen/anh-hung-nho-tuoi-diet-xe-tang","title":"Anh hùng nhỏ tuổi diệt xe tăng","summary":"Lai là một thiếu nhi nhà nghèo. Cha đau ốm, em phải đi thay cha lèn đồn làm phu phen tạp dịch cho bọn Mĩ – Ngụy.","cat":"bedtime"},{"id":"nguoi-con-gai-do-dau-cua-bac-ho","url":"https://truyencotich.top/doc-truyen/nguoi-con-gai-do-dau-cua-bac-ho","title":"Người con gái đỡ đầu của Bác Hồ","summary":"Vào một buổi sáng mùa thu năm 1990, trong đoàn người vào thăm nhà sàn Bác Hồ có hai cha con người Pháp. Đó là ông Ô-brắc và con gái ông, chị Ba-bét, người con gái đỡ đầu của Bác Hồ.","cat":"bedtime"},{"id":"doi-canh-cua-ngua-trang","url":"https://truyencotich.top/doc-truyen/doi-canh-cua-ngua-trang","title":"Đôi cánh của ngựa trắng","summary":"Ngày xưa khi chưa trở về ở với người, ngựa họp thành đàn ởgần rừng. Trên những bãi cỏ xanh rờn, các chú ngựa non tha hồ chạy nhảy, ngày này qua ngày khác.","cat":"bedtime"},{"id":"doi-guoc-bo-quen","url":"https://truyencotich.top/doc-truyen/doi-guoc-bo-quen","title":"Đôi guốc bỏ quên","summary":"Sáng nay cu Việt kêu mệt. Mẹ sờ trán con. Ừ, quả thực đầu Việt có hâm hấp nóng. Mẹ nói với bố đi ngang qua trường xin phép cho cu Việt nghỉ học ngày hôm nay. Đắp chăn cẩn thận và dặn dò con xong, bố mẹ sửa soạn đi làm.","cat":"bedtime"},{"id":"dieu-khong-tinh-truoc","url":"https://truyencotich.top/doc-truyen/dieu-khong-tinh-truoc","title":"Điều không tính trước","summary":"Tôi chuẩn bị đánh nhau. Thoạt đầu tôi định lấy con dao của mẹ tôi làm vũ khí, nhưng khi sờ đến cái lưỡi thép to bản và mát lạnh của nó, tôi đâm ra sờ sợ làm sao! Con dao này mà vung lên một phát là địch thủ ngã như chơi.","cat":"bedtime"},{"id":"thay-giao-day-ve","url":"https://truyencotich.top/doc-truyen/thay-giao-day-ve","title":"Thầy giáo dạy vẽ","summary":"Tôi muốn kể với các em về thầy giáo dạy vẽ của tôi. Thầy dạy chúng tôi cách đây đã mười bảy năm, khi đó chúng tôi mới học lớp 5, mà thầy thì mái tóc đã bạc phơ…","cat":"bedtime"},{"id":"hai-lan-ban-hoc-tung-hung","url":"https://truyencotich.top/doc-truyen/hai-lan-ban-hoc-tung-hung","title":"Hai lần bàn học tưng hửng","summary":"Bàn Học biêt thừa là cái bút ấy của một chú học viên bổ túc bỏ quên tối qua. Cô cậu nào thấy nó đẹp, nhận vơ là của mình thì… Bàn Học sẽ kêu thật to cho bẽ mặt. Sẽ biết tay nhau.","cat":"bedtime"},{"id":"bo-long-ruc-ro-cua-chim-thien-duong","url":"https://truyencotich.top/doc-truyen/bo-long-ruc-ro-cua-chim-thien-duong","title":"Bộ lông rực rỡ của chim thiên đường","summary":"Chim Thiên Đường đi tha rác về lót ổ, chuẩn bị cho mùa đông đang tới gần. Nó bay rất xa, chọn những chiếc lá vàng, lá đỏ thật đẹp, những ngọn cỏ thật thơm, thật mềm.","cat":"bedtime"},{"id":"dot-chay-dong-lua-chin","url":"https://truyencotich.top/doc-truyen/dot-chay-dong-lua-chin","title":"Đốt cháy đồng lúa chín","summary":"Ngày xưa có một cụ già sống trên một ngọn núi cao ở Nhật Bản. Chung quanh nhà cụ, ruộng nương bằng phẳng và phì nhiêu. Ruộng nương đó thuộc về cư dân của một làng nhỏ dưới chân núi dọc ven biển.","cat":"bedtime"},{"id":"hat-dau-thom","url":"https://truyencotich.top/doc-truyen/hat-dau-thom","title":"Hạt đậu thơm","summary":"Một người cha có ba cậu con trai. Hằng ngày, người cha lên rừng đốn củi, để lại cho các con một bát đậu đã luộc để ăn.","cat":"bedtime"},{"id":"cu-ton","url":"https://truyencotich.top/doc-truyen/cu-ton","title":"Cu Tỏn","summary":"Con rạch Cái Gia khá rộng, nước từ sông chảy vào ra cùng hai buổi lớn, ròng. Cứ mỗi năm nghỉ hè, thằng Bách lại về đây chơi suốt một tháng.","cat":"bedtime"},{"id":"cai-gai-va-ba-cu-mit","url":"https://truyencotich.top/doc-truyen/cai-gai-va-ba-cu-mit","title":"Cái gái và bà cụ Mít","summary":"Bà cụ Mít già lụ khụ lưng còng gập xuống, tóc bạc trắng như cước, sống một mình trong cái quán nhỏ dưới gốc đa cổ thụ đầu làng. Hằng ngày cụ nâu nước chè để bán nên trong làng gọi là “quán cụ Mít”.","cat":"bedtime"},{"id":"que-diem-tu-chay","url":"https://truyencotich.top/doc-truyen/que-diem-tu-chay","title":"Que diêm tự cháy","summary":"Chúng ta đã biết người nguyên thủy từng đập đá lấy lửa, từng truyền giữ lửa như báu vật. Và thực tế “thần lửa” luôn luôn được mọi người tôn thờ.","cat":"bedtime"},{"id":"lu-i-pa-xto-va-em-be","url":"https://truyencotich.top/doc-truyen/lu-i-pa-xto-va-em-be","title":"Lu-i Pa-xtơ và em bé","summary":"Năm 1885, một sự kiện đáng ghi vào lịch sử nhân loại : Em bé Giô-dép Mây-xte, chín tuổi, bị chó dại cắn, được mẹ em đưa từ vùng quê An-dát xa xôi đến thủ đô Pa-ri nhờ Lu-i Pa-xtơ cứu chữa.","cat":"bedtime"},{"id":"thi-nhac","url":"https://truyencotich.top/doc-truyen/thi-nhac","title":"Thi nhạc","summary":"Hôm nay, một ngày đáng ghi nhớ, sau bao năm dốc toàn tâm lực dạy dỗ, giờ đây ông sẽ thấy kết quả của mình.","cat":"bedtime"},{"id":"hoi-vo-mua-xuan","url":"https://truyencotich.top/doc-truyen/hoi-vo-mua-xuan","title":"Hội võ mùa xuân","summary":"Mùa xuân năm 1753. Cây đào cổ thụ bên lễ đài thi võ đang trổ hoa đỏ thắm. Lễ đài được trang hoàng rực rỡ. Cờ xí rợp trời. Trên khán đài, đức vua Lê Hiển Tông, chúa Trịnh Doanh và đông đủ các quan đại thần đã tề tựu.","cat":"bedtime"},{"id":"ca-di-an-the","url":"https://truyencotich.top/doc-truyen/ca-di-an-the","title":"Cá đi ăn thề","summary":"Cứ khi mưa mới về thì có từng đàn cá đi chơi. Người ta bảo mưa mới xuống là hội, là tết của họ nhà cá.","cat":"bedtime"},{"id":"van-co-dau-xuan","url":"https://truyencotich.top/doc-truyen/van-co-dau-xuan","title":"Ván cờ đầu xuân","summary":"Mới mười ba tuổi mà thằng Hiển đa nổi danh là một tay cao thủ cờ tướng. Thoạt đầu thằng Hiển tập chơi với anh nó ở nhà, rồi do mê cờ, nó mua thêm sách dạy đánh cờ tướng về nghiên cứu các thế “độc chiêu”.","cat":"bedtime"},{"id":"lam-pla-ti-ni-den-cung","url":"https://truyencotich.top/doc-truyen/lam-pla-ti-ni-den-cung","title":"Làm Pla-ti-ni đến cùng","summary":"Hưng và Trang là hai anh em nhưng trông suýt soát nhau, vì Hưng hơn Trang có một tuổi. Hai anh em cũng rất mê bóng đá. Các buổi tường thuật bóng đá trên truyền hình, hai anh em không bỏ qua một buổi nào.","cat":"bedtime"},{"id":"con-chi-muon-duoc-song-nhu-cac-ban","url":"https://truyencotich.top/doc-truyen/con-chi-muon-duoc-song-nhu-cac-ban","title":"Con chỉ muốn được sống như các bạn","summary":"Người cha của tôi cũng như bao người cha khác. Tình cảm mà người dành cho tôi thật bao la. Tôi cũng rất yêu cha của mình và tự hào về cha, cho dù cha tôi là một người da đen, cho dù bao lời khinh bỉ, chê bai của bạn bè.","cat":"bedtime"},{"id":"suoi-nguon-va-dong-song","url":"https://truyencotich.top/doc-truyen/suoi-nguon-va-dong-song","title":"Suối nguồn và dòng sông","summary":"Có một dòng sông xinh xắn, nước trong vắt. Đây nước soi cả trời mây lồng lộng. Ban đêm, mặt nước lấp lánh trăng sao. Thật huyền ảo và thơ mộng. Dòng Sông ấy là con của bà mẹ Suối Nguồn.","cat":"bedtime"},{"id":"chuyen-gau-an-trang","url":"https://truyencotich.top/doc-truyen/chuyen-gau-an-trang","title":"Chuyện gấu ăn trăng","summary":"Ngày xưa, chú Cuội chưa lên sống trên cung trăng mà vẫn ở mặt đất này cùng với chúng ta. Cuội cũng có bố, có mẹ như chúng ta vậy.","cat":"bedtime"},{"id":"nguoi-viet-su-va-quan-te-tuong","url":"https://truyencotich.top/doc-truyen/nguoi-viet-su-va-quan-te-tuong","title":"Người viết sử và quan tề tướng","summary":"Ngày xưa ở bên Trung Quốc, vua nước Tấn là Tấn Linh Công định giết tề tướng Triệu Thuẫn. Thuẫn hay tin định trốn ra nước ngoài thì người cháu là Triệu Xuyên khuyên đừng đi vội, hãy tạm lánh ra ngoại thành.","cat":"bedtime"},{"id":"nguoi-manh-nhat-hanh-tinh","url":"https://truyencotich.top/doc-truyen/nguoi-manh-nhat-hanh-tinh","title":"Người mạnh nhất hành tinh","summary":"Va-len-tin Di-cun là đứa trẻ sinh thiếu tháng, cân nặng chỉ hơn 1 ki-lô-gam và có nguy cơ chết yểu. Ý chí của người mẹ đã cứu sông cậu bé. Năm 3 tuổi, Va-len-tin mồ côi cả cha lẫn mẹ.","cat":"bedtime"},{"id":"nha-bac-hoc-ga-li-le","url":"https://truyencotich.top/doc-truyen/nha-bac-hoc-ga-li-le","title":"Nhà bác học Ga-li-lê","summary":"Khi còn là giáo sư toán ở trường đại học Pi-dơ, một hôm Ga-li-lê thấy người ta dạy cho sinh viên: vật nặng không bao giờ rơi nhanh hơn vật nhẹ.","cat":"bedtime"},{"id":"nong-noc-tim-me","url":"https://truyencotich.top/doc-truyen/nong-noc-tim-me","title":"Nòng nọc tìm mẹ","summary":"Gió xuân thổi nhè nhẹ, ông mặt trời chiếu những tia nắng rực rỡ xuống mặt đất. Nướctrongao ngày càng trở nên ấm áp. Những quả trứng Ếch dưới ao bắt đầu động đậy, nở ra những chú Nòng Nọc với cái đầu tròn và chiếc đuôi dài xinh xắn.","cat":"bedtime"},{"id":"bac-rat-thuong-loai-vat","url":"https://truyencotich.top/doc-truyen/bac-rat-thuong-loai-vat","title":"Bác rất thương loài vật","summary":"Lúc ở chiến khu, Bác Hồ nuôi một con chó, một con mèo và một con khỉ. Thông thường thì ba loài đó vốn chẳng ưa nhau. Không biết Bác dạy thế nào mà chúng lại quấn quýt nhau, thường đùa giỡn, không trêu chọc nhau bao giờ.","cat":"bedtime"},{"id":"ra-di-tu-ben-nha-rong","url":"https://truyencotich.top/doc-truyen/ra-di-tu-ben-nha-rong","title":"Ra đi từ bến Nhà Rồng","summary":"Mười lăm tuổi, cậu thiếu niên Nguyễn Tất Thành đã sớm biết và rất đau xót trước cảnh thống khổ của nhân dân. Lúc bấy giờ, anh đã có chí đánh đuổi thực dân Pháp, giải phóng đồng bào.","cat":"bedtime"},{"id":"bao-ve-nhu-the-la-rat-tot","url":"https://truyencotich.top/doc-truyen/bao-ve-nhu-the-la-rat-tot","title":"Bảo vệ như thế là rất tốt","summary":"Đơn vị bảo vệ Bác Hồ ở chiến khu có thêm một chiến sĩ mới. Đó là Lí Phúc Nha, người dân tộc Sán Chỉ.","cat":"bedtime"},{"id":"bac-thau-chin-va-em-be-viet-kieu","url":"https://truyencotich.top/doc-truyen/bac-thau-chin-va-em-be-viet-kieu","title":"Bác Thầu Chín và em bé Việt kiều","summary":"Hồi đất nước ta còn sống dưới ách nô lệ của thực dân Pháp, có thời kỳ Bác Hồ phải hoạt động cách mạng bí mật ở bên Thái Lan. Bác tổ chức phong trào yêu nước trong đông đảo đồng bào ta do giặc Pháp sang làm ăn bên đó đã lâu đời.","cat":"bedtime"},{"id":"chiec-re-da-tron","url":"https://truyencotich.top/doc-truyen/chiec-re-da-tron","title":"Chiếc rễ đa tròn","summary":"Buổi sớm hôm ấy, như thường lệ, sau khi tập thể dục, Bác Hồ đi dạo trong vườn. Đến gần cây đa, Bác chợt thấy một chiếc rễ đa nhỏ và dài ngoằn ngoèo nằm trên mặt đất. Chắc là trận gió đêm qua đã làm nó rơi xuống.","cat":"bedtime"},{"id":"alexander-graham-bell-nguoi-phat-minh-ra-dien-thoai","url":"https://truyencotich.top/doc-truyen/alexander-graham-bell-nguoi-phat-minh-ra-dien-thoai","title":"Alexander Graham Bell – người phát minh ra điện thoại","summary":"Ngày 7- 8 – 1922, tất cả các máy điện thoại trên toàn nước Mĩ câm lặng, cả nước cử hành quốc tang tiễn biệt Alexander Graham Bell – người phát minh điện thoại vừa qua đời 5 ngày trước đó.","cat":"bedtime"},{"id":"archimedes-giu-thanh-syracuse","url":"https://truyencotich.top/doc-truyen/archimedes-giu-thanh-syracuse","title":"Archimedes giữ thành Syracuse","summary":"Vào khoảng đầu thế kỉ thứ III trước công nguyên thành Syracuse, quê hương của nhà bác học thiên tài Archimedes bị quân La Mã lăm le xâm lược.","cat":"bedtime"},{"id":"stephen-hawking-nguoi-khuyet-tat-vi-dai","url":"https://truyencotich.top/doc-truyen/stephen-hawking-nguoi-khuyet-tat-vi-dai","title":"Stephen Hawking – người khuyết tật vĩ đại","summary":"Stephen Hawking sinh năm 1942 ở Oxford (Anh). Năm Hawking bước vào trường đại học học khoa Vật lí, anh bị mắc một chứng bệnh quái ác – bệnh rối loạn chức năng điều khiển của hệ thần kinh.","cat":"bedtime"},{"id":"thay-giao-moi","url":"https://truyencotich.top/doc-truyen/thay-giao-moi","title":"Thầy giáo mới","summary":"Thầy giáo mới ngay từ sáng hôm nay đã làm cho tất cả chúng tôi rất thích.","cat":"bedtime"},{"id":"nguoi-ban-moi","url":"https://truyencotich.top/doc-truyen/nguoi-ban-moi","title":"Người bạn mới","summary":"Cả lớp đang giải bài tập toán, bỗng một phụ nữ lạ bước vào, khẽ nói với thầy giáo: Thưa thầy, tôi đưa con gái tôi đến lớp. Nhà trường đã nhận cháu vào học…","cat":"bedtime"},{"id":"nhung-cau-be-dau-troc","url":"https://truyencotich.top/doc-truyen/nhung-cau-be-dau-troc","title":"Những cậu bé đầu trọc","summary":"Gia-sếch được phân vào lớp tôi hồi tháng mười. Hôm đầu đến lớp, nó nhìn quanh lớp một lượt để tìm một chỗ chưa có ai ngồi.","cat":"bedtime"},{"id":"mua-xuan-va-con-chim-nho","url":"https://truyencotich.top/doc-truyen/mua-xuan-va-con-chim-nho","title":"Mùa xuân và con chim nhỏ","summary":"Tết này, cậu bạn Én của tôi tròn 13 tuổi. Sinh nhật Én đúng vào ngày đưa ông Táo lên trời. Tôi muốn tặng Én một món quà nhưng nghĩ hoài mà không biết tặng cái gì.","cat":"bedtime"},{"id":"giai-thoai-ve-ban-xo-nat-anh-trang","url":"https://truyencotich.top/doc-truyen/giai-thoai-ve-ban-xo-nat-anh-trang","title":"Giai thoại về bản xô-nát Ánh trăng","summary":"Gần 200 năm trước đây, nằm bên bờ sông Ranh, miền tây nước Đức, có một thị trấn bé nhỏ và nghèo nàn. Đó là thành phố Bon ngày nay, quê hương của nhà soạn nhạc vĩ đại Bét-tô-ven.","cat":"bedtime"},{"id":"bai-hoc-nho-doi-cua-toi","url":"https://truyencotich.top/doc-truyen/bai-hoc-nho-doi-cua-toi","title":"Bài học nhớ đời của tôi","summary":"Hồi nhỏ, có lần bố tôi đánh tôi một trận rất đau. cảm giác đau tôi quên đã lâu nhưng lí do bị đòn tôi vẫn nhớ như in.","cat":"bedtime"},{"id":"nhung-chu-be-giau-tri-tuong-tuong","url":"https://truyencotich.top/doc-truyen/nhung-chu-be-giau-tri-tuong-tuong","title":"Những chú bé giàu trí tưởng tượng","summary":"Mi-sút-ca và Xta-xích ngồi tán dóc trên chiếc ghế ngoài vườn. Hai cậu thi nhau xem ai bịa chuyện giỏi hơn ai.","cat":"bedtime"},{"id":"hay-de-tien-vao-cho-cu","url":"https://truyencotich.top/doc-truyen/hay-de-tien-vao-cho-cu","title":"Hãy để tiền vào chỗ cũ!","summary":"Pu-ghi có một người láng giềng rất hay sang nhà vay tiền.","cat":"bedtime"},{"id":"giac-mo-cua-cau-be-phun-ton","url":"https://truyencotich.top/doc-truyen/giac-mo-cua-cau-be-phun-ton","title":"Giấc mơ của cậu bé Phun-tơn","summary":"Elô-be Phun-tơn sinh ngày 14-11-1765, tại Mĩ. Cha mất sớm, nhà nghèo, lên 9 tuổi, Phun-tơn mới được đến trường. Vì giàu trí tưởng tượng, biết kể chuyện lại biết vẽ, cậu bé được bè bạn rất quý mến.","cat":"bedtime"},{"id":"dieu-uoc-sao-bang","url":"https://truyencotich.top/doc-truyen/dieu-uoc-sao-bang","title":"Điều ước sao băng","summary":"Rạp xiếc tối nay đông nghịt người. Xen giữa xiếc thú và đu bay có một màn ảo thuật. Người diễn trò không phải một chàng trai thắt nơ đen, miệng luôn luôn mỉm cười bí hiểm mà là một ông già.","cat":"bedtime"},{"id":"toi-lai-co-gia-dinh","url":"https://truyencotich.top/doc-truyen/toi-lai-co-gia-dinh","title":"Tôi lại có gia đình","summary":"Câu chuyện kể về cuộc đời lưu lạc của chú bé Rê-mi. Bị bắt cóc và vứt ra lề đường từ lúc mới sinh, Rê-mi được một gia đình nghèo nuôi, rồi được chủ một gánh xiếc rong là cụ Vi-ta-li dìu dắt nên người.","cat":"bedtime"},{"id":"ki-xuong-hoc-ban","url":"https://truyencotich.top/doc-truyen/ki-xuong-hoc-ban","title":"Kỉ Xương học bắn","summary":"Cam Thằng là nhà thiện xạ thời cổ. Phi Vệ học nghề bắn cung của Cam Thằng, sau giỏi hơn cả thầy.","cat":"bedtime"},{"id":"cau-be-niu-ton","url":"https://truyencotich.top/doc-truyen/cau-be-niu-ton","title":"Cậu bé Niu-tơn","summary":"Sinh ra trong một gia đình nông dân ở Anh, năm 12, cậu bé Niu-tơn mới được ra thành phố đi học. Thoạt đầu, cậu chỉ là một học trò bình thường.","cat":"bedtime"},{"id":"ca-ro-hoi-loi","url":"https://truyencotich.top/doc-truyen/ca-ro-hoi-loi","title":"Ca-rơ hối lỗi","summary":"Ca-rơ là một con chó săn có nhiều tật xấu. Nó không chỉ đuổi bắt cừu và gà mái mà còn hay vào rừng bắt thỏ và gà rừng non nữa.","cat":"bedtime"},{"id":"nguoi-gac-rung-ti-hon","url":"https://truyencotich.top/doc-truyen/nguoi-gac-rung-ti-hon","title":"Người gác rừng tí hon","summary":"Ba em làm nghề gác rừng. Tình yêu rừng của ba đã sớm truyền sang em. Sáng hôm ấy, ba về thăm bà nội ốm. Chiều đến, em đi loanh quanh theo lối ba vẫn đi tuần rừng.","cat":"bedtime"},{"id":"ro-bin-son-o-dao-hoang","url":"https://truyencotich.top/doc-truyen/ro-bin-son-o-dao-hoang","title":"Rô-bin-sơn ở đảo hoang","summary":"Rô-bin-sơn Cru-sô là một chàng trai người Anh rất ham mê đi biển. Trong một chuyến đi, con tàu của anh gặp một cơn bão khủng khiếp. Tất cả các bạn đồng hành của anh đều chết, chỉ mình anh may mắn sông sót.","cat":"bedtime"},{"id":"tran-nguyen-thai-co-gai-doat-5-huy-chuong-vang","url":"https://truyencotich.top/doc-truyen/tran-nguyen-thai-co-gai-doat-5-huy-chuong-vang","title":"Trần Nguyên Thái, cô gái đoạt 5 Huy chương Vàng","summary":"Trần Nguyên Thái sinh ra xinh xắn như nhiều bé gái khác. Năm 1966, tai hoạ giáng xuống khi cô bé mới 2 tuổi. Mẹ đi làm đêm, chị gái 11 tuổi trông em làm đổ đèn dầu.","cat":"bedtime"},{"id":"nguoi-thay-cua-tuoi-tho","url":"https://truyencotich.top/doc-truyen/nguoi-thay-cua-tuoi-tho","title":"Người thầy của tuổi thơ","summary":"Hồi mười một tuổi, tôi vẫn gầy và ẻo lả như một cọng cỏ mảnh. Một hôm, mẹ mang về cho tôi một con mèo mướp nhỏ, ốm yếu.","cat":"bedtime"},{"id":"vo-si-bo-ngua","url":"https://truyencotich.top/doc-truyen/vo-si-bo-ngua","title":"Võ sĩ bọ ngựa","summary":"Một ngày thu, mẹ Bọ Ngựa đưa con tới một bụi hoa hồng. Bà chọn một cành hồng còn sót nhiều lá tươi nhất và bảo: Con hãy ở lại trong cành cây này. Đói thì đã có lá tươi để ăn...","cat":"bedtime"},{"id":"do-choi-cua-ban-thang","url":"https://truyencotich.top/doc-truyen/do-choi-cua-ban-thang","title":"Đồ chơi của bạn Thăng","summary":"Chú Thuận đi làm về không thấy con trai chạy ra đón. Vào nhà, chú ngạc nhiên thấy con ôm gốì nằm trên giường, đôi mắt đỏ hoe","cat":"bedtime"},{"id":"vua-le-dai-hanh-giu-nuoc","url":"https://truyencotich.top/doc-truyen/vua-le-dai-hanh-giu-nuoc","title":"Vua Lê Đại Hành giữ nước","summary":"Tháng 7 năm Canh Thìn (980), đại quân Tống xâm lược Đại Cồ Việt. Vua Lê Đại Hành (tức Lê Hoàn) đã chỉ huy ba quân đánh giặc, đại thắng trên cả hai mặt trận thuỷ bộ, mở ra kỉ nguyên Đại Việt bách thắng.","cat":"bedtime"},{"id":"thu-gui-cac-hoc-sinh","url":"https://truyencotich.top/doc-truyen/thu-gui-cac-hoc-sinh","title":"Thư gửi các học sinh","summary":"Ngày hôm nay là ngày khai trường đầu tiên ở nước Việt Nam Dân chủ Cộng hòa. Tôi đã tưởng tượng thấy thấy trước mắt cái cảnh nhộn nhịp tưng bừng của ngày tựu trường ở khắp các nơi.","cat":"bedtime"},{"id":"hoi-the-dong-quan","url":"https://truyencotich.top/doc-truyen/hoi-the-dong-quan","title":"Hội thề Đông Quan","summary":"Năm 1427, sau hàng loạt chiến thắng, nghĩa quân Lam Sơn tiến về thành Đông Quan (Hà Nội ngày nay). Tướng giặc Vương Thông đóng chặt cửa thành chờ cứu viện.","cat":"bedtime"},{"id":"nguoi-dang-vien-dang-cong-san-dong-duong-goc-bi","url":"https://truyencotich.top/doc-truyen/nguoi-dang-vien-dang-cong-san-dong-duong-goc-bi","title":"Người đảng viên Đảng Cộng sản Đông Dương gốc Bỉ","summary":"Đó là ông Phrăng Đơ Bô-en, tên Việt là Phan Lăng. Quê hương ông ở Vương quốc Bỉ.","cat":"bedtime"},{"id":"anh-hung-nup-o-cu-ba","url":"https://truyencotich.top/doc-truyen/anh-hung-nup-o-cu-ba","title":"Anh hùng Núp ở Cu-ba","summary":"Đất nước đứng lên là cuốn tiểu thuyết của nhà văn Nguyên Ngọc viết về chặng đường chiến đấu anh dũng của anh hùng Núp và đồng bào Tây Nguyên bất khuất, kiên cường chống thực dân Pháp xâm lược.","cat":"bedtime"},{"id":"chu-cho-bac","url":"https://truyencotich.top/doc-truyen/chu-cho-bac","title":"Chú chó Bấc","summary":"Bấc có một tình yêu cuồng nhiệt đối với ông chủ Giôn của mình. Giôn đã cứu sống nó. Hơn thế nữa, anh còn là một ông chủ lí tưởng. Anh chăm sóc Bấc như thể nó là con anh.","cat":"bedtime"},{"id":"chang-no-le-an-roc-co-va-su-tu","url":"https://truyencotich.top/doc-truyen/chang-no-le-an-roc-co-va-su-tu","title":"Chàng nô lệ An-rốc-cơ và sư tử","summary":"Một chàng nô lệ tên là An-rốc-cơ có một lần thoát khỏi tay chủ, bỏ trốn vào rừng sâu. Khi đang lang thang thì An-rốc-cơ bắt gặp một con sư tử đang nằm rên rỉ dưới gốc cây.","cat":"bedtime"},{"id":"nguoi-tho-san-va-con-de-nui","url":"https://truyencotich.top/doc-truyen/nguoi-tho-san-va-con-de-nui","title":"Người thợ săn và con dê núi","summary":"Đã ba lần ông Bỉnh nhìn thấy con dê núi. Lần thứ nhất vào lúc sẩm tối. Ông vừa lội qua con suối, chợt nghe thấy tiếng động ông vội ngước lên...","cat":"bedtime"},{"id":"the-gioi-ti-hon","url":"https://truyencotich.top/doc-truyen/the-gioi-ti-hon","title":"Thế giới tí hon","summary":"Sáng chủ nhật, Tô nai nịt gọn ghẽ rồi đi vào làng. Cậu không quên đem theo con dao díp và khẩu súng cao su làm bằng gỗ ổi đã ngả màu đen bóng.","cat":"bedtime"},{"id":"tro-chuyen-voi-loai-chim","url":"https://truyencotich.top/doc-truyen/tro-chuyen-voi-loai-chim","title":"Trò chuyện với loài chim","summary":"Như con em bao gia đình nông dân nghèo ở làng Phú Thạch dưới chân núi Bạch Mã, ngày ngày, Trương Cảm phải theo cha vào rừng kiếm sống. Mỗi khi đi rừng, Cảm rất thích nghe tiếng chim hót.","cat":"bedtime"},{"id":"cuoc-hop-cua-loai-chim","url":"https://truyencotich.top/doc-truyen/cuoc-hop-cua-loai-chim","title":"Cuộc họp của loài chim","summary":"Hằng năm, loài chim tổ chức họp mặt trên một hòn đảo ở một vùng biển xa xăm. Họ hàng nhà chim từ khắp bốn phương tới đây để thảo luận về mối quan hệ với loài người. Ai nấy thi nhau phát biểu.","cat":"bedtime"},{"id":"cai-cay-co-canh-buom-do","url":"https://truyencotich.top/doc-truyen/cai-cay-co-canh-buom-do","title":"Cái cây có cánh buồm đỏ","summary":"Trên một gò đất, sau mấy ngôi nhà tầng, có một cái cây to, lá xanh, tán xoè rộng. Bọn trẻ chúng tôi thường leo lên cái cây này.","cat":"bedtime"},{"id":"cay-phuong-gia","url":"https://truyencotich.top/doc-truyen/cay-phuong-gia","title":"Cây phượng già","summary":"Tối thứ bảy, trăng sáng vằng vặc. Như thường lệ, lủ trẻ xóm Đông lại tụ tập ở gốc phượng già đầu xóm để nô đùa. Hơn bảy giờ, cả hội đã đủ mặt, chỉ thiếu Hùng.","cat":"bedtime"},{"id":"nin-ho-goc-xon-ti-hon-va-lu-soc","url":"https://truyencotich.top/doc-truyen/nin-ho-goc-xon-ti-hon-va-lu-soc","title":"Nin Hơ-gớc-xơn tí hon và lũ sóc","summary":"Hôm ấy, chủ trang trại nọ bắt được một con sóc cái trong rừng mang về. Mọi người trong trang trại từ già đến trẻ đều thích thú ngắm con vật bé nhỏ, có cái đuôi đẹp, đôi mắt tò mò và thông minh, linh lợi.","cat":"bedtime"},{"id":"cai-ao-hiep-si","url":"https://truyencotich.top/doc-truyen/cai-ao-hiep-si","title":"Cái áo hiệp sĩ","summary":"Nhà tôi có một cây nhãn tơ. Thân nó mập, chắc lẳn. Tán cây xum xuê tròn. Vào cuối mùa xuân, hàng trăm nhánh non màu nâu sậm đua nhau ngoi lên, vượt các lớp lá xanh um.","cat":"bedtime"},{"id":"bay-co","url":"https://truyencotich.top/doc-truyen/bay-co","title":"Bẫy cò","summary":"Năm ấy tôi mười hai, còn bé Vin lên bảy. Vào dịp hè, chúng tôi được tự do chạy nhảy. Vin tết tóc thành hai dải, thắt nơ xanh, bám theo tôi như chiếc bóng.","cat":"bedtime"},{"id":"vua-ly-thai-tong-di-cay","url":"https://truyencotich.top/doc-truyen/vua-ly-thai-tong-di-cay","title":"Vua Lý Thái Tông đi cày","summary":"Lý Thái Tông (1000-1054) là một ông vua có nhiều chiến công hiển hách, đồng thời cũng rất quan tâm phát triển sản xuất, mở mang văn hoá, chăm lo đời sống nhân dân.","cat":"bedtime"},{"id":"day-thun-xanh-day-thun-do","url":"https://truyencotich.top/doc-truyen/day-thun-xanh-day-thun-do","title":"Dây thun xanh, dây thun đỏ","summary":"Mỗi sáng đi học, mẹ cho hai anh em mỗi đứa một nghìn đồng để ăn quà. Bao giờ Hoài Ly cũng tiêu hết số tiền ấy. Thì làm gì mà chẳng hết – một nghìn đồng đủ mua một gói xôi đậu xanh.","cat":"bedtime"},{"id":"nguoi-cha-cua-hon-8000-dua-tre","url":"https://truyencotich.top/doc-truyen/nguoi-cha-cua-hon-8000-dua-tre","title":"Người cha của hơn 8000 đứa trẻ","summary":"Nằm chơi vơi giữa Ấn Độ Dương, Ma-đa-ga-xca là vùng đất khắc nghiệt nhất châu Phi, quanh năm hứng chịu những trận bão từ ngoài khơi đổ bộ vào.","cat":"bedtime"},{"id":"co-giao-va-hai-em-nho","url":"https://truyencotich.top/doc-truyen/co-giao-va-hai-em-nho","title":"Cô giáo và hai em nhỏ","summary":"Nết đã hơn 7 tuổi. Em gái Nết là Na, 6 tuổi. Khi em gái chưa đi học lớp 1, suốt ngày hai chị em quấn quýt bày đồ chơi. Nết sinh ra đã bất hạnh với bàn chân trái thiếu ba ngón.","cat":"bedtime"},{"id":"vai-dien-cuoi-cung","url":"https://truyencotich.top/doc-truyen/vai-dien-cuoi-cung","title":"Vai diễn cuối cùng","summary":"Có một diễn viên già đã về hưu và sống độc thân. Mùa hè năm ấy, ông về một làng vắng vẻ ở vùng núi, sống với gia đình người em của ông là giáo viên trường làng.","cat":"bedtime"},{"id":"nguoi-y-ta-cua-ta-ta","url":"https://truyencotich.top/doc-truyen/nguoi-y-ta-cua-ta-ta","title":"Người y tá của Ta Ta","summary":"Sớm hôm ấy, có một cậu bé ăn mặc kiểu nông thôn đến gặp người gác cổng bệnh viện, xin vào thăm bố. Cậu bé đến từ một làng ở ven Na-pô-li. Bố cậu năm trước sang Pháp để kiếm việc làm nay mới trở về.","cat":"bedtime"},{"id":"quan-phap-lam-son","url":"https://truyencotich.top/doc-truyen/quan-phap-lam-son","title":"Quân pháp Lam Sơn","summary":"Đầu mùa xuân năm Ất Tị (1425), nghĩa quân Lam Sơn của Lê Lợi đã lần lượt giải phóng hết các huyện của Nghệ An. Khi tiến đến đất Thanh Chương ngày nay, nghĩa quân được nhân dân trong vùng nô nức đem rượu thịt ra đón mừng.","cat":"bedtime"},{"id":"hoang-thai-hau-tu-du","url":"https://truyencotich.top/doc-truyen/hoang-thai-hau-tu-du","title":"Hoàng Thái Hậu Từ Dũ","summary":"Bà Từ Dũ tên thật là Phạm Thị Hằng, sinh ngày 19-5-1810, quê ở Gia Định. Năm 14 tuổi, bà được tuyển vào cung và được vua Thiệu Trị rất sủng ái.","cat":"bedtime"},{"id":"mot-quyet-dinh-danh-du","url":"https://truyencotich.top/doc-truyen/mot-quyet-dinh-danh-du","title":"Một quyết định danh dự","summary":"Trọng tài bóng đá có nhiều đẳng cấp: trọng tài quốc tế, trọng tài quốc gia, trọng tài tỉnh, trọng tài huyện và trọng tài làng...","cat":"bedtime"},{"id":"le-nin-trong-hieu-cat-toc","url":"https://truyencotich.top/doc-truyen/le-nin-trong-hieu-cat-toc","title":"Lê-nin trong hiệu cắt tóc","summary":"Hiệu cắt tóc trong điện Krem-li lúc ấy rất đông khách. Mọi người ngồi theo thứ tự trước sau. Anh công nhân I-va-nốp đang chờ tới lượt mình thì cửa phòng lại mở, một người nữa tiến vào.","cat":"bedtime"},{"id":"phi-truc-xu-an","url":"https://truyencotich.top/doc-truyen/phi-truc-xu-an","title":"Phí Trực xử án","summary":"Phí Trực là quan án đời nhà Trần, ông nổi tiếng thông minh và làm việc rất cẩn thận nên ai cũng kính nể. Mỗi lần xử án, Phí Trực thường xem đi xét lại rất kĩ, quyết không chịu xử sai.","cat":"bedtime"},{"id":"cau-be-dung-ngoai-lop-hoc","url":"https://truyencotich.top/doc-truyen/cau-be-dung-ngoai-lop-hoc","title":"Cậu bé đứng ngoài lớp học","summary":"Vũ Duệ người làng Trình Xuyên, huyện Sơn Vi, Sơn Tây (nay là huyện Thanh Sơn, tỉnh Vĩnh Phúc).","cat":"bedtime"},{"id":"doi-ban","url":"https://truyencotich.top/doc-truyen/doi-ban","title":"Đôi bạn","summary":"Làng Mèo Tà Pình và làng Mán Động Hía thù nhau từ đời này qua đời khác chỉ vì cái chuyện giữa nhà thống lí Mèo và nhà vua Mán.","cat":"bedtime"},{"id":"dep-tinh-rieng-vi-nghia-lon","url":"https://truyencotich.top/doc-truyen/dep-tinh-rieng-vi-nghia-lon","title":"Dẹp tình riêng vì nghĩa lớn","summary":"Hưng Đạo Vương Trần Quốc Tuấn (1232 – 1300) là một vị anh hùng dân tộc lỗi lạc. Ông được nhân dân tôn là Thánh (Đức Thánh Trần), đời đời thờ phụng không phải chỉ vì tài năng quân sự kiệt xuất và những chiến thắng lẫy lừng","cat":"bedtime"},{"id":"xa-tac-quy-hon-ngoi-bau","url":"https://truyencotich.top/doc-truyen/xa-tac-quy-hon-ngoi-bau","title":"Xã tắc quý hơn ngôi báu","summary":"Một ngày mùa thu năm Canh Thìn (980), bầu trời Hoa Lư trong vắt. Nắng vàng trải mênh mang trên núi rừng. Hoàng cung Hoa Lư trang nghiêm hôm nay được canh phòng nghiêm ngặt hơn.","cat":"bedtime"},{"id":"vi-giao-su-thong-thai","url":"https://truyencotich.top/doc-truyen/vi-giao-su-thong-thai","title":"Vị giáo sư thông thái","summary":"Giáo sư Tạ Quang Bửu quê ở huyện Nam Đàn, tỉnh Nghệ An. Thuở nhỏ, cậu bé Bửu học ở Quảng Nam. Năm 1917, phủ Tam Kỳ mở kì thi cho học sinh lên bảy, thi cả Hán văn, Toán học lẫn Việt văn.","cat":"bedtime"},{"id":"trang-nguyen-nguyen-ky","url":"https://truyencotich.top/doc-truyen/trang-nguyen-nguyen-ky","title":"Trạng nguyên Nguyễn Kỳ","summary":"Nguyễn Kỳ thuở nhỏ có tên là Nguyễn Thời Lượng, người trấn Sơn Nam (nay thuộc huyện Văn Giang, tỉnh Hưng Yên).","cat":"bedtime"},{"id":"trang-nay-cho-co-xem-thuong","url":"https://truyencotich.top/doc-truyen/trang-nay-cho-co-xem-thuong","title":"Trăng nay chớ có xem thường","summary":"Lê Thánh Tông (1441 – 1497) là một vị vua có nhiều công lao phát triển kinh tế, văn hoá, mở mang đất nước. Nhà vua lập ra Hội Tao đàn để khuyến khích sáng tác thơ văn bằng tiếng Việt.","cat":"bedtime"},{"id":"nguyen-phi-y-lan","url":"https://truyencotich.top/doc-truyen/nguyen-phi-y-lan","title":"Nguyên phi Ỷ Lan","summary":"Sử chép rằng vua Lý Thánh Tông đã ngoài 40 tuổi nhưng chưa sinh được hoàng tử, lấy làm lo lắng lắm, bèn đi cầu tự ở khắp nơi. Lần ấy, vua về thăm chùa ở Thổ Lỗi (nay thuộc huyện Gia Lâm, ngoại thành Hà Nội).","cat":"bedtime"},{"id":"binh-nuoc-va-con-ca-vang","url":"https://truyencotich.top/doc-truyen/binh-nuoc-va-con-ca-vang","title":"Bình nước và con cá vàng","summary":"I-ren Giô-li-ô Quy-ri sinh ra trong một gia đình khoa học. Mẹ bà là Ma-ri Quy-ri hai lần được Giải thưởng Nô-ben (1903, 1911). Bố của bà là Pi-e Quy-ri, được Giải thưởng Nô-ben năm 1903 cùng với vợ.","cat":"bedtime"},{"id":"cha-se-luon-o-ben-con","url":"https://truyencotich.top/doc-truyen/cha-se-luon-o-ben-con","title":"Cha sẽ luôn ở bên con","summary":"Năm 1989, tại Ác-mê-ni-a, một trận động đất 8,2 độ rích-tơ đã san bằng nhiều làng mạc, thành phố, giết hại hơn 30 000 người trong vòng chưa đầy bốn phút.","cat":"bedtime"},{"id":"cuoc-phieu-luu-cua-vien-kim-cuong","url":"https://truyencotich.top/doc-truyen/cuoc-phieu-luu-cua-vien-kim-cuong","title":"Cuộc phiêu lưu của viên kim cương","summary":"Một lần, bác sĩ Oát-xơn đến nhà Sơ-lốc Hôm. Vị thám tử lừng danh đang ngồi đăm chiêu bên một cái mũ sờn cũ và một chiếc kính lúp.","cat":"bedtime"},{"id":"ai-co-loi","url":"https://truyencotich.top/doc-truyen/ai-co-loi","title":"Ai có lỗi?","summary":"Tôi đang nắn nót viết thì Cô-rét-ti chạm khuỷu tay vào tôi làm cho cây bút nguệch ra một đường rất xấu. Tôi nổi giận. Cô-rét-ti cười, đáp: &quot;Mình không cố ý đâu!&quot;","cat":"bedtime"},{"id":"chiec-ao-len","url":"https://truyencotich.top/doc-truyen/chiec-ao-len","title":"Chiếc áo len","summary":"Năm nay, mùa đông đến sớm. Gió thổi từng cơn lạnh buốt. Đã hơn một tuần nay, Lan thấy Hòa có chiếc áo len màu vàng thật đẹp. Áo có dây kéo ở giữa, lại có cả mũ để đội khi gió lạnh hoặc mưa lất phất. Lan đã mặt thử, ấm ơi là ấm.","cat":"bedtime"},{"id":"tran-bong-duoi-long-duong","url":"https://truyencotich.top/doc-truyen/tran-bong-duoi-long-duong","title":"Trận bóng dưới lòng đường","summary":"Trận đấu vừa bắt đầu thì Quang cướp được bóng. Quang bấm nhẹ bóng sang cánh phải cho Vũ. Vũ dẫn bóng lên. Bốn, năm cầu thủ đội bạn lao đến. Vũ ngần ngừ giây lát. Chợt nhận ra cánh trái trống hẳn đi. Vũ chuyền bóng cho Long.","cat":"bedtime"},{"id":"cac-em-nho-va-cu-gia","url":"https://truyencotich.top/doc-truyen/cac-em-nho-va-cu-gia","title":"Các em nhỏ và cụ già","summary":"Mặt trời đã lùi dần về chân núi phía tây. Đàn sếu đang sải cánh trên cao. Sau một cuộc dạo chơi, đám trẻ ra về. Tiếng nói cười ríu rít.","cat":"bedtime"},{"id":"giong-que-huong","url":"https://truyencotich.top/doc-truyen/giong-que-huong","title":"Giọng quê hương","summary":"Thuyên và Đồng rời quê hương đã mấy năm. Một hôm hai anh rủ nhau đi chơi thật xa, nhưng đến giữa trưa thì lạc mất đường về. Hai người phải ghé vào quán gần đấy để hỏi đường, luôn tiện để ăn cho đỡ đói. Cùng ăn trong quán ấy có ba thanh niên.","cat":"bedtime"},{"id":"dat-quy-dat-yeu","url":"https://truyencotich.top/doc-truyen/dat-quy-dat-yeu","title":"Đất quý, đất yêu","summary":"Ngày xưa, có hai người khách du lịch đến nước Ê-ti-ô-pi-a. Họ đi khắp đất nước thăm đường sá, núi đồi, sông ngòi. Vua nước Ê-ti-ô-pi-a mời họ vào cung điện, mở tiệc chiêu đãi và tặng họ nhiều vật quý. Sau đó vua sai một viên quan đưa khách xuống tàu.","cat":"bedtime"},{"id":"luon-nghi-den-mien-nam","url":"https://truyencotich.top/doc-truyen/luon-nghi-den-mien-nam","title":"Luôn nghĩ đến miền Nam","summary":"Đầu năm 1969, một chị cán bộ miền Nam ra Bắc được gặp Bác Hồ.","cat":"bedtime"},{"id":"mot-phat-minh-nho-nho","url":"https://truyencotich.top/doc-truyen/mot-phat-minh-nho-nho","title":"Một phát minh nho nhỏ","summary":"Ma-ri-a là một cô bé rất thích quan sát. Một hôm, trong phòng khách, cô bé nhận thấy mỗi lần gia nhân bưng trà lên, bát đựng trà thoạt đầu rất dễ trượt trong đĩa.","cat":"bedtime"},{"id":"ong-trang-tha-dieu","url":"https://truyencotich.top/doc-truyen/ong-trang-tha-dieu","title":"Ông Trạng thả diều","summary":"Vào đời vua Trần Thái Tông, có một gia đình nghèo sinh được cậu con trai đặt tên là Nguyễn Hiền. Chú bé rất ham thả diều. Lúc còn bé, chú đã biết làm lấy diều để chơi.","cat":"bedtime"},{"id":"mot-nguoi-chinh-truc","url":"https://truyencotich.top/doc-truyen/mot-nguoi-chinh-truc","title":"Một người chính trực","summary":"Tô Hiến Thành làm quan triều Lý, nổi tiếng là người chính trực. Năm 1175, vua Lý Anh Tông mất, di chiếu cho Tô Hiến Thành phò thái tử Long Cán, con bà thái hậu họ Đỗ, lên ngôi.","cat":"bedtime"},{"id":"nguoi-an-xin","url":"https://truyencotich.top/doc-truyen/nguoi-an-xin","title":"Người ăn xin","summary":"Lúc ấy, tôi đang đi trên phố. Một người ăn xin già lọm khọm đứng ngay trước mặt tôi. Đôi mắt ông lão đỏ đọc và giàn giụa nước mắt. Đôi môi tái nhợt, áo quần tả tơi thảm hại…","cat":"bedtime"},{"id":"vua-tau-thuy-bach-thai-buoi","url":"https://truyencotich.top/doc-truyen/vua-tau-thuy-bach-thai-buoi","title":"Vua tàu thủy Bạch Thái Bưởi","summary":"Bưởi mồ côi cha từ nhỏ, phải theo mẹ quẩy gánh hàng rong. Thấy em khôi ngô, nhà họ Bạch nhận làm con nuôi và cho ăn học.","cat":"bedtime"},{"id":"nguoi-tim-duong-len-cac-vi-sao","url":"https://truyencotich.top/doc-truyen/nguoi-tim-duong-len-cac-vi-sao","title":"Người tìm đường lên các vì sao","summary":"Từ nhỏ, Xi-ôn-cốp-xki đã mơ ước được bay lên bầu trời. Có lần, ông dại dột nhảy qua cửa sổ để bay theo những cánh chim.","cat":"bedtime"},{"id":"chiec-dong-ho","url":"https://truyencotich.top/doc-truyen/chiec-dong-ho","title":"Chiếc đồng hồ","summary":"Năm 1954, các cán bộ đang dự hội nghị tổng kết ở Bắc Giang thì có lệnh Trung ương rút bớt một số người đi học lớp tiếp quản Thủ đô. Ai nấy đều háo hức muốn đi. Nhất là những người quê Hà Nội.","cat":"bedtime"},{"id":"nguoi-di-san-va-con-vuon","url":"https://truyencotich.top/doc-truyen/nguoi-di-san-va-con-vuon","title":"Người đi săn và con vượn","summary":"Ngày xưa có một người săn bắn rất tài. Nếu con thú rừng nào không may gặp bác ta thì hôm ấy coi như đó là ngày tận số.","cat":"bedtime"},{"id":"rat-nhieu-mat-trang","url":"https://truyencotich.top/doc-truyen/rat-nhieu-mat-trang","title":"Rất nhiều mặt trăng","summary":"Ở vương quốc nọ có một cô bé xinh xinh chừng năm, sáu tuổi. Bé xíu như vậy, nhưng cô lại là công chúa. Một lần, công chúa ốm nặng. Nhà vua rất lo lắng. Ngài hứa tặng cô con gái bé nhỏ bất kì thứ gì cô muốn, miễn là cô khỏi bệnh.","cat":"bedtime"},{"id":"de-men-benh-vuc-ke-yeu","url":"https://truyencotich.top/doc-truyen/de-men-benh-vuc-ke-yeu","title":"Dế Mèn bênh vực kẻ yếu","summary":"Một hôm, qua một vùng cỏ xước xanh dài. Tôi chợt nghe tiếng khóc tỉ tê. Đi được vài bước nữa, tôi gặp chị Nhà Trò ngồi gục đầu bên tảng đá cuội.","cat":"bedtime"},{"id":"noi-dan-vat-cua-an-dray-ca","url":"https://truyencotich.top/doc-truyen/noi-dan-vat-cua-an-dray-ca","title":"Nỗi dằn vặt của An-đrây-ca","summary":"An-đrây-ca lên 9, sống với mẹ và ông. Ông em 96 tuổi rồi nên rất yếu. Một buổi chiều, ông nói với mẹ An-đrây-ca: &quot;Bố khó thở lắm!...&quot; Mẹ liền bảo An-đrây-ca đi mua thuốc.","cat":"bedtime"},{"id":"nguoi-viet-truyen-that-tha","url":"https://truyencotich.top/doc-truyen/nguoi-viet-truyen-that-tha","title":"Người viết truyện thật thà","summary":"Nhà văn Pháp nổi tiếng Ban-dắc và vợ được mời đi dự tiệc. Lúc sắp lên xe, ông bảo vợ: Anh không muốn ngồi ăn lâu, nhưng chưa biết nên nói thế nào đây.","cat":"bedtime"},{"id":"chi-em-toi","url":"https://truyencotich.top/doc-truyen/chi-em-toi","title":"Chị em tôi","summary":"Từ đó, tôi không bao giờ dám nói dối ba đi chơi nữa. Thỉnh thoảng, hai chị em lại cười phá lên khi nhắc lại chuyện nó rủ bạn vào rạp chiếu bóng chọc tức tôi, làm cho tôi tỉnh ngộ.","cat":"bedtime"},{"id":"thua-chuyen-voi-me","url":"https://truyencotich.top/doc-truyen/thua-chuyen-voi-me","title":"Thưa chuyện với mẹ","summary":"Từ ngày phải nghỉ học, Cương đâm ra nhớ cái lò rèn cạnh trường. Một hôm, em ngỏ ý với mẹ: Mẹ nói với thầy cho con đi học nghề rèn.","cat":"bedtime"},{"id":"ve-trung","url":"https://truyencotich.top/doc-truyen/ve-trung","title":"Vẽ trứng","summary":"Ngay từ nhỏ, cậu bé Lê-ô-nác-đô đa Vin-xi đã rất thích vẽ. Cha cậu đưa cậu đến nhờ nhà danh họa Vê-rô-ki-ô dạy dỗ.","cat":"bedtime"},{"id":"trong-quan-an-ba-ca-bong","url":"https://truyencotich.top/doc-truyen/trong-quan-an-ba-ca-bong","title":"Trong quán ăn &quot;Ba cá bống&quot;","summary":"Bu-ra-ti-nô là một chú bé bằng gỗ. Chú có cái mũi rất dài. Chú người gỗ được bác rùa tốt bụng Toóc-ti-la tặng cho chiếc chìa khóa vàng để mở một kho báu.","cat":"bedtime"},{"id":"van-hay-chu-tot","url":"https://truyencotich.top/doc-truyen/van-hay-chu-tot","title":"Văn hay chữ tốt","summary":"Thuở đi học, Cao Bá Quát viết chữ rất xấu nên nhiều bài văn dù hay vẫn bị thầy cho điểm kém.","cat":"bedtime"},{"id":"chu-dat-nung","url":"https://truyencotich.top/doc-truyen/chu-dat-nung","title":"Chú Đất Nung","summary":"Tết Trung thu, cu Chắt được món quà. Đó là một chàng kị sĩ rất bảnh, cưỡi ngựa tía, dây cương vàng và một nàng công chúa mặt trắng, ngồi trong mái lầu son. Chắt còn một đồ chơi nữa là chú bé bằng đất em nặn lúc đi chăn trâu.","cat":"bedtime"},{"id":"nham-thang-quan-thu-ma-ban","url":"https://truyencotich.top/doc-truyen/nham-thang-quan-thu-ma-ban","title":"Nhằm thẳng quân thù mà bắn!","summary":"Tháng 8 năm 1964, giặc Mỹ bắt đầu cho máy bay bắn phá gây tội ác ở miền Bắc. Thiếu úy Nguyễn Viết Xuân cùng đồng đội hành quân lên miền tây Quảng Bình bảo vệ vùng trời của Tổ quốc.","cat":"bedtime"},{"id":"giao-su-luong-dinh-cua-nha-bac-hoc-cua-dong-ruong","url":"https://truyencotich.top/doc-truyen/giao-su-luong-dinh-cua-nha-bac-hoc-cua-dong-ruong","title":"Giáo sư Lương Định Của - Nhà bác học của đồng ruộng","summary":"Tốt nghiệp bác sĩ nông học [1] tại Nhật Bản, bác Lương Định Của được bổ nhiệm làm giáo sư giảng dạy ở trường đại học Ki-ô-đô (ở Nhật) với tiện nghi của một cuộc sống đầy đủ thỏa mãn.","cat":"bedtime"},{"id":"nghe-si-piano-dang-thai-son","url":"https://truyencotich.top/doc-truyen/nghe-si-piano-dang-thai-son","title":"Nghệ sĩ piano Đặng Thái Sơn","summary":"Đặng Thái Sơn sinh ra và lớn lên trong một gia đình có truyền thống âm nhạc. Cha của Đặng Thái Sơn là nhạc sĩ Đặng Đình Hưng, mẹ là Nhà giáo Nhân dân, Nghệ sĩ Ưu tú Thái Thị Liên, nguyên chủ nhiệm khoa đàn piano Nhạc viện Hà Nội.","cat":"bedtime"},{"id":"tieng-bom-sa-dien","url":"https://truyencotich.top/doc-truyen/tieng-bom-sa-dien","title":"Tiếng bom Sa Diện","summary":"Thời Pháp thuộc, bọn thực dân và phong kiến áp bức, bóc lột nhân dân ta thậm tệ. Già, trẻ, trai, gái hết thảy đều căm ghét chúng. Nhiều thanh niên ưu tú không cam tâm làm nô lệ đã tìm đường ra nước ngoài học tập và làm cách mạng.","cat":"bedtime"},{"id":"bac-ho-o-slum-luc","url":"https://truyencotich.top/doc-truyen/bac-ho-o-slum-luc","title":"Bác Hồ ở Slum-Lực","summary":"Mùa xuân năm 1944, để tránh không cho giặc Pháp dồn làng bắt thanh niên, các đồng chí cán bộ cách mạng ở Pác Bó tổ chức di chuyển nhà cửa sang Slum-Lực lập làng mới giữa một vùng núi non trung điệp. Mỗi người chung sống trong một nhà tập thể.","cat":"bedtime"},{"id":"cu-goi-toi-la-ba-nhu-ngay-truoc","url":"https://truyencotich.top/doc-truyen/cu-goi-toi-la-ba-nhu-ngay-truoc","title":"Cứ gọi tôi là Ba như ngày trước","summary":"Ở phố Ngõ Nghè (Hải Phòng) có một ông già mù cả hai mắt tên là Thuyết. Hồi còn trẻ, ông làm thủy thủ [1] trên nhiều tàu buôn nước ngoài, về sau ông làm công trong một hiệu ảnh bên Pháp.","cat":"bedtime"},{"id":"hon-mot-nghin-ngay-vong-quanh-trai-dat","url":"https://truyencotich.top/doc-truyen/hon-mot-nghin-ngay-vong-quanh-trai-dat","title":"Hơn một nghìn ngày vòng quanh trái đất","summary":"Ngày 20 tháng 9 năm 1519, từ cảng Xê-vi-la lớn giong buồm ra khơi. Đó là hạm đội do Ma-gien-lăng chỉ huy, với nhiệm vụ khám phá con đường trên biển dẫn đến những vùng đất mới.","cat":"bedtime"},{"id":"khat-vong-song","url":"https://truyencotich.top/doc-truyen/khat-vong-song","title":"Khát vọng sống","summary":"Giôn và Bin khập khiễng đi ra bờ suối. Mỗi người mang một khẩu súng và một cuộn chăn trên vai. Cả hai đều thấm mệt sau những ngày gian khổ dài đằng đẵng. Giôn bỗng trượt chân suýt ngã.","cat":"bedtime"},{"id":"con-da-lon-that-roi","url":"https://truyencotich.top/doc-truyen/con-da-lon-that-roi","title":"Con đã lớn thật rồi!","summary":"Có một cô bé sang nhà dì chơi. Vì đang dỗi mẹ nên em ngồi buồn thiu. Thấy vậy, dì hỏi: Cháu có chuyện gì buồn à? Đến bữa rồi, ăn cơm với dì nhé?","cat":"bedtime"},{"id":"an-mam-da","url":"https://truyencotich.top/doc-truyen/an-mam-da","title":"Ăn &quot;mầm đá&quot;","summary":"Tương truyền vào thời vua Lê - chúa Trịnh có ông Trạng Quỳnh là người rất thông minh. Trạng thường dùng lối nói hài hước hoặc những cách độc đáo để châm biếm thói xấu của vua chúa, quan lại và bênh vực dân lành.","cat":"bedtime"},{"id":"anh-hung-ly-tu-trong","url":"https://truyencotich.top/doc-truyen/anh-hung-ly-tu-trong","title":"Anh hùng Lý Tự Trọng","summary":"Anh Lý Tự Trọng sinh ra trong một gia đình nông dân nghèo ở Hà Tĩnh. Anh giác ngộ cách mạng rất sớm và được tổ chức đưa ra nước ngoài học tập. Vốn thông minh, anh học rất giỏi, nói thạo tiếng Trung Quốc và tiếng Anh.","cat":"bedtime"},{"id":"cai-gi-quy-nhat","url":"https://truyencotich.top/doc-truyen/cai-gi-quy-nhat","title":"Cái gì quý nhất?","summary":"Một hôm, trên đường đi học về, Hùng, Quý và Nam trao đổi với nhau xem ở trên đời này, cái gì quý nhất.","cat":"bedtime"},{"id":"dan-ca-heo-va-ban-nhac","url":"https://truyencotich.top/doc-truyen/dan-ca-heo-va-ban-nhac","title":"Đàn cá heo và bản nhạc","summary":"Ở vùng biển Bắc cực trời rét đậm. Băng giá ngay càng nhiều, diện tích mặt nước chưa đóng băng dần dần bị thu hẹp lại. Đàn cá heo sống trong khu vực đó vùng vẫy và có nguy cơ chết vì băng giá.","cat":"bedtime"},{"id":"kho-bau-cua-cha","url":"https://truyencotich.top/doc-truyen/kho-bau-cua-cha","title":"Kho báu của cha","summary":"Ngày xưa, có hai vợ chồng người nông dân kia quanh năm hai sương một nắng, cuốc bẫm cày sâu. Hai ông bà thường ra đồng từ lúc gà gáy sáng và trở về nhà khi đã lặn mặt trời.","cat":"bedtime"},{"id":"qua-tang-chu-he","url":"https://truyencotich.top/doc-truyen/qua-tang-chu-he","title":"Quà tặng chú hề","summary":"Mẹ đưa Trang đi xem xiếc. Trang rất thích tiết mục “Quả bóng kì lạ” của chú hề. Quả bóng kì lạ thật! Nó mỏng manh thế mà kéo chú hề chạy theo, xiêu vẹo cả người. Có lúc chú phải nhảy người lên ấn quả bóng xuống mà không nổi.","cat":"bedtime"},{"id":"chuyen-di-xa-cua-chu-chuot-nho","url":"https://truyencotich.top/doc-truyen/chuyen-di-xa-cua-chu-chuot-nho","title":"Chuyến đi xa của chú chuột nhỏ","summary":"Một buổi sáng, chú chuột nhỏ lên đường đi du lịch. Chuột bà nướng cho cháu rất nhiều bánh để ăn đường và tiễn cháu đến cửa hang. Nhưng ngay buổi chiều hôm đó, chú chuột trở về.","cat":"bedtime"},{"id":"minh-ban-hoc","url":"https://truyencotich.top/doc-truyen/minh-ban-hoc","title":"Mình bận học","summary":"Vào một buổi sáng thứ bảy đẹp trời, Vô-lô-đi-a đang cắm cúi chuẩn bị bài thì một bạn đến rủ đi bắn chim vì cậu ta vừa mua một khẩu súng mới toanh. Khẩu súng mới! Điều đó thật hấp dẫn đối với các bạn trai.","cat":"bedtime"},{"id":"nui-cuoi","url":"https://truyencotich.top/doc-truyen/nui-cuoi","title":"Núi cười","summary":"Ngày xưa, ở một bản nọ có hai anh em. Anh thì ham chơi. Em thì chăm học, chăm làm.","cat":"bedtime"},{"id":"dep-ma-khong-dep","url":"https://truyencotich.top/doc-truyen/dep-ma-khong-dep","title":"Đẹp mà không đẹp","summary":"Thấy bác Thành đi qua, Hùng liền gọi: Bác Thành ơi, bác xem con ngựa cháu vẽ có đẹp không?","cat":"bedtime"},{"id":"di-tim-ban","url":"https://truyencotich.top/doc-truyen/di-tim-ban","title":"Đi tìm bạn","summary":"Thỏ Xám và Nhím Xù là đôi bạn chơi với nhau rất thân. Những buổi sáng mùa hè, hai bạn rủ nhau là bờ suối hái hoa, đào củ. Những buổi tối mùa thu hai bạn kéo nhau ra bãi cỏ nô đùa dưới ánh trăng.","cat":"bedtime"},{"id":"phong-canh-den-hung","url":"https://truyencotich.top/doc-truyen/phong-canh-den-hung","title":"Phong cảnh đền Hùng","summary":"Đền Thượng nằm chót vót trên dỉnh núi Nghĩa Cương. Trước đền, những khóm hải đường đâm bông rực đỏ, những cánh bướm nhiều màu sắc bay rập rờn như đang múa quạt xòe hoa trước sân.","cat":"bedtime"},{"id":"ai-can-dam","url":"https://truyencotich.top/doc-truyen/ai-can-dam","title":"Ai can đảm?","summary":"Bây giờ thì mình không sợ gì hết! Hùng vừa nói vừa giơ khẩu súng lục bằng nhựa ra khoe.","cat":"bedtime"},{"id":"lam-viec-that-la-vui","url":"https://truyencotich.top/doc-truyen/lam-viec-that-la-vui","title":"Làm việc thật là vui","summary":"Quanh ta, mọi người đều làm việc. Cái đồng hồ tích tắc báo phút, báo giờ. Con gà trống gáy vang ò … ó … o, báo cho mọi người biết trời sắp sáng, mau mau thức dậy.","cat":"bedtime"},{"id":"tren-duong-den-nha-lao","url":"https://truyencotich.top/doc-truyen/tren-duong-den-nha-lao","title":"Trên đường đến nhà lao","summary":"Bầu trời Côn Đảo trong buổi bình minh rất đẹp. Con đường từ Bến Đầm đến nhà lao uốn quanh bờ biển, men theo triền núi, bên trên là cây cối um tùm, bên dưới là sóng trắng vỗ bờ đá dựng.","cat":"bedtime"},{"id":"tran-quoc-toan-ra-quan","url":"https://truyencotich.top/doc-truyen/tran-quoc-toan-ra-quan","title":"Trần Quốc Toản ra quân","summary":"Sáng hôm ấy, Trần Quốc Toản dậy sớm từ biệt mẹ già: Con đi phen này thề sống chết với giặc. Bao giờ đất nước được yên, con mới trở về…","cat":"bedtime"},{"id":"hai-ban-tay","url":"https://truyencotich.top/doc-truyen/hai-ban-tay","title":"Hai bàn tay","summary":"Năm 1911, năm ấy Bác còn trẻ lắm mới khoảng 21 tuổi. Một hôm anh Ba - tên của Bác hồi ấy, cùng một người bạn đi dạo khắp thành phố Sài Gòn, rồi bỗng đột nhiên anh Ba hỏi người bạn cùng đi: Anh Lê, anh có yêu nước không ?","cat":"bedtime"},{"id":"nha-bac-hoc-khong-ngung-hoc","url":"https://truyencotich.top/doc-truyen/nha-bac-hoc-khong-ngung-hoc","title":"Nhà bác học không ngừng học","summary":"Đác – uyn là nhà bác học nổi tiếng trên thế giới. Ông còn rất ham học. Vào một đêm giá lạnh, mọi người đã say ngủ. Con ông chợt thức giấc và thấy phòng cha vẫn còn sáng ánh đèn.","cat":"bedtime"},{"id":"con-lon-nho-khon-ngoan","url":"https://truyencotich.top/doc-truyen/con-lon-nho-khon-ngoan","title":"Con lợn nhỏ khôn ngoan","summary":"Ngày xưa có một con lợn nhỏ sống trong rừng rậm. Một hôm trời rét căm căm, có lão chó sói tìm đến hang, cất tiếng gọi: Chú lợn ơi! Chú cho ta vào nhà chú ngồi một tí cho đỡ lạnh.","cat":"bedtime"},{"id":"ong-chu-cua-hang-banh-keo","url":"https://truyencotich.top/doc-truyen/ong-chu-cua-hang-banh-keo","title":"Ông chủ cửa hàng bánh kẹo","summary":"Tại vùng Tơ-lan-păng có một cửa hàng bánh kẹo nổi tiếng của bác Phơ-lip. Không ai biết cửa hàng này có từ bao giờ, chỉ biết bác Phơ-lip đã nối tiếp nghề nghiệp của cha ông từ ba đời nay, và được nhân dân trong vùng quý mến.","cat":"bedtime"},{"id":"chinh-toi-co-loi","url":"https://truyencotich.top/doc-truyen/chinh-toi-co-loi","title":"Chính tôi có lỗi","summary":"Ngoài hành lang nhà ở của Vla-đi-mia I-lích, người chỉ huy đội bảo vệ điện Krem-li đặt một trạm gác. Các học sinh trường quân sự trực nhật hằng ngày. Hôm ấy, một học sinh quân trẻ tuổi không biết mặt Lê-nin được cử tới gác.","cat":"bedtime"},{"id":"dong-muoi-xu","url":"https://truyencotich.top/doc-truyen/dong-muoi-xu","title":"Đồng mười xu","summary":"Hôm ấy, mẹ Cốt bảo: Cốt, con cầm mười xu ra hiệu mua bánh mì nhé! Đi từ từ thôi kẻo vấp ngã...","cat":"bedtime"},{"id":"le-nin-va-ong-lao-di-san","url":"https://truyencotich.top/doc-truyen/le-nin-va-ong-lao-di-san","title":"Lê-nin và ông lão đi săn￼","summary":"Ông lão bắt đầu kể với tôi rất tỉ mỉ về việc sau một chuyến đi săn, Lê-nin mời ông đến Mát-xcơ-va để thăm Lê-nin và xem xét mọi việc. Từ một nơi thâm sơn cùng cốc đến thẳng Mát-xcơ-va thăm Lê-nin, có phải chuyện chơi đâu.","cat":"bedtime"},{"id":"toi-xin-chua-benh-cho-ngai","url":"https://truyencotich.top/doc-truyen/toi-xin-chua-benh-cho-ngai","title":"Tôi xin chữa bệnh cho ngài","summary":"Ô-guyn là một người chỉ thích ăn luôn miệng và ít hoạt động thân thể. Người gã béo ục ịch quá đỗi, có lúc tưởng nghẹt thở.","cat":"bedtime"},{"id":"nhu-the-nao-la-mot-ngay-dep","url":"https://truyencotich.top/doc-truyen/nhu-the-nao-la-mot-ngay-dep","title":"Như thế nào là một ngày đẹp?","summary":"Châu Chấu nhảy lên gò, chìa cái lưng màu xanh ra phơi nắng. Nó búng chân tanh tách, cọ giũa đôi càng: Một ngày tuyệt đẹp!","cat":"bedtime"},{"id":"hoi-nghi-dien-hong","url":"https://truyencotich.top/doc-truyen/hoi-nghi-dien-hong","title":"Hội nghị Diên Hồng","summary":"Thượng hoàng Thánh Tông trịnh trọng hỏi các bô lão: Nước Đại Việt ta tuy là một nước nhỏ ở phương nam nhưng luôn bị nước ngoài nhòm ngó…","cat":"bedtime"},{"id":"hot-man","url":"https://truyencotich.top/doc-truyen/hot-man","title":"Hột mận","summary":"Một bà mẹ mua mận cho các con ăn sau bữa cơm. Bà để mận trên một cái đĩa ở giữa bàn. Va-ni-a chưa bao giờ được ăn mận nên thèm lắm.","cat":"bedtime"},{"id":"gian-di","url":"https://truyencotich.top/doc-truyen/gian-di","title":"Giản dị","summary":"Vào một đêm cuối xuân năm 1947, khoảng hai giờ sáng, trên đường đi công tác, Bác Hồ đến nghỉ chân ở một nhà bên đường.","cat":"bedtime"},{"id":"mot-que-diem","url":"https://truyencotich.top/doc-truyen/mot-que-diem","title":"Một que diêm","summary":"Sau khi đến thăm nhà câu lạc bộ, nhà ăn và ra xem chuồng lợn, Bác đi vào bếp. Thấy đồng chí Hào, tổ trưởng anh nuôi của đơn vị đang bê một nồi cơm to từ trên bếp lò xuống...","cat":"bedtime"},{"id":"ai-manh-nhat-tren-doi","url":"https://truyencotich.top/doc-truyen/ai-manh-nhat-tren-doi","title":"Ai mạnh nhất trên đời?","summary":"Chú gà rừng đến bờ sông để tìm nước uống cho đỡ khát. Chú ta tìm được một chỗ nước chưa đóng băng tròn như cái đĩa. Chú uống cho đến lúc đôi cánh cũng bị băng đóng cứng đờ.","cat":"bedtime"},{"id":"chiec-dao-nong-nay","url":"https://truyencotich.top/doc-truyen/chiec-dao-nong-nay","title":"Chiếc dao nóng nảy","summary":"Mi-chi-a cầm dao gọt một chiếc gậy, nhưng gọt một chốc, cậu quẳng gậy xuống đất. Chiếc gậy cong queo, sần sùi, trông thật xấu.","cat":"bedtime"},{"id":"co-mot-lan","url":"https://truyencotich.top/doc-truyen/co-mot-lan","title":"Có một lần","summary":"Tôi chẳng muốn kể chuyện này vì tôi thấy ngượng quá. Nhưng dù sao, tôi cũng xin kể để các bạn nghe. Mọi người đều tưởng là tôi bị đau thật, nhưng có phải là tôi bị sưng bộng răng đâu.","cat":"bedtime"},{"id":"bo-cua-xi-mong","url":"https://truyencotich.top/doc-truyen/bo-cua-xi-mong","title":"Bố của Xi-mông","summary":"Chuông báo trưa vừa dứt. Cửa trường mở, và bọn trẻ con chen lấn nhau ùa ra cho nhanh. Nhưng chúng không mau tản mát về nhà ăn trưa như mọi ngày mà còn dừng lại, cách đó vài bước, tụ tập thành nhóm, thì thào to nhỏ.","cat":"bedtime"},{"id":"lam-cach-nao-ve-de-hon","url":"https://truyencotich.top/doc-truyen/lam-cach-nao-ve-de-hon","title":"Làm cách nào về dễ hơn","summary":"Ba cậu bé rủ nhau vào rừng. Trong rừng có nấm, có quả rừng, lại có đủ các thứ chim. Ba cậu mải chơi nên không để ý là trời đã về chiều, sắp tối. Về bây giờ thì sợ lắm!","cat":"bedtime"},{"id":"vao-nghe","url":"https://truyencotich.top/doc-truyen/vao-nghe","title":"Vào nghề","summary":"Hè năm ấy, Va-li-a theo bố mẹ đi xem xiếc. Em thích nhất tiết mục “Cô gái phi ngựa đánh đàn”. Va-li-a nghĩ: “Cô ấy xinh đẹp, dũng cảm thật”. Và em mơ ước trở thành diễn viên phi ngựa.","cat":"bedtime"},{"id":"bai-hoc-quy","url":"https://truyencotich.top/doc-truyen/bai-hoc-quy","title":"Bài học quý","summary":"Trong khu rừng kia, chú Sẻ và chú Chích chơi với nhau rất thân. Một hôm, Sẻ nhận được món quà của bà ngoại gửi đến. Đó là một chiếc hộp đựng toàn hạt kê. Sẻ không hề nói với bạn một lời nào về món quà lớn ấy cả.","cat":"bedtime"},{"id":"chang-giong-nhau","url":"https://truyencotich.top/doc-truyen/chang-giong-nhau","title":"Chẳng giống nhau","summary":"Nghỉ hè, Ni-ki-ta, Gô-sa, Chi-om-ka về thăm bà ngoại. Ăn cơm xong, cả ba rời khỏi bàn...","cat":"bedtime"},{"id":"qua-tang-cha","url":"https://truyencotich.top/doc-truyen/qua-tang-cha","title":"Quà tặng cha","summary":"Một bữa, Pa-xcan – khi đó đã là sinh viên – đi đâu khuya về thấy bố vẫn cặm cụi trước bàn làm việc. Anh rón rén lại gần. Ông bố vẫn mải mê với những con số: ông đang phải kiểm tra sổ sách của Sở tài chính mà ông mới được bổ nhiệm phụ trách.","cat":"bedtime"},{"id":"chu-de-sau-lo-suoi","url":"https://truyencotich.top/doc-truyen/chu-de-sau-lo-suoi","title":"Chú dế sau lò sưởi","summary":"Buổi tối ấy, nhà Mô-da thật yên tĩnh. Cậu bé thiu thiu ngủ trên ghế bành. Bỗng dưng!… Hình như có một cái gì đó đã xảy ra?","cat":"bedtime"},{"id":"mot-phut","url":"https://truyencotich.top/doc-truyen/mot-phut","title":"Một phút","summary":"Mọi người trong gia đình đều có tính cẩn thận và quý trọng thời giờ, chỉ trừ có Mi-chi-a. Mi-chi-a bao giờ cũng chậm trễ hơn người khác. Đến giờ ăn, mọi người đã ngồi vào bàn, chỉ thiếu Mi-chia-a.","cat":"bedtime"},{"id":"co-cham","url":"https://truyencotich.top/doc-truyen/co-cham","title":"Cô Chấm","summary":"Chấm không phải là cô con gái đẹp, nhưng là người mà ai đã gặp thì không thể lẫn lộn với bất cứ một người nào khác.","cat":"bedtime"},{"id":"vuot-bac","url":"https://truyencotich.top/doc-truyen/vuot-bac","title":"Vượt bậc","summary":"Hôm chủ nhật, bố và Nam đến nhà bác chơi. Nam có một chuyện rất thú, Nam sẽ kể cho các chị nghe. Tháng này, Nam vượt từ thứ hai mươi lên thứ tám trong lớp. Nam được cô giáo khen là học khá.","cat":"bedtime"},{"id":"gio-lanh-dau-mua","url":"https://truyencotich.top/doc-truyen/gio-lanh-dau-mua","title":"Gió lạnh đầu mùa","summary":"Buổi sáng hôm nay, mùa đông đột nhiên đến, không báo trước. Vừa mới ngày hôm qua giời hãy còn nắng ấm và hanh, cái nắng về cuối tháng mười làm nứt nẻ đất ruộng và làm giòn khô những chiếc lá rơi.","cat":"bedtime"},{"id":"qua-tao-cua-bac-ho","url":"https://truyencotich.top/doc-truyen/qua-tao-cua-bac-ho","title":"Quả táo của Bác Hồ","summary":"Tháng 4-1946, với danh nghĩa là Chủ tịch nước Việt Nam Dân chủ Cộng hòa, Bác Hồ sang Pháp để đàm phán với Chính phủ Pháp về những vấn đề có liên quan đến vận mệnh của đất nước.","cat":"bedtime"},{"id":"qua-suoi","url":"https://truyencotich.top/doc-truyen/qua-suoi","title":"Qua suối","summary":"Một lần, trên đường đi công tác, Bác Hồ và các chiến sĩ bảo vệ phải qua một con suối. Trên dòng suối có những hòn đá bắc thành lối đi. Khi Bác đã sang đến bờ bên kia, một chiến sĩ đi phía sau bỗng sẩy chân ngã.","cat":"bedtime"},{"id":"bai-tap-lam-van","url":"https://truyencotich.top/doc-truyen/bai-tap-lam-van","title":"Bài tập làm văn","summary":"Có lần, cô giáo ra cho chúng tôi một đề văn ở lớp: “Em đã làm gì để giúp đỡ mẹ?’’","cat":"bedtime"},{"id":"con-voi-cua-tran-hung-dao","url":"https://truyencotich.top/doc-truyen/con-voi-cua-tran-hung-dao","title":"Con voi của Trần Hưng Đạo","summary":"Trong cuộc kháng chiến chống quân Nguyên, trên đường tiến quân, voi của Trần Hưng Đạo bị sa lầy. Quân sĩ cùng nhân dân trong vùng tìm đủ mọi cách để cứu voi nhưng vô hiệu.","cat":"bedtime"},{"id":"co-nhung-mua-dong","url":"https://truyencotich.top/doc-truyen/co-nhung-mua-dong","title":"Có những mùa đông","summary":"Có một mùa đông, Bác Hồ sống bên nước Anh. Lúc ấy bác còn trẻ. Bác làm việc cào tuyết trong một trường học để có tiền sinh sống.","cat":"bedtime"},{"id":"co-va-vac","url":"https://truyencotich.top/doc-truyen/co-va-vac","title":"Cò và vạc","summary":"Cò và Vạc là hai anh em, nhưng tính nết rất khác nhau. Cò thì ngoan ngoãn, chăm chỉ học tập, sách vở sạch sẽ luôn luôn được thầy yêu bạn mến. Còn Vạc thì lười biếng, suốt ngày chỉ nằm ngủ. Cò bảo mãi, Vạc chẳng nghe.","cat":"bedtime"},{"id":"co-chi-thi-nen","url":"https://truyencotich.top/doc-truyen/co-chi-thi-nen","title":"Có chí thì nên","summary":"Đầu năm học, Bắc được bố đưa đến trường. Bố cậu nói với thầy giáo: Xin thầy kiên nhẫn, thật kiên nhẫn, vì con tôi tối dạ lắm!","cat":"bedtime"},{"id":"chu-bo-doi-lai-may-bay","url":"https://truyencotich.top/doc-truyen/chu-bo-doi-lai-may-bay","title":"Chú bộ đội lái máy bay","summary":"Trước giờ vào lớp, chúng em đang chơi thì có một chú bộ đội đến. Chú đội chiếc mũ có ông sao trên nền xanh da trời. Chú hỏi thăm cô giáo. Một bạn vào thưa với cô. Cô vội vàng bước ra.","cat":"bedtime"},{"id":"cai-o-ga","url":"https://truyencotich.top/doc-truyen/cai-o-ga","title":"Cái ổ gà","summary":"Chiều nay, Dũng đứng chơi trước cửa chờ đón bố về. Dũng nhìn xe cộ và mọi người qua đường. Một bác chở một bó củi sau xe đạp, định tránh ổ gà thì một chiếc xe khác ở phía trước xô tới.","cat":"bedtime"},{"id":"be-mai-da-lon","url":"https://truyencotich.top/doc-truyen/be-mai-da-lon","title":"Bé Mai đã lớn","summary":"Bé Mai rất thích làm người lớn. Bé thử đủ mọi cách: bé đi dép của mẹ, bé cài trâm lên mái tóc theo kiểu của cô. Bé lại còn đeo đồng hồ tay nữa. Nhưng chẳng có kết quả. Mọi người chỉ nhìn bé, cười chế giễu.","cat":"bedtime"},{"id":"buoi-hoc-cuoi-nam","url":"https://truyencotich.top/doc-truyen/buoi-hoc-cuoi-nam","title":"Buổi học cuối năm","summary":"Hôm nay Minh đến lớp, lòng hồi hộp. Buổi học này là buổi học cuối năm. Các bạn Minh cũng đã có mặt đông đủ. Ai cũng muốn đến sớm hơn mọi ngày một chút để được nói chuyện vui đùa với nhau.","cat":"bedtime"},{"id":"be-va-chim-chich-bong","url":"https://truyencotich.top/doc-truyen/be-va-chim-chich-bong","title":"Bé và chim chích bông","summary":"Buổi sáng, Bé dậy sớm, ngồi học bài. Dậy sớm học bài là một thói quen tốt. Nhưng phải cố gắng lắm mới có được thói quen ấy. Rét ghê. Thế mà Bé vùng dậy, chui ra được khỏi cái chăn ấm. Bé ngồi học bài.","cat":"bedtime"},{"id":"ban-tay-me","url":"https://truyencotich.top/doc-truyen/ban-tay-me","title":"Bàn tay mẹ","summary":"Bình yêu nhất là đôi bàn tay mẹ. Tay mẹ không trắng đâu. Bàn tay mẹ rám nắng, các ngón tay gầy gầy, xương xương. Bình rất thích áp hai bàn tay của mẹ vào má. Hai bàn tay xoa vào má cứ ram ráp nhưng không hiểu sao Bình rất thích.","cat":"bedtime"},{"id":"mot-nguoi-ham-doc-sach","url":"https://truyencotich.top/doc-truyen/mot-nguoi-ham-doc-sach","title":"Một người ham đọc sách","summary":"Đan – tê là một nhà thơ lớn của nước Ý. Ông còn nổi tiếng là người ham đọc sách. Ông thường tìm đọc các loại sách vừa xuất bản.","cat":"bedtime"},{"id":"chu-gau-mi-sa","url":"https://truyencotich.top/doc-truyen/chu-gau-mi-sa","title":"Chú gấu Mi-sa","summary":"Mi-sa là một chú gấu bông rất dễ thương. Nhưng sáng nay, cô chủ bỗng túm lấy chú, bỏ vào nhà kho. Mi-sa tủi thân, bèn lách qua cái lỗ mèo chui rồi bỏ đi.","cat":"bedtime"},{"id":"con-heo-dat","url":"https://truyencotich.top/doc-truyen/con-heo-dat","title":"Con heo đất","summary":"Tôi đang mong bố mua cho tôi một con rô bốt. Nhưng bố lại mang về một con heo đất.","cat":"bedtime"},{"id":"tu-cau-be-lam-thue","url":"https://truyencotich.top/doc-truyen/tu-cau-be-lam-thue","title":"Từ cậu bé làm thuê","summary":"Ông Nguyễn Sơn Hà là người khai sinh ra ngành sơn Việt Nam.","cat":"bedtime"},{"id":"su-tich-ngay-va-dem","url":"https://truyencotich.top/doc-truyen/su-tich-ngay-va-dem","title":"Sự tích ngày và đêm","summary":"Ngày xửa ngày xưa, Mặt Trăng, Mặt Trời và Gà Trống cùng sống với nhau trên trời. Mặt Trăng mặc cái áo màu trắng, Gà Trống đội một chiếc mũ màu đỏ. Mặt Trăng thích cái mũ đỏ của Gà Trống lắm.","cat":"bedtime"},{"id":"hai-anh-em-ga-con","url":"https://truyencotich.top/doc-truyen/hai-anh-em-ga-con","title":"Hai anh em gà con","summary":"Hai chú Gà con tìm được một mẩu bánh mì. Chúng thích thú vô cùng và bắt đầu dùng cái mỏ xinh xinh mổ vào miếng mồi ngon. Một chú Vịt con chơi gần đấy nhìn thấy và chạy lại, xin Gà con cùng được ăn.","cat":"bedtime"},{"id":"chu-soc-thong-minh","url":"https://truyencotich.top/doc-truyen/chu-soc-thong-minh","title":"Chú sóc thông minh","summary":"Trên cành cao, một chú Sóc đang vui vẻ nhảy nhót. Dưới đất, có con Sói đang đi tìm bữa điểm tâm. Nhìn thấy Sóc, Sói nghĩ cách để ăn thịt Sóc, bèn nói: Chúc buổi sáng tốt lành!","cat":"bedtime"},{"id":"may-trang-va-may-den","url":"https://truyencotich.top/doc-truyen/may-trang-va-may-den","title":"Mây Trắng và mây Đen","summary":"Mây Trắng và mây Đen xưa kia đều là con của Thần Nước. Khi mới sinh ra, hai chị em đều mặc áo xám giống hệt nhau, nên người ta thường gọi chung một tên là: Mây Xám.","cat":"bedtime"},{"id":"nhung-chiec-ao-am","url":"https://truyencotich.top/doc-truyen/nhung-chiec-ao-am","title":"Những chiếc áo ấm","summary":"Gió bấc thổi ào ào qua khu rừng vắng. Những cành cây khẳng khiu chốc chốc run lên bần bật. Mưa phùn lất phất.. Bên gốc đa, một chú Thỏ bước ra, tay cầm một tấm vải dệt bằng rong.","cat":"bedtime"},{"id":"em-cua-ti-ban","url":"https://truyencotich.top/doc-truyen/em-cua-ti-ban","title":"Em của Tí Bẩn","summary":"NGÀY XƯA, có một cậu bé ăn ở bừa bãi đến nỗi mọi người gọi cậu ta là Tí Bẩn. Cậu vứt sách vở trên sàn nhà, để giày lấm lên bàn học, cậu khoắng ngón tay vào hộp mứt, đổ lọ mực lên cái áo mới. Chưa thấy ai bừa bãi như cậu bao giờ.","cat":"bedtime"},{"id":"con-vet-ngheo","url":"https://truyencotich.top/doc-truyen/con-vet-ngheo","title":"Con vẹt nghèo","summary":"HẰNG NĂM, MỖI KHI MÙA XUÂN VỀ, các giống chim và thú vật lại rủ nhau tới rừng mở hội. Nào Voi, Gấu, Hổ, Lợn Lòi... trổ tài thi khoẻ. Nào Khỉ, Vượn, Sóc... đua nhau leo trèo. Còn các giống chim khác thì thi giọng hát.","cat":"bedtime"},{"id":"rua-va-huou","url":"https://truyencotich.top/doc-truyen/rua-va-huou","title":"Rùa và Hươu","summary":"Rùa vốn chậm chạp nhất trong các loài chim thú. Nó biết phận mình nên chẳng khi nào tỏ ra kiêu ngạo. Trái lại, nó rất khiêm nhường.","cat":"bedtime"},{"id":"dung-chet-vi-so-hai","url":"https://truyencotich.top/doc-truyen/dung-chet-vi-so-hai","title":"Đừng chết vì sợ hãi","summary":"Khu rừng mà Dê Trắng sinh sống có một con Hổ Xám rất hung ác. Bao nhiêu con vật hiền lành đã phải bỏ mạng dưới nanh vuốt của nó. Hổ Xám trở thành ác mộng đối với các con vật. Không khí chết chóc bao trùm lên cả khu rừng.","cat":"bedtime"},{"id":"cuoc-hop-trong-cap-sach","url":"https://truyencotich.top/doc-truyen/cuoc-hop-trong-cap-sach","title":"Cuộc họp trong cặp sách","summary":"Bé phải mất cả buổi sáng để tranh luận với anh Huy về chuyện đồ vật có biết nói hay không? Anh Huy chỉ quen nghe bằng tai thôi. Anh quả quyết rằng nếu các đồ vật xung quanh ta biết chuyện trò thì anh sẽ ngay lập tức lên tận sao Hoả.","cat":"bedtime"},{"id":"chuyen-co-tich-buon","url":"https://truyencotich.top/doc-truyen/chuyen-co-tich-buon","title":"Chuyện cổ tích buồn","summary":"Sáng nào dậy sớm, Ly cũng nhìn thấy bà. Bà đang lúi húi nhặt những bông hoa sứ rụng ngay trước cổng nhà. Lưng bà còng, tóc bà bạc trắng. Hình như bà đã đến nhặt hoa ở đây từ lâu lắm, vì cây hoa sứ này còn nhiều tuổi hơn Ly gấp mấy lần.","cat":"bedtime"},{"id":"mua-he-giay-di-dau","url":"https://truyencotich.top/doc-truyen/mua-he-giay-di-dau","title":"Mùa hè giầy đi đâu?","summary":"Đầu mùa hè các đồ vật chơi trò trốn tìm. Viên Bi trốn kĩ đến nỗi trời tối mà không ai tìm được Bi cả. Viết Chì vẽ một cây Đèn Pin để đi tìm Bi. Đèn soi vào góc bàn, hộc tủ, túi áo, xó nhà và soi cả trong kẹt cửa nữa...","cat":"bedtime"},{"id":"doi-dep","url":"https://truyencotich.top/doc-truyen/doi-dep","title":"Đôi dép","summary":"Hai chiếc dép là đôi bạn chơi với nhau rất thân. Không biết chúng chơi chung từ bao giờ, chỉ biết từ rất lâu, lâu lắm rồi.","cat":"bedtime"},{"id":"loi-bac-giu-kho","url":"https://truyencotich.top/doc-truyen/loi-bac-giu-kho","title":"Lời bác giữ kho","summary":"Thường ngày, Dạ Dày là một bác giữ kho làm việc giỏi. Kho của bác không bao giờ giữ lại lâu một thứ gì. Bác thường dặn cậu Mồm: Bất cứ làm việc gì cũng phải có kế hoạch. Ăn cũng thế, phải điều độ.","cat":"bedtime"},{"id":"hat-cuom-tham-an","url":"https://truyencotich.top/doc-truyen/hat-cuom-tham-an","title":"Hạt cườm tham ăn","summary":"Có một chị chim vành khuyên đẻ được tám trứng, ấp nở ra tám vành khuyên con. Ngày ngày chim mẹ đi kiếm mồi về để nuôi con. Khi chúng mới nở, chim mẹ phải mớm cho từng con một.","cat":"bedtime"},{"id":"ca-chuoi-con","url":"https://truyencotich.top/doc-truyen/ca-chuoi-con","title":"Cá chuối con","summary":"Bơi càng gần lên mặt ao, thấy nước càng nóng, cái chuối mẹ bơi mãi, cố tìm hướng vào bờ. Mặt ao sủi bọt, nổi lên từng đám rêu. Rất khó nhận ra phương hướng. Chuối mẹ phải vừa bơi vừa nghếch lên mặt nước để tìm hướng khóm tre.","cat":"bedtime"},{"id":"hai-em-be-trong-rung-ram","url":"https://truyencotich.top/doc-truyen/hai-em-be-trong-rung-ram","title":"Hai em bé trong rừng rậm","summary":"CÓ HAI EM BÉ, một trai và một gái, đang đến trường. Chúng phải đi qua một khu rừng rậm và đẹp. Trên đường thì nóng và bụi, nhưng trong rừng lại mát và vui.","cat":"bedtime"},{"id":"ba-chu-de-con","url":"https://truyencotich.top/doc-truyen/ba-chu-de-con","title":"Ba chú dê con","summary":"Một buổi chiều nắng gắt. Trên sườn đồi vắng vẻ, ba chú dê con rủ nhau đi ăn cỏ. Chúng chạy nhảy vui đùa, chẳng sợ gì ánh nắng tháng năm gay gắt thiêu đốt.","cat":"bedtime"},{"id":"chu-tho-tinh-khon","url":"https://truyencotich.top/doc-truyen/chu-tho-tinh-khon","title":"Chú thỏ tinh khôn","summary":"Trong khu rừng nọ có một chú thỏ, ngày kia khi nó đang thảnh thơi nằm ngủ ở dưới gốc sung. Đột nhiên có quả sung chín từ trên cây rới xuống đánh một cái bốp ngay giữa đầu.","cat":"bedtime"},{"id":"se-non-va-dieu-giay","url":"https://truyencotich.top/doc-truyen/se-non-va-dieu-giay","title":"Sẻ non và diều giấy","summary":"Sẻ non đang sập sè bay lượn. Vừa được bố mẹ cho “ra riêng” dăm hôm, sẻ ta nhìn thế giới thấy cái gì cũng đẹp, cũng lạ. Trời xanh này. Nắng vàng này. Bên dưới là cánh đồng mênh mông, rập rờn biển lúa chín vàng.","cat":"bedtime"},{"id":"ca-nha-deu-lam-viec","url":"https://truyencotich.top/doc-truyen/ca-nha-deu-lam-viec","title":"Cả nhà đều làm việc","summary":"Cả nhà ai cũng làm việc. Này nhé, anh Trâu to lớn theo bố đi cày. Chị Đòn Gánh dẻo dai thì giúp mẹ gánh mạ ra đồng. Đến ông MặtTrời cũng làm việc.","cat":"bedtime"},{"id":"que-ai-dep-nhat","url":"https://truyencotich.top/doc-truyen/que-ai-dep-nhat","title":"Quê ai đẹp nhất?","summary":"Một con Ếch đã sống từ lâu bên sườn dốc. Nó mơ ước đến một ngày nào đó sẽ đi du lịch một chuyến đến kinh thành. Một con Ếch sống ở kinh thành lại ngày đêm mơ ước được xuống vùng sườn dốc.","cat":"bedtime"},{"id":"ran-va-chuot","url":"https://truyencotich.top/doc-truyen/ran-va-chuot","title":"Rắn và chuột","summary":"Một hôm, Rắn bò đến một cái hang. Nó nghĩ đây chắc là nhà của một con vật bé nhỏ nào đó. Lúc này, Rắn đã đói bụng lắm, nó chẳng muốn đi đâu nữa.","cat":"bedtime"},{"id":"quy-dinh-ro-rang","url":"https://truyencotich.top/doc-truyen/quy-dinh-ro-rang","title":"Quy định rõ ràng","summary":"Một lần, Thị trưởng của một thành phố nước Pháp đã sa thải người thư kí vì anh ta thảo một lệnh không rõ ràng và vì sai lầm ấy, ngài thị trưởng đã gặp một số phiền phức. Ngài không chịu nghe những lời giải thích hoặc biện hộ.","cat":"bedtime"},{"id":"vu-a-dinh","url":"https://truyencotich.top/doc-truyen/vu-a-dinh","title":"Vừ A Dính","summary":"Vừ A Dính sinh ngày 12 tháng 9 năm 1934, người dân tộc H’Mông, quê ở Pú Nhung, vùng cao huyện Tuần Giáo, tỉnh Lai Châu. Sinh ra trong gia đình giàu truyền thống cách mạng, cậu bé thông minh, gan dạ và nhanh nhẹn...","cat":"bedtime"},{"id":"cuoc-chay-dua-trong-rung","url":"https://truyencotich.top/doc-truyen/cuoc-chay-dua-trong-rung","title":"Cuộc chạy đua trong rừng","summary":"Ngày mai, muông thú trong rừng mở cuộc thi chạy để chọn con vật chạy nhanh nhất. Ngựa Con thích lắm. Chú tin chắc sẽ giành được vòng nguyệt quế.","cat":"bedtime"},{"id":"muu-chu-se","url":"https://truyencotich.top/doc-truyen/muu-chu-se","title":"Mưu chú Sẻ","summary":"Buổi sớm, một con Mèo chộp được một chú Sẻ. Sẻ hoảng lắm, nhưng nó nén sợ, lễ phép nói: Thưa anh, tại sao một người sạch sẽ như anh trước khi ăn sáng lại không rửa mặt?","cat":"bedtime"},{"id":"anh-hung-kim-dong","url":"https://truyencotich.top/doc-truyen/anh-hung-kim-dong","title":"Anh hùng Kim Đồng","summary":"Anh hùng Kim Đồng (tên thật là Nông Văn Dền) sinh năm 1928, dân tộc Nùng, tại bản Nà Mạ, xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng. Khi hy sinh, Kim Đồng là đội trưởng Đội Nhi đồng Cứu quốc...","cat":"bedtime"},{"id":"bat-che-se-doi","url":"https://truyencotich.top/doc-truyen/bat-che-se-doi","title":"Bát chè sẻ đôi","summary":"Đồng chí liên lạc đưa công văn 10 giờ đêm mới đến. Bác gọi mang ra một bát, một thìa con. Rồi Bác đem bát chè đậu đen, đường phèn, mà anh em phục vụ vừa mang lên, xẻ một nửa cho đồng chí liên lạc.","cat":"bedtime"},{"id":"co-con-gai-ut-cua-ong-mat-troi","url":"https://truyencotich.top/doc-truyen/co-con-gai-ut-cua-ong-mat-troi","title":"Cô con gái út của ông mặt trời","summary":"Ông mặt trời có rất nhiều con nhưng chỉ có một cô con gái duy nhất là Út Trăng xinh đẹp, bé bỏng.","cat":"bedtime"},{"id":"chu-meo-danh-rang","url":"https://truyencotich.top/doc-truyen/chu-meo-danh-rang","title":"Chú mèo đánh răng","summary":"Bác Lợn mới mở cửa hàng bán bàn chải đánh răng, trước cửa có treo một biển quảng cáo rất to: “Bàn chải đánh răng chất lượng hạng nhất, một lần sạch ngay”.","cat":"bedtime"},{"id":"bac-si-chim","url":"https://truyencotich.top/doc-truyen/bac-si-chim","title":"Bác sĩ chim","summary":"Những con chim nhỏ quyết định mở một bệnh viện chữa bệnh từ thiện cho các con vật. Các bác sĩ chim mặc áo đồng phục trắng và chờ bệnh nhân đến. Cô Chim Chào Mào được giao nhiệm vụ tiếp bệnh nhân.","cat":"bedtime"},{"id":"cu-cai-trang","url":"https://truyencotich.top/doc-truyen/cu-cai-trang","title":"Củ cải trắng","summary":"Mùa đông đã đến rồi, trời lạnh buốt. Thỏ con không còn gì để ăn nữa, nó đành mặc áo ấm và đi ra khỏi nhà để tìm cái ăn.","cat":"bedtime"},{"id":"khi-con-biet-vang-loi","url":"https://truyencotich.top/doc-truyen/khi-con-biet-vang-loi","title":"Khỉ Con biết vâng lời","summary":"Một buổi sáng, Khỉ mẹ dặn Khỉ con xuống núi đi hái trái cây. Khỉ con mang giỏ trên lưng, rong chơi trên đường đi và quên mất lời mẹ dặn. Khỉ con thấy chó Thỏ đang đuổi bắt Chuồn Chuồn.","cat":"bedtime"},{"id":"nang-tien-mua","url":"https://truyencotich.top/doc-truyen/nang-tien-mua","title":"Nàng tiên mưa","summary":"Hôm nay, Vịt con được mẹ cho ra sông tắm mát. Vịt con thích lắm. Những hạt nước bé xíu tinh nghịch rủ nhau trèo lên lưng, lên đầu Vịt con rồi lại lăn xuống mặt nước.","cat":"bedtime"},{"id":"tho-hong-chanh-choe","url":"https://truyencotich.top/doc-truyen/tho-hong-chanh-choe","title":"Thỏ hồng chảnh chọe","summary":"Xưa thật xưa, trên hòn đảo nọ có rất nhiều động vật, chim chóc sinh sống, trong đó có gia đình nhà Thỏ Hồng. Khi Thỏ Hồng đến tuổi đi học, mẹ sắm cho Thỏ Hồng một chiếc cặp màu vàng thật xinh.","cat":"bedtime"},{"id":"gau-con-ngoan-ngoan","url":"https://truyencotich.top/doc-truyen/gau-con-ngoan-ngoan","title":"Gấu con ngoan ngoãn","summary":"Bác Voi tới nhà Gấu con chơi và tặng Gấu con một rổ lê thơm. Gấu con mừng lắm và không quên cám ơn bác Voi.","cat":"bedtime"},{"id":"chuyen-du-lich-cua-chu-ga-trong-choai","url":"https://truyencotich.top/doc-truyen/chuyen-du-lich-cua-chu-ga-trong-choai","title":"Chuyến du lịch của chú Gà Trống Choai","summary":"Có một chú gà trống choai có chiếc mào màu đỏ với cái đuôi vểnh lên rất hùng dũng. Chú rất thích đi du lịch. Chú rất mong được nhìn thấy biển vì vậy chú lên kế hoạch đi du lịch ra biển.","cat":"bedtime"},{"id":"chiec-ao-dep","url":"https://truyencotich.top/doc-truyen/chiec-ao-dep","title":"Chiếc áo đẹp","summary":"Gió bấc thổi ào ào qua khu rừng vắng. Một chú Thỏ bước ra, tay cầm lá cọ che thân. Bỗng cơn gió bay vèo kéo theo tấm lá của Thỏ xuống nước. Rét quá, Thỏ co ro thầm nghĩ trong bụng: “Giá như mình có một chiếc áo thì hay biết mấy”.","cat":"bedtime"},{"id":"niem-vui-tu-bat-canh-cai","url":"https://truyencotich.top/doc-truyen/niem-vui-tu-bat-canh-cai","title":"Niềm vui từ bát canh cải","summary":"Xem tivi thấy các chú bộ đội đảo Trường Sa trồng rau trong khay gỗ, bé Mai thích lắm nói với bố: “ Con muốn được trồng rau như các chú bộ đội”.","cat":"bedtime"},{"id":"bac-gau-den-va-hai-chu-tho","url":"https://truyencotich.top/doc-truyen/bac-gau-den-va-hai-chu-tho","title":"Bác gấu đen và hai chú thỏ","summary":"Trời mưa to như trút nước. Gió thổi ào ào… bẻ gẫy cả cành cây. Gấu Đen đi chơi về bị ướt lướt thướt, nước mưa chảy ròng ròng xuống mặt Gấu. Gấu chạy mãi, chạy mãi trong rừng để tìm chỗ trú nhờ.","cat":"bedtime"},{"id":"cai-ho-ben-duong","url":"https://truyencotich.top/doc-truyen/cai-ho-ben-duong","title":"Cái hố bên đường","summary":"Có một bầy thú nhỏ sống cùng nhau trong khu rừng nọ. Ngày ngày chúng thường đi trên một con đường nhỏ rồi băng qua một ngã tư có chốt đèn giao thông để tới trường.","cat":"bedtime"},{"id":"mot-chuyen-tham-quan","url":"https://truyencotich.top/doc-truyen/mot-chuyen-tham-quan","title":"Một chuyến tham quan","summary":"Bé Loan học lớp mẫu giáo 5 tuổi. Một hôm, cơ quan mẹ Loan tổ chức đi tham quan Hà Nội. Thấy Loan ngoan, biết vâng lời bố mẹ, mẹ bàn với bố cho Loan đi cùng.","cat":"bedtime"},{"id":"xe-dap-con-tren-duong-pho","url":"https://truyencotich.top/doc-truyen/xe-dap-con-tren-duong-pho","title":"Xe đạp con trên đường phố","summary":"Sáng sớm nay mọi người đã đi làm hết. Chỉ còn mỗi mình Xe Đạp con ở nhà. Nằm một mình buồn quá, Xe Đạp con nghĩ: “Mình phải đi dạo phố mới được!”","cat":"bedtime"},{"id":"doi-dap-voi-vua","url":"https://truyencotich.top/doc-truyen/doi-dap-voi-vua","title":"Đối đáp với vua","summary":"Một lần, vua Minh Mạng từ kinh đô Huế ngự giá ra Thăng Long (Hà Nội). Vua cho xa giá đến Hồ Tây ngắm cảnh. Xa giá đi đến đâu, quân lính cũng thét đuổi tất cả mọi người, không cho ai đến gần.","cat":"bedtime"},{"id":"thay-va-tro","url":"https://truyencotich.top/doc-truyen/thay-va-tro","title":"Thầy và trò","summary":"Năm nọ, cậu học trò dốt nhất lớp đến chúc Tết thầy. Ông đồ quá ngạc nhiên vì trò này luôn chậm chạp nhất lớp lại đến chúc Tết thầy sớm nhất.","cat":"bedtime"},{"id":"cuoc-phieu-luu-cua-bo-cong-anh","url":"https://truyencotich.top/doc-truyen/cuoc-phieu-luu-cua-bo-cong-anh","title":"Cuộc phiêu lưu của bồ công anh","summary":"Kìa một cụm hoa Bồ Công Anh đang im lìm buồn bã. Những cánh hoa nhỏ li ti sắp rời thân mẹ, bay xa bay xa...","cat":"bedtime"},{"id":"su-tich-con-ong","url":"https://truyencotich.top/doc-truyen/su-tich-con-ong","title":"Sự tích con Ong","summary":"Ngày xưa, có một người đàn bà tên là nàng Ong. Nàng Ong làm việc chăm chỉ, nhưng vẫn nghèo túng vì nhà đông miệng ăn. Nàng Ong mong các con khôn lớn để đỡ đần mình.","cat":"bedtime"},{"id":"cam-on-anh-ha-ma","url":"https://truyencotich.top/doc-truyen/cam-on-anh-ha-ma","title":"Cảm ơn anh hà mã","summary":"Dê rủ cún vào rừng chơi, khi quay về thì bị lạc đường.","cat":"bedtime"},{"id":"dua-con-cua-me-vit-bau","url":"https://truyencotich.top/doc-truyen/dua-con-cua-me-vit-bau","title":"Đứa con của mẹ Vịt Bầu","summary":"Ổ trứng 10 quả của nhà Vịt Bầu vừa mới nở. Ngắm đàn con thơm tho, xinh đẹp, mịn như nhung đang nằm trong lòng Vịt mẹ cảm thấy mình chính là bà mẹ hạnh phúc nhất thế gian.","cat":"bedtime"},{"id":"qua-va-dan-bo-cau","url":"https://truyencotich.top/doc-truyen/qua-va-dan-bo-cau","title":"Quạ và đàn bồ câu","summary":"Quạ thấy đàn bồ câu được nuôi ăn đầy đủ, không phải đi kiếm thức ăn, không phải ăn xác thối, nó bôi trắng lông mình rồi bay vào chuồng bồ câu.","cat":"bedtime"},{"id":"nguoi-rong-luong-va-ke-keo-kiet","url":"https://truyencotich.top/doc-truyen/nguoi-rong-luong-va-ke-keo-kiet","title":"Người rộng lượng và kẻ keo kiệt","summary":"Ngày xửa ngày xưa, có hai người hàng xóm, một người thì khẳn khái, rộng lượng, còn một người thì keo kiệt, bủn xỉn...","cat":"bedtime"},{"id":"meo-con-va-quyen-sach","url":"https://truyencotich.top/doc-truyen/meo-con-va-quyen-sach","title":"Mèo con và quyển sách","summary":"Mèo con ngồi bên một hốc cây, trên tay chú là quyển sách tậo tô rất mới, rất đẹp. Mèo con ngắm nghía một lúc rồi “soạt! soạt!”, chú ta xé quyển sách.","cat":"bedtime"},{"id":"long-trung-thuc-cua-mot-ga-an-may-dang-kinh","url":"https://truyencotich.top/doc-truyen/long-trung-thuc-cua-mot-ga-an-may-dang-kinh","title":"Lòng trung thực của một gã ăn mày đáng kính","summary":"Một ngày nọ, ông lão ăn xin gõ cửa một lâu đài tráng lệ. Ông nói với người quản gia: Vì tình yêu của Chúa, xin hãy bố thí cho kẻ nghèo này...","cat":"bedtime"},{"id":"loi-noi-co-phep-la","url":"https://truyencotich.top/doc-truyen/loi-noi-co-phep-la","title":"Lời nói có phép lạ","summary":"Một cụ già tóc trắng như cước ngồi trên chiếc ghế dài ngoài vườn hoa. Cụ hỏi bé Pavlik vừa đi tới: Hình như cậu đang có điều gì buồn bực?","cat":"bedtime"},{"id":"cap-sung-va-doi-chan","url":"https://truyencotich.top/doc-truyen/cap-sung-va-doi-chan","title":"Cặp sừng và đôi chân","summary":"Mỗi ngày, Hươu đều tự soi mình dưới nước và tự nhủ: “Với cặp sừng lung linh, mình là con hươu đẹp nhất khu rừng”. Nhưng nó lại chẳng hề thích đôi chân chút nào vì cho rằng chúng trông thật xấu xí.","cat":"bedtime"},{"id":"ngay-nhu-the-nao-la-dep","url":"https://truyencotich.top/doc-truyen/ngay-nhu-the-nao-la-dep","title":"Ngày như thế nào là đẹp?","summary":"Châu chấu nhảy lên gò, chìa cái lưng màu xanh ra phơi nắng. Nó búng chân tanh tách, cọ giũa đôi càng: Một ngày tuyệt đẹp!","cat":"bedtime"},{"id":"ech-sop-du-xuan","url":"https://truyencotich.top/doc-truyen/ech-sop-du-xuan","title":"Ếch Sộp du xuân","summary":"Ếch Sộp được sinh ra và lớn lên trong một vũng lầy. ở đó lúc nào cũng sẵn ruồi muỗi, sâu bọ cho nó mặc sức nhấm nháp. Sau khi đã no chán, chú ta vác cái bụng phình trương lên bờ ngồi sưởi nắng...","cat":"bedtime"},{"id":"bi-mat-cua-may-nho","url":"https://truyencotich.top/doc-truyen/bi-mat-cua-may-nho","title":"Bí mật của mây nhỏ","summary":"Có một đám mây nhỏ đang bay lững lờ trên bầu trời. Hôm nay, nó buồn. Buồn một cách rất lạ. Nó cũng không biết vì sao mình buồn, chỉ thấy trong lòng nặng trĩu.","cat":"bedtime"}];
